INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经营并提供某种通信或网络服务的企业。", "primary_collocate": null, "pronunciation": "yùn yíng shāng", "ipa": "yn⁵¹ iŋ³⁵ ʂɑŋ⁵⁵", "syllable_count": 3, "sentences": [{"text": "三大运营商都在城市里建了新的基站。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家运营商为全国的客户提供网络服务。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要求运营商保护用户的信息。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家运营商的总部在北京，有一万多名员工。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运营商把网络服务卖给学校和公司。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运营商每年都要花很多钱建设网络。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的运营商还做电视和宽带生意。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家运营商今年的客户比去年多了一倍。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话和上网的价格，运营商可以自己定。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家运营商一起建了一个新的网络。", "target_word": "运营商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "电信运营商", "label": "复合"}, {"form": "运营商们", "label": "复数"}, {"form": "運營商", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经营通信或网络服务的企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5538bf12-020f-423d-a46d-0a1f06c15aac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运营商", "is_correct": true, "explanation": "正确：「三大」后接行业中的大型通信企业，能在城市里建基站。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不建通信基站，「三大医院建基站」与句意不符。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是卖东西的地方，不会在城市里建通信基站。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：「三大」通常修饰行业中的大型企业，「三大花园」不成立。"}], "explanations": {"运营商": "正确：「三大」后接行业中的大型通信企业，能在城市里建基站。", "医院": "语义：医院不建通信基站，「三大医院建基站」与句意不符。", "超市": "语义：超市是卖东西的地方，不会在城市里建通信基站。", "花园": "搭配：「三大」通常修饰行业中的大型企业，「三大花园」不成立。"}, "sentence_index": 0, "correct_answer": "运营商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家运营商负责把饭菜送到学校，每天都很准时。", "explanation": "这里应该用〈餐饮公司〉。运营商提供通信或网络服务，不负责送餐；给学校供应饭菜的要说「餐饮公司」。"}, {"text": "这家运营商每年生产几百万台冰箱。", "explanation": "这里应该用〈厂商〉。运营商不生产冰箱等实物，生产家电的要说「厂商」。"}, {"text": "学校请了这家运营商来修建教学楼，工期很短。", "explanation": "这里应该用〈承包商〉。运营商只提供通信或网络服务，不负责修建楼房；承接建筑工程的公司要说「承包商」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运营商", "is_correct": true, "explanation": "正确：能做电视和宽带生意的是通信或网络服务的企业。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会做生意，与「做电视和宽带生意」的主体不符。"}, {"text": "花朵", "is_correct": false, "explanation": "配价：「做生意」的主体须是能经营的人或企业，「花朵」不能作主体。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不会经营业务，句子无法成立。"}], "explanations": {"运营商": "正确：能做电视和宽带生意的是通信或网络服务的企业。", "石头": "语义：石头不会做生意，与「做电视和宽带生意」的主体不符。", "花朵": "配价：「做生意」的主体须是能经营的人或企业，「花朵」不能作主体。", "树木": "语义：树木不会经营业务，句子无法成立。"}, "sentence_index": 6, "correct_answer": "运营商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家运营商为客户提供存款和贷款服务。", "explanation": "这里应该用〈银行〉。存款、贷款是银行的业务，运营商只提供通信或网络服务。"}, {"text": "这家运营商每个月给工厂供应大量零件。", "explanation": "这里应该用〈供应商〉。运营商提供的是通信或网络服务，不向工厂供应零件，供货要说「供应商」。"}, {"text": "我们请这家运营商帮忙卖房子，手续很快。", "explanation": "这里应该用〈中介〉。运营商只提供通信或网络服务，不帮人买卖房产；代办买卖、租赁的机构要说「中介」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两家运营商们都建了新网络。", "corrected_sentence": "这两家运营商都建了新网络。", "error_description": "错误：「运营商们」。「们」不能与「这两家」这样的数量词一起使用，正确为「这两家运营商」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天终于选定了一运营商，因为它的网速快。", "corrected_sentence": "我今天终于选定了一家运营商，因为它的网速快。", "error_description": "错误：「一运营商」。「一」与「运营商」之间缺少量词，正确为「一家运营商」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25e11881-f8ba-4c4b-abdd-056fa73f7a32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
