INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89243, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "殴打是用手或东西打人，把人打痛。", "primary_collocate": null, "pronunciation": "ōu dǎ", "ipa": "ou˥ ta˨˩˦", "syllable_count": 2, "sentences": [{"text": "他殴打了自己的同学。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打人是不对的，不能殴打别人。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男人用棍子殴打小偷。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，有人在路边殴打老人。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为殴打别人，警察把他带走了。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不应该互相殴打。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板殴打工人，大家都很生气。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经殴打过自己的弟弟。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个人殴打他，他的脸都肿了。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在学校里，不许殴打同学。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "殴打了", "label": "体标"}, {"form": "殴打过", "label": "体标"}, {"form": "毆打", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用手或东西打人使人疼痛，日常打人义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批准", "is_correct": false, "explanation": "配价：「批准」的宾语是申请、计划等事项，不能是人，不能说「批准了自己的同学」。"}, {"text": "殴打", "is_correct": true, "explanation": "正确：「殴打」指用拳脚或器物打人，与句中「他」对同学的动作相符。"}, {"text": "晾", "is_correct": false, "explanation": "搭配：「晾」的对象是衣物等，不能用于人，不能说「晾了自己的同学」。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语是食物，不能说「吃了自己的同学」。"}], "explanations": {"批准": "配价：「批准」的宾语是申请、计划等事项，不能是人，不能说「批准了自己的同学」。", "殴打": "正确：「殴打」指用拳脚或器物打人，与句中「他」对同学的动作相符。", "晾": "搭配：「晾」的对象是衣物等，不能用于人，不能说「晾了自己的同学」。", "吃": "搭配：「吃」的宾语是食物，不能说「吃了自己的同学」。"}, "sentence_index": 0, "correct_answer": "殴打"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我队在决赛中殴打了对手，最后获胜。", "explanation": "这里应该用〈击败〉。殴打指用拳脚或器物伤人，比赛中战胜对手要用击败。"}, {"text": "他轻轻殴打了一下门，然后走了进去。", "explanation": "这里应该用〈碰〉。殴打是伤人的暴力行为，轻轻碰一下门要用碰，不能用殴打。"}, {"text": "他一边听歌，一边用手指殴打着节拍。", "explanation": "这里应该用〈敲〉。殴打是伤人的暴力行为，用手指打节拍要用敲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修剪", "is_correct": false, "explanation": "配价：「修剪」的对象是树木、草坪等，不能用于工人。"}, {"text": "粉刷", "is_correct": false, "explanation": "配价：「粉刷」的对象是墙面等表面，不能用于工人。"}, {"text": "浇灌", "is_correct": false, "explanation": "配价：「浇灌」的对象是植物或土地，不能用于工人。"}, {"text": "殴打", "is_correct": true, "explanation": "正确：「殴打」指用拳脚或器物伤人，与老板的行为及众人生气相符。"}], "explanations": {"修剪": "配价：「修剪」的对象是树木、草坪等，不能用于工人。", "粉刷": "配价：「粉刷」的对象是墙面等表面，不能用于工人。", "浇灌": "配价：「浇灌」的对象是植物或土地，不能用于工人。", "殴打": "正确：「殴打」指用拳脚或器物伤人，与老板的行为及众人生气相符。"}, "sentence_index": 6, "correct_answer": "殴打"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快殴打了这个问题，大家都松了一口气。", "explanation": "这里应该用〈解决〉。殴打的对象是人或动物，问题要用解决。"}, {"text": "我们认真研究了这个方案，然后殴打了它。", "explanation": "这里应该用〈修改〉。殴打的对象是人或动物，方案要修改，不能殴打。"}, {"text": "妈妈殴打了坏掉的台灯，很快就修好了。", "explanation": "这里应该用〈修理〉。殴打是伤人的动作，修好坏掉的台灯要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没有殴打了任何人。", "corrected_sentence": "他没有殴打任何人。", "error_description": "「没有殴打了任何人」错误：否定句中「没有」与动词同用时不带「了」，应为「没有殴打任何人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从没殴打着同学。", "corrected_sentence": "他从没殴打过同学。", "error_description": "体标错误：表示从未有过的经历要用“过”，“着”表示动作持续，不能用于“从没”的句子。应为“他从没殴打过同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
