INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89244, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用拳脚或器物击打他人身体。", "primary_collocate": null, "pronunciation": "ōu dǎ", "ipa": "ou˥ ta˨˩˦", "syllable_count": 2, "sentences": [{"text": "嫌疑人用拳头殴打受害者。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几名男子在街上殴打路人。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院认为，他殴打他人，应该受罚。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用拳脚殴打对方，对方受了伤。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殴打他人是违法的行为。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方抓住了殴打店员的人。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认自己殴打过邻居。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殴打他人的人要向对方道歉。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了酒，他在门口殴打了一个陌生人。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的经理殴打了一名工人。", "target_word": "殴打", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "殴打了", "label": "体标"}, {"form": "殴打过", "label": "体标"}, {"form": "毆打", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用拳脚或器物击打他人身体，法律、新闻语境义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抚摸", "is_correct": false, "explanation": "搭配：「用拳头」只用于击打，不能与「抚摸」搭配。"}, {"text": "救助", "is_correct": false, "explanation": "语义：「嫌疑人」是加害方，不会「救助」受害者，与句意相反。"}, {"text": "目击", "is_correct": false, "explanation": "配价：「目击」的宾语是事件或场面，不能直接带「受害者」这类人。"}, {"text": "殴打", "is_correct": true, "explanation": "正确：「殴打」指用拳头伤人，与「嫌疑人」和「受害者」的关系相符。"}], "explanations": {"抚摸": "搭配：「用拳头」只用于击打，不能与「抚摸」搭配。", "救助": "语义：「嫌疑人」是加害方，不会「救助」受害者，与句意相反。", "目击": "配价：「目击」的宾语是事件或场面，不能直接带「受害者」这类人。", "殴打": "正确：「殴打」指用拳头伤人，与「嫌疑人」和「受害者」的关系相符。"}, "sentence_index": 0, "correct_answer": "殴打"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用抹布殴打桌子，把桌子擦干净了。", "explanation": "这里应该用〈清洁〉。殴打是伤人的动作，用抹布收拾桌面要用清洁。"}, {"text": "他见到老师，向老师殴打了一下，表示问候。", "explanation": "这里应该用〈打招呼〉。殴打是伤人的动作，表示问候要用打招呼。"}, {"text": "他温柔地殴打了小狗，让它安静下来。", "explanation": "这里应该用〈安抚〉。殴打是粗暴的伤害，让小狗安静下来要用安抚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扫除", "is_correct": false, "explanation": "配价：「扫除」的宾语是垃圾、障碍等，不能是「邻居」这样的人。"}, {"text": "浇灌", "is_correct": false, "explanation": "配价：「浇灌」的对象是植物或土地，不能是「邻居」这样的人。"}, {"text": "粉刷", "is_correct": false, "explanation": "配价：「粉刷」的对象是墙面等表面，不能是「邻居」这样的人。"}, {"text": "殴打", "is_correct": true, "explanation": "正确：「殴打」指伤人的过失行为，「承认」所承认的正是这种行为。"}], "explanations": {"扫除": "配价：「扫除」的宾语是垃圾、障碍等，不能是「邻居」这样的人。", "浇灌": "配价：「浇灌」的对象是植物或土地，不能是「邻居」这样的人。", "粉刷": "配价：「粉刷」的对象是墙面等表面，不能是「邻居」这样的人。", "殴打": "正确：「殴打」指伤人的过失行为，「承认」所承认的正是这种行为。"}, "sentence_index": 6, "correct_answer": "殴打"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "双方在会议上殴打了这份合同。", "explanation": "这里应该用〈签订〉。殴打的对象是人或动物，合同要签订，不能殴打。"}, {"text": "经理殴打了这个项目，很快就完成了。", "explanation": "这里应该用〈推进〉。殴打的对象是人或动物，项目要推进。"}, {"text": "他饭后殴打了一支香烟。", "explanation": "这里应该用〈抽〉。殴打是伤人的动作，吸烟要用抽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "嫌疑人并没有殴打了受害者。", "corrected_sentence": "嫌疑人并没有殴打受害者。", "error_description": "「并没有殴打了」错误：否定句中「没有」后的动词不带「了」，应为「并没有殴打受害者」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说他从前殴打着一个陌生人。", "corrected_sentence": "他说他从前殴打过一个陌生人。", "error_description": "体标错误：表示从前有过的经历要用“过”，“着”表示动作持续，不能用于此句。应为“殴打过一个陌生人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
