INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在学术上有专门研究、有成就的人。", "primary_collocate": null, "pronunciation": "xué zhě", "ipa": "ɕɥe˧˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是研究历史的著名学者。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者在经济方面很有成就。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多学者来参加这次会议。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者写了十本关于语言的书。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们正在讨论新的研究结果。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位有名的法律学者。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国外的学者来我们大学做报告。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者得到了很多奖。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位学者研究中国文学三十年了。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位学者对这个问题的看法不同。", "target_word": "学者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學者", "label": "繁体"}, {"form": "学者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "在某个学术领域有专门研究和成就的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db53ca1e-ed36-4d8f-b5e7-254742013a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学者", "is_correct": true, "explanation": "正确：「学者」指在某个学术领域有专门研究和成就的人，与「研究历史的著名」相符。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手的工作是唱歌，与「研究历史」不相符。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员以表演为业，与「研究历史」的专业不符。"}, {"text": "建筑", "is_correct": false, "explanation": "搭配：「他是……建筑」不成立，「建筑」指物，不指人。"}], "explanations": {"学者": "正确：「学者」指在某个学术领域有专门研究和成就的人，与「研究历史的著名」相符。", "歌手": "语义：歌手的工作是唱歌，与「研究历史」不相符。", "演员": "语义：演员以表演为业，与「研究历史」的专业不符。", "建筑": "搭配：「他是……建筑」不成立，「建筑」指物，不指人。"}, "sentence_index": 0, "correct_answer": "学者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位学者给十个病人看病。", "explanation": "这里应该用〈医生〉。「学者」指学术上有研究成就的人，给病人看病的是医生。"}, {"text": "这位学者做了十道拿手菜。", "explanation": "这里应该用〈厨师〉。「学者」指学术研究者，做拿手菜的是厨师。"}, {"text": "这位学者在菜市场卖水果。", "explanation": "这里应该用〈小贩〉。「学者」指学术上有成就的人，在菜市场卖水果的是小贩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学者", "is_correct": true, "explanation": "正确：「国外的学者来大学做报告」，「学者」是在学术上有成就的人，与句意相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：「游客」一般不做学术报告，与「来大学做报告」的句意不合。"}, {"text": "司机", "is_correct": false, "explanation": "语义：「司机」的职责是驾驶，与「做报告」的语境不合。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，一般不会到大学做学术报告，与句意不合。"}], "explanations": {"学者": "正确：「国外的学者来大学做报告」，「学者」是在学术上有成就的人，与句意相符。", "游客": "语义：「游客」一般不做学术报告，与「来大学做报告」的句意不合。", "司机": "语义：「司机」的职责是驾驶，与「做报告」的语境不合。", "厨师": "语义：厨师的工作是做饭，一般不会到大学做学术报告，与句意不合。"}, "sentence_index": 6, "correct_answer": "学者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位学者每天在路口指挥交通。", "explanation": "这里应该用〈交警〉。「学者」指学术研究者，每天在路口指挥交通的是交警。"}, {"text": "这位学者在银行里数钱。", "explanation": "这里应该用〈出纳〉。「学者」指学术研究者，在银行数钱的是出纳。"}, {"text": "这位学者在机场帮游客拿行李。", "explanation": "这里应该用〈搬运工〉。「学者」指学术研究者，帮游客拿行李的是搬运工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只研究哲学的知名学者。", "corrected_sentence": "她是一位研究哲学的知名学者。", "error_description": "量词错误：「学者」指人，应用量词「位」，不能用「只」，应说「一位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座学者很受大家尊敬。", "corrected_sentence": "那位学者很受大家尊敬。", "error_description": "量词错误：「学者」指人，应用量词「位」，「座」用于山、楼、桥等大型物体，应说「那位学者」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '374f6472-e12b-48f8-86aa-f5f7bc7cc1bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89247, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "时髦", "is_correct": true, "explanation": "反义：“时髦”指款式新潮、流行，与“过时”相对。"}, {"text": "善良", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“善良”形容品性。"}, {"text": "热情", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“热情”形容待人的态度。"}, {"text": "聪明", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“聪明”形容人的智力。"}], "correct_answer": "时髦", "explanations": {"时髦": "反义：“时髦”指款式新潮、流行，与“过时”相对。", "善良": "与“过时”没有近义或反义关系。“善良”形容品性。", "热情": "与“过时”没有近义或反义关系。“热情”形容待人的态度。", "聪明": "与“过时”没有近义或反义关系。“聪明”形容人的智力。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89247, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "时尚", "is_correct": true, "explanation": "反义：“时尚”指潮流、时兴，与“过时”（款式不再时兴）相对。"}, {"text": "诚实", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“诚实”形容品行。"}, {"text": "勇敢", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“勇敢”形容人的胆量。"}, {"text": "认真", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“认真”形容做事的态度。"}], "correct_answer": "时尚", "explanations": {"时尚": "反义：“时尚”指潮流、时兴，与“过时”（款式不再时兴）相对。", "诚实": "与“过时”没有近义或反义关系。“诚实”形容品行。", "勇敢": "与“过时”没有近义或反义关系。“勇敢”形容人的胆量。", "认真": "与“过时”没有近义或反义关系。“认真”形容做事的态度。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89247, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "过时是以前很新，现在已经旧了、不时兴了。", "primary_collocate": null, "pronunciation": "guò shí", "ipa": "kuɔ˥˩ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这件衣服的样子过时了。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手机太旧，款式已经过时。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在谁还穿这么过时的裤子？", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种发型早就过时了。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时尚变得很快，今年的颜色明年就过时了。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买的包过时了，不想用。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的衣服不过时，很好看。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌太过时，年轻人不听。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过时的衣服可以送给别人。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼镜样子有点过时。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "過時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "样式、款式不再时兴，显得旧了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89247, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "过时", "is_correct": true, "explanation": "过时（guò shí）指款式、样子不再时兴，是本题的正确答案。"}, {"text": "果实", "is_correct": false, "explanation": "guǒ（第三声）与 guò（第四声）声调不同，意思是果实，与“过时”不同。"}, {"text": "过失", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是过错。"}, {"text": "国事", "is_correct": false, "explanation": "guó 与 guò、shì 与 shí 的声调都不同，意思是国家大事。"}, {"text": "过世", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是去世。"}], "explanations": {"过时": "过时（guò shí）指款式、样子不再时兴，是本题的正确答案。", "果实": "guǒ（第三声）与 guò（第四声）声调不同，意思是果实，与“过时”不同。", "过失": "shī（第一声）与 shí（第二声）声调不同，意思是过错。", "国事": "guó 与 guò、shì 与 shí 的声调都不同，意思是国家大事。", "过世": "shì（第四声）与 shí（第二声）声调不同，意思是去世。"}, "sentence_index": null, "correct_answer": "过时"}, "level_3": {"options": [{"text": "过时", "is_correct": true, "explanation": "正确。“过时”指衣服的样子已经不再时兴，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能用来说衣服的样子。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”指待人的态度，与衣服的样子无关。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”用来说人或动物的身形，不能用来说衣服的样子。"}], "explanations": {"过时": "正确。“过时”指衣服的样子已经不再时兴，符合句意。", "聪明": "搭配：“聪明”形容人的智力，不能用来说衣服的样子。", "热情": "语义：“热情”指待人的态度，与衣服的样子无关。", "胖": "体貌：“胖”用来说人或动物的身形，不能用来说衣服的样子。"}, "sentence_index": 0, "correct_answer": "过时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这罐酸奶已经过时了，不能再喝了。", "explanation": "这里应该用〈过期〉。食品超过保质期要说过期，不说过时；过时指款式等不再时兴。"}, {"text": "这套旧版操作规程已经过时，不再适用了。", "explanation": "这句说的是规程不再适用，是“过时”的另一个义项（不再适用）。此处要说的是款式以前很新、现在不时兴，所以这句用错了意思。"}, {"text": "这份评分标准已经过时，现在不用了。", "explanation": "这句说的是标准不再适用，是“过时”的另一个义项（不再适用）。此处要说的是款式不再时兴，所以这句用错了意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89247, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "过时", "is_correct": true, "explanation": "过时（guò shí）指款式、样子不再时兴，是本题的正确答案。"}, {"text": "国史", "is_correct": false, "explanation": "guó 与 guò、shǐ 与 shí 的声调都不同，意思是国家历史。"}, {"text": "古时", "is_correct": false, "explanation": "gǔ（第三声）与 guò（第四声）声调不同，意思是从前。"}, {"text": "古史", "is_correct": false, "explanation": "gǔ 与 guò 声调不同，shǐ 与 shí 声调也不同，意思是古代历史。"}], "explanations": {"过时": "过时（guò shí）指款式、样子不再时兴，是本题的正确答案。", "国史": "guó 与 guò、shǐ 与 shí 的声调都不同，意思是国家历史。", "古时": "gǔ（第三声）与 guò（第四声）声调不同，意思是从前。", "古史": "gǔ 与 guò 声调不同，shǐ 与 shí 声调也不同，意思是古代历史。"}, "sentence_index": null, "correct_answer": "过时"}, "level_3": {"options": [{"text": "过时", "is_correct": true, "explanation": "正确。“不过时”指衣服没有落伍、仍然时兴，符合句意。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的胆量，不能用来说衣服。"}, {"text": "小气", "is_correct": false, "explanation": "语义：“小气”指人不大方，与衣服是否好看无关。"}, {"text": "害羞", "is_correct": false, "explanation": "搭配：“害羞”形容人的情绪和神态，不能用来说衣服。"}], "explanations": {"过时": "正确。“不过时”指衣服没有落伍、仍然时兴，符合句意。", "勇敢": "搭配：“勇敢”形容人的胆量，不能用来说衣服。", "小气": "语义：“小气”指人不大方，与衣服是否好看无关。", "害羞": "搭配：“害羞”形容人的情绪和神态，不能用来说衣服。"}, "sentence_index": 6, "correct_answer": "过时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种旧的记账方法已经过时，财务上不能再用了。", "explanation": "这句说的是方法不再适用，是“过时”的另一个义项（不再适用）。此处要说的是眼镜样子不再时兴，所以这句用错了意思。"}, {"text": "这本旧词典的释义已经过时，需要更新了。", "explanation": "这句说的是释义不再符合现状，是“过时”的另一个义项（不再适用）。此处要说的是样子不再时兴，所以这句用错了意思。"}, {"text": "这个旧接口的协议已经过时，不能再对接了。", "explanation": "这句说的是协议不再适用，是“过时”的另一个义项（不再适用）。此处要说的是样子不再时兴，所以这句用错了意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件外套被过时了。", "corrected_sentence": "这件外套已经过时了。", "error_description": "“过时”是形容词，表示款式不再时兴，不能用“被”构成被动句。应把“被”改为“已经”，说“这件外套已经过时了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋的款式把过时了。", "corrected_sentence": "这双鞋的款式已经过时了。", "error_description": "“把”用错：“过时”是形容词，不能跟在“把”后面作谓语。“已经”是修饰“过时”的副词，应说“这双鞋的款式已经过时了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89248, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "先进", "is_correct": true, "explanation": "反义：“先进”指办法、技术等新而领先，与“过时”（已不再适用、落后）相对。"}, {"text": "大方", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“大方”形容待人不吝啬。"}, {"text": "诚实", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“诚实”形容品行。"}, {"text": "安静", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“安静”形容环境或状态。"}], "correct_answer": "先进", "explanations": {"先进": "反义：“先进”指办法、技术等新而领先，与“过时”（已不再适用、落后）相对。", "大方": "与“过时”没有近义或反义关系。“大方”形容待人不吝啬。", "诚实": "与“过时”没有近义或反义关系。“诚实”形容品行。", "安静": "与“过时”没有近义或反义关系。“安静”形容环境或状态。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89248, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "适用", "is_correct": true, "explanation": "反义：“适用”指合乎需要、能够使用，与“过时”（不再适用）相对。"}, {"text": "勤劳", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“勤劳”形容人的工作态度。"}, {"text": "善良", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“善良”形容品性。"}, {"text": "认真", "is_correct": false, "explanation": "与“过时”没有近义或反义关系。“认真”形容做事的态度。"}], "correct_answer": "适用", "explanations": {"适用": "反义：“适用”指合乎需要、能够使用，与“过时”（不再适用）相对。", "勤劳": "与“过时”没有近义或反义关系。“勤劳”形容人的工作态度。", "善良": "与“过时”没有近义或反义关系。“善良”形容品性。", "认真": "与“过时”没有近义或反义关系。“认真”形容做事的态度。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89248, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "过时是办法、规定、知识等已不再适用，不能照着用了。", "primary_collocate": null, "pronunciation": "guò shí", "ipa": "kuɔ˥˩ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这个老办法已经过时了。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容过时了，要买新的。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法太过时。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规定早就过时了，应该改一改。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑技术变化快，知识很容易过时。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件过时了，不能用。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过时的地图找不到新路。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的看法过时了，现在不是这样。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器已经过时，没有人再用。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个说法过时了。", "target_word": "过时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "過時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办法、规定、知识、技术等已不再适用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89248, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "过时", "is_correct": true, "explanation": "过时（guò shí）指办法、规定等不再适用，是本题的正确答案。"}, {"text": "过失", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是过错。"}, {"text": "国史", "is_correct": false, "explanation": "guó 与 guò、shǐ 与 shí 的声调都不同，意思是国家历史。"}, {"text": "古时", "is_correct": false, "explanation": "gǔ（第三声）与 guò（第四声）声调不同，意思是从前。"}], "explanations": {"过时": "过时（guò shí）指办法、规定等不再适用，是本题的正确答案。", "过失": "shī（第一声）与 shí（第二声）声调不同，意思是过错。", "国史": "guó 与 guò、shǐ 与 shí 的声调都不同，意思是国家历史。", "古时": "gǔ（第三声）与 guò（第四声）声调不同，意思是从前。"}, "sentence_index": null, "correct_answer": "过时"}, "level_3": {"options": [{"text": "过时", "is_correct": true, "explanation": "正确。“过时”指办法已经不再适用，符合句意。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的胆量，不能用来说办法。"}, {"text": "害羞", "is_correct": false, "explanation": "搭配：“害羞”形容人的情绪和神态，不能用来说办法。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”用来说人或动物的身形，不能用来说办法。"}], "explanations": {"过时": "正确。“过时”指办法已经不再适用，符合句意。", "勇敢": "搭配：“勇敢”形容人的胆量，不能用来说办法。", "害羞": "搭配：“害羞”形容人的情绪和神态，不能用来说办法。", "瘦": "体貌：“瘦”用来说人或动物的身形，不能用来说办法。"}, "sentence_index": 0, "correct_answer": "过时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款鞋的款式过时了，现在很少有人穿。", "explanation": "这句说的是款式不再时兴，属于“过时”的另一个义项（不再时兴），不是办法、规定等不再适用。"}, {"text": "这件外套的样式太过时了，年轻人都不穿了。", "explanation": "这句说的是样式不再时兴，属于另一个义项（不再时兴），与办法、规定不再适用的义项不同。"}, {"text": "她的发型太过时了，应该换个新样子。", "explanation": "这句说的是发型不再时兴，属于另一个义项（不再时兴），与办法、规定不再适用的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89248, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "过时", "is_correct": true, "explanation": "过时（guò shí）指办法、规定等不再适用，是本题的正确答案。"}, {"text": "果实", "is_correct": false, "explanation": "guǒ（第三声）与 guò（第四声）声调不同，意思是果实。"}, {"text": "过世", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是去世。"}, {"text": "古史", "is_correct": false, "explanation": "gǔ 与 guò 声调不同，shǐ 与 shí 声调也不同，意思是古代历史。"}, {"text": "国事", "is_correct": false, "explanation": "guó 与 guò、shì 与 shí 的声调都不同，意思是国家大事。"}], "explanations": {"过时": "过时（guò shí）指办法、规定等不再适用，是本题的正确答案。", "果实": "guǒ（第三声）与 guò（第四声）声调不同，意思是果实。", "过世": "shì（第四声）与 shí（第二声）声调不同，意思是去世。", "古史": "gǔ 与 guò 声调不同，shǐ 与 shí 声调也不同，意思是古代历史。", "国事": "guó 与 guò、shì 与 shí 的声调都不同，意思是国家大事。"}, "sentence_index": null, "correct_answer": "过时"}, "level_3": {"options": [{"text": "过时", "is_correct": true, "explanation": "正确。“过时的地图”指不再适用的地图，符合句意。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的待人态度，不能用来修饰地图。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”用来说人或动物的身形，不能用来说地图。"}, {"text": "认真", "is_correct": false, "explanation": "搭配：“认真”形容人做事的态度，不能用来修饰地图。"}], "explanations": {"过时": "正确。“过时的地图”指不再适用的地图，符合句意。", "热情": "语义：“热情”形容人的待人态度，不能用来修饰地图。", "胖": "体貌：“胖”用来说人或动物的身形，不能用来说地图。", "认真": "搭配：“认真”形容人做事的态度，不能用来修饰地图。"}, "sentence_index": 6, "correct_answer": "过时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顶帽子的样式过时了，年轻人都不戴了。", "explanation": "这句说的是样式不再时兴，属于“过时”的另一个义项（不再时兴），不是办法、规定等不再适用。"}, {"text": "这条裙子太过时，穿出去不好看了。", "explanation": "这句说的是款式不再时兴，属于另一个义项（不再时兴），与办法、知识不再适用的义项不同。"}, {"text": "那种发型早就过时了，现在没人留了。", "explanation": "这句说的是发型不再时兴，属于另一个义项（不再时兴），不是办法、规定等不再适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content =