INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套方法被过时了。", "corrected_sentence": "这套方法过时了。", "error_description": "“过时”是形容词，表示不再流行或不再适用，不能用“被”构成被动句。应去掉“被”，说“这套方法过时了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧规矩把过时了。", "corrected_sentence": "这些旧规矩已经过时了。", "error_description": "“把”用错：“过时”是形容词，不能跟在“把”后面作谓语。“已经”是修饰“过时”的副词，应说“这些旧规矩已经过时了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
