INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89251, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对过是路或房子的另一边。", "primary_collocate": null, "pronunciation": "duì guò", "ipa": "tweɪ˥˩ kuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "我家对过是一家小超市。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邮局就在马路对过。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他住在我家对过。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校对过有一个公园。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你站在路这边,他在路对过。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对过的房子比我们家的新。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们两家是邻居,他家就在我家对过。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对过那家饭馆的菜很好吃。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院对过有一个小花店。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你看一下,对过是不是有人在等你?", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "对过儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "路或房子的另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对过", "is_correct": true, "explanation": "对过指路或房子的另一边，“我家对过是一家小超市”说超市在我家的对面。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的房间，不能作为家门外超市的位置，与句意不合。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“花园”不能作“一家小超市”的方位，这里的位置要用表示方向的词。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“学校”与“我家”的位置关系不合，句子说的是家门口的小超市。"}], "explanations": {"对过": "对过指路或房子的另一边，“我家对过是一家小超市”说超市在我家的对面。", "厨房": "语义：“厨房”是做饭的房间，不能作为家门外超市的位置，与句意不合。", "花园": "搭配：“花园”不能作“一家小超市”的方位，这里的位置要用表示方向的词。", "学校": "语义：“学校”与“我家”的位置关系不合，句子说的是家门口的小超市。"}, "sentence_index": 0, "correct_answer": "对过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个方案的对过很明显。", "explanation": "这里应该用〈对比〉。对过只指路或房子的另一边，不能表示两者的差异对照。"}, {"text": "他是我的对过，我们准备结婚。", "explanation": "这里应该用〈对象〉。对过只指路或房子的另一边，不能指恋爱或结婚的对象。"}, {"text": "对过很强，我们要小心。", "explanation": "这里应该用〈对方〉。对过只指路或房子的另一边，不能指比赛中的另一方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对过", "is_correct": true, "explanation": "对过指路或房子的另一边，“他家就在我家对过”说他家与我家房子相对，位置很近。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是住处，不能说“就在我家冰箱”。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“教室”是学习的场所，不能作为“他家”的位置。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所不能作为居住的地点，句子说的是邻居的家。"}], "explanations": {"对过": "对过指路或房子的另一边，“他家就在我家对过”说他家与我家房子相对，位置很近。", "冰箱": "语义：冰箱是家电，不是住处，不能说“就在我家冰箱”。", "教室": "搭配：“教室”是学习的场所，不能作为“他家”的位置。", "厕所": "语义：厕所不能作为居住的地点，句子说的是邻居的家。"}, "sentence_index": 6, "correct_answer": "对过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个难题，他想出了一个好的对过。", "explanation": "这里应该用〈对策〉。对过只指路或房子的另一边，不能指解决问题的办法。"}, {"text": "这场比赛里，我的对过很厉害。", "explanation": "这里应该用〈对手〉。对过只指路或房子的另一边，不能指竞争中的对手。"}, {"text": "这两扇窗户是对过的。", "explanation": "这里应该用〈对称〉。对过只指位置相对，不能用来形容图形左右匀称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "超市很对过有一家药店。", "corrected_sentence": "超市对过有一家药店。", "error_description": "错误在“很”放在了“对过”前面。“对过”是方位词，不能被“很”修饰；正确说法是“超市对过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "银行很对过有一家面包店。", "corrected_sentence": "银行对过有一家面包店。", "error_description": "错误在“很”放在了“对过”前面。“对过”是方位名词，不能被“很”修饰；去掉“很”，应说“银行对过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
