INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对面,指隔着街道或空地相对的一边。", "primary_collocate": null, "pronunciation": "duì guò", "ipa": "tweɪ˥˩ kuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "车站在街道对过,不太远。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空地对过有一排新房子。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在街这边,朋友在街对过。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广场对过有很多卖花的人。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在街对过向我招手。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家门口的街对过新开了一家书店。", "target_word": "对过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交站就在街对过,走几步就到。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对过的小孩儿正在空地上玩儿。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家咖啡店在公园大门对过。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市对过的空地上停着很多车。", "target_word": "对过", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "对过儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "隔着街道或空地的对面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02276004-84a8-4d18-83b0-76a551fd581a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对过", "is_correct": true, "explanation": "对过指隔着街道或空地相对的一边，“车站在街道对过，不太远”说车站就在街对面。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是室内做饭的地方，不能是街道上的位置，与句意不合。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：街道上不会用黑板这类室内物品来标示车站的位置。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是摆设，不能作为车站的位置，句子不通。"}], "explanations": {"对过": "对过指隔着街道或空地相对的一边，“车站在街道对过，不太远”说车站就在街对面。", "厨房": "语义：厨房是室内做饭的地方，不能是街道上的位置，与句意不合。", "黑板": "搭配：街道上不会用黑板这类室内物品来标示车站的位置。", "花瓶": "语义：花瓶是摆设，不能作为车站的位置，句子不通。"}, "sentence_index": 0, "correct_answer": "对过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两种做法的对过很明显。", "explanation": "这里应该用〈对比〉。对过只指隔着街道或空地相对的一边，不能表示两者的差异对照。"}, {"text": "比赛刚开始，对过就先进了一个球。", "explanation": "这里应该用〈对方〉。对过只指隔着街道或空地相对的一边，不能指比赛中的另一方。"}, {"text": "这一局他是我的对过，我们谁也不让谁。", "explanation": "这里应该用〈对手〉。对过只指隔着街道或空地相对的一边，不能指比赛中的对手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对过", "is_correct": true, "explanation": "对过指隔着街道相对的一边，“公交站就在街对过，走几步就到”说公交站在街对面，很近。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是放书的家具，不能作为公交站的位置，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能作为公交站的方位，与句意不合。"}, {"text": "窗台", "is_correct": false, "explanation": "语义：窗台是窗户下的台面，公交站不会设在窗台，句子不通。"}], "explanations": {"对过": "对过指隔着街道相对的一边，“公交站就在街对过，走几步就到”说公交站在街对面，很近。", "书架": "语义：书架是放书的家具，不能作为公交站的位置，句子不通。", "冰箱": "语义：冰箱是家电，不能作为公交站的方位，与句意不合。", "窗台": "语义：窗台是窗户下的台面，公交站不会设在窗台，句子不通。"}, "sentence_index": 6, "correct_answer": "对过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题很难，大家想出了一个好对过。", "explanation": "这里应该用〈对策〉。对过只指隔着街道或空地相对的一边，不能指解决问题的办法。"}, {"text": "他是我的对过，我们准备结婚。", "explanation": "这里应该用〈对象〉。对过只指位置相对，不能指恋爱或结婚的对象。"}, {"text": "这段对过很精彩。", "explanation": "这里应该用〈对话〉。对过是位置名词，不能指两人之间的对话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街道很对过有一家书店。", "corrected_sentence": "街道对过有一家书店。", "error_description": "错误在“很”放在了“对过”前面。“对过”是方位词，不能被“很”修饰；正确说法是“街道对过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饭馆很对过有一个停车场。", "corrected_sentence": "饭馆对过有一个停车场。", "error_description": "错误在“很”放在了“对过”前面。“对过”是方位名词，不能被“很”修饰；去掉“很”，应说“饭馆对过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8feae2-f0e1-479e-9be0-1dfb83e67054') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89253, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "正：指人正派、心术端正，与“邪”（心思不正派）构成反义。"}, {"text": "慷慨", "is_correct": false, "explanation": "慷慨：形容大方、不吝啬，与“邪”没有反义关系。"}, {"text": "灿烂", "is_correct": false, "explanation": "灿烂：形容光彩耀眼，与“邪”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：指没有声音或不吵闹，与“邪”没有反义关系。"}], "correct_answer": "正", "explanations": {"正": "正：指人正派、心术端正，与“邪”（心思不正派）构成反义。", "慷慨": "慷慨：形容大方、不吝啬，与“邪”没有反义关系。", "灿烂": "灿烂：形容光彩耀眼，与“邪”没有反义关系。", "安静": "安静：指没有声音或不吵闹，与“邪”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89253, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "正：指人正派、心术端正，与“邪”（心思不正派）构成反义。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：指场面喧闹、人多，与“邪”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：指清晰、明白，与“邪”没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松：指不费力、不紧张，与“邪”没有反义关系。"}], "correct_answer": "正", "explanations": {"正": "正：指人正派、心术端正，与“邪”（心思不正派）构成反义。", "热闹": "热闹：指场面喧闹、人多，与“邪”没有反义关系。", "清楚": "清楚：指清晰、明白，与“邪”没有反义关系。", "轻松": "轻松：指不费力、不紧张，与“邪”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89253, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "人的心思、神态不正派，不是好的。", "primary_collocate": null, "pronunciation": "xié", "ipa": "ɕje˧˥", "syllable_count": 1, "sentences": [{"text": "这个人看起来有点邪，我不想靠近他。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得很邪，一看就不是好人。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人的眼神又冷又邪。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心眼太邪了，总想着骗别人。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的坏人总是一副很邪的样子。", "target_word": "邪", "complexity_tier": "T3", "furigana": "diàn yǐng lǐ de huài rén zǒng shì yí fù hěn xié de yàng zi", "sentence_source": "generated"}, {"text": "他的想法有点邪，我们别听他的。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个老板心很邪。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候妈妈说，心不能邪。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长得不丑，就是笑起来太邪。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的做法很邪，大家都不喜欢。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邪气", "label": "复合"}, {"form": "邪恶", "label": "复合"}], "register": "口语", "sense_fingerprint": "人的心思、神态不正派，不是好的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89253, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "邪", "is_correct": true, "explanation": "邪（xié）：不正派、不是好的，指人的心思或神态不正。"}, {"text": "写", "is_correct": false, "explanation": "xiě（第三声）与 xié（第二声）声调不同，意思是写字。"}, {"text": "谢", "is_correct": false, "explanation": "xiè（第四声）与 xié（第二声）声调不同，意思是感谢。"}, {"text": "些", "is_correct": false, "explanation": "xiē（第一声）与 xié（第二声）声调不同，意思是一些。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 xié 声母不同（j 与 x），意思是节日。"}], "explanations": {"邪": "邪（xié）：不正派、不是好的，指人的心思或神态不正。", "写": "xiě（第三声）与 xié（第二声）声调不同，意思是写字。", "谢": "xiè（第四声）与 xié（第二声）声调不同，意思是感谢。", "些": "xiē（第一声）与 xié（第二声）声调不同，意思是一些。", "节": "jié（第二声）与 xié 声母不同（j 与 x），意思是节日。"}, "sentence_index": null, "correct_answer": "邪"}, "level_3": {"options": [{"text": "邪", "is_correct": true, "explanation": "邪：指人的神态或心思不正派，与“看起来有点”搭配，给人不好的印象。"}, {"text": "友善", "is_correct": false, "explanation": "语义：“友善”表示和气亲切，与后半句“我不想靠近他”矛盾。"}, {"text": "可亲", "is_correct": false, "explanation": "语义：“可亲”指容易亲近，和“我不想靠近他”的意思正相反。"}, {"text": "慈祥", "is_correct": false, "explanation": "语域：“慈祥”偏书面，多用来形容长辈的和蔼，且与“我不想靠近他”矛盾。"}], "explanations": {"邪": "邪：指人的神态或心思不正派，与“看起来有点”搭配，给人不好的印象。", "友善": "语义：“友善”表示和气亲切，与后半句“我不想靠近他”矛盾。", "可亲": "语义：“可亲”指容易亲近，和“我不想靠近他”的意思正相反。", "慈祥": "语域：“慈祥”偏书面，多用来形容长辈的和蔼，且与“我不想靠近他”矛盾。"}, "sentence_index": 0, "correct_answer": "邪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他感冒了，嗓子很邪，说不出话。", "explanation": "这里应该用〈沙哑〉。“邪”不形容嗓音，嗓子哑了要说“沙哑”。"}, {"text": "这碗汤很邪，烫得没法喝。", "explanation": "这里应该用〈烫〉。“邪”不形容温度，汤太热要说“烫”。"}, {"text": "这件毛衣很邪，穿着特别舒服。", "explanation": "这里应该用〈暖和〉。“邪”是贬义，不形容衣服好穿、保暖，要说“暖和”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89253, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "邪", "is_correct": true, "explanation": "邪（xié）：不正派、不是好的，指人心术不正。"}, {"text": "学", "is_correct": false, "explanation": "xué（第二声）与 xié 韵母不同（ue 与 ie），意思是学习。"}, {"text": "茄", "is_correct": false, "explanation": "qié（第二声）与 xié 声母不同（q 与 x），意思是茄子。"}, {"text": "歇", "is_correct": false, "explanation": "xiē（第一声）与 xié（第二声）声调不同，意思是休息。"}], "explanations": {"邪": "邪（xié）：不正派、不是好的，指人心术不正。", "学": "xué（第二声）与 xié 韵母不同（ue 与 ie），意思是学习。", "茄": "qié（第二声）与 xié 声母不同（q 与 x），意思是茄子。", "歇": "xiē（第一声）与 xié（第二声）声调不同，意思是休息。"}, "sentence_index": null, "correct_answer": "邪"}, "level_3": {"options": [{"text": "邪", "is_correct": true, "explanation": "邪：指心术不正派，用在“心很……”后面，表示人心不善。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”只形容身体，不能用来形容一个人的心。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”只形容身体的胖瘦，不能说心很瘦。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”形容高度，不能用来修饰“心”。"}], "explanations": {"邪": "邪：指心术不正派，用在“心很……”后面，表示人心不善。", "胖": "体貌：“胖”只形容身体，不能用来形容一个人的心。", "瘦": "体貌：“瘦”只形容身体的胖瘦，不能说心很瘦。", "矮": "搭配：“矮”形容高度，不能用来修饰“心”。"}, "sentence_index": 6, "correct_answer": "邪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水很邪，太凉了，我不想喝。", "explanation": "这里应该用〈凉〉。“邪”不形容温度，水太凉要说“凉”。"}, {"text": "这杯茶很邪，太苦了，我喝不下。", "explanation": "这里应该用〈苦〉。“邪”不形容味道，茶太苦要说“苦”。"}, {"text": "这件衣服很邪，穿着太紧了。", "explanation": "这里应该用〈紧〉。“邪”不形容衣服松紧，衣服太小要说“紧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提的主意邪得，大家都不敢听。", "corrected_sentence": "他提的主意邪得很，大家都不敢听。", "error_description": "补语缺失：错误形式为“邪得”，正确形式为“邪得很”。“得”后要接程度补语“很”，只说“邪得”句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个很邪人，大家都不敢跟他来往。", "corrected_sentence": "他是一个很邪的人，大家都不敢跟他来往。", "error_description": "错误：“很邪”后面缺少“的”。正确：“很邪的人”，形容词修饰名词时要加“的”，少了“的”修饰关系不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
