INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89254, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情或现象怪异，让人说不清为什么。", "primary_collocate": null, "pronunciation": "xié", "ipa": "ɕje˧˥", "syllable_count": 1, "sentences": [{"text": "这事真邪，我刚想起他，他就来电话了。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天真邪，手机怎么都打不开。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子晚上很邪，常听到奇怪的声音。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说来也邪，我一回家，雨就停了。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事有点邪，谁也说不清为什么。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫半夜叫个不停，真邪。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路晚上很邪，没有人敢走。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里的灯无缘无故地亮了，真邪。", "target_word": "邪", "complexity_tier": "T3", "furigana": "wū lǐ de dēng wú yuán wú gù de liàng le zhēn xié", "sentence_source": "generated"}, {"text": "你说邪不邪，我买什么都会坏。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天气太邪了，早上下雪，中午就热了。", "target_word": "邪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邪气", "label": "复合"}, {"form": "邪恶", "label": "复合"}], "register": "口语", "sense_fingerprint": "事情或现象怪异，让人觉得说不清", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89254, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "邪", "is_correct": true, "explanation": "邪（xié）：事情或现象怪异，让人说不清为什么。"}, {"text": "写", "is_correct": false, "explanation": "xiě（第三声）与 xié（第二声）声调不同，意思是写字。"}, {"text": "谢", "is_correct": false, "explanation": "xiè（第四声）与 xié（第二声）声调不同，意思是感谢。"}, {"text": "些", "is_correct": false, "explanation": "xiē（第一声）与 xié（第二声）声调不同，意思是一些。"}, {"text": "茄", "is_correct": false, "explanation": "qié（第二声）与 xié 声母不同（q 与 x），意思是茄子。"}], "explanations": {"邪": "邪（xié）：事情或现象怪异，让人说不清为什么。", "写": "xiě（第三声）与 xié（第二声）声调不同，意思是写字。", "谢": "xiè（第四声）与 xié（第二声）声调不同，意思是感谢。", "些": "xiē（第一声）与 xié（第二声）声调不同，意思是一些。", "茄": "qié（第二声）与 xié 声母不同（q 与 x），意思是茄子。"}, "sentence_index": null, "correct_answer": "邪"}, "level_3": {"options": [{"text": "邪", "is_correct": true, "explanation": "邪：指事情怪异、说不清，与后半句的巧合相符。"}, {"text": "精确", "is_correct": false, "explanation": "搭配：“精确”多形容计算、数据，不用来形容一件怪事。"}, {"text": "温馨", "is_correct": false, "explanation": "语义：“温馨”表示温暖的感觉，与这种离奇的巧合不符。"}, {"text": "壮观", "is_correct": false, "explanation": "语义：“壮观”形容景象宏伟，不能用来形容一件巧合的事。"}], "explanations": {"邪": "邪：指事情怪异、说不清，与后半句的巧合相符。", "精确": "搭配：“精确”多形容计算、数据，不用来形容一件怪事。", "温馨": "语义：“温馨”表示温暖的感觉，与这种离奇的巧合不符。", "壮观": "语义：“壮观”形容景象宏伟，不能用来形容一件巧合的事。"}, "sentence_index": 0, "correct_answer": "邪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他嗓子很邪，说话声音哑得听不清。", "explanation": "这里应该用〈沙哑〉。“邪”不形容嗓音，嗓子哑了要说“沙哑”。"}, {"text": "这块饼干很邪，咬不动。", "explanation": "这里应该用〈硬〉。“邪”不形容食物的软硬，饼干太硬要说“硬”。"}, {"text": "这碗汤很邪，太烫了，喝不了。", "explanation": "这里应该用〈烫〉。“邪”不形容温度，汤太热要说“烫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89254, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "邪", "is_correct": true, "explanation": "邪（xié）：事情或现象怪异，让人说不清为什么。"}, {"text": "学", "is_correct": false, "explanation": "xué（第二声）与 xié 韵母不同（ue 与 ie），意思是学习。"}, {"text": "歇", "is_correct": false, "explanation": "xiē（第一声）与 xié（第二声）声调不同，意思是休息。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 xié 声母不同（j 与 x），意思是节日。"}], "explanations": {"邪": "邪（xié）：事情或现象怪异，让人说不清为什么。", "学": "xué（第二声）与 xié 韵母不同（ue 与 ie），意思是学习。", "歇": "xiē（第一声）与 xié（第二声）声调不同，意思是休息。", "节": "jié（第二声）与 xié 声母不同（j 与 x），意思是节日。"}, "sentence_index": null, "correct_answer": "邪"}, "level_3": {"options": [{"text": "邪", "is_correct": true, "explanation": "邪：指地方或现象怪异、让人害怕，与“没有人敢走”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”说明场面喧闹，与“没有人敢走”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或建筑的体形，不用来形容一条路。"}, {"text": "安全", "is_correct": false, "explanation": "语义：“安全”表示没有危险，与“没有人敢走”矛盾。"}], "explanations": {"邪": "邪：指地方或现象怪异、让人害怕，与“没有人敢走”相符。", "热闹": "语义：“热闹”说明场面喧闹，与“没有人敢走”矛盾。", "高大": "搭配：“高大”形容人或建筑的体形，不用来形容一条路。", "安全": "语义：“安全”表示没有危险，与“没有人敢走”矛盾。"}, "sentence_index": 6, "correct_answer": "邪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张床很邪，躺着太硬了。", "explanation": "这里应该用〈硬〉。“邪”不形容软硬，床板太硬要说“硬”。"}, {"text": "这双鞋很邪，太小了，穿不进去。", "explanation": "这里应该用〈小〉。“邪”不形容尺寸，鞋子不合脚要说“小”。"}, {"text": "这碗粥很邪，太甜了，我喝不下。", "explanation": "这里应该用〈甜〉。“邪”不形容味道，粥太甜要说“甜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件怪事邪得，我到现在也想不明白。", "corrected_sentence": "这件怪事邪得很，我到现在也想不明白。", "error_description": "补语缺失：错误形式为“邪得”，正确形式为“邪得很”。“得”后要接程度补语“很”，只说“邪得”句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋后有一口很邪井，附近的人都不敢靠近。", "corrected_sentence": "屋后有一口很邪的井，附近的人都不敢靠近。", "error_description": "错误：“很邪”后面缺少“的”。正确：“很邪的井”，形容词修饰名词时要加“的”，少了“的”修饰关系不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
