INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "体育或其他比赛中设置的具体竞赛类别。", "primary_collocate": null, "pronunciation": "bǐ sài xiàng mù", "ipa": "pi˨˩˦ sai˥˩ ɕjaŋ˥˩ mu˥˩", "syllable_count": 4, "sentences": [{"text": "游泳是这次运动会的比赛项目之一。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奥运会新增了几个比赛项目。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她报名参加了两个比赛项目。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田径比赛项目包括跑步和跳远。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛项目要求运动员跑得快。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乒乓球是中国最强的比赛项目。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校取消了一个比赛项目。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男子和女子的比赛项目不一样。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的比赛项目是一百米跑。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬奥会有十几个比赛项目。", "target_word": "比赛项目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "比賽項目", "label": "繁体"}], "register": "中性", "sense_fingerprint": "运动会等正式赛事中设置的具体竞赛类别，如游泳、跳远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裁判", "is_correct": false, "explanation": "语义：「裁判」是执裁比赛的人，游泳不是裁判，「之一」后应接同类事物。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：「运动员」指人，「游泳」是运动项目，二者不是同类。"}, {"text": "奖牌", "is_correct": false, "explanation": "搭配：「是……之一」要接同类事物，「奖牌」不能与「游泳」并列为同类。"}, {"text": "比赛项目", "is_correct": true, "explanation": "正确：「比赛项目」指运动会上设置的竞赛类别，游泳是其中之一，符合句意。"}], "explanations": {"裁判": "语义：「裁判」是执裁比赛的人，游泳不是裁判，「之一」后应接同类事物。", "运动员": "语义：「运动员」指人，「游泳」是运动项目，二者不是同类。", "奖牌": "搭配：「是……之一」要接同类事物，「奖牌」不能与「游泳」并列为同类。", "比赛项目": "正确：「比赛项目」指运动会上设置的竞赛类别，游泳是其中之一，符合句意。"}, "sentence_index": 0, "correct_answer": "比赛项目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我买了一件红色的比赛项目。", "explanation": "这里应该用〈衣服〉。比赛项目是赛事中的竞赛类别，不能买来穿，买来穿的是衣服。"}, {"text": "这台机器上有五个比赛项目。", "explanation": "这里应该用〈零件〉。比赛项目指比赛中的竞赛类别，机器上的是零件，不能说比赛项目。"}, {"text": "他是学校的游泳比赛项目。", "explanation": "这里应该用〈运动员〉。比赛项目是竞赛类别，指人要用运动员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "配价：「取消」的宾语是活动、规定等，不能是「学生」这样的人。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：「取消」用于活动或安排，「蛋糕」不是可以被取消的安排。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：「取消」用于活动或规定，学校不会取消一个厨房这样的场所。"}, {"text": "比赛项目", "is_correct": true, "explanation": "正确：「比赛项目」是学校可以安排或取消的竞赛类别，符合句意。"}], "explanations": {"学生": "配价：「取消」的宾语是活动、规定等，不能是「学生」这样的人。", "蛋糕": "语义：「取消」用于活动或安排，「蛋糕」不是可以被取消的安排。", "厨房": "语义：「取消」用于活动或规定，学校不会取消一个厨房这样的场所。", "比赛项目": "正确：「比赛项目」是学校可以安排或取消的竞赛类别，符合句意。"}, "sentence_index": 6, "correct_answer": "比赛项目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中秋节是一个重要的比赛项目。", "explanation": "这里应该用〈节日〉。中秋节是传统节日，不是竞赛类别。"}, {"text": "冬奥会新建了十几座比赛项目。", "explanation": "这里应该用〈场馆〉。比赛项目是竞赛类别，不能新建，新建的是比赛场馆。"}, {"text": "这次比赛他吃掉了一个好比赛项目。", "explanation": "这里应该用〈食物〉。比赛项目是竞赛类别，不能吃，吃的是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次运动会增设了两副比赛项目。", "corrected_sentence": "这次运动会增设了两个比赛项目。", "error_description": "「两副比赛项目」错误：「副」用于成对的物品，比赛项目应用量词「个」，应为「两个比赛项目」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校决定增加一根比赛项目。", "corrected_sentence": "学校决定增加一个比赛项目。", "error_description": "「一根比赛项目」错误：「根」用于细长条状物，比赛项目应用量词「个」，应为「一个比赛项目」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从那个时候开始，一直到后来。", "primary_collocate": null, "pronunciation": "cóng cǐ", "ipa": "tsʰʊŋ˧˥ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他搬到了北京，从此很少回家。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次生病以后，她从此不再吃肉。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明学会了游泳，从此天天去河边。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在车站见了面，从此成了好朋友。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机丢了，从此再也不乱放东西。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学毕业去了上海，从此一直住在那里。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她得了奖，从此更努力地学习。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评了他一次，从此他上课再也不说话了。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一只小狗，从此每天都很开心。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天以后，两个人从此没有再见面。", "target_word": "从此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從此", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从过去某个时间点起一直持续到后来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e7e323-496a-4e04-9d9e-25a70cdf1aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从此", "is_correct": true, "explanation": "正确。“从此”表示搬家之后起持续下来的情况，与“很少回家”相合。"}, {"text": "经常", "is_correct": false, "explanation": "语义：“经常”指反复发生，与“很少回家”矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”强调瞬间发生，与“很少回家”这种长期状态不合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰程度，与“很少”的程度叠加，句子不通。"}], "explanations": {"从此": "正确。“从此”表示搬家之后起持续下来的情况，与“很少回家”相合。", "经常": "语义：“经常”指反复发生，与“很少回家”矛盾。", "立刻": "语义：“立刻”强调瞬间发生，与“很少回家”这种长期状态不合。", "非常": "搭配：“非常”修饰程度，与“很少”的程度叠加，句子不通。"}, "sentence_index": 0, "correct_answer": "从此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天去了超市，从此买了一瓶水。", "explanation": "“从此”指从某时起持续下去的变化，用于一次性的动作不自然；这里应该用〈然后〉表示动作的先后。"}, {"text": "明天我们从此要去北京出差。", "explanation": "“从此”需承接已发生的事件，与“明天”这一未来时间冲突；应去掉“从此”。"}, {"text": "从此到学校只要五分钟。", "explanation": "“从此”只指时间，不指地点，不能表示“从这里”，这里应该用〈从这里〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从此", "is_correct": true, "explanation": "正确。“从此”表示得奖之后起一直更努力，与前句相合。"}, {"text": "随便", "is_correct": false, "explanation": "搭配：“随便”不能修饰“更努力地学习”，句子不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“更努力地学习”的持续状态矛盾。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”表示长期如此，与“得了奖”引出的变化不合。"}], "explanations": {"从此": "正确。“从此”表示得奖之后起一直更努力，与前句相合。", "随便": "搭配：“随便”不能修饰“更努力地学习”，句子不通。", "偶尔": "语义：“偶尔”表示不常发生，与“更努力地学习”的持续状态矛盾。", "一向": "语义：“一向”表示长期如此，与“得了奖”引出的变化不合。"}, "sentence_index": 6, "correct_answer": "从此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行很累，从此我想睡觉。", "explanation": "“从此”只表示时间上的延续，不表示因果，这里应该用〈因此〉。"}, {"text": "这本书很厚，我从此读了三天。", "explanation": "“从此”指从那时起持续下去的变化，不表示时间的长短；这里应该用〈整整〉来强调时间长。"}, {"text": "他洗完澡，从此穿上了衣服。", "explanation": "“从此”表示时间的延续，不表示动作的先后顺序；这里应该用〈接着〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年结了婚，从此的再也没回过老家。", "corrected_sentence": "他去年结了婚，从此再也没回过老家。", "error_description": "错误：副词“从此”后多加了“的”，写成“从此的再也”。副词不带“的”，应去掉，说“从此再也没回过老家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下个月以后，他从此不再迟到了。", "corrected_sentence": "那次比赛以后，他从此不再迟到了。", "error_description": "错误：“从此”要承接已经发生的事，不能接未来时间“下个月”。应改为过去的事件，如“那次比赛以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
