INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89261, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乡人是住在同一个乡下地方的人。", "primary_collocate": null, "pronunciation": "xiāng rén", "ipa": "ɕiaŋ˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "老王是我的乡人，我们从小在同一个村子长大。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他是乡人，小时候住在同一个村子。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个乡人一起坐火车去南方打工。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的乡人每天傍晚都在老槐树下乘凉。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是帮助乡人，大家都很喜欢他。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子里的乡人都姓王。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乡人们世世代代住在河边。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的乡人一到冬天就聚在一起烤火聊天。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请乡人吃了一顿饭。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张的乡人一辈子都住在这个村子里。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "鄉人", "label": "繁体"}], "register": "书面", "sense_fingerprint": "乡人：住在同一个乡下地方的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乡人", "is_correct": true, "explanation": "〈乡人〉指住在同一个乡下地方的人，与「从小在同一个村子长大」相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：〈游客〉是外来参观的人，不会和我「从小在同一个村子长大」。"}, {"text": "石头", "is_correct": false, "explanation": "语义：〈石头〉不是人，不能和我一起「从小长大」。"}, {"text": "大树", "is_correct": false, "explanation": "语义：〈大树〉不是人，不能说「老王是我的大树」并一起长大。"}], "explanations": {"乡人": "〈乡人〉指住在同一个乡下地方的人，与「从小在同一个村子长大」相符。", "游客": "语义：〈游客〉是外来参观的人，不会和我「从小在同一个村子长大」。", "石头": "语义：〈石头〉不是人，不能和我一起「从小长大」。", "大树": "语义：〈大树〉不是人，不能说「老王是我的大树」并一起长大。"}, "sentence_index": 0, "correct_answer": "乡人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在外地多年，心里一直装着浓浓的乡人。", "explanation": "这里应该用〈乡愁〉。〈乡人〉指人，不能表示思念家乡的感情；〈乡愁〉才是这种感情。"}, {"text": "我小时候在乡人住了十年，后来搬到了城里。", "explanation": "这里应该用〈家乡〉。〈乡人〉指人，不能指一个住了十年的地方。"}, {"text": "这个乡人有一百多户人家，村口有一棵大树。", "explanation": "这里应该用〈村子〉。〈乡人〉指人，不能指有一百多户人家的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乡人", "is_correct": true, "explanation": "〈乡人〉指住在同一个乡下地方的人，这里说他们世世代代住在河边。"}, {"text": "飞机", "is_correct": false, "explanation": "搭配：〈飞机〉不能“住在河边”，〈住〉的对象应该是人。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：〈窗户〉不是人，不能「世世代代住在河边」。"}, {"text": "游客", "is_correct": false, "explanation": "语义：〈游客〉只是来参观的人，不会世世代代住在河边。"}], "explanations": {"乡人": "〈乡人〉指住在同一个乡下地方的人，这里说他们世世代代住在河边。", "飞机": "搭配：〈飞机〉不能“住在河边”，〈住〉的对象应该是人。", "窗户": "搭配：〈窗户〉不是人，不能「世世代代住在河边」。", "游客": "语义：〈游客〉只是来参观的人，不会世世代代住在河边。"}, "sentence_index": 6, "correct_answer": "乡人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老张家养的那只猫是他的乡人，每天陪他吃饭。", "explanation": "这里应该用〈宠物〉。〈乡人〉指住在同一个乡下地方的人，只用于人，不能用来称呼猫。"}, {"text": "老张在城里长大，大家都说他是个典型的乡人。", "explanation": "这里应该用〈城里人〉。〈乡人〉指住在乡下的人，在城里长大的人不符合这个意思。"}, {"text": "他一开口就带着浓浓的乡人，老张一听就知道是老家的人。", "explanation": "这里应该用〈乡音〉。〈乡人〉指住在同一个乡下地方的人，不指说话的口音；〈乡音〉才是家乡的口音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们几只乡人一起去城里赶集。", "corrected_sentence": "他们几个乡人一起去城里赶集。", "error_description": "量词错误：〈乡人〉指人，应用量词〈个〉；〈只〉多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个乡人们在河边聊天。", "corrected_sentence": "几个乡人在河边聊天。", "error_description": "词缀错误：〈们〉表示复数，不能与数量词〈几个〉同用，应说“几个乡人”，不能说“几个乡人们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
