INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89262, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同乡的人；乡下的人。", "primary_collocate": null, "pronunciation": "xiāng rén", "ipa": "ɕiaŋ˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "在外地遇到乡人，他特别高兴。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位乡人和我是同一个村子的。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乡人们一起帮他盖了新房子。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在城里碰到一个乡人，两人聊了很久。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，乡人都回村里看望老人。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乡人说话很直，也很热情。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个乡人背着菜，走了很远的路来城里卖。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乡人进城办事，常常找他帮忙。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开家乡二十年，还记得每一位乡人。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里人对乡人很客气，从不看不起他们。", "target_word": "乡人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "鄉人", "label": "繁体"}], "register": "书面", "sense_fingerprint": "乡人：同乡的人，或乡下的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乡人", "is_correct": true, "explanation": "〈乡人〉指同乡的人。在外地遇到同乡，自然会特别高兴。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：遇到〈敌人〉不会“特别高兴”，与句中的心情相矛盾。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：遇到〈小偷〉不会高兴，与“特别高兴”相矛盾。"}, {"text": "麻烦", "is_correct": false, "explanation": "语义：在外地遇到〈麻烦〉不会「特别高兴」，与句中的心情相矛盾。"}], "explanations": {"乡人": "〈乡人〉指同乡的人。在外地遇到同乡，自然会特别高兴。", "敌人": "语义：遇到〈敌人〉不会“特别高兴”，与句中的心情相矛盾。", "小偷": "语义：遇到〈小偷〉不会高兴，与“特别高兴”相矛盾。", "麻烦": "语义：在外地遇到〈麻烦〉不会「特别高兴」，与句中的心情相矛盾。"}, "sentence_index": 0, "correct_answer": "乡人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在外地多年，心里总是装着浓浓的乡人。", "explanation": "这里应该用〈乡愁〉。〈乡人〉指人，不能表示思念家乡的感情；〈乡愁〉才是这种感情。"}, {"text": "我小时候住在乡人，后来搬到了城里。", "explanation": "这里应该用〈家乡〉。〈乡人〉指人，不能指住的地方；〈家乡〉才是出生长大的地方。"}, {"text": "周末我们常常回乡人，看看老房子。", "explanation": "这里应该用〈乡下〉。〈乡人〉是人，不能作为要回去的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乡人", "is_correct": true, "explanation": "〈乡人〉指乡下的人，这里是背着菜进城卖的乡下人。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：〈皇帝〉不会背着菜走远路进城去卖，与句意相矛盾。"}, {"text": "飞机", "is_correct": false, "explanation": "搭配：〈飞机〉不能“背着菜”，这个动作只能由人来完成。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：〈老虎〉是动物，不会背着菜进城去卖。"}], "explanations": {"乡人": "〈乡人〉指乡下的人，这里是背着菜进城卖的乡下人。", "皇帝": "语义：〈皇帝〉不会背着菜走远路进城去卖，与句意相矛盾。", "飞机": "搭配：〈飞机〉不能“背着菜”，这个动作只能由人来完成。", "老虎": "语义：〈老虎〉是动物，不会背着菜进城去卖。"}, "sentence_index": 6, "correct_answer": "乡人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的狗是我的乡人，每天陪我去田里。", "explanation": "动物：〈乡人〉只指人，不能用来称呼狗。这里应该说〈伙伴〉之类的词。"}, {"text": "他从小在城里长大，是个典型的乡人。", "explanation": "这里应该用〈城里人〉。〈乡人〉指乡下的人或同乡的人，从小在城里长大的人不符合这个意思。"}, {"text": "他一开口就带着浓浓的乡人，大家一听就知道他是老家的人。", "explanation": "这里应该用〈乡音〉。〈乡人〉指人，不能指说话的口音；〈乡音〉才是家乡的口音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里来了一只乡人，大家都很热情。", "corrected_sentence": "村里来了一个乡人，大家都很热情。", "error_description": "量词错误：〈乡人〉指人，应用量词〈个〉；〈只〉多用于动物，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一群乡人们在车站等车。", "corrected_sentence": "一群乡人在车站等车。", "error_description": "词缀错误：〈们〉表示复数，不能与数量词〈一群〉同用，应说“一群乡人”，不能说“一群乡人们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
