INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "积极参与并推动社会、政治或公益活动的人。", "primary_collocate": null, "pronunciation": "huó dòng rén shì", "ipa": "xuo˧˥ tʊŋ˥˩ ʐən˧˥ ʂɨ˥˩", "syllable_count": 4, "sentences": [{"text": "她是一位保护环境的活动人士。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位活动人士为女性的权利努力了很多年。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动人士在广场上要求政府改变政策。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多活动人士参加了这次游行。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是有名的人权活动人士。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动人士希望更多人关心动物保护。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位活动人士每年都组织公益活动。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位活动人士给市长写了一封信。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做了二十年的活动人士，一直为穷人说话。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动人士把大家的意见交给了政府。", "target_word": "活动人士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "人权活动人士", "label": "复合"}], "register": "中性", "sense_fingerprint": "积极参与、推动社会政治或公益活动的人，公共议题义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活动人士", "is_correct": true, "explanation": "正确：她是一位保护环境的活动人士，符合句意。"}, {"text": "屠夫", "is_correct": false, "explanation": "语义：屠夫以杀牲为业，与“保护环境”相反。"}, {"text": "杀手", "is_correct": false, "explanation": "语义：杀手的职业与“保护环境”相矛盾。"}, {"text": "保安", "is_correct": false, "explanation": "搭配：保安负责看守安全，不说“保护环境的保安”。"}], "explanations": {"活动人士": "正确：她是一位保护环境的活动人士，符合句意。", "屠夫": "语义：屠夫以杀牲为业，与“保护环境”相反。", "杀手": "语义：杀手的职业与“保护环境”相矛盾。", "保安": "搭配：保安负责看守安全，不说“保护环境的保安”。"}, "sentence_index": 0, "correct_answer": "活动人士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位活动人士在树上筑了一个巢。", "explanation": "这里应该用〈小鸟〉。活动人士是人，不会在树上筑巢，筑巢的是小鸟。"}, {"text": "这台活动人士每小时能生产一百个杯子。", "explanation": "这里应该用〈机器〉。活动人士是推动社会公益的人，不能用「台」，也不会生产杯子，那是机器。"}, {"text": "妈妈把活动人士放进冰箱里保鲜。", "explanation": "这里应该用〈水果〉。活动人士是人，不能放进冰箱保鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活动人士", "is_correct": true, "explanation": "正确：这位活动人士每年都组织公益活动，符合句意。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷是偷东西的人，不会组织公益活动。"}, {"text": "赌徒", "is_correct": false, "explanation": "语义：赌徒沉迷赌博，与“组织公益活动”不符。"}, {"text": "囚犯", "is_correct": false, "explanation": "语义：「囚犯」正在服刑，不会组织公益活动。"}], "explanations": {"活动人士": "正确：这位活动人士每年都组织公益活动，符合句意。", "小偷": "语义：小偷是偷东西的人，不会组织公益活动。", "赌徒": "语义：赌徒沉迷赌博，与“组织公益活动”不符。", "囚犯": "语义：「囚犯」正在服刑，不会组织公益活动。"}, "sentence_index": 6, "correct_answer": "活动人士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "活动人士被我们放进锅里煮熟了。", "explanation": "这里应该用〈饺子〉。活动人士是人，不是食物。"}, {"text": "这件活动人士我穿了三年，有点旧了。", "explanation": "这里应该用〈衣服〉。活动人士是推动社会公益的人，不能穿。"}, {"text": "那只活动人士在草地上吃草。", "explanation": "这里应该用〈羊〉。活动人士是人，吃草的是羊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只保护环境的活动人士每周都去河边。", "corrected_sentence": "这位保护环境的活动人士每周都去河边。", "error_description": "量词错误：“只”多用于动物，指人应用“位”。正确形式是“这位保护环境的活动人士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位活动人士把大家的意见交了给政府。", "corrected_sentence": "几位活动人士把大家的意见交给了政府。", "error_description": "动态助词位置错误：“交给”是动补结构，“了”应放在“给”后面，应说“交给了政府”，不能说“交了给政府”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
