INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种社交网络服务，用户可以发布简短的文字、图片，供别人关注和转发。", "primary_collocate": null, "pronunciation": "wēi bó", "ipa": "weɪ̯˥ pwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "微博是一种社交网络，大家可以关注别人。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在微博上有一百万粉丝。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位明星的微博每天都有人转发。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我关注了他的微博。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多公司用微博介绍新产品。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微博上的消息传得很快。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她注册了一个新的微博账号。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在微博上转发这条新闻。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在微博上只能发很短的文字。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的微博每天有几千人看。", "target_word": "微博", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "微博账号", "label": "复合"}], "register": "口语", "sense_fingerprint": "社交网络服务，发布简短内容供关注转发", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de4d7edf-4df1-41f1-b1d8-d079da48dec8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微博", "is_correct": true, "explanation": "正确：微博就是一种社交网络，大家可以在上面关注别人。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“电视”不是社交网络的说法，电视没有“关注别人”的功能。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行提供金融服务，与“关注别人”无关。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不是社交网络。"}], "explanations": {"微博": "正确：微博就是一种社交网络，大家可以在上面关注别人。", "电视": "搭配：“电视”不是社交网络的说法，电视没有“关注别人”的功能。", "银行": "语义：银行提供金融服务，与“关注别人”无关。", "汽车": "语义：汽车是交通工具，不是社交网络。"}, "sentence_index": 0, "correct_answer": "微博"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个微博每个月出版一次。", "explanation": "这里应该用〈杂志〉。“出版”指印刷品定期印刷发行，微博是网络服务，不会按期出版。"}, {"text": "我的微博经常来我家吃饭。", "explanation": "这里应该用〈朋友〉。来家里吃饭的是人，微博是网络服务，不能来家里。"}, {"text": "他去微博寄信。", "explanation": "这里应该用〈邮局〉。寄信要去邮局，微博是网络服务，不能去寄信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微博", "is_correct": true, "explanation": "正确：“新的微博账号”指微博网站上的账号，符合句子的语境。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是网络服务，不能注册账号，句子说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是网络服务，不能有账号，句子说不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通方式，不能用来注册账号。"}], "explanations": {"微博": "正确：“新的微博账号”指微博网站上的账号，符合句子的语境。", "雨伞": "语义：雨伞不是网络服务，不能注册账号，句子说不通。", "冰箱": "语义：冰箱不是网络服务，不能有账号，句子说不通。", "地铁": "语义：地铁是交通方式，不能用来注册账号。"}, "sentence_index": 6, "correct_answer": "微博"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他早上吃微博。", "explanation": "这里应该用〈面包〉。吃的是食物，微博是网络服务，不能吃。"}, {"text": "妈妈用微博做饭。", "explanation": "这里应该用〈炉子〉。做饭要用炉子之类的工具，微博是网络服务，不能用来做饭。"}, {"text": "他的微博很好听。", "explanation": "这里应该用〈歌〉。“好听”形容歌曲或声音，微博是文字和图片的平台，不能用来听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她昨天注册了一只微博。", "corrected_sentence": "她昨天注册了一个微博。", "error_description": "错误形式：一只微博。作为网络服务，“微博”的量词应该是“个”，“只”多用于动物，不能用来数微博。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没看了他的微博。", "corrected_sentence": "我没看过他的微博。", "error_description": "错误形式：没看了。表示经历的否定要用“没……过”，正确形式是“没看过”，“了”用在这里不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fbe845-3fbb-4abf-be61-dd4245c079c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
