INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89268, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词,用于计量温度、角度、电量等。", "primary_collocate": null, "pronunciation": "dù", "ipa": "tu˥˩", "syllable_count": 1, "sentences": [{"text": "这个月我家用了一百二十度电。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把桌子转了九十度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个角是四十五度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天用空调，一个月要用二百度电。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "方向盘向右转了三十度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面热得很，有四十度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月电费很贵，一共用了三百度电。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把椅子再向左转十度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三角形里有一个角是九十度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的体温降到了三十七度。", "target_word": "度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "度：计量温度、角度、电量的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b6d23d-90ac-4dc8-9c4e-4b812c474339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "度", "is_correct": true, "explanation": "正确。dù（第四声），计量温度、角度、电量的量词。"}, {"text": "赌", "is_correct": false, "explanation": "dǔ（第三声）与 dù（第四声）声调不同，意思是“打赌”。"}, {"text": "独", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，意思是“单独”。"}, {"text": "督", "is_correct": false, "explanation": "dū（第一声）与 dù（第四声）声调不同，意思是“监督”。"}, {"text": "嘟", "is_correct": false, "explanation": "dū（第一声）与 dù（第四声）声调不同，常用于“嘟嘟声”。"}], "explanations": {"度": "正确。dù（第四声），计量温度、角度、电量的量词。", "赌": "dǔ（第三声）与 dù（第四声）声调不同，意思是“打赌”。", "独": "dú（第二声）与 dù（第四声）声调不同，意思是“单独”。", "督": "dū（第一声）与 dù（第四声）声调不同，意思是“监督”。", "嘟": "dū（第一声）与 dù（第四声）声调不同，常用于“嘟嘟声”。"}, "sentence_index": null, "correct_answer": "度"}, "level_3": {"options": [{"text": "个", "is_correct": false, "explanation": "搭配：“个”不用于电量，这里应说“度”。"}, {"text": "度", "is_correct": true, "explanation": "正确。“度”是电量单位，“一百二十度电”表示用电量。"}, {"text": "斤", "is_correct": false, "explanation": "语义：“斤”是重量单位，不计电量。"}, {"text": "元", "is_correct": false, "explanation": "语义：“元”是货币单位，表示钱数，不表示用电量。"}], "explanations": {"个": "搭配：“个”不用于电量，这里应说“度”。", "度": "正确。“度”是电量单位，“一百二十度电”表示用电量。", "斤": "语义：“斤”是重量单位，不计电量。", "元": "语义：“元”是货币单位，表示钱数，不表示用电量。"}, "sentence_index": 0, "correct_answer": "度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家住在五度。", "explanation": "这里应该用〈层〉。度不用于计量楼层，楼层要用“层”，说“住在五层”。"}, {"text": "这套书一共三度。", "explanation": "这里应该用〈本〉。度不用于计量书籍，书要用“本”，说“一共三本”。"}, {"text": "我家有两度车。", "explanation": "这里应该用〈辆〉。度不用于计量车辆，车要用“辆”，说“有两辆车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "度", "is_correct": true, "explanation": "正确。dù（第四声），计量温度、角度、电量的量词。"}, {"text": "嘟", "is_correct": false, "explanation": "dū（第一声）与 dù（第四声）声调不同，常用于“嘟嘟声”。"}, {"text": "堵", "is_correct": false, "explanation": "dǔ（第三声）与 dù（第四声）声调不同，意思是“堵塞”。"}, {"text": "毒", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，意思是“毒”。"}, {"text": "读", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，意思是“阅读”。"}], "explanations": {"度": "正确。dù（第四声），计量温度、角度、电量的量词。", "嘟": "dū（第一声）与 dù（第四声）声调不同，常用于“嘟嘟声”。", "堵": "dǔ（第三声）与 dù（第四声）声调不同，意思是“堵塞”。", "毒": "dú（第二声）与 dù（第四声）声调不同，意思是“毒”。", "读": "dú（第二声）与 dù（第四声）声调不同，意思是“阅读”。"}, "sentence_index": null, "correct_answer": "度"}, "level_3": {"options": [{"text": "桶", "is_correct": false, "explanation": "语义：“桶”是容器，不能计量用电量。"}, {"text": "度", "is_correct": true, "explanation": "正确。“度”是电量单位，“三百度电”表示用电量。"}, {"text": "盏", "is_correct": false, "explanation": "搭配：“盏”是量灯的量词，不用于计量用电量。"}, {"text": "斗", "is_correct": false, "explanation": "语义：“斗”是容量单位，不计电量。"}], "explanations": {"桶": "语义：“桶”是容器，不能计量用电量。", "度": "正确。“度”是电量单位，“三百度电”表示用电量。", "盏": "搭配：“盏”是量灯的量词，不用于计量用电量。", "斗": "语义：“斗”是容量单位，不计电量。"}, "sentence_index": 6, "correct_answer": "度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果重十度。", "explanation": "这里应该用〈斤〉。度不用于计量重量，苹果的重量要用“斤”，说“重十斤”。"}, {"text": "他在医院住了十度。", "explanation": "这里应该用〈天〉。度不用于计量时间，住院的时间要用“天”，说“住了十天”。"}, {"text": "这双鞋卖二百度。", "explanation": "这里应该用〈元〉。度不用于计量价钱，价格要用“元”，说“卖二百元”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 