INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89269, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "配件是机器上可以换的小零件。", "primary_collocate": null, "pronunciation": "pèi jiàn", "ipa": "pʰeɪ˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这台机器的配件坏了。", "target_word": "配件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买自行车的配件。", "target_word": "配件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板，这个配件多少钱？", "target_word": "配件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机器坏了，我们要换一个新配件。", "target_word": "配件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些配件都是原装的。", "target_word": "配件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把旧配件放进了箱子里。", "target_word": "配件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的配件不贵，也很好买。", "target_word": "配件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在检查机器上的配件。", "target_word": "配件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修机器的时候，别忘了带配件。", "target_word": "配件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个配件太小了，我找不到。", "target_word": "配件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个配件", "label": "量词"}, {"form": "一套配件", "label": "量词"}, {"form": "汽车配件", "label": "复合"}, {"form": "配件厂", "label": "复合"}], "register": "通用", "sense_fingerprint": "机器上可以更换的小零件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a929c76-6771-4b07-b944-72f67b1dd6c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口味", "is_correct": false, "explanation": "语义：口味不属于机器，“口味坏了”说不通。"}, {"text": "配件", "is_correct": true, "explanation": "配件是机器上可更换的零件，可以“坏了”，与句意相合。"}, {"text": "体型", "is_correct": false, "explanation": "语义：体型指人或动物的外形，机器的零件不能说“体型坏了”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不会“坏”，“价格坏了”说不通。"}], "explanations": {"口味": "语义：口味不属于机器，“口味坏了”说不通。", "配件": "配件是机器上可更换的零件，可以“坏了”，与句意相合。", "体型": "语义：体型指人或动物的外形，机器的零件不能说“体型坏了”。", "价格": "语义：价格不会“坏”，“价格坏了”说不通。"}, "sentence_index": 0, "correct_answer": "配件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的配件是老师。", "explanation": "这里应该用〈配偶〉。配件指机器上可更换的零件，不能指人。"}, {"text": "这部电影的配件很动人。", "explanation": "这里应该用〈配乐〉。配乐指电影中的背景音乐，配件是机器上可以换的小零件，不能用来形容电影的感染力。"}, {"text": "我的配件很健康。", "explanation": "这里应该用〈身体〉。健康形容人或生物的身体状态，配件是机器零件，不能说健康。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：机器没有身高，“身高不贵”说不通。"}, {"text": "电量", "is_correct": false, "explanation": "搭配：“不贵”形容价格，不能用来形容电量。"}, {"text": "配件", "is_correct": true, "explanation": "配件是机器上可更换的零件，可以说贵或不贵，与句意相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：机器没有年龄，“年龄不贵”说不通。"}], "explanations": {"身高": "语义：机器没有身高，“身高不贵”说不通。", "电量": "搭配：“不贵”形容价格，不能用来形容电量。", "配件": "配件是机器上可更换的零件，可以说贵或不贵，与句意相合。", "年龄": "语义：机器没有年龄，“年龄不贵”说不通。"}, "sentence_index": 6, "correct_answer": "配件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个配件太甜了。", "explanation": "这里应该用〈蛋糕〉。“太甜”形容食物的味道，配件是机器零件，不能说甜。"}, {"text": "我的配件五十岁了。", "explanation": "这里应该用〈爸爸〉。“五十岁”说的是人的年龄，配件是机器零件，没有岁数。"}, {"text": "他的配件写完了。", "explanation": "这里应该用〈作业〉。“写完”用于作业、文章等，配件是机器零件，不能写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想买一位新配件。", "corrected_sentence": "我想买一个新配件。", "error_description": "量词错误：“位”只用于人，配件是零件，应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人已经装了上配件。", "corrected_sentence": "工人已经装上了配件。", "error_description": "补语位置错误：趋向补语“上”应紧跟动词，动态助词“了”放在补语之后、宾语之前，应说“装上了配件”，不能说“装了上配件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
