INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由较好的地位或状态变为不好的地位或状态。", "primary_collocate": null, "pronunciation": "lún wéi", "ipa": "luən˧˥ ueɪ˧˥", "syllable_count": 2, "sentences": [{"text": "那个国家曾经很强大，后来沦为了弱国。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从老板沦为了打工的人。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司倒闭后，经理沦为了普通工人。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队从冠军沦为了二流队伍。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王子沦为了奴隶，每天都很辛苦。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店从名店沦为了没人去的小店。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经很有钱，现在却沦为穷人。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝沦为普通百姓，没有人想到。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个富人家的孩子沦为了小偷。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好学生沦为差生，是因为他不努力了。", "target_word": "沦为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沦为了", "label": "体标"}], "register": "书面语", "sense_fingerprint": "从好的地位落到差的地位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '790811c9-6e97-424f-b6aa-eb7a3bd287ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赢得", "is_correct": false, "explanation": "搭配：“赢得”接胜利、尊重等，不接“弱国”。"}, {"text": "沦为", "is_correct": true, "explanation": "正确答案。沦为指由强变弱，符合“曾经很强大，后来……弱国”的语境。"}, {"text": "生育", "is_correct": false, "explanation": "语义：生育只用于人或动物，不能用于国家，句子读不通。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是栽培植物的动作，与国家无关，句子读不通。"}], "explanations": {"赢得": "搭配：“赢得”接胜利、尊重等，不接“弱国”。", "沦为": "正确答案。沦为指由强变弱，符合“曾经很强大，后来……弱国”的语境。", "生育": "语义：生育只用于人或动物，不能用于国家，句子读不通。", "种植": "语义：种植是栽培植物的动作，与国家无关，句子读不通。"}, "sentence_index": 0, "correct_answer": "沦为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支球队从二流沦为了冠军。", "explanation": "这里应该用〈升为〉。沦为指由好变差，这里是由二流变成冠军，应该用“升为”。"}, {"text": "他从员工沦为经理。", "explanation": "这里应该用〈晋升〉。沦为指地位下降，这里是职位上升，应该用“晋升”。"}, {"text": "这个国家从弱国沦为强国。", "explanation": "这里应该用〈崛起〉。沦为指状态变差，这里是由弱变强，应该用“崛起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收购", "is_correct": false, "explanation": "搭配：“收购”接物品或公司，不接“穷人”。"}, {"text": "建造", "is_correct": false, "explanation": "搭配：“建造”接建筑或房屋，不能用于人。"}, {"text": "沦为", "is_correct": true, "explanation": "正确答案。沦为指由好的状态变成不好的状态，符合“曾经很有钱，现在却……穷人”的语境。"}, {"text": "驯化", "is_correct": false, "explanation": "语义：驯化是使动植物或野生物服从人，用于人不合常理，句子读不通。"}], "explanations": {"收购": "搭配：“收购”接物品或公司，不接“穷人”。", "建造": "搭配：“建造”接建筑或房屋，不能用于人。", "沦为": "正确答案。沦为指由好的状态变成不好的状态，符合“曾经很有钱，现在却……穷人”的语境。", "驯化": "语义：驯化是使动植物或野生物服从人，用于人不合常理，句子读不通。"}, "sentence_index": 6, "correct_answer": "沦为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从差生沦为好学生。", "explanation": "这里应该用〈蜕变〉。沦为指由好变差，这里是由差变好，应该用“蜕变”。"}, {"text": "这个孩子在老师的帮助下，沦为优秀的学生。", "explanation": "这里应该用〈成长〉。沦为指状态变差，这里是逐渐变好，应该用“成长为”。"}, {"text": "这所学校沦为全国名校。", "explanation": "这里应该用〈跃升〉。沦为指地位下降，这里是地位大幅上升，应该用“跃升”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个王朝最终被沦为了一个小国。", "corrected_sentence": "那个王朝最终沦为了一个小国。", "error_description": "错误在“被”。“沦为”表示变成某种不好的状态，不能用“被”构成被动句，应说“沦为了一个小国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的生意失败后，沦为着穷人。", "corrected_sentence": "他的生意失败后，沦为了穷人。", "error_description": "错误在“着”。“沦为”表示已经发生的变化，应用“了”，不用“着”。正确说法是“沦为了穷人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
