INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容人的外貌或举止对异性有吸引力。", "primary_collocate": null, "pronunciation": "xìng gǎn", "ipa": "ɕiŋ˥˩ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个模特儿穿着黑色长裙，看起来很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走路的姿势又慢又美，特别性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志选他为最性感的男明星。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女明星穿得很性感，很多男人看着她。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼神很性感，让人忍不住看她。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的睡衣不贴身，一点也不性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的声音很低，女孩子都觉得性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说，会笑的人比好看的人更性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发放下来，样子一下子变得很性感。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个舞蹈动作很性感，让男孩子红了脸。", "target_word": "性感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性感明星", "label": "复合"}, {"form": "性感美女", "label": "复合"}], "register": "中性", "sense_fingerprint": "外貌或举止对异性有吸引力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6df07d-0870-46ca-9127-847b9f9f2ba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”多用于声音或环境，不能用来形容人看起来的样子。"}, {"text": "性感", "is_correct": true, "explanation": "正确：“性感”形容模特儿的外貌有吸引力，符合句意。"}, {"text": "酸", "is_correct": false, "explanation": "语义：“酸”指味道，不能形容外表。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，不能形容人的外表。"}], "explanations": {"嘈杂": "搭配：“嘈杂”多用于声音或环境，不能用来形容人看起来的样子。", "性感": "正确：“性感”形容模特儿的外貌有吸引力，符合句意。", "酸": "语义：“酸”指味道，不能形容外表。", "咸": "语义：“咸”指味道，不能形容人的外表。"}, "sentence_index": 0, "correct_answer": "性感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜很性感，吃完大家都很满意。", "explanation": "这里应该用〈好吃〉。性感形容人的外貌或举止，不用来形容菜的味道，菜味道好要说好吃。"}, {"text": "这个小朋友玩得很性感，跑来跑去。", "explanation": "这里应该用〈活泼〉。性感不用来形容孩子玩耍的样子，孩子爱动、有朝气要说活泼。"}, {"text": "这些书摆得很性感，整整齐齐放在书架上。", "explanation": "这里应该用〈整洁〉。性感不用来形容书的摆放，东西摆得干净利落要说整洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方", "is_correct": false, "explanation": "语义：“方”形容形状，不能用来形容人的感觉。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”多用于天气或物体，不能用来形容声音带给人的感觉。"}, {"text": "性感", "is_correct": true, "explanation": "正确：“性感”形容声音带来的吸引力，符合句意。"}, {"text": "弯", "is_correct": false, "explanation": "语义：“弯”形容形状，不能用来形容声音。"}], "explanations": {"方": "语义：“方”形容形状，不能用来形容人的感觉。", "潮湿": "搭配：“潮湿”多用于天气或物体，不能用来形容声音带给人的感觉。", "性感": "正确：“性感”形容声音带来的吸引力，符合句意。", "弯": "语义：“弯”形容形状，不能用来形容声音。"}, "sentence_index": 6, "correct_answer": "性感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市的价格很性感，大家都愿意来买东西。", "explanation": "这里应该用〈便宜〉。性感不用来形容价格，价格低要说便宜。"}, {"text": "这段话解释得很性感，大家都听懂了。", "explanation": "这里应该用〈清楚〉。性感不用来形容讲解的内容，说明得明白要说清楚。"}, {"text": "图书馆里很性感，大家都在学习。", "explanation": "这里应该用〈安静〉。性感不用来形容图书馆的环境，环境不吵要说安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她性感的走过舞台。", "corrected_sentence": "她性感地走过舞台。", "error_description": "错误：“性感的走”。正确：“性感地走”。“性感”修饰动词时要用“地”，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的笑容很性感极了。", "corrected_sentence": "他的笑容性感极了。", "error_description": "错误：“很性感极了”。正确：“性感极了”。“极了”已经表示程度很高，前面不能再加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f86f5aa6-32bf-4679-a3b6-b3b9061a7dfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89279, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有罪", "is_correct": true, "explanation": "“有罪”与“无罪”意思相反，指犯了罪、有过错。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”与“无罪”在任何义项上都没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与“无罪”没有反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”形容范围广大，与“无罪”没有反义关系。"}], "correct_answer": "有罪", "explanations": {"有罪": "“有罪”与“无罪”意思相反，指犯了罪、有过错。", "聪明": "“聪明”与“无罪”在任何义项上都没有反义关系。", "明亮": "“明亮”形容光线或颜色，与“无罪”没有反义关系。", "辽阔": "“辽阔”形容范围广大，与“无罪”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89279, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有罪", "is_correct": true, "explanation": "“有罪”与“无罪”意思相反，指犯了罪、有过错。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”形容味道，与“无罪”没有反义关系。"}, {"text": "寂静", "is_correct": false, "explanation": "“寂静”形容环境安静，与“无罪”没有反义关系。"}, {"text": "漫长", "is_correct": false, "explanation": "“漫长”形容时间很久，与“无罪”没有反义关系。"}], "correct_answer": "有罪", "explanations": {"有罪": "“有罪”与“无罪”意思相反，指犯了罪、有过错。", "甜": "“甜”形容味道，与“无罪”没有反义关系。", "寂静": "“寂静”形容环境安静，与“无罪”没有反义关系。", "漫长": "“漫长”形容时间很久，与“无罪”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89279, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无罪是说没有做坏事，没有错。", "primary_collocate": null, "pronunciation": "wú zuì", "ipa": "u˧˥ tswei˥˩", "syllable_count": 2, "sentences": [{"text": "孩子还小，什么都不懂，他是无罪的。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被大家误会了，其实他无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没做坏事，我觉得自己无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱美无罪，你想穿就穿吧。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己什么坏事也没做过，所以无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说，他只是不小心，他无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直说，他无罪，这件事不是他做的。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，小孩打破杯子是无心的，无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你只是说了实话，说实话无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有骗人，也没有害人，自己无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指没有做坏事、没有过错，不是法律上的判决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a716b1e6-c5ce-40f3-a6a3-7a805e3ea816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无罪", "is_correct": true, "explanation": "“无罪”指没有做坏事、没有过错，与前文“什么都不懂”的前提相符。"}, {"text": "有罪", "is_correct": false, "explanation": "语义：“有罪”说他犯了错，与“什么都不懂”的前提矛盾。"}, {"text": "成熟", "is_correct": false, "explanation": "语义：“成熟”与前文“孩子还小”矛盾。"}, {"text": "有效", "is_correct": false, "explanation": "搭配：“有效”修饰事物，不能用来说人。"}], "explanations": {"无罪": "“无罪”指没有做坏事、没有过错，与前文“什么都不懂”的前提相符。", "有罪": "语义：“有罪”说他犯了错，与“什么都不懂”的前提矛盾。", "成熟": "语义：“成熟”与前文“孩子还小”矛盾。", "有效": "搭配：“有效”修饰事物，不能用来说人。"}, "sentence_index": 0, "correct_answer": "无罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的味道一直无罪，很多人都来吃。", "explanation": "这里应该用〈好〉。无罪说的是有没有做坏事或过错，不用来评价味道。"}, {"text": "他跑步的速度无罪，很快就到了终点。", "explanation": "这里应该用〈快〉。无罪不用来形容速度，形容速度要用“快”。"}, {"text": "这首歌的旋律一直无罪，大家都很喜欢。", "explanation": "这里应该用〈优美〉。无罪说的是有没有做坏事或过错，不用来评价旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无罪", "is_correct": true, "explanation": "“无罪”与“这件事不是他做的”相符，表示他没有过错。"}, {"text": "有错", "is_correct": false, "explanation": "语义：“有错”说他有过错，与后半句“这件事不是他做的”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材外形，不能用来说明“一直说”的内容。"}, {"text": "无愧", "is_correct": false, "explanation": "配价：“无愧”要带宾语，如“无愧于心”，单用“他无愧”不成立。"}], "explanations": {"无罪": "“无罪”与“这件事不是他做的”相符，表示他没有过错。", "有错": "语义：“有错”说他有过错，与后半句“这件事不是他做的”矛盾。", "高大": "体貌：“高大”形容身材外形，不能用来说明“一直说”的内容。", "无愧": "配价：“无愧”要带宾语，如“无愧于心”，单用“他无愧”不成立。"}, "sentence_index": 6, "correct_answer": "无罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的颜色无罪，大家都说很好看。", "explanation": "这里应该用〈漂亮〉。无罪不用来形容颜色，形容颜色要用“漂亮”。"}, {"text": "他唱歌的声音一直无罪，大家都爱听。", "explanation": "这里应该用〈好听〉。无罪不用来形容声音，形容声音要用“好听”。"}, {"text": "这所学校的操场一直无罪。", "explanation": "这里应该用〈宽敞〉。无罪不用来形容场地，形容操场要用“宽敞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事是个误会，他的确没无罪，大家都该相信他。", "corrected_sentence": "这件事是个误会，他的确无罪，大家都该相信他。", "error_description": "“无罪”本身已含否定，前面不能再加“没”。错误形式是“没无罪”，正确形式是“无罪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都看得出来，她没有骗人，她很无罪。", "corrected_sentence": "我们都看得出来，她没有骗人，她无罪。", "error_description": "“无罪”表示有没有罪，不分程度，不能用“很”修饰。错误形式是“很无罪”，正确形式是“无罪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
