INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89280, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有犯罪，经审判确认不应受到刑罚。", "primary_collocate": null, "pronunciation": "wú zuì", "ipa": "u˧˥ tswei˥˩", "syllable_count": 2, "sentences": [{"text": "法院判他无罪，他可以回家了。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过审判，法官宣布他无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的案子拖了很久，最后法院证明他无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的律师说，他是无罪的。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法庭上，大家都在等着听他是有罪还是无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子里，法院认为她无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在牢里住了三年，后来法院判他无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师拿出新证据，希望法官判她无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，证据不够，只能宣布他无罪。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到法官说他无罪，他哭了。", "target_word": "无罪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无罪释放", "label": "复合"}, {"form": "无罪判决", "label": "复合"}], "register": "正式", "sense_fingerprint": "法律上经审判确认没有犯罪、不应受刑罚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a716b1e6-c5ce-40f3-a6a3-7a805e3ea816') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无罪", "is_correct": true, "explanation": "“无罪”指经审判确认没有犯罪，与“法院判他”和“可以回家了”相符。"}, {"text": "有罪", "is_correct": false, "explanation": "语义：“有罪”说他犯了罪，与后半句“他可以回家了”矛盾。"}, {"text": "无效", "is_correct": false, "explanation": "搭配：“无效”说的是判决或行为的效力，“判”后不能直接接“无效”来判定一个人。"}, {"text": "坚决", "is_correct": false, "explanation": "搭配：“坚决”形容态度，不能作为“判”的结果。"}], "explanations": {"无罪": "“无罪”指经审判确认没有犯罪，与“法院判他”和“可以回家了”相符。", "有罪": "语义：“有罪”说他犯了罪，与后半句“他可以回家了”矛盾。", "无效": "搭配：“无效”说的是判决或行为的效力，“判”后不能直接接“无效”来判定一个人。", "坚决": "搭配：“坚决”形容态度，不能作为“判”的结果。"}, "sentence_index": 0, "correct_answer": "无罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同已经过期，现在无罪了。", "explanation": "这里应该用〈无效〉。合同过期说的是失去效力，要用“无效”；无罪说的是人有没有犯罪。"}, {"text": "这个指控无罪，证据很充分。", "explanation": "这里应该用〈成立〉。指控可以成立或不成立，不能说无罪。"}, {"text": "他的履历一直无罪。", "explanation": "这里应该用〈清白〉。无罪说的是人有没有犯罪，描述履历要用“清白”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无罪", "is_correct": true, "explanation": "“无罪”与“后来法院判他”搭配，指经审判确认没有犯罪。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”说明情况明白，不是法院判决的结果。"}, {"text": "轻松", "is_correct": false, "explanation": "搭配：“轻松”形容心情或状态，不能用来形容“判”的结果。"}, {"text": "公开", "is_correct": false, "explanation": "搭配：“公开”说的是过程是否对外，不能直接作“判他”的内容。"}], "explanations": {"无罪": "“无罪”与“后来法院判他”搭配，指经审判确认没有犯罪。", "清楚": "语义：“清楚”说明情况明白，不是法院判决的结果。", "轻松": "搭配：“轻松”形容心情或状态，不能用来形容“判”的结果。", "公开": "搭配：“公开”说的是过程是否对外，不能直接作“判他”的内容。"}, "sentence_index": 6, "correct_answer": "无罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的做法是无罪的，没有问题。", "explanation": "这里应该用〈正当〉。正当说行为合理合法，无罪只说人没有犯罪。"}, {"text": "这次审判无罪，结果很合理。", "explanation": "这里应该用〈公正〉。审判可以公正或不公正，不能说无罪。"}, {"text": "这份证据是无罪的，可以使用。", "explanation": "这里应该用〈合法〉。证据要说合法或不合法，不用“无罪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于被法院无罪了，可以回家了。", "corrected_sentence": "他终于被法院判无罪了，可以回家了。", "error_description": "“无罪”是形容词，不能直接放在“被”后作动词。错误形式是“被无罪”，正确形式是“被判无罪”，需要加“判”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到法官宣布他很无罪，她高兴得哭了。", "corrected_sentence": "听到法官宣布他无罪，她高兴得哭了。", "error_description": "“无罪”表示是否有罪，没有程度变化，不能用“很”修饰。错误形式是“很无罪”，正确形式是“无罪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b118dade-29da-432d-9039-96230af87a56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
