INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89281, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89281, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "脑子里忽然又记得一件事。", "primary_collocate": null, "pronunciation": "xiǎng qǐ lái", "ipa": "ɕjɑŋ˨˩ tɕʰi˨˩ lai˧˥", "syllable_count": 3, "sentences": [{"text": "我突然想起来，今天要交作业。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走到门口，他才想起来没带钥匙。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想起来了，那本书在桌子上。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她忽然想起来，今天是妈妈的生日。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚走出家门，我想起来没关火。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听你这么一说，我想起来了。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了一下头，想起来忘了给朋友打电话。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，我想起来明天要早起。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭的时候，我想起来还没给老师回信。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那张照片，他突然想起来一件旧事。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想起来了", "label": "完成体"}, {"form": "想不起来", "label": "可能补语否定式"}, {"form": "想得起来", "label": "可能补语肯定式"}], "register": "口语", "sense_fingerprint": "忽然记起一件事，突然想到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89281, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想起来", "is_correct": true, "explanation": "想起来：忽然记起，符合句意。"}, {"text": "想要", "is_correct": false, "explanation": "语义：“想要”表示希望得到某物，与“忽然记起要交作业”的句意不符。"}, {"text": "想念", "is_correct": false, "explanation": "语义：“想念”指惦记、思念，与“突然记起”的句意不符，“我突然想念”后接“今天要交作业”不通。"}, {"text": "收到", "is_correct": false, "explanation": "配价：“收到”需要接收的对象（信件、通知），句中缺少宾语，也不表示记起。"}], "explanations": {"想起来": "想起来：忽然记起，符合句意。", "想要": "语义：“想要”表示希望得到某物，与“忽然记起要交作业”的句意不符。", "想念": "语义：“想念”指惦记、思念，与“突然记起”的句意不符，“我突然想念”后接“今天要交作业”不通。", "收到": "配价：“收到”需要接收的对象（信件、通知），句中缺少宾语，也不表示记起。"}, "sentence_index": 0, "correct_answer": "想起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很想起来远方的妈妈。", "explanation": "这里应该用〈想念〉。“想起来”表示忽然记起某事，不表示惦记之情，不能用“很”修饰。"}, {"text": "他认真想起来了这个问题。", "explanation": "这里应该用〈思考〉。“想起来”表示忽然记起，不能表示有意识地认真思考问题。"}, {"text": "孩子在想起来未来的生活。", "explanation": "这里应该用〈想象〉。“想起来”表示记起过去的事，不能表示对未来生活的设想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想起来", "is_correct": true, "explanation": "想起来：忽然记起，与“拍了一下头”的动作衔接自然。"}, {"text": "放下", "is_correct": false, "explanation": "语义：“放下”指放置，不表示记起，句意不通。"}, {"text": "拿出来", "is_correct": false, "explanation": "语义：“拿出来”指取出，与“忘了打电话”的语义不符。"}, {"text": "掏出来", "is_correct": false, "explanation": "搭配：“掏出来”一般带具体的物品作宾语，不能用于“忘了……”的句式。"}], "explanations": {"想起来": "想起来：忽然记起，与“拍了一下头”的动作衔接自然。", "放下": "语义：“放下”指放置，不表示记起，句意不通。", "拿出来": "语义：“拿出来”指取出，与“忘了打电话”的语义不符。", "掏出来": "搭配：“掏出来”一般带具体的物品作宾语，不能用于“忘了……”的句式。"}, "sentence_index": 6, "correct_answer": "想起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我饿了，想起来吃一碗面。", "explanation": "这里应该用〈想〉。“想起来”表示记起某件事，不表示打算或想要做某事。"}, {"text": "我想起来他别去。", "explanation": "这里应该用〈劝〉。“想起来”表示记起某件事，不能接“别去”这类劝阻的内容。"}, {"text": "我想起来音乐。", "explanation": "这里应该用〈喜欢〉。“想起来”的宾语是记起的事情，不能表示喜爱的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没想起来了明天要还书。", "corrected_sentence": "他没想起来明天要还书。", "error_description": "体标错误：“没”否定的动作后面不能再加“了”，应说“他没想起来明天要还书”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89281, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想起来着一件旧事。", "corrected_sentence": "他想起来了一件旧事。", "error_description": "体标错误：表示已经想起的完成动作要用“了”，“着”表示持续状态，“想起来着一件旧事”不符合句意，应说“想起来了一件旧事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
