INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回忆起来；记起某事。", "primary_collocate": null, "pronunciation": "xiǎng qǐ lái", "ipa": "ɕjɑŋ˨˩ tɕʰi˨˩ lai˧˥", "syllable_count": 3, "sentences": [{"text": "我想起来了，他是我的小学同学。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再想想，能想起来那个人的名字吗？", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌叫什么，我终于想起来了。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢想起来小时候住过的那个村子。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过提醒，她想起来昨天去过哪里。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人想起来年轻时的事，笑了。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怎么也没想起来钥匙放在哪儿。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到旧房子，他想起来很多往事。", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想起来那天谁来过吗？", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问她，能想起来出事时的情况吗？", "target_word": "想起来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想起来了", "label": "完成体"}, {"form": "想不起来", "label": "可能补语否定式"}, {"form": "想得起来", "label": "可能补语肯定式"}], "register": "口语", "sense_fingerprint": "回忆起过去的人或事，记起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想起来", "is_correct": true, "explanation": "想起来：记起过去的人或事，符合句意。"}, {"text": "想出", "is_correct": false, "explanation": "语义：“想出”指想出办法或主意，与“他是我的小学同学”的回忆不符。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：“收拾”指整理东西，与“他是我的小学同学”不搭。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”需要具体的被拿之物作宾语，句中“我拿了”不完整。"}], "explanations": {"想起来": "想起来：记起过去的人或事，符合句意。", "想出": "语义：“想出”指想出办法或主意，与“他是我的小学同学”的回忆不符。", "收拾": "语义：“收拾”指整理东西，与“他是我的小学同学”不搭。", "拿": "配价：“拿”需要具体的被拿之物作宾语，句中“我拿了”不完整。"}, "sentence_index": 0, "correct_answer": "想起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很想起来故乡。", "explanation": "这里应该用〈想念〉。“想起来”表示记起某事，不表示思念，不能用“很”修饰。"}, {"text": "他正在想起来换工作。", "explanation": "这里应该用〈考虑〉。“想起来”表示记起，不能表示正在权衡是否换工作。"}, {"text": "他正在想起来一种从没见过的动物。", "explanation": "这里应该用〈想象〉。“想起来”表示回忆已有的记忆，与“从没见过”矛盾，不能用于凭空构想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想起来", "is_correct": true, "explanation": "想起来：记起，用在“没想起来”的否定句中，符合句意。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”不能表示记忆，“没放钥匙放在哪儿”不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，与“钥匙放在哪儿”的回忆不符。"}, {"text": "数", "is_correct": false, "explanation": "语义：“数”指清点数目，与记不起位置的句意不符。"}], "explanations": {"想起来": "想起来：记起，用在“没想起来”的否定句中，符合句意。", "放": "搭配：“放”不能表示记忆，“没放钥匙放在哪儿”不通。", "洗": "语义：“洗”指清洁，与“钥匙放在哪儿”的回忆不符。", "数": "语义：“数”指清点数目，与记不起位置的句意不符。"}, "sentence_index": 6, "correct_answer": "想起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次行动完全想起来了我。", "explanation": "这里应该用〈说服〉。“想起来”表示记起，不表示使人信服，不能用于“完全想起来了我”。"}, {"text": "这幅画想起来了很多人。", "explanation": "这里应该用〈吸引〉。“想起来”表示记起，不表示引起他人的注意或兴趣。"}, {"text": "这件事想起来了大家。", "explanation": "这里应该用〈感动〉。“想起来”表示记起，不表示使人情绪被打动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想起来着，她是我中学时的老师。", "corrected_sentence": "我想起来了，她是我中学时的老师。", "error_description": "体标错误：“想起来”表示记起的结果已实现，应用完成体“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人没想起来了年轻时的往事，笑了。", "corrected_sentence": "老人想起来了年轻时的往事，笑了。", "error_description": "否定与体标冲突：“没”与完成体“了”不能同时用于“想起来”，应说“没想起来”或“想起来了”，不能说“没想起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
