INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89283, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重做是再做一次，从头再来。", "primary_collocate": null, "pronunciation": "chóng zuò", "ipa": "ʈʂʰʊŋ˧˥ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "作业写错了，必须从头重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太小，裁缝要重做一件。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频有问题，我们要重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不满意，让他把方案重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手工课上，她的小船坏了，只好重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试卷错得太多，老师让他重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重做比修改更花时间。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的地板不平，工人只能重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他重做过这个实验，结果还是一样。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤的味道不对，奶奶重做了一锅。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重做了", "label": "体标"}, {"form": "重做过", "label": "体标"}], "register": "中性", "sense_fingerprint": "从头再做一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重做", "is_correct": true, "explanation": "重做：从头再做一次，与“写错了”的语境相符。"}, {"text": "跳过", "is_correct": false, "explanation": "语义：“跳过”是略过不做，与“必须从头”矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再做，与“必须”的要求相反。"}, {"text": "保存", "is_correct": false, "explanation": "搭配：“保存”不能与“从头”搭配表示再做一次。"}], "explanations": {"重做": "重做：从头再做一次，与“写错了”的语境相符。", "跳过": "语义：“跳过”是略过不做，与“必须从头”矛盾。", "放弃": "语义：“放弃”是不再做，与“必须”的要求相反。", "保存": "搭配：“保存”不能与“从头”搭配表示再做一次。"}, "sentence_index": 0, "correct_answer": "重做"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书很有意思，我又重做了一遍。", "explanation": "这里应该用〈重读〉。重做指把做过的事（作业、实验）再做一遍，读书要说“重读”。"}, {"text": "体检时，护士又重做了一遍心跳。", "explanation": "这里应该用〈数〉。心跳是数出来的，不是做出来的，应说“又数了一遍心跳”。"}, {"text": "这首歌太好听了，请重做一遍。", "explanation": "这里应该用〈唱〉。“重做”用于做过的事情，要求再唱一遍应说“请再唱一遍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重做", "is_correct": true, "explanation": "重做：从头再做，与“比修改更花时间”的比较相符。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”是对人宽恕，不能与“修改”比较花费的时间。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉”几乎不花时间，与“更花时间”的意思矛盾。"}, {"text": "忍受", "is_correct": false, "explanation": "搭配：“忍受”的对象是痛苦或困难，不能以“花时间”作比较的主语。"}], "explanations": {"重做": "重做：从头再做，与“比修改更花时间”的比较相符。", "原谅": "语义：“原谅”是对人宽恕，不能与“修改”比较花费的时间。", "扔掉": "语义：“扔掉”几乎不花时间，与“更花时间”的意思矛盾。", "忍受": "搭配：“忍受”的对象是痛苦或困难，不能以“花时间”作比较的主语。"}, "sentence_index": 6, "correct_answer": "重做"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的笑容很可爱，我们请他重做一遍。", "explanation": "这里应该用〈再笑〉。笑容不能“重做”，应说“请他再笑一次”。"}, {"text": "猫饿了，他又重做了一次。", "explanation": "这里应该用〈喂〉。喂猫是动作，不是可以“重做”的任务，应说“又喂了一次”。"}, {"text": "护士又重做了一遍身高。", "explanation": "这里应该用〈测〉。身高是测量出来的，应说“又测了一遍身高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份试卷错得太多，他只能全部了重做。", "corrected_sentence": "这份试卷错得太多，他只能全部重做。", "error_description": "错误：“了”插在“全部”和“重做”之间（“全部了重做”）。正确：“了”不能放在动词“重做”之前，应为“他只能全部重做。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案我已经重做了过两次。", "corrected_sentence": "这个方案我已经重做过两次。", "error_description": "错误：“了”和“过”同时用在“重做”后。正确：表示经历过某事只用“重做过”，不能与“了”并用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
