INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重新做；从头再做一遍。", "primary_collocate": null, "pronunciation": "chóng zuò", "ipa": "ʈʂʰʊŋ˧˥ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "这道题错了，你要重做一遍。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我把作业重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模型装错了，他只好重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告不合格，明天必须重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕烤坏了，妈妈打算重做一个。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验结果不对，我们要重做实验。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他重做了三次，终于做对了。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计图太难看，设计师决定重做。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想重做，这次一定要做对。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜太咸了，请厨师重做一份。", "target_word": "重做", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重做了", "label": "体标"}, {"form": "重做过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把做过的事重新做一遍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重做", "is_correct": true, "explanation": "重做：重新做一遍，与“错了”的语境相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”是不再记得，与“这道题错了，你要……一遍”的要求不符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再做，与“你要……一遍”的要求相反。"}, {"text": "保留", "is_correct": false, "explanation": "搭配：“保留”不能与“一遍”搭配表示再做一次。"}], "explanations": {"重做": "重做：重新做一遍，与“错了”的语境相符。", "忘记": "语义：“忘记”是不再记得，与“这道题错了，你要……一遍”的要求不符。", "放弃": "语义：“放弃”是不再做，与“你要……一遍”的要求相反。", "保留": "搭配：“保留”不能与“一遍”搭配表示再做一次。"}, "sentence_index": 0, "correct_answer": "重做"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影很精彩，我又重做了一遍。", "explanation": "这里应该用〈看〉。重做指把做过的事（作业、实验）再做一遍，看电影要说“又看了一遍”。"}, {"text": "老师说的话很重要，请同学们重做一遍。", "explanation": "这里应该用〈重复〉。重做是把做过的事再做一遍，要求别人再说一遍话应说“重复”。"}, {"text": "他的手机摔坏了，已经送去重做。", "explanation": "这里应该用〈修理〉。坏了的东西要修理，重做指把做过的事再做一遍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重做", "is_correct": true, "explanation": "重做：重新做，与“三次”和“终于做对了”的过程相符。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”是去看地方，与“做对了”的结果没有关系。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”与“终于做对了”的结果无关，不能表示再做一次。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：“关闭”与“终于做对了”的结果不相干。"}], "explanations": {"重做": "重做：重新做，与“三次”和“终于做对了”的过程相符。", "参观": "语义：“参观”是去看地方，与“做对了”的结果没有关系。", "搬运": "语义：“搬运”与“终于做对了”的结果无关，不能表示再做一次。", "关闭": "语义：“关闭”与“终于做对了”的结果不相干。"}, "sentence_index": 6, "correct_answer": "重做"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师讲得太快，请你重做一遍。", "explanation": "这里应该用〈说〉。重做是把做过的事再做一遍，请别人再说一遍应说“再说一遍”。"}, {"text": "这首歌很好听，请重做一遍。", "explanation": "这里应该用〈唱〉。歌是唱出来的，“重做”用于做过的事情，不能用于唱歌。"}, {"text": "我昨天逛过这家店，今天想重做一次。", "explanation": "这里应该用〈再去〉。重做指把做过的事（作业、实验）再做一遍，去一家店不是要重做的任务，应说“今天想再去一次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把作业重做着一遍。", "corrected_sentence": "他把作业重做了一遍。", "error_description": "错误：“重做”后用“着”表示持续，不能与“一遍”（完成的动作次数）搭配。正确：“他把作业重做了一遍。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把整个计划做重做了一遍。", "corrected_sentence": "他把整个计划重做了一遍。", "error_description": "错误：多出一个“做”，“做重做”不成结构。正确：“他把整个计划重做了一遍。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：「争取」是努力去得到，「放弃」是不再努力去得到，二者意思相反。"}, {"text": "休息", "is_correct": false, "explanation": "不是反义词：「休息」指停下来不做事，与「争取」没有对立关系。"}, {"text": "忘记", "is_correct": false, "explanation": "不是反义词：「忘记」指不再记得，与「争取」的意思不构成对立。"}, {"text": "认识", "is_correct": false, "explanation": "不是反义词：「认识」指知道某人或某事，与「争取」不构成对立。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：「争取」是努力去得到，「放弃」是不再努力去得到，二者意思相反。", "休息": "不是反义词：「休息」指停下来不做事，与「争取」没有对立关系。", "忘记": "不是反义词：「忘记」指不再记得，与「争取」的意思不构成对立。", "认识": "不是反义词：「认识」指知道某人或某事，与「争取」不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：「争取」是努力得到，「放弃」是不再努力得到，二者意思相反。"}, {"text": "散步", "is_correct": false, "explanation": "不是反义词：「散步」指慢慢走路，与「争取」没有对立关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "不是反义词：「唱歌」指发声演唱，与「争取」不构成对立。"}, {"text": "睡觉", "is_correct": false, "explanation": "不是反义词：「睡觉」指闭眼休息，与「争取」不构成对立。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：「争取」是努力得到，「放弃」是不再努力得到，二者意思相反。", "散步": "不是反义词：「散步」指慢慢走路，与「争取」没有对立关系。", "唱歌": "不是反义词：「唱歌」指发声演唱，与「争取」不构成对立。", "睡觉": "不是反义词：「睡觉」指闭眼休息，与「争取」不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "争取是努力去得到想要的东西。", "primary_collocate": null, "pronunciation": "zhēng qǔ", "ipa": "ʈʂɤŋ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "他想争取一次去北京工作的机会。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要争取拿到这个奖学金。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了争取好成绩，她每天学到很晚。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李努力争取老师的同意。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在比赛中一直争取第一名。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想争取一个星期的假期。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队正在争取进入决赛的资格。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在争取这份工作。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈同意了，因为我争取了很久。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们争取到了免费参观的机会。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争取了", "label": "完成体"}, {"form": "争取过", "label": "经历体"}, {"form": "争取到", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "争取：努力去得到想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b6d23d-90ac-4dc8-9c4e-4b812c474339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "争取", "is_correct": true, "explanation": "争取 zhēng qǔ：正确答案，指努力去得到想要的东西。"}, {"text": "蒸煮", "is_correct": false, "explanation": "zhēng zhǔ 与 zhēng qǔ 的区别在第二个音节的声母：zh 与 q 不同。蒸煮 指用水蒸或煮。"}, {"text": "称取", "is_correct": false, "explanation": "第一个音节 chēng 与 zhēng 的声母不同。称取 指用秤称出一定的量。"}, {"text": "争气", "is_correct": false, "explanation": "zhēng qì 与 zhēng qǔ 的第二个音节韵母和声调不同：qì 与 qǔ。争气 指不甘落后、努力上进。"}, {"text": "征求", "is_correct": false, "explanation": "zhēng qiú 与 zhēng qǔ 的第二个音节韵母和声调不同：qiú 与 qǔ。征求 指向别人询问意见。"}], "explanations": {"争取": "争取 zhēng qǔ：正确答案，指努力去得到想要的东西。", "蒸煮": "zhēng zhǔ 与 zhēng qǔ 的区别在第二个音节的声母：zh 与 q 不同。蒸煮 指用水蒸或煮。", "称取": "第一个音节 chēng 与 zhēng 的声母不同。称取 指用秤称出一定的量。", "争气": "zhēng qì 与 zhēng qǔ 的第二个音节韵母和声调不同：qì 与 qǔ。争气 指不甘落后、努力上进。", "征求": "zhēng qiú 与 zhēng qǔ 的第二个音节韵母和声调不同：qiú 与 qǔ。征求 指向别人询问意见。"}, "sentence_index": null, "correct_answer": "争取"}, "level_3": {"options": [{"text": "争取", "is_correct": true, "explanation": "这里的「争取」表示努力获得，与「想」和「一次机会」搭配，句意通顺。"}, {"text": "错过", "is_correct": false, "explanation": "语义：「错过」是没有赶上，与「想」的意愿相反，不说「想错过机会」。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的宾语是地点或展览，不能说「参观机会」。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的宾语是饮料，不能与「机会」搭配。"}], "explanations": {"争取": "这里的「争取」表示努力获得，与「想」和「一次机会」搭配，句意通顺。", "错过": "语义：「错过」是没有赶上，与「想」的意愿相反，不说「想错过机会」。", "参观": "搭配：「参观」的宾语是地点或展览，不能说「参观机会」。", "喝": "搭配：「喝」的宾语是饮料，不能与「机会」搭配。"}, "sentence_index": 0, "correct_answer": "争取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个人为这件事争取了半天，谁也不肯让步。", "explanation": "这里应该用〈争论〉。两人在辩论谁对谁错，「争取」指努力得到想要的东西，没有争辩的意思。"}, {"text": "他不小心争取到了一身感冒。", "explanation": "这里应该用〈染上〉。「争取」表示有意努力得到想要的东西，与「不小心」矛盾，无意间染上疾病要用「染上」。"}, {"text": "他默默争取了一场意外的车祸。", "explanation": "这里应该用〈遭遇〉。「争取」表示有意努力得到想要的东西，车祸这类不希望发生的意外不能被争取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争取", "is_correct": true, "explanation": "「争取」表示努力得到，与「正在」和「进入决赛的资格」搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语是食物，不能说「吃资格」。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」的宾语是器物，不能说「修理资格」。"}, {"text": "送给", "is_correct": false, "explanation": "配价：「送给」需要接受者和被送的东西，句中缺少接受者，句子不成立。"}], "explanations": {"争取": "「争取」表示努力得到，与「正在」和「进入决赛的资格」搭配。", "吃": "搭配：「吃」的宾语是食物，不能说「吃资格」。", "修理": "搭配：「修理」的宾语是器物，不能说「修理资格」。", "送给": "配价：「送给」需要接受者和被送的东西，句中缺少接受者，句子不成立。"}, "sentence_index": 6, "correct_answer": "争取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直在争取一个大错误。", "explanation": "这里应该用〈犯〉。「争取」的宾语应是人想要得到的好东西，「错误」不能被争取，应说「犯错误」。"}, {"text": "他上课时争取了一个觉，被老师批评了。", "explanation": "这里应该用〈睡〉。「争取」指为得到想要的东西而有意努力，上课打瞌睡不是努力争得的东西，应说「睡了一觉」。"}, {"text": "他们争取了一场很大的暴雨。", "explanation": "这里应该用〈遭遇〉。「争取」指有意努力得到想要的东西，暴雨这类自然现象不由人争取，只能说「遭遇」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了争取了这个职位，她准备了很久。", "corrected_sentence": "为了争取这个职位，她准备了很久。", "error_description": "错误：「为了」引导的目的分句中，「争取」后不能加「了」。正确说法是「为了争取这个职位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直在努力争取了这份工作。", "corrected_sentence": "他一直在努力争取这份工作。", "error_description": "错误：「在……」表示正在进行，不能与完成体「了」同用，应去掉「争取」后的「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：「争取」是努力得到，「放弃」是不再努力得到，二者意思相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "不是反义词：「唱歌」指用嗓子唱曲子，与「争取」没有对立关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "不是反义词：「吃饭」指进食，与「争取」不构成对立。"}, {"text": "旅行", "is_correct": false, "explanation": "不是反义词：「旅行」指外出游览，与「争取」不构成对立。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：「争取」是努力得到，「放弃」是不再努力得到，二者意思相反。", "唱歌": "不是反义词：「唱歌」指用嗓子唱曲子，与「争取」没有对立关系。", "吃饭": "不是反义词：「吃饭」指进食，与「争取」不构成对立。", "旅行": "不是反义词：「旅行」指外出游览，与「争取」不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：「争取」是努力得到，「放弃」是不再努力得到，二者意思相反。"}, {"text": "写作", "is_correct": false, "explanation": "不是反义词：「写作」指写文章，与「争取」没有对立关系。"}, {"text": "游泳", "is_correct": false, "explanation": "不是反义词：「游泳」指在水中活动，与「争取」不构成对立。"}, {"text": "洗澡", "is_correct": false, "explanation": "不是反义词：「洗澡」指清洁身体，与「争取」不构成对立。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：「争取」是努力得到，「放弃」是不再努力得到，二者意思相反。", "写作": "不是反义词：「写作」指写文章，与「争取」没有对立关系。", "游泳": "不是反义词：「游泳」指在水中活动，与「争取」不构成对立。", "洗澡": "不是反义词：「洗澡」指清洁身体，与「争取」不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "努力设法做到或得到想要的结果。", "primary_collocate": null, "pronunciation": "zhēng qǔ", "ipa": "ʈʂɤŋ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们要争取早点儿把工作做完。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你争取明天下午到。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在争取新的客户。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想争取更多的练习时间。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家争取今年买下房子。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理争取到了一个很好的合同。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她争取每天都能睡八个小时。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们争取在天黑以前回到家。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师鼓励大家争取更好的成绩。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想争取妈妈的支持。", "target_word": "争取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "争取了", "label": "完成体"}, {"form": "争取过", "label": "经历体"}, {"form": "争取到", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "争取：设法做到某事，或努力得到想要的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60b6d23d-90ac-4dc8-9c4e-4b812c474339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "争取", "is_correct": true, "explanation": "争取 zhēng qǔ：正确答案，指设法得到。"}, {"text": "蒸煮", "is_correct": false, "explanation": "zhēng zhǔ 与 zhēng qǔ 的区别在第二个音节的声母：zh 与 q 不同。蒸煮 指用水蒸或煮。"}, {"text": "蒸汽", "is_correct": false, "explanation": "第二个音节 qì 与 qǔ 的韵母和声调都不同。蒸汽 指水受热后变成的气。"}, {"text": "征求", "is_correct": false, "explanation": "第二个音节 qiú 与 qǔ 的韵母和声调不同。征求 指询问别人的意见。"}, {"text": "称取", "is_correct": false, "explanation": "第一个音节 chēng 与 zhēng 的声母不同。称取 指用秤称出一定的量。"}], "explanations": {"争取": "争取 zhēng qǔ：正确答案，指设法得到。", "蒸煮": "zhēng zhǔ 与 zhēng qǔ 的区别在第二个音节的声母：zh 与 q 不同。蒸煮 指用水蒸或煮。", "蒸汽": "第二个音节 qì 与 qǔ 的韵母和声调都不同。蒸汽 指水受热后变成的气。", "征求": "第二个音节 qiú 与 qǔ 的韵母和声调不同。征求 指询问别人的意见。", "称取": "第一个音节 chēng 与 zhēng 的声母不同。称取 指用秤称出一定的量。"}, "sentence_index": null, "correct_answer": "争取"}, "level_3": {"options": [{"text": "争取", "is_correct": true, "explanation": "这里的「争取」表示设法做到，与「要」和「早点儿把工作做完」搭配，句意通顺。"}, {"text": "错过", "is_correct": false, "explanation": "语义：「错过」是没有赶上，与「要」的意愿相反，不说「要错过早点儿把工作做完」。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」的对象是地点或展览，不能带「把工作做完」这样的动作结构。"}, {"text": "送给", "is_correct": false, "explanation": "配价：「送给」需要接受者，句中缺少接受者，句子不成立。"}], "explanations": {"争取": "这里的「争取」表示设法做到，与「要」和「早点儿把工作做完」搭配，句意通顺。", "错过": "语义：「错过」是没有赶上，与「要」的意愿相反，不说「要错过早点儿把工作做完」。", "参观": "搭配：「参观」的对象是地点或展览，不能带「把工作做完」这样的动作结构。", "送给": "配价：「送给」需要接受者，句中缺少接受者，句子不成立。"}, "sentence_index": 0, "correct_answer": "争取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两位老师为教学方法争取了一下午。", "explanation": "这里应该用〈争论〉。句子说的是辩论意见，「争取」表示努力得到，没有争辩的意思。"}, {"text": "他不知不觉争取了一身病。", "explanation": "这里应该用〈得〉。「争取」表示有意努力得到，与「不知不觉」矛盾，无意间得病要用「得」。"}, {"text": "他想争取很多作业。", "explanation": "「争取」的宾语应是想要得到的好东西，「作业」不属于这一类，这里说的是「做作业」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争取", "is_correct": true, "explanation": "这里的「争取」表示设法做到，与「她」和「每天都能睡八个小时」搭配，句意通顺。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：「制造」的宾语是事物，不能说「制造每天都能睡八个小时」。"}, {"text": "思考", "is_correct": false, "explanation": "搭配：「思考」的宾语是问题或想法，不能接一个状态。"}, {"text": "叹息", "is_correct": false, "explanation": "配价：「叹息」是不及物动词，不能带「每天都能睡八个小时」这样的宾语。"}], "explanations": {"争取": "这里的「争取」表示设法做到，与「她」和「每天都能睡八个小时」搭配，句意通顺。", "制造": "搭配：「制造」的宾语是事物，不能说「制造每天都能睡八个小时」。", "思考": "搭配：「思考」的宾语是问题或想法，不能接一个状态。", "叹息": "配价：「叹息」是不及物动词，不能带「每天都能睡八个小时」这样的宾语。"}, "sentence_index": 6, "correct_answer": "争取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子争取到了妈妈的支持。", "explanation": "这里应该用〈获得〉。「争取」的主语须是能主动努力的人或团体，椅子不能主动争取，只能说「获得」。"}, {"text": "他一直在争取一场大雨。", "explanation": "这里应该用〈盼望〉。「争取」指努力去得到，大雨不是人能努力争取的东西，表示希望下雨应说「盼望」。"}, {"text": "他一直想争取妈妈的生气。", "explanation": "这里应该用〈惹〉。「争取」指努力得到好的、想要的东西，「生气」不能被争取，应说「惹妈妈生气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该争取了更多的时间完成任务。", "corrected_sentence": "我们应该争取更多的时间完成任务。", "error_description": "错误：「应该」表示应当，动作还未发生，「争取」后不能加「了」，应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她正在努力争取了一个学习的机会。", "corrected_sentence": "她正在努力争取一个学习的机会。", "error_description": "错误：「正在」表示动作进行中，不能与完成体「了」同用，应去掉「争取」后的「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '301014e9-3c69-4684-959f-41fdf4d658af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
