INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89288, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由理事组成、负责决策或管理某一组织事务的机构。", "primary_collocate": null, "pronunciation": "lǐ shì huì", "ipa": "li˨˩˦ ʂɻ̩˥˩ xueɪ˥˩", "syllable_count": 3, "sentences": [{"text": "理事会是这家基金会最高的决策机构。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协会成立了新的理事会，负责管理大事。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理事会通过了今年的预算。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的理事会选出了新院长。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织的理事会由九位理事组成。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理事会有权决定钱怎么用。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会的理事会每年开两次会。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理事会要对所有会员负责。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们向理事会提出了新的计划。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理事会批准了她的辞职申请。", "target_word": "理事会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "组织中负责决策和管理的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '790811c9-6e97-424f-b6aa-eb7a3bd287ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财务部", "is_correct": false, "explanation": "语义：财务部负责账目，不是最高的决策机构。"}, {"text": "理事会", "is_correct": true, "explanation": "正确。理事会是负责决策和管理的机构，符合“最高的决策机构”。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室是办事的场所，不负责决策。"}, {"text": "员工", "is_correct": false, "explanation": "搭配：“是……决策机构”要求主语是组织，“员工”是个人，不能作决策机构。"}], "explanations": {"财务部": "语义：财务部负责账目，不是最高的决策机构。", "理事会": "正确。理事会是负责决策和管理的机构，符合“最高的决策机构”。", "办公室": "语义：办公室是办事的场所，不负责决策。", "员工": "搭配：“是……决策机构”要求主语是组织，“员工”是个人，不能作决策机构。"}, "sentence_index": 0, "correct_answer": "理事会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我是这个基金会的理事会，负责管钱。", "explanation": "这里应该用〈理事〉。理事会是管理机构，不能指一个人；「我」负责管钱，应是理事。"}, {"text": "我和妻子在家开了一个理事会，商量晚饭吃什么。", "explanation": "这里应该用〈商量〉或〈家庭会议〉。理事会是组织中由理事组成的决策机构，不用于夫妻在家讨论晚饭这样的家庭小事。"}, {"text": "理事会每天的工作是送外卖。", "explanation": "这里应该用〈外卖员〉。理事会负责决策或管理某一组织的事务，送外卖是外卖员的工作，不能用理事会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本是教材，不能召开会议，句子读不通。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是出版物，不能召开会议。"}, {"text": "理事会", "is_correct": true, "explanation": "正确。理事会是能定期召开会议的管理机构，符合“每年开两次会”。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是用餐场所，不能召开会议。"}], "explanations": {"课本": "语义：课本是教材，不能召开会议，句子读不通。", "报纸": "语义：报纸是出版物，不能召开会议。", "理事会": "正确。理事会是能定期召开会议的管理机构，符合“每年开两次会”。", "食堂": "语义：食堂是用餐场所，不能召开会议。"}, "sentence_index": 6, "correct_answer": "理事会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家理事会的饺子又便宜又好吃。", "explanation": "这里应该用〈饭馆〉。理事会是负责决策和管理的机构，不卖饭菜；卖饺子的是饭馆。"}, {"text": "理事会可以用来切菜。", "explanation": "这里应该用〈菜刀〉。理事会是负责决策和管理的机构，不是工具，不能用来切菜；切菜要用〈菜刀〉。"}, {"text": "理事会是一种液体，可以用杯子装。", "explanation": "这里应该用〈水〉。理事会是由理事组成的机构，不是液体，不能用杯子装；液体要用〈水〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个基金会换了一名新的理事会。", "corrected_sentence": "这个基金会换了一个新的理事会。", "error_description": "量词用错：理事会是团体，应该用“个”；“名”只用于人。正确应为“一个新的理事会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "理事会们的决定需要全体投票通过。", "corrected_sentence": "理事会的决定需要全体投票通过。", "error_description": "“们”用错：理事会是集体名词，不能加“们”表示复数。正确应为“理事会的决定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3885ddb8-c785-4870-bf8b-2d618c7cb430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
