INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "放在一篇文章最上面的名字。", "primary_collocate": null, "pronunciation": "biāo tí", "ipa": "piɑʊ̯˥ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "请把标题写在文章最上面。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇作文的标题在第一行。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的标题放在中间，字要大一点。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我写完作文，还没有想好标题。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标题下面是作者的名字。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要我们给文章加一个标题。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章最上面的标题用了红色。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把标题改成了“我的家”。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这页纸上没有标题，不知道是什么文章。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标题要写得比正文大一些。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "副标题", "label": "复合"}, {"form": "小标题", "label": "复合"}, {"form": "標題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写在文章最上面的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb53a5c-65d7-4ea3-9d02-709f50e00d34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89289, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标题", "is_correct": true, "explanation": "“标题”是写在文章最上面的名字，这里说“写在文章最上面”，合适。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不说“写照片”，“把照片写在文章最上面”不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是可以写在纸上的文字，不能“写在文章最上面”。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是文章的题目，“把垃圾写在文章最上面”不通。"}], "explanations": {"标题": "“标题”是写在文章最上面的名字，这里说“写在文章最上面”，合适。", "照片": "搭配：“写”的对象是文字，不说“写照片”，“把照片写在文章最上面”不通。", "闹钟": "语义：闹钟不是可以写在纸上的文字，不能“写在文章最上面”。", "垃圾": "语义：垃圾不是文章的题目，“把垃圾写在文章最上面”不通。"}, "sentence_index": 0, "correct_answer": "标题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师出的标题很难，大家都做不出来。", "explanation": "这里应该用〈题目〉。“题目”指考试或练习中要回答的问题，“标题”是放在文章最上面的名字，不能用来指试题。"}, {"text": "我给这篇作文加了一把标题。", "explanation": "这里应该用〈个〉。“把”用于有柄、能拿起的东西，“标题”是文字，要用“个”。"}, {"text": "这篇作文的最后写着作者的标题。", "explanation": "这里应该用〈署名〉。署名写在文章末尾，“标题”写在文章最上面，不能放在末尾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89289, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标题", "is_correct": true, "explanation": "“标题”位于文章最上面，这里说它“用了红色”，符合语境。"}, {"text": "点心", "is_correct": false, "explanation": "语义：点心不是写在文章上的字，“文章最上面的点心”不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是文章的一部分，“文章最上面的窗户”不通。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“用了红色”说的是字或符号的颜色，不能说小猫“用了红色”。"}], "explanations": {"标题": "“标题”位于文章最上面，这里说它“用了红色”，符合语境。", "点心": "语义：点心不是写在文章上的字，“文章最上面的点心”不通。", "窗户": "语义：窗户不是文章的一部分，“文章最上面的窗户”不通。", "小猫": "搭配：“用了红色”说的是字或符号的颜色，不能说小猫“用了红色”。"}, "sentence_index": 6, "correct_answer": "标题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的标题很可爱，大家都叫他小明。", "explanation": "这里应该用〈昵称〉。“昵称”是给人起的亲切叫法，“标题”是放在文章最上面的名字，不能用来指人。"}, {"text": "这颗标题很长，我记不住。", "explanation": "这里应该用〈个〉。量词“颗”用于颗粒状的小东西，“标题”不能用“颗”来数。"}, {"text": "这瓶酒的标题上写着产地和年份。", "explanation": "这里应该用〈标签〉。“标签”贴在瓶子或商品上，写着产地、年份等信息，“标题”是放在文章最上面的名字，不能用来指商品上的信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请标题写在纸的最上面。", "corrected_sentence": "请把标题写在纸的最上面。", "error_description": "“把”字句中，要用“把”把“标题”提到动词“写”前面，应说“请把标题写在……”，不能省略“把”说“请标题写在……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章地标题很短。", "corrected_sentence": "这篇文章的标题很短。", "error_description": "修饰名词“标题”要用结构助词“的”，不能用“地”（“地”用于动词、形容词前作状语）。应说“这篇文章的标题很短”，不能说“这篇文章地标题很短”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
