INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "概括文章、新闻或作品内容的题目。", "primary_collocate": null, "pronunciation": "biāo tí", "ipa": "piɑʊ̯˥ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这篇新闻的标题很短，但很清楚。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的标题能说出文章的主要内容。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻标题让很多人点开了它。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了标题，我就知道这本书写什么。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的标题和故事内容不一样。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上的标题常常只有几个字。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作品标题很长，不容易记住。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，标题要能概括全文。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标题太夸张，内容却很普通。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先读标题，再决定看不看新闻。", "target_word": "标题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "副标题", "label": "复合"}, {"form": "大标题", "label": "复合"}, {"form": "標題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "概括新闻、文章或作品内容的题目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb53a5c-65d7-4ea3-9d02-709f50e00d34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标题", "is_correct": true, "explanation": "“标题”指概括新闻内容的题目，这里说它“很短”“很清楚”，最合适。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是文章的题目，“这篇新闻的天气很短”不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”可说深浅，不说长短，“颜色很短”不成立。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：“字体”说字形、粗细，不说长短，“字体很短”不成立。"}], "explanations": {"标题": "“标题”指概括新闻内容的题目，这里说它“很短”“很清楚”，最合适。", "天气": "语义：“天气”不是文章的题目，“这篇新闻的天气很短”不通。", "颜色": "搭配：“颜色”可说深浅，不说长短，“颜色很短”不成立。", "字体": "搭配：“字体”说字形、粗细，不说长短，“字体很短”不成立。"}, "sentence_index": 0, "correct_answer": "标题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给这只小狗起了一个很可爱的标题。", "explanation": "这里应该用〈名字〉。“标题”指文章或新闻的题目，给小狗起名要用“名字”。"}, {"text": "这把标题写得很大，大家都能看见。", "explanation": "这里应该用〈个〉。“把”用于有柄、能拿起的东西，“标题”是文字，量词要用“个”。"}, {"text": "他给这家新开的饭馆起了一个很好听的标题。", "explanation": "这里应该用〈店名〉。“标题”是文章、新闻或作品的题目，不能用来给饭馆起名，给店起名要用“店名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标题", "is_correct": true, "explanation": "“标题”指作品的题目，这里说它“很长”“不容易记住”，合适。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说高低，不说长短，“作品价格很长”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性情，不属于作品，“作品脾气很长”不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人或动物的高矮，作品没有身高，“作品身高很长”不通。"}], "explanations": {"标题": "“标题”指作品的题目，这里说它“很长”“不容易记住”，合适。", "价格": "搭配：“价格”说高低，不说长短，“作品价格很长”不成立。", "脾气": "语义：“脾气”是人的性情，不属于作品，“作品脾气很长”不通。", "身高": "体貌：“身高”指人或动物的高矮，作品没有身高，“作品身高很长”不通。"}, "sentence_index": 6, "correct_answer": "标题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个牌子的标题很有名，大家都知道。", "explanation": "这里应该用〈商标〉。“商标”是产品上的标记，“标题”是文章或作品的题目，不能用来指牌子。"}, {"text": "这首标题太长了，读者记不住。", "explanation": "这里应该用〈个〉。量词“首”用于歌曲、诗词，“标题”是题目，要说“这个标题”。"}, {"text": "这瓶酒的标题很漂亮。", "explanation": "这里应该用〈标签〉。“标签”贴在瓶子上、写着产品信息，“标题”是文章的题目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本标题很有意思。", "corrected_sentence": "这个标题很有意思。", "error_description": "“标题”的量词应该用“个”，不能用“本”（“本”用于书籍、册子）。这里说的是标题，不是书，所以“这本标题”不对，应说“这个标题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在本子上写了一张标题。", "corrected_sentence": "我在本子上写了一个标题。", "error_description": "错误：“标题”的量词不能用“张”（“张”用于纸、桌子等平面的东西）。正确：“一个标题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8374c6eb-bbfb-4c2d-b36a-11c2e0a7fe0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
