INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89291, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "重地是很重要的地方，不是谁都能进。", "primary_collocate": null, "pronunciation": "zhòng dì", "ipa": "ʈʂʊŋ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "军事重地不是谁都能进去的。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要走进这个重地，里面很危险。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，办公室后面是公司重地。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在重地工作，每天都要刷卡。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电厂是国家的重地，外人不能随便参观。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重地门口有保安，没有卡进不去。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港口是海防重地，要检查很多次。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子好奇地问：“为什么那里是重地？”", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "档案室是单位的重地，只有负责人能进。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走近重地时，警卫拦住了我们。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "军事重地", "label": "复合"}], "register": "正式", "sense_fingerprint": "不是谁都能进的重要地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89291, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重地", "is_correct": true, "explanation": "〈重地〉指不是谁都能进的重要地方，与句意相符。"}, {"text": "公园", "is_correct": false, "explanation": "语义：〈公园〉谁都能进去，与“不是谁都能进去”相矛盾。"}, {"text": "市场", "is_correct": false, "explanation": "语义：〈市场〉人人都能进，与“不是谁都能进去”相矛盾。"}, {"text": "咖啡馆", "is_correct": false, "explanation": "搭配：“军事”不能修饰〈咖啡馆〉。"}], "explanations": {"重地": "〈重地〉指不是谁都能进的重要地方，与句意相符。", "公园": "语义：〈公园〉谁都能进去，与“不是谁都能进去”相矛盾。", "市场": "语义：〈市场〉人人都能进，与“不是谁都能进去”相矛盾。", "咖啡馆": "搭配：“军事”不能修饰〈咖啡馆〉。"}, "sentence_index": 0, "correct_answer": "重地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子的重地有五公斤，搬起来很费力。", "explanation": "这里应该用〈重量〉。〈重地〉指重要、不能随便进入的地方，不能用来说物体的轻重。"}, {"text": "这场比赛是今年的重地，全校师生都来看。", "explanation": "这里应该用〈重点〉。〈重地〉指需要严加防守、不是谁都能进的地方，不能用来指一场比赛。"}, {"text": "他是公司的重地，每天都要刷卡。", "explanation": "这里应该用〈职员〉。〈重地〉是地方，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89291, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重地", "is_correct": true, "explanation": "〈重地〉指重要而需严加防守的地方，与“海防”和“要检查很多次”相符。"}, {"text": "饭馆", "is_correct": false, "explanation": "搭配：“海防”不能修饰〈饭馆〉。"}, {"text": "游乐园", "is_correct": false, "explanation": "语义：〈游乐园〉不需要检查很多次，与“要检查很多次”相矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“海防”不能修饰〈教室〉。"}], "explanations": {"重地": "〈重地〉指重要而需严加防守的地方，与“海防”和“要检查很多次”相符。", "饭馆": "搭配：“海防”不能修饰〈饭馆〉。", "游乐园": "语义：〈游乐园〉不需要检查很多次，与“要检查很多次”相矛盾。", "教室": "搭配：“海防”不能修饰〈教室〉。"}, "sentence_index": 6, "correct_answer": "重地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家那只狗是我们的重地，每天陪我们散步。", "explanation": "动物：〈重地〉指地方，不能指狗。这里应该用〈宠物〉。"}, {"text": "我们在重地里排队买票，人很多。", "explanation": "这里应该用〈车站〉。〈重地〉要求严加防守，不能有排队买票的公共场所。"}, {"text": "这个重地太漫长，我们等了整整一天。", "explanation": "这里应该用〈时期〉。〈重地〉指需要严加防守的地方，不能用来指一段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子后面有一条重地，外人不能进。", "corrected_sentence": "院子后面有一处重地，外人不能进。", "error_description": "量词错误：〈重地〉指地方，应用量词〈处〉；〈条〉多用于狭长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在重地们外面等了很久。", "corrected_sentence": "我们在重地外面等了很久。", "error_description": "词缀错误：〈们〉只加在指人的名词后，〈重地〉指地方，不能加〈们〉；应说“在重地外面”，不能说“在重地们外面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
