INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89292, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "重要的、需要严加防守的地方。", "primary_collocate": null, "pronunciation": "zhòng dì", "ipa": "ʈʂʊŋ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这里是军事重地，外人不能进去。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的仓库是重地，没有证件不能进。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口写着“机要重地，闲人免进”。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察守在重地门口，不让陌生人靠近。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的金库是重地，有很多人看守。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想进这个重地，可是门卫不同意。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片山区是国防重地，游客不能拍照。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座变电站是全市供电的重地，每天都有人值守。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室是学校的重地，学生要先问老师才能进。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个重地很安全，晚上也有人守着。", "target_word": "重地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "军事重地", "label": "复合"}], "register": "正式", "sense_fingerprint": "重要且需严加防守的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v