INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重地", "is_correct": true, "explanation": "〈重地〉指需要严加防守的地方，与“军事”和“外人不能进去”相符。"}, {"text": "公园", "is_correct": false, "explanation": "语义：〈公园〉对公众开放，与“外人不能进去”相矛盾。"}, {"text": "市场", "is_correct": false, "explanation": "语义：〈市场〉人人可以进去，与“外人不能进去”相矛盾。"}, {"text": "咖啡馆", "is_correct": false, "explanation": "搭配：“军事”不能修饰〈咖啡馆〉。"}], "explanations": {"重地": "〈重地〉指需要严加防守的地方，与“军事”和“外人不能进去”相符。", "公园": "语义：〈公园〉对公众开放，与“外人不能进去”相矛盾。", "市场": "语义：〈市场〉人人可以进去，与“外人不能进去”相矛盾。", "咖啡馆": "搭配：“军事”不能修饰〈咖啡馆〉。"}, "sentence_index": 0, "correct_answer": "重地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场音乐会是今年的重地，人人都可以来听。", "explanation": "这里应该用〈盛事〉。〈重地〉指需要严加防守的地方，不能用来指一场音乐会。"}, {"text": "这袋大米的重地是十公斤。", "explanation": "这里应该用〈重量〉。〈重地〉指需要严加防守的地方，不能用来说东西有多重。"}, {"text": "王师傅很认真，他是公司最好的重地。", "explanation": "这里应该用〈员工〉。〈重地〉是地方，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重地", "is_correct": true, "explanation": "〈重地〉指需要严加防守的地方，与“国防”和“游客不能拍照”相符。"}, {"text": "景区", "is_correct": false, "explanation": "搭配：“国防”不能修饰〈景区〉，景区以开放游览为主。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：〈游乐场〉是供游客玩耍的地方，与“国防”的严肃语境不符。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“国防”不能修饰〈饭店〉。"}], "explanations": {"重地": "〈重地〉指需要严加防守的地方，与“国防”和“游客不能拍照”相符。", "景区": "搭配：“国防”不能修饰〈景区〉，景区以开放游览为主。", "游乐场": "语义：〈游乐场〉是供游客玩耍的地方，与“国防”的严肃语境不符。", "饭店": "搭配：“国防”不能修饰〈饭店〉。"}, "sentence_index": 6, "correct_answer": "重地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗是我家的重地，每天守在门口。", "explanation": "动物：〈重地〉指地方，不能指狗。这里应该用〈看门狗〉。"}, {"text": "这个重地很大，有两张床和一个衣柜。", "explanation": "这里应该用〈房间〉。〈重地〉是需要严加防守的地方，不用来形容有床和衣柜的房间。"}, {"text": "这个重地很热闹，周末游客特别多。", "explanation": "这里应该用〈景区〉。〈重地〉要求严加防守，不能指游客多的开放场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面有一条重地，闲人不能靠近。", "corrected_sentence": "前面有一处重地，闲人不能靠近。", "error_description": "量词错误：〈重地〉指地方，应用量词〈处〉；〈条〉多用于狭长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些重地们都有人守着。", "corrected_sentence": "这些重地都有人守着。", "error_description": "词缀错误：〈们〉只加在指人的名词后，〈重地〉指地方，不能加〈们〉；应说“这些重地”，不能说“这些重地们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89293, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "普通", "is_correct": true, "explanation": "普通：与特殊相对，指平常、一般，正是“跟平常的不一样”的反面。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容明白、不模糊，与特殊没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容人多、有声音，与特殊不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：形容没有声音、不吵闹，与特殊不构成反义关系。"}], "correct_answer": "普通", "explanations": {"普通": "普通：与特殊相对，指平常、一般，正是“跟平常的不一样”的反面。", "清楚": "清楚：形容明白、不模糊，与特殊没有反义关系。", "热闹": "热闹：形容人多、有声音，与特殊不构成反义关系。", "安静": "安静：形容没有声音、不吵闹，与特殊不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
