INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89293, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "特殊是跟平常的不一样。", "primary_collocate": null, "pronunciation": "tè shū", "ipa": "tʰɤ˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "今天是个特殊的日子。", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的样子很特殊。", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的口音有点特殊。", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果的味道很特殊。", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院给老人安排了特殊的房间。", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的天气有点特殊，夏天也下雪。", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜做法很特殊。", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用了一种特殊的纸写信。", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的作息时间很特殊。", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么特殊的爱好吗？", "target_word": "特殊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "特殊化", "label": "复合"}, {"form": "特殊性", "label": "复合"}], "register": "中性", "sense_fingerprint": "跟平常的不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4b1fec-b529-465b-92b7-6f05dc3c0020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89293, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特殊", "is_correct": true, "explanation": "特殊：跟平常不一样，填入后句意“今天是个与平常不同的日子”通顺。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”形容食物的味道，不用来形容日子。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：锋利指刀刃等很快，与日子无关，句意不通。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：清脆形容声音清亮，用在日子上与句意不合。"}], "explanations": {"特殊": "特殊：跟平常不一样，填入后句意“今天是个与平常不同的日子”通顺。", "好吃": "搭配：“好吃”形容食物的味道，不用来形容日子。", "锋利": "语义：锋利指刀刃等很快，与日子无关，句意不通。", "清脆": "语义：清脆形容声音清亮，用在日子上与句意不合。"}, "sentence_index": 0, "correct_answer": "特殊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜特殊地好吃，我每天都想吃。", "explanation": "这里应该用〈特别〉。“特殊地”表示“与平常不同地”，不表示程度很高，这里说的是程度，要用〈特别〉。"}, {"text": "我特殊地累，走不动了。", "explanation": "这里应该用〈特别〉。“特殊地”表示“与平常不同地”，不表示程度很高。"}, {"text": "这个房间的布置特殊地周到。", "explanation": "这里应该用〈特别〉。“特殊地”表示“与平常不同地”，不用于表示程度；此处说的是周到的程度，要用〈特别〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89293, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特殊", "is_correct": true, "explanation": "特殊：与平常不同，填入后句意“这家店的菜做法与平常不同”通顺。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：清澈形容水或眼睛，不用来形容做法。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：高大形容人或建筑的体形，不用来说做法。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：响亮形容声音大而清楚，与做法无关，句意不通。"}], "explanations": {"特殊": "特殊：与平常不同，填入后句意“这家店的菜做法与平常不同”通顺。", "清澈": "搭配：清澈形容水或眼睛，不用来形容做法。", "高大": "搭配：高大形容人或建筑的体形，不用来说做法。", "响亮": "语义：响亮形容声音大而清楚，与做法无关，句意不通。"}, "sentence_index": 6, "correct_answer": "特殊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的风景特殊地美，我们都很惊讶。", "explanation": "这里应该用〈格外〉。“特殊地”表示“与平常不同地”，不表示程度特别高。"}, {"text": "这首歌特殊地动听，大家都在听。", "explanation": "这里应该用〈尤其〉。“特殊地”强调与众不同，不表示程度特别高。"}, {"text": "这家店的服务特殊地热情。", "explanation": "这里应该用〈十分〉。“特殊地”表示“与平常不同地”，不表示程度很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种茶的味道很特殊地。", "corrected_sentence": "这种茶的味道很特殊。", "error_description": "错误：“很特殊地”，正确：“很特殊”。“特殊”在这里作谓语，作谓语的形容词后不加“地”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89293, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他特殊地想法让我们很惊讶。", "corrected_sentence": "他特殊的想法让我们很惊讶。", "error_description": "错误：“特殊地想法”，正确：“特殊的想法”。“地”用于修饰动词，修饰名词“想法”要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89295, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亲近", "is_correct": true, "explanation": "亲近与生分（原本亲近的人变得疏远）意思相反，是该义项的反义词。"}, {"text": "坚硬", "is_correct": false, "explanation": "坚硬形容物体的硬度，与生分没有反义关系。"}, {"text": "清爽", "is_correct": false, "explanation": "清爽形容感觉舒适干净，与生分没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明形容智力，与生分没有反义关系。"}], "correct_answer": "亲近", "explanations": {"亲近": "亲近与生分（原本亲近的人变得疏远）意思相反，是该义项的反义词。", "坚硬": "坚硬形容物体的硬度，与生分没有反义关系。", "清爽": "清爽形容感觉舒适干净，与生分没有反义关系。", "聪明": "聪明形容智力，与生分没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89295, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亲近", "is_correct": true, "explanation": "亲近与生分（感情疏远）意思相反，是该义项的反义词。"}, {"text": "嘈杂", "is_correct": false, "explanation": "嘈杂形容声音吵闹，与生分没有反义关系。"}, {"text": "巨大", "is_correct": false, "explanation": "巨大形容体积或数量，与生分没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "简单形容事情或结构不复杂，与生分没有反义关系。"}], "correct_answer": "亲近", "explanations": {"亲近": "亲近与生分（感情疏远）意思相反，是该义项的反义词。", "嘈杂": "嘈杂形容声音吵闹，与生分没有反义关系。", "巨大": "巨大形容体积或数量，与生分没有反义关系。", "简单": "简单形容事情或结构不复杂，与生分没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89295, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生分是说两个人以前很亲，现在变得不熟悉了。", "primary_collocate": null, "pronunciation": "shēng fen", "ipa": "ʂəŋ˥ fən", "syllable_count": 2, "sentences": [{"text": "我们十年没见，现在有点生分了。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们以前无话不说，现在变得生分了。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬走以后，我和老邻居慢慢生分了。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少了联系，好朋友也会生分。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出国多年，回家后跟弟弟生分了。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们小时候那么好，怎么现在这么生分？", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵过一次架，两个人就生分了。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去了外地工作，跟同学渐渐生分了。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同学很久不联系，见面时有点生分。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别因为小事，让朋友生分了。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "原本亲近的人因为分开或失去联系而变得疏远陌生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed153e7-0a2c-4ca6-9ac2-d5bcdbc4229a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89295, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生分", "is_correct": true, "explanation": "生分（shēng fen）：原本亲近的人因分开而变得不熟悉。"}, {"text": "省份", "is_correct": false, "explanation": "省份（shěng fèn）与生分（shēng fen）两个音节的声调都不同，意思是行政区划。"}, {"text": "生粪", "is_correct": false, "explanation": "生粪（shēng fèn）与生分（shēng fen）第二音节声调不同，意思是未经发酵的粪肥。"}, {"text": "生粉", "is_correct": false, "explanation": "生粉（shēng fěn）与生分（shēng fen）第二音节声调不同，意思是淀粉。"}], "explanations": {"生分": "生分（shēng fen）：原本亲近的人因分开而变得不熟悉。", "省份": "省份（shěng fèn）与生分（shēng fen）两个音节的声调都不同，意思是行政区划。", "生粪": "生粪（shēng fèn）与生分（shēng fen）第二音节声调不同，意思是未经发酵的粪肥。", "生粉": "生粉（shēng fěn）与生分（shēng fen）第二音节声调不同，意思是淀粉。"}, "sentence_index": null, "correct_answer": "生分"}, "level_3": {"options": [{"text": "生分", "is_correct": true, "explanation": "“十年没见”说明两人长期分开，“有点……了”描述关系的变化，只有“生分”符合语境。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不形容人与人之间的关系。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”形容天气或物体，与“十年没见”的情形不符。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，与两人关系的变化无关。"}], "explanations": {"生分": "“十年没见”说明两人长期分开，“有点……了”描述关系的变化，只有“生分”符合语境。", "高大": "体貌：“高大”形容身材，不形容人与人之间的关系。", "干燥": "语义：“干燥”形容天气或物体，与“十年没见”的情形不符。", "响亮": "语义：“响亮”形容声音，与两人关系的变化无关。"}, "sentence_index": 0, "correct_answer": "生分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我多年没下棋，棋艺已经很生分了。", "explanation": "这里应该用〈生疏〉。生分指人际关系疏远，不用于形容棋艺；技艺荒废要说生疏。"}, {"text": "我刚搬到这个小区，对附近还很生分。", "explanation": "这里应该用〈陌生〉。生分指原本亲近的人关系变淡，不用于形容新环境；初到一个地方要说陌生。"}, {"text": "他对这件事的态度一直很生分。", "explanation": "这里应该用〈冷淡〉。生分形容人与人之间的关系，对事情的态度要用冷淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89295, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生分", "is_correct": true, "explanation": "生分（shēng fen）：原本亲近的人因分开而变得不熟悉。"}, {"text": "身份", "is_correct": false, "explanation": "身份（shēn fèn）与生分（shēng fen）的第一音节前鼻音和后鼻音不同（shēn/shēng），第二音节声调也不同。身份的意思是人的地位或资格。"}, {"text": "生风", "is_correct": false, "explanation": "生风（shēng fēng）与生分（shēng fen）的第二音节韵母不同（eng/en），声调也不同。生风的意思是起风，常说“虎虎生风”。"}, {"text": "升分", "is_correct": false, "explanation": "升分（shēng fēn）与生分（shēng fen）的第二音节一个读阴平，一个读轻声。升分的意思是分数提高。"}], "explanations": {"生分": "生分（shēng fen）：原本亲近的人因分开而变得不熟悉。", "身份": "身份（shēn fèn）与生分（shēng fen）的第一音节前鼻音和后鼻音不同（shēn/shēng），第二音节声调也不同。身份的意思是人的地位或资格。", "生风": "生风（shēng fēng）与生分（shēng fen）的第二音节韵母不同（eng/en），声调也不同。生风的意思是起风，常说“虎虎生风”。", "升分": "升分（shēng fēn）与生分（shēng fen）的第二音节一个读阴平，一个读轻声。升分的意思是分数提高。"}, "sentence_index": null, "correct_answer": "生分"}, "level_3": {"options": [{"text": "生分", "is_correct": true, "explanation": "“吵过一次架”导致两人关系疏远，“就……了”表示结果，只有“生分”符合语境。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面或气氛，与两人关系的变化不符。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”形容身体或物体牢固，不描述人际关系。"}, {"text": "亮堂", "is_correct": false, "explanation": "语义：“亮堂”形容光线明亮，与人际关系无关。"}], "explanations": {"生分": "“吵过一次架”导致两人关系疏远，“就……了”表示结果，只有“生分”符合语境。", "热闹": "语义：“热闹”形容场面或气氛，与两人关系的变化不符。", "结实": "语义：“结实”形容身体或物体牢固，不描述人际关系。", "亮堂": "语义：“亮堂”形容光线明亮，与人际关系无关。"}, "sentence_index": 6, "correct_answer": "生分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用这个软件很久了，操作得很生分。", "explanation": "这里应该用〈生疏〉。生分指感情疏远，不用于形容操作技能；操作不熟练要说生疏。"}, {"text": "这间老屋子我住了很多年，对它很生分。", "explanation": "这里应该用〈熟悉〉。生分说的是人际关系疏远，不用于形容住过的房屋；对房屋很熟悉要说熟悉。"}, {"text": "这份报告的数据他写得很生分。", "explanation": "这里应该用〈生硬〉。生分指人与人之间感情疏远，不用于形容表达方式；文字呆板、不流畅要说生硬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "离开家乡多年，我跟老朋友渐渐有点很生分了。", "corrected_sentence": "离开家乡多年，我跟老朋友渐渐有点生分了。", "error_description": "程度重复：“有点”与“很”都表示程度，不能连用。应说“渐渐有点生分了”，不能说“渐渐有点很生分了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们多年没联系，说话生分的很。", "corrected_sentence": "他们多年没联系，说话生分得很。", "error_description": "补语标记错误：形容词后引出补语要用结构助词“得”，不能用“的”。应说“说话生分得很”，不能说“说话生分的很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89296, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亲近", "is_correct": true, "explanation": "亲近与生分（感情疏远）意思相反，是该义项的反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明形容智力，与生分的感情含义没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净形容清洁程度，与生分没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与生分没有反义关系。"}], "correct_answer": "亲近", "explanations": {"亲近": "亲近与生分（感情疏远）意思相反，是该义项的反义词。", "聪明": "聪明形容智力，与生分的感情含义没有反义关系。", "干净": "干净形容清洁程度，与生分没有反义关系。", "明亮": "明亮形容光线或颜色，与生分没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
