INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89296, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "感情疏远，不亲近。", "primary_collocate": null, "pronunciation": "shēng fen", "ipa": "ʂəŋ˥ fən", "syllable_count": 2, "sentences": [{"text": "他们是亲兄弟，见面却很生分。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子和爷爷不常见面，有点生分。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你跟我还这么客气，太生分了。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友见面，一点也不生分。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的同事对我很生分，不爱说话。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小在外婆家长大，跟父母反而生分。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对邻居总是客客气气，显得很生分。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别对家人这么生分，有话就直说。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人说话很客气，听起来有点生分。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在一起三年，我们还是有些生分。", "target_word": "生分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "人与人之间感情疏远、不亲近，见面客气拘谨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed153e7-0a2c-4ca6-9ac2-d5bcdbc4229a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = 