INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89296, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生分", "is_correct": true, "explanation": "生分（shēng fen）：感情疏远，不亲近，见面客气拘谨。"}, {"text": "省份", "is_correct": false, "explanation": "省份（shěng fèn）与生分（shēng fen）两个音节的声调都不同，意思是行政区划。"}, {"text": "生粪", "is_correct": false, "explanation": "生粪（shēng fèn）与生分（shēng fen）第二音节声调不同，意思是未经发酵的粪肥。"}, {"text": "生粉", "is_correct": false, "explanation": "生粉（shēng fěn）与生分（shēng fen）第二音节声调不同，意思是淀粉。"}], "explanations": {"生分": "生分（shēng fen）：感情疏远，不亲近，见面客气拘谨。", "省份": "省份（shěng fèn）与生分（shēng fen）两个音节的声调都不同，意思是行政区划。", "生粪": "生粪（shēng fèn）与生分（shēng fen）第二音节声调不同，意思是未经发酵的粪肥。", "生粉": "生粉（shēng fěn）与生分（shēng fen）第二音节声调不同，意思是淀粉。"}, "sentence_index": null, "correct_answer": "生分"}, "level_3": {"options": [{"text": "生分", "is_correct": true, "explanation": "“亲兄弟”与“却”形成转折，两人见面却疏远，只有“生分”符合语境。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不描述两人见面时的情形。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”不用于形容人与人之间的感情。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”指身体或物体牢固，与“见面”的情形不符。"}], "explanations": {"生分": "“亲兄弟”与“却”形成转折，两人见面却疏远，只有“生分”符合语境。", "清脆": "语义：“清脆”形容声音，不描述两人见面时的情形。", "干净": "搭配：“干净”不用于形容人与人之间的感情。", "结实": "语义：“结实”指身体或物体牢固，与“见面”的情形不符。"}, "sentence_index": 0, "correct_answer": "生分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他好几年没弹钢琴了，手指已经很生分。", "explanation": "这里应该用〈生疏〉。生分指人与人之间感情疏远，不用于形容技艺；手指不熟练要说生疏。"}, {"text": "这个城市我第一次来，对它还很生分。", "explanation": "这里应该用〈陌生〉。生分说的是感情疏远，不用于形容地方；初到一个城市要说陌生。"}, {"text": "他对这份工作一直很生分。", "explanation": "这里应该用〈冷淡〉。生分形容人际关系，对工作的态度要用冷淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89296, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "生分", "is_correct": true, "explanation": "生分（shēng fen）：感情疏远，不亲近。"}, {"text": "身份", "is_correct": false, "explanation": "身份（shēn fèn）与生分（shēng fen）的第一音节前鼻音和后鼻音不同（shēn/shēng），第二音节声调也不同。身份的意思是人的地位或资格。"}, {"text": "生风", "is_correct": false, "explanation": "生风（shēng fēng）与生分（shēng fen）的第二音节韵母不同（eng/en），声调也不同。生风的意思是起风，常说“虎虎生风”。"}, {"text": "升分", "is_correct": false, "explanation": "升分（shēng fēn）与生分（shēng fen）的第二音节一个读阴平，一个读轻声。升分的意思是分数提高。"}], "explanations": {"生分": "生分（shēng fen）：感情疏远，不亲近。", "身份": "身份（shēn fèn）与生分（shēng fen）的第一音节前鼻音和后鼻音不同（shēn/shēng），第二音节声调也不同。身份的意思是人的地位或资格。", "生风": "生风（shēng fēng）与生分（shēng fen）的第二音节韵母不同（eng/en），声调也不同。生风的意思是起风，常说“虎虎生风”。", "升分": "升分（shēng fēn）与生分（shēng fen）的第二音节一个读阴平，一个读轻声。升分的意思是分数提高。"}, "sentence_index": null, "correct_answer": "生分"}, "level_3": {"options": [{"text": "生分", "is_correct": true, "explanation": "“显得很”后接表示人际距离的形容词，且与“客客气气”的礼貌态度相符，只有“生分”合适。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容环境或物体的湿度，不描述人际关系。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”多用于物品的做工，不用于形容人与邻居之间的关系。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”指事理明白，与人际距离无关。"}], "explanations": {"生分": "“显得很”后接表示人际距离的形容词，且与“客客气气”的礼貌态度相符，只有“生分”合适。", "潮湿": "语义：“潮湿”形容环境或物体的湿度，不描述人际关系。", "精致": "搭配：“精致”多用于物品的做工，不用于形容人与邻居之间的关系。", "清楚": "语义：“清楚”指事理明白，与人际距离无关。"}, "sentence_index": 6, "correct_answer": "生分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用这个软件很久了，操作得很生分。", "explanation": "这里应该用〈生疏〉。生分指感情疏远，不用于形容操作技能；操作不熟练要说生疏。"}, {"text": "这台老机器我用了很久，对它很生分。", "explanation": "这里应该用〈熟悉〉。生分说的是人与人之间的感情疏远，不用于形容使用过的物品；对物品很熟悉要说熟悉。"}, {"text": "他做事很生分，从不偷懒。", "explanation": "这里应该用〈认真〉。生分形容人际关系，不形容做事的态度；做事不偷懒要说认真。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们多年没见，见面时有点生分得。", "corrected_sentence": "他们多年没见，见面时有点生分。", "error_description": "多余的“得”：形容词前已有“有点”作状语，形容词直接作谓语，不需要用“得”引出补语。应说“有点生分”，不能说“有点生分得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对我越来越很生分了。", "corrected_sentence": "他对我越来越生分了。", "error_description": "程度重复：“越来越”已表示程度的递进，不能再与“很”连用。应说“越来越生分了”，不能说“越来越很生分了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
