INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89297, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "找不到，不知道在哪里。", "primary_collocate": null, "pronunciation": "wú zhuó", "ipa": "u˧˥ ʈʂwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "小狗跑丢了，下落至今无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬家以后，行踪一直无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找了三天，孩子的下落还是无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老同学搬走以后，下落一直无着。", "target_word": "无着", "complexity_tier": "T3", "furigana": "nà wèi lǎo tóng xué bān zǒu yǐ hòu, xià luò yì zhí wú zhuó.", "sentence_source": "generated"}, {"text": "那位走失的登山者，至今下落无着。", "target_word": "无着", "complexity_tier": "T3", "furigana": "nà wèi zǒu shī de dēng shān zhě, zhì jīn xià luò wú zhuó.", "sentence_source": "generated"}, {"text": "警察找了很久，那个人的去向仍然无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年没有消息，老朋友的下落无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船出海一个月了，行踪无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只受伤的鹰飞走以后，行踪无着。", "target_word": "无着", "complexity_tier": "T3", "furigana": "nà zhī shòu shāng de yīng fēi zǒu yǐ hòu, xíng zōng wú zhuó.", "sentence_source": "generated"}, {"text": "那个离家出走的少年，至今下落无着。", "target_word": "无着", "complexity_tier": "T3", "furigana": "nà ge lí jiā chū zǒu de shào nián, zhì jīn xià luò wú zhuó.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "无着|找不到，下落不明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89297, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无着", "is_correct": true, "explanation": "正确：无着，指找不到下落，与“小狗跑丢了”的语境相符。"}, {"text": "明确", "is_correct": false, "explanation": "语义：“明确”指清楚确定，与“小狗跑丢了”、下落未知的语境相矛盾。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：“清晰”多修饰声音、图像、思路，不说“下落清晰”。"}, {"text": "稳定", "is_correct": false, "explanation": "搭配：“稳定”多修饰状态、局势，不说“下落稳定”。"}], "explanations": {"无着": "正确：无着，指找不到下落，与“小狗跑丢了”的语境相符。", "明确": "语义：“明确”指清楚确定，与“小狗跑丢了”、下落未知的语境相矛盾。", "清晰": "搭配：“清晰”多修饰声音、图像、思路，不说“下落清晰”。", "稳定": "搭配：“稳定”多修饰状态、局势，不说“下落稳定”。"}, "sentence_index": 0, "correct_answer": "无着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套家具的款式很无着，但质量很好。", "explanation": "这里应该用〈过时〉。无着指人或物下落不明、找不到，不用来形容款式陈旧。"}, {"text": "这件古董的来历无着，没人说得清。", "explanation": "这里应该用〈不明〉。无着只用于人或物的去向、下落，不用于说来历。"}, {"text": "这起事故的起因无着，调查还在继续。", "explanation": "这里应该用〈不详〉。无着只说去向或下落不明，不用来说原因不清。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无着", "is_correct": true, "explanation": "正确：无着，指找不到下落，与“多年没有消息”的语境相符。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”指明白确定，与“多年没有消息”的语境相矛盾。"}, {"text": "确切", "is_correct": false, "explanation": "语义：“确切”指准确可靠，与“没有消息”的情况不符。"}, {"text": "固定", "is_correct": false, "explanation": "搭配：“固定”多修饰位置、时间，不说“下落固定”。"}], "explanations": {"无着": "正确：无着，指找不到下落，与“多年没有消息”的语境相符。", "清楚": "语义：“清楚”指明白确定，与“多年没有消息”的语境相矛盾。", "确切": "语义：“确切”指准确可靠，与“没有消息”的情况不符。", "固定": "搭配：“固定”多修饰位置、时间，不说“下落固定”。"}, "sentence_index": 6, "correct_answer": "无着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗的节奏十分无着，读起来很别扭。", "explanation": "这里应该用〈凌乱〉。无着指人或物下落不明，不用来形容节奏。"}, {"text": "房间里的东西摆得十分无着。", "explanation": "这里应该用〈无序〉。无着指下落不明，不用来形容东西摆放得杂乱。"}, {"text": "他在国外一切都好，身体无着。", "explanation": "这里应该用〈无恙〉。无着不能用来说身体没有病痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子出门后再也没回来，至今下落无着着。", "corrected_sentence": "孩子出门后再也没回来，至今下落无着。", "error_description": "错误：“无着”后面多加了“着”。“无着”是形容词，不能再加“着”。正确说法：下落无着。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他离开以后，行踪很无着，大家都找不到他。", "corrected_sentence": "他离开以后，行踪无着，大家都找不到他。", "error_description": "错误：“无着”前面多加了“很”。“无着”表示下落不明，没有程度之分，不能受“很”修饰，应写成“行踪无着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
