INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89298, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有着落；没有依靠或找不到出路。", "primary_collocate": null, "pronunciation": "wú zhuó", "ipa": "u˧˥ ʈʂwɔ˧˥", "syllable_count": 2, "sentences": [{"text": "他丢了工作，生活一下子无着了。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱还没有到，这个月的费用仍然无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚到大城市，住处和工作都无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校没有钱，修路的经费一直无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司关门后，工人们的生活无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人没有家人，晚年生活无着，真让人担心。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱迟迟无着，工程只好停下来。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学费一直无着，他只好先去打工。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有亲人，毕业后工作也无着。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的生活无着，天天为吃饭发愁。", "target_word": "无着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "无着|没有着落，没有依靠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无着", "is_correct": true, "explanation": "正确：无着，没有着落，与“丢了工作”的语境相符。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指钱财充足，与“丢了工作”的困境相反。"}, {"text": "安定", "is_correct": false, "explanation": "语义：“安定”指平稳、有保障，与“丢了工作”后的处境矛盾。"}, {"text": "顺利", "is_correct": false, "explanation": "语义：“顺利”指进展没有阻碍，与“丢了工作”后的处境相反。"}], "explanations": {"无着": "正确：无着，没有着落，与“丢了工作”的语境相符。", "富裕": "语义：“富裕”指钱财充足，与“丢了工作”的困境相反。", "安定": "语义：“安定”指平稳、有保障，与“丢了工作”后的处境矛盾。", "顺利": "语义：“顺利”指进展没有阻碍，与“丢了工作”后的处境相反。"}, "sentence_index": 0, "correct_answer": "无着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他讲的笑话很无着，大家都没笑。", "explanation": "这里应该用〈无聊〉。无着说的是事情或生活没有着落、没有依靠，不表示笑话没有意思。"}, {"text": "她的字写得很无着，别人几乎看不懂。", "explanation": "这里应该用〈潦草〉。无着用于事情、经费、生活的没有着落，不用来形容字迹。"}, {"text": "这张桌子的腿十分无着，一碰就晃。", "explanation": "这里应该用〈松动〉。无着用于事情或生活没有着落，不用来形容物件连接是否牢固。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无着", "is_correct": true, "explanation": "正确：无着，没有着落，与“工程只好停下来”的因果相符。"}, {"text": "充裕", "is_correct": false, "explanation": "语义：“充裕”指数量足够，与“迟迟”未到的语境矛盾。"}, {"text": "有效", "is_correct": false, "explanation": "语义：“有效”指有作用、能生效，与“钱迟迟不到”的情况不符。"}, {"text": "稳定", "is_correct": false, "explanation": "搭配：“稳定”多修饰局势、状态，不说“钱稳定”。"}], "explanations": {"无着": "正确：无着，没有着落，与“工程只好停下来”的因果相符。", "充裕": "语义：“充裕”指数量足够，与“迟迟”未到的语境矛盾。", "有效": "语义：“有效”指有作用、能生效，与“钱迟迟不到”的情况不符。", "稳定": "搭配：“稳定”多修饰局势、状态，不说“钱稳定”。"}, "sentence_index": 6, "correct_answer": "无着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些旧报纸已经无着了，可以扔掉。", "explanation": "这里应该用〈无用〉。无着说事情、生活没有着落，不能用来说物品没有用处。"}, {"text": "他是无着的，不应该受到惩罚。", "explanation": "这里应该用〈无辜〉。无着形容事情或生活没有依靠，不能用来说一个人没有罪。"}, {"text": "他对这个行业很无着。", "explanation": "这里应该用〈无知〉。无着不表示缺少知识，“对……无知”才是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的店铺被烧毁以后，全家的生活一下子无着着了。", "corrected_sentence": "他的店铺被烧毁以后，全家的生活一下子无着了。", "error_description": "错误：“无着”后面多加了“着”。“无着”是形容词，不能再加表示动作持续的“着”。正确说法：无着了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子的田地被淹以后，农民们的生计没无着。", "corrected_sentence": "这个村子的田地被淹以后，农民们的生计无着。", "error_description": "错误：“无着”前面多加了“没”。“无着”的“无”已经表示否定，不能再加“没”。正确说法：生计无着。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
