INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物理量的最小不可分割的基本单位，微观世界中能量等的最小份额。", "primary_collocate": null, "pronunciation": "liàng zǐ", "ipa": "ljɑŋ˥˩ tsɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "量子是能量最小的、不能再分的单位。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普朗克在一九零零年提出了量子的想法。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光的能量是一份一份的，每一份就是一个量子。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱因斯坦用量子解释了光电效应。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在微观世界里，能量只能一个量子一个量子地变化。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家发现，原子放出能量时，一次放出一个量子。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个量子带着的能量，和光的颜色有关系。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公式可以算出一个量子有多少能量。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯越亮，放出的量子就越多。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理书上说，能量的最小份额叫量子。", "target_word": "量子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个量子", "label": "量词搭配：个"}, {"form": "量子力学", "label": "复合词"}, {"form": "量子计算机", "label": "复合词"}], "register": "书面", "sense_fingerprint": "量子：物理学中能量等物理量的最小不可分割单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89300, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "量子", "is_correct": true, "explanation": "量子：物理学中能量的最小不可分割单位，与句中的定义相符。"}, {"text": "米", "is_correct": false, "explanation": "语义：“米”是长度单位，不是能量的最小单位，与句意矛盾。"}, {"text": "千克", "is_correct": false, "explanation": "语义：“千克”是质量单位，不是能量的最小单位，与句意矛盾。"}, {"text": "原子", "is_correct": false, "explanation": "语义：“原子”是构成物质的粒子，不是能量最小的单位，与句意不符。"}], "explanations": {"量子": "量子：物理学中能量的最小不可分割单位，与句中的定义相符。", "米": "语义：“米”是长度单位，不是能量的最小单位，与句意矛盾。", "千克": "语义：“千克”是质量单位，不是能量的最小单位，与句意矛盾。", "原子": "语义：“原子”是构成物质的粒子，不是能量最小的单位，与句意不符。"}, "sentence_index": 0, "correct_answer": "量子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的量子很重，搬不动。", "explanation": "这里应该用〈重量〉。“量子”指能量的最小份额，不能表示物体的轻重，石头重要说“重量”。"}, {"text": "这本书的量子很多，我一天看不完。", "explanation": "这里应该用〈页数〉。“量子”指能量的最小份额，不能表示书的页数。"}, {"text": "他用量子测量了体温。", "explanation": "这里应该用〈温度计〉。“量子”不是测量仪器，测体温要用温度计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "量子", "is_correct": true, "explanation": "量子：能量的最小份额，与“带着的能量和光的颜色有关”相符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不是能量的单位，不能带着能量与光的颜色有关。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是机械零件，与光的颜色和能量的最小份额无关。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“声音”与光的颜色没有这种对应关系，说声音带着能量与光的颜色有关，搭配不当。"}], "explanations": {"量子": "量子：能量的最小份额，与“带着的能量和光的颜色有关”相符。", "房间": "语义：房间不是能量的单位，不能带着能量与光的颜色有关。", "螺丝": "语义：螺丝是机械零件，与光的颜色和能量的最小份额无关。", "声音": "搭配：“声音”与光的颜色没有这种对应关系，说声音带着能量与光的颜色有关，搭配不当。"}, "sentence_index": 6, "correct_answer": "量子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果的量子很大。", "explanation": "这里应该用〈质量〉。“量子”指能量的最小份额，不能用来说苹果的重量。"}, {"text": "这个箱子的量子很大，装不下。", "explanation": "这里应该用〈体积〉。“量子”不表示物体占据空间的大小，箱子大要说“体积”。"}, {"text": "这台机器的量子很大，需要很多电。", "explanation": "这里应该用〈能量〉。“量子”指能量的最小份额，不能用来说机器能量的多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个实验测到了一条量子的能量。", "corrected_sentence": "这个实验测到了一个量子的能量。", "error_description": "量词错误：“量子”应搭配“个”，说“一个量子”；“条”用于细长的东西，不能用于量子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员测量了一本量子的能量。", "corrected_sentence": "研究人员测量了一个量子的能量。", "error_description": "量词错误：“量子”应搭配“个”，说“一个量子”；“本”用于书籍等，不能用于量子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
