INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "移民是搬到别的国家去长久住。", "primary_collocate": null, "pronunciation": "yí mín", "ipa": "i˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "我姐姐去年移民到了美国,不打算回来了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想带着家人移民到新西兰。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人毕业后选择移民到澳大利亚。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们邻居三年前就移民德国了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是有机会,你愿意移民到别的国家吗?", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的叔叔移民法国以后,开了一家中餐馆。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小在日本长大,后来跟着父母移民到了中国。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都劝他不要移民,可是他已经决定了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办好手续以后,他们就可以移民了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同学的全家都移民去了加拿大。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移民了", "label": "体标"}, {"form": "移民过", "label": "体标"}, {"form": "移民局", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词:搬到别的国家长久居住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9529bd-5bd4-47cc-94ca-e0bf014980b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移民", "is_correct": true, "explanation": "移民指长期迁居到另一个国家，与“不打算回来了”的语境相符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”指短期游玩，与“不打算回来了”所表达的长期留居相矛盾。"}, {"text": "回国", "is_correct": false, "explanation": "搭配：“回国”指返回本国，与“到了美国”的去向及“不打算回来了”相矛盾。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问”指短暂拜访，与长期不回来的语境不符。"}], "explanations": {"移民": "移民指长期迁居到另一个国家，与“不打算回来了”的语境相符。", "旅游": "语义：“旅游”指短期游玩，与“不打算回来了”所表达的长期留居相矛盾。", "回国": "搭配：“回国”指返回本国，与“到了美国”的去向及“不打算回来了”相矛盾。", "访问": "语义：“访问”指短暂拜访，与长期不回来的语境不符。"}, "sentence_index": 0, "correct_answer": "移民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去年移民，只在德国待了两个星期。", "explanation": "这里应该用〈出国〉。移民指长期定居，只待两个星期的短期出国不能用“移民”。"}, {"text": "她每天都移民，所以很累。", "explanation": "移民是一次性的长期迁居，不能每天重复发生。"}, {"text": "他把书架移民到了客厅。", "explanation": "这里应该用〈搬〉。移民只用于人迁居到另一地长久居住，书架不能移民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移民", "is_correct": true, "explanation": "移民指迁居到另一个国家长期居住，与“从小在日本长大，后来跟着父母到了中国”的语境相符。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”指短期观光，与从小长大后长期定居的情形不符。"}, {"text": "购物", "is_correct": false, "explanation": "语义：“购物”指买东西，不能表示迁到另一个国家长期居住，也不能说“购物到了中国”。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公短期外出，与“从小在日本长大”后长期定居的语境矛盾。"}], "explanations": {"移民": "移民指迁居到另一个国家长期居住，与“从小在日本长大，后来跟着父母到了中国”的语境相符。", "游览": "语义：“游览”指短期观光，与从小长大后长期定居的情形不符。", "购物": "语义：“购物”指买东西，不能表示迁到另一个国家长期居住，也不能说“购物到了中国”。", "出差": "语义：“出差”指因公短期外出，与“从小在日本长大”后长期定居的语境矛盾。"}, "sentence_index": 6, "correct_answer": "移民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末去博物馆移民。", "explanation": "这里应该用〈参观〉。移民指搬到别的国家长久居住，去博物馆看展览不能用“移民”。"}, {"text": "他把工作移民到了别的公司。", "explanation": "移民只用于人搬到另一个国家长久居住，工作这类事物不能移民。"}, {"text": "这群候鸟每年都移民到南方。", "explanation": "这里应该用〈迁徙〉。移民只用于人，候鸟群体的迁移应当用〈迁徙〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的老师去年移民局到了荷兰。", "corrected_sentence": "我的老师去年移民到了荷兰。", "error_description": "“移民局”是名词（政府机构），不能充当谓语；应为动词“移民”，即“我的老师去年移民到了荷兰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我侄子两年前移民过到了法国。", "corrected_sentence": "我侄子两年前移民到了法国。", "error_description": "“移民”后面加“过”表示曾经发生，与“到了法国”表示已完成的迁居相矛盾。正确说法是“我侄子两年前移民到了法国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
