INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迁居到外国或外地长期居住。", "primary_collocate": null, "pronunciation": "yí mín", "ipa": "i˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "他们一家十年前移民到了加拿大。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的表哥打算明年移民澳大利亚。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了孩子的教育,他们决定移民。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她已经移民国外很多年了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了建水库,村里的人全都移民到了外省。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外住了很久,后来决定移民,不回来了。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友移民到英国以后,很少回国。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说去年有很多人移民去了新加坡。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷年轻时从北方移民到了南方。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想移民,所以正在学习英语。", "target_word": "移民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "移民了", "label": "体标"}, {"form": "移民过", "label": "体标"}, {"form": "移民潮", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词:迁居到外国或外地并长期居住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9529bd-5bd4-47cc-94ca-e0bf014980b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "移民", "is_correct": true, "explanation": "移民指迁居到外国或外地长期居住，与“一家十年前到了加拿大”的语境相符。"}, {"text": "回国", "is_correct": false, "explanation": "搭配：“回国”指返回自己的国家，不能与“到了加拿大”这种去往他国的去向搭配。"}, {"text": "访问", "is_correct": false, "explanation": "语义：“访问”指短暂拜访，不能表示一家人长期定居在某地。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公短期外出，与“一家十年前”的长期定居不符。"}], "explanations": {"移民": "移民指迁居到外国或外地长期居住，与“一家十年前到了加拿大”的语境相符。", "回国": "搭配：“回国”指返回自己的国家，不能与“到了加拿大”这种去往他国的去向搭配。", "访问": "语义：“访问”指短暂拜访，不能表示一家人长期定居在某地。", "出差": "语义：“出差”指因公短期外出，与“一家十年前”的长期定居不符。"}, "sentence_index": 0, "correct_answer": "移民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我这次移民，只是去参加一个会议。", "explanation": "这里应该用〈出国〉。移民指长期定居，只为参加会议的短期外出不能用“移民”。"}, {"text": "他们把家具移民到了卧室。", "explanation": "移民只用于人迁居到国外或外地，家具不能移民。"}, {"text": "他上个月移民到了新小区。", "explanation": "这里应该用〈搬〉。移民指迁居到国外或外地长期居住，同一座城市里换小区不能说移民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "移民", "is_correct": true, "explanation": "移民指迁居到外国长期居住，与“朋友移民到英国以后很少回国”的语境相符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”指短期游览，与“很少回国”所说的长期定居不相符。"}, {"text": "派遣", "is_correct": false, "explanation": "搭配：“派遣”需要有派遣的一方，朋友不能自己派遣自己到英国。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指短时间的步行，不能用来指迁居到另一个国家。"}], "explanations": {"移民": "移民指迁居到外国长期居住，与“朋友移民到英国以后很少回国”的语境相符。", "旅游": "语义：“旅游”指短期游览，与“很少回国”所说的长期定居不相符。", "派遣": "搭配：“派遣”需要有派遣的一方，朋友不能自己派遣自己到英国。", "散步": "语义：“散步”指短时间的步行，不能用来指迁居到另一个国家。"}, "sentence_index": 6, "correct_answer": "移民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他暑假回老家移民。", "explanation": "这里应该用〈探亲〉。移民指长期迁居，回老家看望亲人不能用“移民”。"}, {"text": "学校把我们班的同学都移民到了别的教室。", "explanation": "移民指迁居到国外或外地长期居住，班级之间的调动不能用“移民”。"}, {"text": "这群候鸟每年都移民到南方过冬。", "explanation": "这里应该用〈迁徙〉。移民只用于人，候鸟群体的迁移应当用〈迁徙〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我叔叔去年很移民到了德国。", "corrected_sentence": "我叔叔去年移民到了德国。", "error_description": "“很”是程度副词，一般修饰形容词，不能直接修饰动词“移民”。正确说法是“我叔叔去年移民到了德国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹两年前把移民到了美国。", "corrected_sentence": "我妹妹两年前移民到了美国。", "error_description": "“把”字句需要一个被处置的宾语，这里“移民”后没有宾语，结构不成立。正确说法是“我妹妹两年前移民到了美国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
