INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89303, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用字是写文章时用了哪些字。", "primary_collocate": null, "pronunciation": "yòng zì", "ipa": "yʊŋ˥˩ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "请看一下，这封信的用字有没有问题。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写作文时，你的用字要小心。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的作文用字不多，但是很清楚。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸的用字一般比较容易懂。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的用字很特别，我很喜欢。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们说说诗里的用字好在哪里。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写东西，用字总是很简洁。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌词的用字很美。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的用字还不多，句子都很短。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇短文的用字很简单，小孩也能看懂。", "target_word": "用字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "写文章时所用的字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90443c19-7a61-476e-90a3-d5c5a7345015') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89303, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用字", "is_correct": true, "explanation": "正确。“这封信的用字”指信中选用的字，与“有没有问题”相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：信没有年龄，“这封信的年龄有没有问题”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：信的温度与选字无关，句意不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，用在请人检查书面用字的句子里不合语域，且语义不通。"}], "explanations": {"用字": "正确。“这封信的用字”指信中选用的字，与“有没有问题”相合。", "年龄": "语义：信没有年龄，“这封信的年龄有没有问题”说不通。", "温度": "语义：信的温度与选字无关，句意不通。", "玩意儿": "语域：“玩意儿”是口语，用在请人检查书面用字的句子里不合语域，且语义不通。"}, "sentence_index": 0, "correct_answer": "用字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的用字很便宜。", "explanation": "这里应该用〈价格〉。用字指写作时选用的字，不能用来说东西贵不贵，要用〈价格〉。"}, {"text": "这间房子的用字很宽敞。", "explanation": "这里应该用〈面积〉。用字指写作时选用的字，说房间大小要用〈面积〉。"}, {"text": "他的用字很潦草，老师看不清楚。", "explanation": "这里应该用〈字迹〉。潦草说的是字的书写，用字指选用哪些字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用字", "is_correct": true, "explanation": "正确。“用字”指写东西时选用的字，“很简洁”与之相合。"}, {"text": "车速", "is_correct": false, "explanation": "语义：车速是车辆的行驶速度，与写东西无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人或物的重量，与写东西时的选字无关。"}, {"text": "声调", "is_correct": false, "explanation": "搭配：“简洁”说文字、语言，不说声调。"}], "explanations": {"用字": "正确。“用字”指写东西时选用的字，“很简洁”与之相合。", "车速": "语义：车速是车辆的行驶速度，与写东西无关，句意不通。", "体重": "语义：体重是人或物的重量，与写东西时的选字无关。", "声调": "搭配：“简洁”说文字、语言，不说声调。"}, "sentence_index": 6, "correct_answer": "用字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的用字很鲜艳，很吸引人。", "explanation": "这里应该用〈用色〉。绘画中选用颜色要说用色；用字只指写作时选字。"}, {"text": "这个字的用字是木字旁，所以和树木有关。", "explanation": "这里应该用〈部首〉。用字讲的是选用哪些字，不能用来说字的部首。"}, {"text": "这张桌子的用字很讲究。", "explanation": "这里应该用〈用料〉。用字只用于写作选字，家具的材料要说用料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告的用字得很讲究。", "corrected_sentence": "这份报告的用字很讲究。", "error_description": "错误形式是“用字得很讲究”，正确形式是“用字很讲究”。名词“用字”作主语，后面直接用“很讲究”作谓语，不能插入结构助词“得”；“得”只用于动词或形容词之后引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作者在用字很用心。", "corrected_sentence": "作者在用字上很用心。", "error_description": "错误形式是“在用字很用心”，正确形式是“在用字上很用心”。“在……上”格式表示在某方面，“用字”后面要加方位词“上”，不能缺少。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
