INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89305, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家想法不一样，你说你的，我说我的，吵起来。", "primary_collocate": null, "pronunciation": "zhēng lùn", "ipa": "ʈʂɤŋ˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "他们为小事争论起来，谁也不让谁。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个孩子为玩具争论不休。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们别在这儿争论了，小声点儿。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸妈妈为钱的事争论了一晚上。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想和你争论，你说什么都对。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在会上争论得很厉害，声音越来越大。", "target_word": "争论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了一个座位，在车上争论得很激烈。", "target_word": "争论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别争论了，我们先吃饭吧。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他俩一见面就争论，从来没有好好说过话。", "target_word": "争论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们争论了半天，最后谁也没说服谁。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "争论了", "label": "完成体"}, {"form": "争论过", "label": "经历体"}, {"form": "争论着", "label": "持续体"}, {"form": "爭論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "争论：想法不同，各说各的，吵起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e7e323-496a-4e04-9d9e-25a70cdf1aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "争论", "is_correct": true, "explanation": "争论：各执己见、吵起来，与“为小事”引发的争执和“谁也不让谁”的态度相合。"}, {"text": "合作", "is_correct": false, "explanation": "语义：合作要求双方协调配合，与“谁也不让谁”的对立局面相反。"}, {"text": "让步", "is_correct": false, "explanation": "语义：让步就是退让，与句中“谁也不让谁”直接矛盾。"}, {"text": "道歉", "is_correct": false, "explanation": "搭配：“道歉起来”表示认错，与“谁也不让谁”的态度不搭配。"}], "explanations": {"争论": "争论：各执己见、吵起来，与“为小事”引发的争执和“谁也不让谁”的态度相合。", "合作": "语义：合作要求双方协调配合，与“谁也不让谁”的对立局面相反。", "让步": "语义：让步就是退让，与句中“谁也不让谁”直接矛盾。", "道歉": "搭配：“道歉起来”表示认错，与“谁也不让谁”的态度不搭配。"}, "sentence_index": 0, "correct_answer": "争论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都没有意见，只用了五分钟就争论完了。", "explanation": "这里应该用〈商量〉。争论是各执己见、互相辩驳，大家没有分歧时只能说商量，不能说争论。"}, {"text": "这件事大家早已达成共识，会议上只是例行争论了一下。", "explanation": "这里应该用〈确认〉。争论是各执己见、互不相让，大家早已达成共识时只能说确认，不能说争论。"}, {"text": "老师说完，大家都表示认同，没有人提出异议，却纷纷争论起来。", "explanation": "这里应该用〈赞同〉。争论指各执己见，大家都表示认同时只能说赞同，不能说争论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争论", "is_correct": true, "explanation": "争论：各不相让地争执，与“为了一个座位……很激烈”的争抢场面相合。"}, {"text": "谦让", "is_correct": false, "explanation": "语义：谦让是互相让着，与“很激烈”的争抢状态相反。"}, {"text": "调解", "is_correct": false, "explanation": "语义：调解需要第三方从中调和，而句中“他们”正是争座位的当事人，不能作调解者。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃座位意味着不再争，与“争得很激烈”矛盾。"}], "explanations": {"争论": "争论：各不相让地争执，与“为了一个座位……很激烈”的争抢场面相合。", "谦让": "语义：谦让是互相让着，与“很激烈”的争抢状态相反。", "调解": "语义：调解需要第三方从中调和，而句中“他们”正是争座位的当事人，不能作调解者。", "放弃": "语义：放弃座位意味着不再争，与“争得很激烈”矛盾。"}, "sentence_index": 6, "correct_answer": "争论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们听了老师的笑话，一起争论起来，笑得前仰后合。", "explanation": "这里应该用〈欢笑〉。争论是各执己见、互不相让，不能用来形容笑得前仰后合的情景。"}, {"text": "他默默地坐着，一句话也没说，却争论得很激烈。", "explanation": "这里应该用〈沉默〉。争论需要双方发表意见，一句话也不说时不能说争论得很激烈。"}, {"text": "他向大家微微一笑，说了声“再见”，就转身走出了教室，却又和大家争论起来。", "explanation": "这里应该用〈离开〉。人已经走出教室，就不可能再和大家当面争论；争论要求双方在场、各执己见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我他争论了半天，谁也没说服谁。", "corrected_sentence": "我跟他争论了半天，谁也没说服谁。", "error_description": "“争论”不能直接带人作宾语，与人争论要用介词“跟”引出对象：漏掉“跟”，应说“我跟他争论了半天”，不说“我他争论了半天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在电话里争论地很激烈。", "corrected_sentence": "他们在电话里争论得很激烈。", "error_description": "争论后接程度补语要用助词“得”，不能用“地”。正确：争论得很激烈；错误：争论地很激烈。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
