INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "各执己见，互相辩论。", "primary_collocate": null, "pronunciation": "zhēng lùn", "ipa": "ʈʂɤŋ˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "专家们对这个问题争论了很久。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学者们在会上争论教育该不该改革。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网友们在网上争论这件事该怎么办。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家各说各的理由，争论了一个下午。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两位老师对作文怎么评分争论起来。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们争论的问题，到现在也没有答案。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们争论着谁的办法更好。", "target_word": "争论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在课上争论过这个问题。", "target_word": "争论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不要争论了，先查一下资料吧。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人各有各的看法，争论得没完没了。", "target_word": "争论", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "争论了", "label": "完成体"}, {"form": "争论过", "label": "经历体"}, {"form": "争论着", "label": "持续体"}, {"form": "爭論", "label": "繁体"}], "register": "中性", "sense_fingerprint": "争论：各执己见，就问题互相辩论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e7e323-496a-4e04-9d9e-25a70cdf1aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "争论", "is_correct": true, "explanation": "争论：各执己见、互相辩论，与“对这个问题……很久”相合。"}, {"text": "同意", "is_correct": false, "explanation": "配价：“同意”后要带具体内容的宾语，不能在“对……”后独立做谓语并接“很久”。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“专家们”讨论学术问题，“嘲笑”与严肃的学术态度相冲突。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是人，不能说“对这个问题感谢”。"}], "explanations": {"争论": "争论：各执己见、互相辩论，与“对这个问题……很久”相合。", "同意": "配价：“同意”后要带具体内容的宾语，不能在“对……”后独立做谓语并接“很久”。", "嘲笑": "语义：“专家们”讨论学术问题，“嘲笑”与严肃的学术态度相冲突。", "感谢": "搭配：“感谢”的对象是人，不能说“对这个问题感谢”。"}, "sentence_index": 0, "correct_answer": "争论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到好消息后争论起来，高兴得跳了起来。", "explanation": "这里应该用〈欢呼〉。争论是各执己见、互相辩驳，表达高兴时不能说争论，应说欢呼。"}, {"text": "老师把这道题的解法讲得很清楚，大家都听懂了，没有人提出疑问，却争论起来。", "explanation": "这里应该用〈讲解〉。解法讲清楚、大家都听懂后就没有分歧，不能说争论起来；争论是各执己见。"}, {"text": "这两个人一句话都没有说，却争论了整整一个下午。", "explanation": "这里应该用〈沉默〉。争论需要双方发表意见，一句话也不说时不能说争论了一个下午。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争论", "is_correct": true, "explanation": "争论：各执己见地辩论，与“谁的办法更好”的比较相合。"}, {"text": "合作", "is_correct": false, "explanation": "语义：合作是共同做事，与“谁的办法更好”的比较判断不相容。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃就是不再争，与“争……谁的办法更好”的评判过程矛盾。"}, {"text": "夸奖", "is_correct": false, "explanation": "配价：“夸奖”要带受夸的人作宾语，不能说“夸奖着谁的办法更好”。"}], "explanations": {"争论": "争论：各执己见地辩论，与“谁的办法更好”的比较相合。", "合作": "语义：合作是共同做事，与“谁的办法更好”的比较判断不相容。", "放弃": "语义：放弃就是不再争，与“争……谁的办法更好”的评判过程矛盾。", "夸奖": "配价：“夸奖”要带受夸的人作宾语，不能说“夸奖着谁的办法更好”。"}, "sentence_index": 6, "correct_answer": "争论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都赞同他的意见，纷纷争论起来。", "explanation": "这里应该用〈附和〉。争论是各执己见、互相辩驳；大家都赞同他时只能说附和，不能说争论。"}, {"text": "同学们轮流争论课文，每个人都读得很清楚。", "explanation": "这里应该用〈朗读〉。争论是各执己见、互相辩驳，不是念课文；念课文要用朗读。"}, {"text": "他在台上争论了自己的经历，大家听得很感动。", "explanation": "这里应该用〈叙述〉。争论是辩驳，不是讲述经历，讲述往事要用叙述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和他争论了过这个问题。", "corrected_sentence": "我和他争论过这个问题。", "error_description": "“争论”后的体标“过”已表示经历，不能再加“了”。“了”和“过”不能同时出现在动词后，应说“争论过这个问题”，不说“争论了过这个问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天不争论过这个问题。", "corrected_sentence": "我们昨天没争论过这个问题。", "error_description": "经历体的否定要用“没”，不能用“不”。“争论过”表示经历，否定应说“没争论过”，不说“不争论过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
