INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89307, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "错爱是别人太喜欢你，其实你不值得。是客气话。", "primary_collocate": null, "pronunciation": "cuò ài", "ipa": "tsʰwo˥˩ ai˥˩", "syllable_count": 2, "sentences": [{"text": "谢谢您错爱我。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您太错爱我了，我不敢当。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板错爱我，我一定努力工作。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家这样错爱我，我真不好意思。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您这样错爱我，我心里不安。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "承蒙您错爱，我很感动。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有那么好，谢谢您错爱。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢朋友们这么错爱我。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师这样错爱我，我怕做不好。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您错爱我，我只能多做事来感谢。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "错爱了", "label": "体标"}, {"form": "錯愛", "label": "繁体"}], "register": "礼貌", "sense_fingerprint": "客气话：对方过分喜爱自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "错爱", "is_correct": true, "explanation": "错爱：对方过分喜爱自己，是客气话，符合「谢谢您」的语境。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：「讨厌」表示不喜欢，与「谢谢您」的感激语境相反。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：「冷落」表示怠慢、不关心，与对方的好意相反。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：「放弃」表示不再坚持，不能用来指对方对「我」的态度。"}], "explanations": {"错爱": "错爱：对方过分喜爱自己，是客气话，符合「谢谢您」的语境。", "讨厌": "语义：「讨厌」表示不喜欢，与「谢谢您」的感激语境相反。", "冷落": "语义：「冷落」表示怠慢、不关心，与对方的好意相反。", "放弃": "搭配：「放弃」表示不再坚持，不能用来指对方对「我」的态度。"}, "sentence_index": 0, "correct_answer": "错爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很错爱他的帮助。", "explanation": "这里应该用〈感激〉。错爱指别人对我的过分喜爱，对别人的帮助要说感激。"}, {"text": "我很错爱远方的父母。", "explanation": "这里应该用〈思念〉。错爱指对方对我的过分喜爱，表示我想念远方的父母要说思念。"}, {"text": "他错爱了我的意思。", "explanation": "这里应该用〈误会〉。错爱指对方过分喜爱我，把别人的意思理解错要说误会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错爱", "is_correct": true, "explanation": "错爱：对方过分喜爱自己，是客气话，符合「谢谢您」的语境。"}, {"text": "吓唬", "is_correct": false, "explanation": "语义：「吓唬」表示使人害怕，与「我没有那么好」后的感谢语境不符。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：「忽视」表示不重视，与感谢的语境相反。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：「欺负」表示欺凌刁难，与「谢谢您」的感激语境相反。"}], "explanations": {"错爱": "错爱：对方过分喜爱自己，是客气话，符合「谢谢您」的语境。", "吓唬": "语义：「吓唬」表示使人害怕，与「我没有那么好」后的感谢语境不符。", "忽视": "语义：「忽视」表示不重视，与感谢的语境相反。", "欺负": "语义：「欺负」表示欺凌刁难，与「谢谢您」的感激语境相反。"}, "sentence_index": 6, "correct_answer": "错爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师错爱了我的失误。", "explanation": "这里应该用〈原谅〉。错爱表示对方过分的喜爱，不表示宽恕过失，宽恕过失要说原谅。"}, {"text": "她错爱我的动机。", "explanation": "这里应该用〈怀疑〉。错爱表示对方的喜爱，不表示对动机的怀疑，此处要说怀疑。"}, {"text": "他错爱了那只杯子。", "explanation": "这里应该用〈喜欢〉。错爱只用于人对人的过分爱护，对物品的喜爱要说喜欢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谢谢您一直错爱把我。", "corrected_sentence": "谢谢您一直错爱我。", "error_description": "语序错误：多出「把」字。错误形式是「错爱把我」，「把」不能插在动词「错爱」与宾语「我」之间；正确形式是「错爱我」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "感谢您的错爱了，我很感动。", "corrected_sentence": "感谢您的错爱，我很感动。", "error_description": "错误形式是「您的错爱了」，正确形式是「您的错爱」。「了」表示动作完成，不能加在名词化的「错爱」后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
