INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89308, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "谦辞，称对方过分的爱护或厚待。", "primary_collocate": null, "pronunciation": "cuò ài", "ipa": "tsʰwo˥˩ ai˥˩", "syllable_count": 2, "sentences": [{"text": "承蒙校长错爱，我才有这个机会。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感谢各位错爱，我会尽力做好。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蒙您错爱，我一定不让您失望。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您如此错爱，晚辈不胜感激。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "承蒙领导错爱，让我担任这个工作。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生错爱，我实在不敢接受。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感谢您一直以来的错爱，我深感荣幸。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老前辈错爱我，我很不敢当。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "承蒙各位错爱，这本书才有今天。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多谢您错爱，我会继续学习。", "target_word": "错爱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "错爱了", "label": "体标"}, {"form": "錯愛", "label": "繁体"}], "register": "书面", "sense_fingerprint": "谦辞：称对方对自己过分爱护厚待", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "错爱", "is_correct": true, "explanation": "错爱：谦辞，称对方过分的爱护或厚待，符合「承蒙」的语境。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：「冷落」表示怠慢，与「承蒙」所表示的恩惠相反。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：「忽略」表示不在意，无法带来「有这个机会」的结果。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：「承蒙」后面常接表示恩惠的动词，「嘲笑」是贬义动作，两者不搭配。"}], "explanations": {"错爱": "错爱：谦辞，称对方过分的爱护或厚待，符合「承蒙」的语境。", "冷落": "语义：「冷落」表示怠慢，与「承蒙」所表示的恩惠相反。", "忽略": "语义：「忽略」表示不在意，无法带来「有这个机会」的结果。", "嘲笑": "搭配：「承蒙」后面常接表示恩惠的动词，「嘲笑」是贬义动作，两者不搭配。"}, "sentence_index": 0, "correct_answer": "错爱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很错爱这份礼物。", "explanation": "这里应该用〈感谢〉。错爱是对方对我的过分爱护的谦辞，对别人送的礼物要说感谢。"}, {"text": "我很错爱自己的孩子。", "explanation": "这里应该用〈疼爱〉。错爱是称对方对自己过分爱护的谦辞，不能用于自己对孩子的爱，此处要说疼爱。"}, {"text": "我很错爱这首诗。", "explanation": "这里应该用〈欣赏〉。错爱是对方对我的过分爱护，对作品的欣赏要说欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错爱", "is_correct": true, "explanation": "错爱：名词化后指过分的爱护，符合「感谢您一直以来的」的语境。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：「冷淡」表示态度疏远，与「深感荣幸」的感激语境相反。"}, {"text": "怨恨", "is_correct": false, "explanation": "语义：「怨恨」表示恨，与「感谢」的语境相反。"}, {"text": "轻视", "is_correct": false, "explanation": "搭配：「感谢」的对象应是善意，不能与「轻视」搭配。"}], "explanations": {"错爱": "错爱：名词化后指过分的爱护，符合「感谢您一直以来的」的语境。", "冷淡": "语义：「冷淡」表示态度疏远，与「深感荣幸」的感激语境相反。", "怨恨": "语义：「怨恨」表示恨，与「感谢」的语境相反。", "轻视": "搭配：「感谢」的对象应是善意，不能与「轻视」搭配。"}, "sentence_index": 6, "correct_answer": "错爱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她很错爱这件衣服。", "explanation": "这里应该用〈喜爱〉。错爱是称对方对自己过分爱护的谦辞，不表示自己对物品的喜欢，此处要说喜爱。"}, {"text": "领导很错爱群众的呼声。", "explanation": "这里应该用〈重视〉。错爱是对方过分爱护我的谦辞，不能用于领导对群众呼声的态度，要说重视。"}, {"text": "我认真错爱这个问题。", "explanation": "这里应该用〈思考〉。错爱表示过分的爱护，不能用于对问题的思考，此处要说思考。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "承蒙老师错爱地，我很惭愧。", "corrected_sentence": "承蒙老师错爱，我很惭愧。", "error_description": "「地」用来修饰其后的动词，而「错爱地」之后并无动词，句子残缺。错误形式是「错爱地」，正确形式是「错爱」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "承蒙您的错爱了，我深感荣幸。", "corrected_sentence": "承蒙您的错爱，我深感荣幸。", "error_description": "错误形式是「您的错爱了」，正确形式是「您的错爱」。「了」表示动作完成，不能加在名词化的「错爱」后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代：过去的时代，与“我们现在生活的时代”相对，是时间上的反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "与“当代”没有反义关系，是具体的家具名词。"}, {"text": "河流", "is_correct": false, "explanation": "与“当代”没有反义关系，是自然地理名词。"}, {"text": "手套", "is_correct": false, "explanation": "与“当代”没有反义关系，是具体的衣物名词。"}], "correct_answer": "古代", "explanations": {"古代": "古代：过去的时代，与“我们现在生活的时代”相对，是时间上的反义词。", "桌子": "与“当代”没有反义关系，是具体的家具名词。", "河流": "与“当代”没有反义关系，是自然地理名词。", "手套": "与“当代”没有反义关系，是具体的衣物名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代：过去的时代，与“我们现在生活的时代”相对，是时间上的反义词。"}, {"text": "石头", "is_correct": false, "explanation": "与“当代”没有反义关系，是自然物名词。"}, {"text": "黑板", "is_correct": false, "explanation": "与“当代”没有反义关系，是教学用具名词。"}, {"text": "雨伞", "is_correct": false, "explanation": "与“当代”没有反义关系，是日用品名词。"}], "correct_answer": "古代", "explanations": {"古代": "古代：过去的时代，与“我们现在生活的时代”相对，是时间上的反义词。", "石头": "与“当代”没有反义关系，是自然物名词。", "黑板": "与“当代”没有反义关系，是教学用具名词。", "雨伞": "与“当代”没有反义关系，是日用品名词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "我们现在生活的这个时代。", "primary_collocate": null, "pronunciation": "dāng dài", "ipa": "taŋ˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们生活在当代，用手机很方便。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在当代，很多人都有手机。", "target_word": "当代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代的人骑马，当代的人坐飞机。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代的孩子比以前的孩子知道得多。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生活在当代的我们，应该好好儿学习。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些问题，当代的我们都要面对。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在当代，坐飞机去外国已经不难了。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想知道古代和当代有什么不同。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代的生活比过去好多了。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在当代，人们每天都用网络聊天。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "当代人", "label": "复合"}, {"form": "当代史", "label": "复合"}, {"form": "當代", "label": "繁体"}], "register": "书面", "sense_fingerprint": "当代：我们现在生活的时代，常与古代、过去相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e7e323-496a-4e04-9d9e-25a70cdf1aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当代", "is_correct": true, "explanation": "当代：我们现在生活的时代，与“用手机很方便”的语境相合。"}, {"text": "石器时代", "is_correct": false, "explanation": "语义：石器时代没有手机，与“用手机很方便”直接矛盾。"}, {"text": "清朝", "is_correct": false, "explanation": "语义：清朝没有手机，与“用手机很方便”的语境矛盾。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“生活在”后接时代或地点，不能接“星期”。"}], "explanations": {"当代": "当代：我们现在生活的时代，与“用手机很方便”的语境相合。", "石器时代": "语义：石器时代没有手机，与“用手机很方便”直接矛盾。", "清朝": "语义：清朝没有手机，与“用手机很方便”的语境矛盾。", "星期": "搭配：“生活在”后接时代或地点，不能接“星期”。"}, "sentence_index": 0, "correct_answer": "当代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的祖先在当代就发明了造纸术。", "explanation": "这里应该用〈古代〉。祖先生活在过去，“当代”指现在，不能说祖先在当代发明了造纸术。"}, {"text": "我小时候，当代的孩子还没有电脑。", "explanation": "这里应该用〈当时〉。当代指现在这个时代，不能指我小时候的那段时间。"}, {"text": "这件文物是当代的，已经有三千年历史了。", "explanation": "这里应该用〈古代〉。“当代”指现在，不能用来指已有三千年历史的文物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当代", "is_correct": true, "explanation": "当代：我们现在生活的时代，作状语，与“坐飞机去外国已经不难了”相合。"}, {"text": "春秋", "is_correct": false, "explanation": "语义：春秋时期还没有飞机，与“坐飞机去外国已经不难了”矛盾。"}, {"text": "西周", "is_correct": false, "explanation": "语义：西周没有飞机，与“坐飞机去外国”的情景矛盾。"}, {"text": "明天", "is_correct": false, "explanation": "搭配：“已经”表示已经实现，不与将来的“明天”搭配。"}], "explanations": {"当代": "当代：我们现在生活的时代，作状语，与“坐飞机去外国已经不难了”相合。", "春秋": "语义：春秋时期还没有飞机，与“坐飞机去外国已经不难了”矛盾。", "西周": "语义：西周没有飞机，与“坐飞机去外国”的情景矛盾。", "明天": "搭配：“已经”表示已经实现，不与将来的“明天”搭配。"}, "sentence_index": 6, "correct_answer": "当代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些石头已经存在几百万年了，是当代形成的。", "explanation": "这里应该用〈远古〉。当代指现在，几百万年的石头不能说是当代形成的。"}, {"text": "他在班里当代了三年班长。", "explanation": "这里应该用〈担任〉。当代是名词，不能作动词；表示担任职务要说“担任”。"}, {"text": "我们的城市有三个当代。", "explanation": "这里应该用〈时代〉。当代只指现在这一个时代，不能数成“三个当代”；说多个时期要用“时代”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们生活当代，很少有人不用手机。", "corrected_sentence": "我们生活在当代，很少有人不用手机。", "error_description": "“生活”后接时代，要加介词“在”，应说“生活在当代”，不说“生活当代”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89309, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当代地年轻人很重视健康。", "corrected_sentence": "当代的年轻人很重视健康。", "error_description": "“当代”作定语，后面应用“的”，不用“地”；“地”用于修饰动词、形容词。应说“当代的年轻人”，不说“当代地年轻人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代：过去的时代，与“当前这个时代”相对，是时间上的反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "与“当代”没有反义关系，是具体的家具名词。"}, {"text": "河流", "is_correct": false, "explanation": "与“当代”没有反义关系，是自然地理名词。"}, {"text": "手套", "is_correct": false, "explanation": "与“当代”没有反义关系，是具体的衣物名词。"}], "correct_answer": "古代", "explanations": {"古代": "古代：过去的时代，与“当前这个时代”相对，是时间上的反义词。", "桌子": "与“当代”没有反义关系，是具体的家具名词。", "河流": "与“当代”没有反义关系，是自然地理名词。", "手套": "与“当代”没有反义关系，是具体的衣物名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古代", "is_correct": true, "explanation": "古代：过去的时代，与“当前这个时代”相对，是时间上的反义词。"}, {"text": "石头", "is_correct": false, "explanation": "与“当代”没有反义关系，是自然物名词。"}, {"text": "黑板", "is_correct": false, "explanation": "与“当代”没有反义关系，是教学用具名词。"}, {"text": "雨伞", "is_correct": false, "explanation": "与“当代”没有反义关系，是日用品名词。"}], "correct_answer": "古代", "explanations": {"古代": "古代：过去的时代，与“当前这个时代”相对，是时间上的反义词。", "石头": "与“当代”没有反义关系，是自然物名词。", "黑板": "与“当代”没有反义关系，是教学用具名词。", "雨伞": "与“当代”没有反义关系，是日用品名词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当前这个时代；现今。", "primary_collocate": null, "pronunciation": "dāng dài", "ipa": "taŋ˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他喜欢读当代文学作品。", "target_word": "当代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位画家是当代最有名的画家。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个博物馆里有很多当代艺术品。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代年轻人很喜欢在网上买东西。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代社会发展得非常快。", "target_word": "当代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她是一位很有名的当代作家。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书讲的是当代中国人的生活。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去看一场当代音乐会。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当代科学家正在研究怎么保护地球。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画是当代画家画的，不是前人留下的作品。", "target_word": "当代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "当代人", "label": "复合"}, {"form": "当代文学", "label": "复合"}, {"form": "當代", "label": "繁体"}], "register": "书面", "sense_fingerprint": "当代：当前这个时代，多修饰文学、艺术等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e7e323-496a-4e04-9d9e-25a70cdf1aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当代", "is_correct": true, "explanation": "当代：当前这个时代，作定语修饰“文学作品”，与句意相合。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：“拖鞋”不能修饰文学作品，“拖鞋文学作品”不成搭配。"}, {"text": "蜡烛", "is_correct": false, "explanation": "搭配：“蜡烛”不能修饰文学作品，“蜡烛文学作品”不成搭配。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，与“喜欢读……文学作品”的阅读对象不相容。"}], "explanations": {"当代": "当代：当前这个时代，作定语修饰“文学作品”，与句意相合。", "拖鞋": "搭配：“拖鞋”不能修饰文学作品，“拖鞋文学作品”不成搭配。", "蜡烛": "搭配：“蜡烛”不能修饰文学作品，“蜡烛文学作品”不成搭配。", "厨房": "语义：厨房是场所，与“喜欢读……文学作品”的阅读对象不相容。"}, "sentence_index": 0, "correct_answer": "当代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候，当代的生活还很简单。", "explanation": "这里应该用〈当时〉。当代指现在这个时代，不能指过去的某段时间。"}, {"text": "这是一千年前的当代诗人写的诗。", "explanation": "这里应该用〈古代〉。当代指现今，一千年前的诗人是古代诗人，不能说“当代诗人”。"}, {"text": "这间屋子已经有一百年的历史了，是当代的。", "explanation": "这里应该用〈古老〉。当代指现在，不能用来形容已有一百年历史的老屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当代", "is_correct": true, "explanation": "当代：当前这个时代，作定语修饰“中国人的生活”，与句意相合。"}, {"text": "植物", "is_correct": false, "explanation": "语义：“植物”不能用来修饰“中国人”，“植物中国人的生活”不成话。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“中国人”前只能用时代、地区类修饰语，不能用“汽车”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命之物，与“中国人的生活”的主体不符。"}], "explanations": {"当代": "当代：当前这个时代，作定语修饰“中国人的生活”，与句意相合。", "植物": "语义：“植物”不能用来修饰“中国人”，“植物中国人的生活”不成话。", "汽车": "搭配：“中国人”前只能用时代、地区类修饰语，不能用“汽车”。", "石头": "语义：石头是无生命之物，与“中国人的生活”的主体不符。"}, "sentence_index": 6, "correct_answer": "当代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们住在当代，离学校很近。", "explanation": "这里应该用〈地方〉。当代是时间名词，指现在这个时代，不是地点；说住的地方要用“地方”。"}, {"text": "他在学校当代了三年班长。", "explanation": "这里应该用〈担任〉。当代是名词，不能作动词；表示担任职务要说“担任”。"}, {"text": "我的书架上有三本当代，都很有名。", "explanation": "这里应该用〈小说〉。当代是时代名词，不能用“本”来数；说书架上的书要说“三本小说”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐很喜欢当代地小说。", "corrected_sentence": "我姐姐很喜欢当代小说。", "error_description": "“当代”修饰名词时直接接名词，中间不加“地”。“地”用于修饰动词或形容词，此处应说“当代小说”，不说“当代地小说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们过着当代地生活，很多事都很方便。", "corrected_sentence": "我们过着当代的生活，很多事都很方便。", "error_description": "“当代”修饰名词“生活”时要用“的”，不用“地”；“地”用于修饰动词或形容词。应说“当代的生活”，不说“当代地生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
