INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "按含金量划分的黄金成色，如十八开金。", "primary_collocate": null, "pronunciation": "kāi jīn", "ipa": "kʰai˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "这家店的首饰大多是开金的，不是纯金的。", "target_word": "开金", "complexity_tier": "T3", "furigana": "zhè jiā diàn de shǒu shi dà duō shì kāi jīn de bú shì chún jīn de", "sentence_source": "generated"}, {"text": "你买戒指前要先问清楚是不是开金的。", "target_word": "开金", "complexity_tier": "T3", "furigana": "nǐ mǎi jiè zhǐ qián yào xiān wèn qīng chu shì bú shì kāi jīn de", "sentence_source": "generated"}, {"text": "我妈妈的手镯是开金的，戴了很多年还很亮。", "target_word": "开金", "complexity_tier": "T3", "furigana": "wǒ mā ma de shǒu zhuó shì kāi jīn de dài le hěn duō nián hái hěn liàng", "sentence_source": "generated"}, {"text": "这条项链是开金的，价格比纯金便宜一半。", "target_word": "开金", "complexity_tier": "T3", "furigana": "zhè tiáo xiàng liàn shì kāi jīn de jià gé bǐ chún jīn pián yi yí bàn", "sentence_source": "generated"}, {"text": "他问店员，这个戒指是不是开金的，含金量有多高。", "target_word": "开金", "complexity_tier": "T3", "furigana": "tā wèn diàn yuán zhè ge jiè zhǐ shì bú shì kāi jīn de hán jīn liàng yǒu duō gāo", "sentence_source": "generated"}, {"text": "这个耳环看起来很亮，其实是开金的，不是纯金。", "target_word": "开金", "complexity_tier": "T3", "furigana": "zhè ge ěr huán kàn qǐ lái hěn liàng qí shí shì kāi jīn de bú shì chún jīn", "sentence_source": "generated"}, {"text": "店员说，开金的数字越大，含金量越高。", "target_word": "开金", "complexity_tier": "T3", "furigana": "diàn yuán shuō kāi jīn de shù zì yuè dà hán jīn liàng yuè gāo", "sentence_source": "generated"}, {"text": "他给女儿买了一只开金的手镯，她很喜欢。", "target_word": "开金", "complexity_tier": "T3", "furigana": "tā gěi nǚ ér mǎi le yì zhī kāi jīn de shǒu zhuó tā hěn xǐ huan", "sentence_source": "generated"}, {"text": "开金的颜色比纯金淡，因为里面掺了别的金属。", "target_word": "开金", "complexity_tier": "T3", "furigana": "kāi jīn de yán sè bǐ chún jīn dàn yīn wèi lǐ miàn chān le bié de jīn shǔ", "sentence_source": "generated"}, {"text": "做首饰常用开金，因为它又结实又好看。", "target_word": "开金", "complexity_tier": "T3", "furigana": "zuò shǒu shi cháng yòng kāi jīn yīn wèi tā yòu jiē shi yòu hǎo kàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "開金", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开金：按含金量划分的黄金成色等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开金", "is_correct": true, "explanation": "正确。「开金」是按含金量划分的成色，符合句子的说法。"}, {"text": "纯金", "is_correct": false, "explanation": "语义：「纯金」与后半句「不是纯金的」矛盾，整句会自相矛盾。"}, {"text": "金店", "is_correct": false, "explanation": "搭配：「是……的」后接材质或成色，「金店」是店名，不能这样用。"}, {"text": "戒指", "is_correct": false, "explanation": "语义：「戒指」是饰品，不是材质或成色。"}], "explanations": {"开金": "正确。「开金」是按含金量划分的成色，符合句子的说法。", "纯金": "语义：「纯金」与后半句「不是纯金的」矛盾，整句会自相矛盾。", "金店": "搭配：「是……的」后接材质或成色，「金店」是店名，不能这样用。", "戒指": "语义：「戒指」是饰品，不是材质或成色。"}, "sentence_index": 0, "correct_answer": "开金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条项链是开金的，所以它是纯金的。", "explanation": "这里应该用〈足金〉。足金是纯度最高的黄金，开金是低于纯金的成色等级，两者不能等同，所以不能说它「是开金的」又「是纯金的」。"}, {"text": "这条项链的开金很多，一共有三克。", "explanation": "这里应该用〈金子〉。金子指金属本身，可以说有多少克；开金是成色等级的叫法，不表示数量，不能说「开金很多」。"}, {"text": "这条项链的开金是银的，所以很便宜。", "explanation": "这里应该用〈材质〉。开金是按含金量划分的黄金成色，不是材料本身，只能是金的，不能说它是银的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开金", "is_correct": true, "explanation": "正确。「开金」就是句中所说按含金量划分的成色。"}, {"text": "金价", "is_correct": false, "explanation": "搭配：「数字越大，含金量越高」说的是成色数字，「金价」指价格，不能这样搭配。"}, {"text": "手镯", "is_correct": false, "explanation": "语义：「手镯」是饰品，不是表示含金量数字的叫法。"}, {"text": "首饰", "is_correct": false, "explanation": "语义：「首饰」是统称，不表示成色的数字，与句子的说法不符。"}], "explanations": {"开金": "正确。「开金」就是句中所说按含金量划分的成色。", "金价": "搭配：「数字越大，含金量越高」说的是成色数字，「金价」指价格，不能这样搭配。", "手镯": "语义：「手镯」是饰品，不是表示含金量数字的叫法。", "首饰": "语义：「首饰」是统称，不表示成色的数字，与句子的说法不符。"}, "sentence_index": 6, "correct_answer": "开金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "做首饰常用开金，因为它不掺任何别的金属。", "explanation": "这里应该用〈足金〉。足金几乎不掺别的金属；开金正是掺了别的金属的黄金，不能说它不掺别的金属。"}, {"text": "这枚戒指重二十开金。", "explanation": "这里应该用〈克〉。克是重量单位；开金是黄金的成色等级，不能用来表示重量。"}, {"text": "做首饰常用开金，因为它是金子的重量。", "explanation": "开金指黄金的成色等级，不指重量，不能说它是金子的重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条链子是开金了的，价格比较便宜。", "corrected_sentence": "这条链子是开金的，价格比较便宜。", "error_description": "错误形式：「开金了的」。正确形式：「开金的」。「了」不能加在「开金」后面，此处只用「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店员解释了开金了的意思。", "corrected_sentence": "店员解释了开金的意思。", "error_description": "错误：「开金」后面多加了「了」，成了「开金了的」。正确：「店员解释了开金的意思。」「了」不能加在「开金」后面，此处只用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
