INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89315, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面上面，天上那一片地方。", "primary_collocate": null, "pronunciation": "kōng zhōng", "ipa": "kʰʊŋ˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "一只鸟在空中飞来飞去。", "target_word": "空中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "空中有很多白云。", "target_word": "空中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们抬头看空中的飞机。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空中飞着几只风筝，红的黄的都有。", "target_word": "空中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以前，空中的云越来越黑。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一架飞机从空中飞过去了。", "target_word": "空中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日的晚上，空中放满了烟花。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看见空中有一个很大的气球。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了，空中出现了一条彩虹。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，空中亮起了很多星星。", "target_word": "空中", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "空中小姐", "label": "复合"}, {"form": "空中花园", "label": "复合"}], "register": "中性", "sense_fingerprint": "空中：地面上面的天上，鸟、飞机、云所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e7e323-496a-4e04-9d9e-25a70cdf1aa8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水里", "is_correct": false, "explanation": "语义：水里是液体中，鸟不能在水里飞来飞去。"}, {"text": "空中", "is_correct": true, "explanation": "空中指地面以上的天空，正是鸟飞来飞去的地方。"}, {"text": "泥土里", "is_correct": false, "explanation": "搭配：“飞来飞去”需要开阔的空间，不能和“泥土里”搭配。"}, {"text": "地下", "is_correct": false, "explanation": "语义：地下在地面以下，鸟不能在那里飞来飞去。"}], "explanations": {"水里": "语义：水里是液体中，鸟不能在水里飞来飞去。", "空中": "空中指地面以上的天空，正是鸟飞来飞去的地方。", "泥土里": "搭配：“飞来飞去”需要开阔的空间，不能和“泥土里”搭配。", "地下": "语义：地下在地面以下，鸟不能在那里飞来飞去。"}, "sentence_index": 0, "correct_answer": "空中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上有个空中，老鼠从那里钻了进去。", "explanation": "这里应该用〈空隙〉。“空中”指地面以上的空间，墙上的缝隙要说空隙，不能说墙上有个空中。"}, {"text": "试卷上有一个空中，要填上正确的答案。", "explanation": "这里应该用〈空白〉。“空中”指地面以上的空间，纸上没写字的地方要说空白，不能说空中。"}, {"text": "车上还有一个空中，你可以坐下。", "explanation": "这里应该用〈空位〉。“空中”指地面以上的空间，车上没人坐的座位要说空位，不能说空中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱里", "is_correct": false, "explanation": "语义：冰箱是用来冷藏食物的，不能在里面放满烟花。"}, {"text": "清晨", "is_correct": false, "explanation": "搭配：“放满”需要一个处所，“清晨”是时间，而且与“节日的晚上”相矛盾。"}, {"text": "空中", "is_correct": true, "explanation": "空中指地面以上的天空，节日的烟花正是在那里绽放。"}, {"text": "烤箱里", "is_correct": false, "explanation": "语义：烤箱是烤食物的器具，不能用来放满烟花。"}], "explanations": {"冰箱里": "语义：冰箱是用来冷藏食物的，不能在里面放满烟花。", "清晨": "搭配：“放满”需要一个处所，“清晨”是时间，而且与“节日的晚上”相矛盾。", "空中": "空中指地面以上的天空，节日的烟花正是在那里绽放。", "烤箱里": "语义：烤箱是烤食物的器具，不能用来放满烟花。"}, "sentence_index": 6, "correct_answer": "空中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子的空中很新鲜，我们开窗通通风吧。", "explanation": "这里应该用〈空气〉。“空中”指地面以上的空间，是处所，不能用来说气味或清新程度，应说空气。"}, {"text": "这个箱子里面的空中很大，能放很多东西。", "explanation": "这里应该用〈空间〉。“空中”指地面以上的天上，箱子里面能放东西的地方应说空间。"}, {"text": "屋前有一块空中，我们在那里种花。", "explanation": "这里应该用〈空地〉。“空中”指地面以上的空间，地面上没有被占用的地方应说空地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只小鸟在空中里盘旋。", "corrected_sentence": "一只小鸟在空中盘旋。", "error_description": "多出了“里”。“空中”本身已经包含“中”，后面不能再加“里”，应说“在空中盘旋”，不能说“在空中里盘旋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一群大雁在的空中飞过。", "corrected_sentence": "一群大雁在空中飞过。", "error_description": "多出了“的”。“在空中”是状语，“在”与“空中”之间不能加“的”，应说“在空中飞过”，不能说“在的空中飞过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af84a8c0-c7d9-49e6-8f46-3b8727f48a92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
