INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89317, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "相好是说两个人关系很好，常在一起。", "primary_collocate": null, "pronunciation": "xiāng hǎo", "ipa": "ɕjaŋ˥ xaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他和小王很相好，天天一起上学。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们相好，下课总是在一起。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个孩子相好，常常一起玩。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我俩相好，周末常一起去爬山。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相好多年，常在一起吃饭。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李和小张最相好，走到哪儿都在一起。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个女孩相好，每天一起回家。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居老张和老李相好，天天一起下棋。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩很相好，总是一块儿出门。", "target_word": "相好", "complexity_tier": "T3", "furigana": "xiānghǎo", "sentence_source": "generated"}, {"text": "同学们都知道他们俩相好，形影不离。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个人关系很好，常常待在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89317, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相好", "is_correct": true, "explanation": "正确答案。相好 xiāng hǎo，指两个人关系很好，常在一起。"}, {"text": "想好", "is_correct": false, "explanation": "xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想好了。"}, {"text": "向好", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是朝好的方向发展。"}, {"text": "伤好", "is_correct": false, "explanation": "shāng 与 xiāng 声母不同（sh 与 x），意思是伤口愈合。"}, {"text": "相合", "is_correct": false, "explanation": "hé（第二声）与 hǎo（第三声）的韵母和声调都不同，意思是彼此符合。"}], "explanations": {"相好": "正确答案。相好 xiāng hǎo，指两个人关系很好，常在一起。", "想好": "xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想好了。", "向好": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是朝好的方向发展。", "伤好": "shāng 与 xiāng 声母不同（sh 与 x），意思是伤口愈合。", "相合": "hé（第二声）与 hǎo（第三声）的韵母和声调都不同，意思是彼此符合。"}, "sentence_index": null, "correct_answer": "相好"}, "level_3": {"options": [{"text": "相好", "is_correct": true, "explanation": "正确。“相好”指两人关系很好，与“天天一起上学”的情境相符。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指不熟悉，与“天天一起上学”矛盾。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容地方或场面，不能用来形容两个人的关系。"}, {"text": "老", "is_correct": false, "explanation": "语义：“老”形容年纪大，不能说两个人“很老”来表示关系，与“天天一起上学”说不通。"}], "explanations": {"相好": "正确。“相好”指两人关系很好，与“天天一起上学”的情境相符。", "陌生": "语义：“陌生”指不熟悉，与“天天一起上学”矛盾。", "冷清": "搭配：“冷清”形容地方或场面，不能用来形容两个人的关系。", "老": "语义：“老”形容年纪大，不能说两个人“很老”来表示关系，与“天天一起上学”说不通。"}, "sentence_index": 0, "correct_answer": "相好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的颜色很相好。", "explanation": "这里应该用〈好看〉。相好指人与人之间感情亲密，衣服颜色好要说好看。"}, {"text": "他对这条路线很相好。", "explanation": "这里应该用〈熟悉〉。相好要求双方彼此亲近，人对路线的了解要说熟悉。"}, {"text": "售货员对陌生顾客很相好。", "explanation": "这里应该用〈友善〉。相好指彼此亲密，对陌生人的和气态度要说友善。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相好", "is_correct": true, "explanation": "正确。“相好”指两人关系很好，与“每天一起回家”相符。"}, {"text": "生疏", "is_correct": false, "explanation": "语义：“生疏”指不熟悉，与“每天一起回家”矛盾。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指没有污垢，与两个女孩的关系无关，句子说不通。"}, {"text": "空荡", "is_correct": false, "explanation": "搭配：“空荡”形容空间里没有人或东西，不能用来形容两个人的关系。"}], "explanations": {"相好": "正确。“相好”指两人关系很好，与“每天一起回家”相符。", "生疏": "语义：“生疏”指不熟悉，与“每天一起回家”矛盾。", "干净": "语义：“干净”指没有污垢，与两个女孩的关系无关，句子说不通。", "空荡": "搭配：“空荡”形容空间里没有人或东西，不能用来形容两个人的关系。"}, "sentence_index": 6, "correct_answer": "相好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家酒店的服务很相好。", "explanation": "这里应该用〈周到〉。相好指人与人之间彼此亲近、关系好，服务的细致程度要说周到。"}, {"text": "双方的讨论很相好。", "explanation": "这里应该用〈热烈〉。相好指人与人之间感情亲密，讨论的气氛和热度要说热烈。"}, {"text": "这首歌的旋律很相好。", "explanation": "这里应该用〈动听〉。相好用于描述人与人之间的关系，旋律悦耳要说动听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "李明和同桌相好很，每天一起去食堂。", "corrected_sentence": "李明和同桌相好得很，每天一起去食堂。", "error_description": "补语错误：表示程度的补语要用“得”引出，应说“相好得很”，不能漏掉“得”说“相好很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个女孩渐渐相好很了，每天一起回家。", "corrected_sentence": "这两个女孩渐渐相好起来了，每天一起回家。", "error_description": "副词误用：“很”修饰形容词，不能与“了”连用；表示关系渐渐变好应说“相好起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
