INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89318, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "彼此感情亲密，关系好。", "primary_collocate": null, "pronunciation": "xiāng hǎo", "ipa": "ɕjaŋ˥ xaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们俩从小就很相好。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家人多年来一直很相好。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐妹俩很相好，什么心里话都说。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同桌从小学起就特别相好。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们相好得像亲姐妹一样。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同事们一直相好，谁也不争吵。", "target_word": "相好", "complexity_tier": "T3", "furigana": "xiānghǎo", "sentence_source": "generated"}, {"text": "他们两家相好了二十年。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位老朋友一直相好，从不吵架。", "target_word": "相好", "complexity_tier": "T3", "furigana": "xiānghǎo", "sentence_source": "generated"}, {"text": "听说这两位老师最相好。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不是亲兄弟，却比亲兄弟还相好。", "target_word": "相好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "彼此感情亲密、关系好，强调感情深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89318, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相好", "is_correct": true, "explanation": "正确答案。相好 xiāng hǎo，指彼此感情亲密、关系好。"}, {"text": "想好", "is_correct": false, "explanation": "xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想好了。"}, {"text": "向好", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是朝好的方向发展。"}, {"text": "伤好", "is_correct": false, "explanation": "shāng 与 xiāng 声母不同（sh 与 x），意思是伤口愈合。"}, {"text": "相合", "is_correct": false, "explanation": "hé（第二声）与 hǎo（第三声）的韵母和声调都不同，意思是彼此符合。"}], "explanations": {"相好": "正确答案。相好 xiāng hǎo，指彼此感情亲密、关系好。", "想好": "xiǎng（第三声）与 xiāng（第一声）声调不同，意思是想好了。", "向好": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是朝好的方向发展。", "伤好": "shāng 与 xiāng 声母不同（sh 与 x），意思是伤口愈合。", "相合": "hé（第二声）与 hǎo（第三声）的韵母和声调都不同，意思是彼此符合。"}, "sentence_index": null, "correct_answer": "相好"}, "level_3": {"options": [{"text": "相好", "is_correct": true, "explanation": "正确。“相好”指彼此感情亲密，与“从小就很”搭配，说明两人自小关系就好。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄小，与“从小就很”说不通，句子意思不成立。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容地方或场面，不能用来形容两个人的关系。"}, {"text": "老", "is_correct": false, "explanation": "语义：“老”形容年纪大或显老，与“从小”的时间线索矛盾，也不能表示关系好。"}], "explanations": {"相好": "正确。“相好”指彼此感情亲密，与“从小就很”搭配，说明两人自小关系就好。", "年轻": "语义：“年轻”说年龄小，与“从小就很”说不通，句子意思不成立。", "冷清": "搭配：“冷清”形容地方或场面，不能用来形容两个人的关系。", "老": "语义：“老”形容年纪大或显老，与“从小”的时间线索矛盾，也不能表示关系好。"}, "sentence_index": 0, "correct_answer": "相好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋穿起来很相好。", "explanation": "这里应该用〈舒服〉。相好指人与人之间感情亲密，鞋子穿着感觉好要说舒服。"}, {"text": "我对这座城市很相好。", "explanation": "这里应该用〈熟悉〉。相好要求双方彼此亲近，人对城市的了解要说熟悉。"}, {"text": "他对陌生人很相好。", "explanation": "这里应该用〈友善〉。相好指彼此亲密，对陌生人的和气态度要说友善。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相好", "is_correct": true, "explanation": "正确。“相好”指彼此感情亲密，与“两家”和“了二十年”搭配，符合语境。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌或事物，不能用来形容两家之间的关系。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指没有污垢，与两家的关系无关，句子说不通。"}, {"text": "瘦", "is_correct": false, "explanation": "语义：“瘦”形容人的体形，不能用来说两家的关系。"}], "explanations": {"相好": "正确。“相好”指彼此感情亲密，与“两家”和“了二十年”搭配，符合语境。", "漂亮": "搭配：“漂亮”形容外貌或事物，不能用来形容两家之间的关系。", "干净": "语义：“干净”指没有污垢，与两家的关系无关，句子说不通。", "瘦": "语义：“瘦”形容人的体形，不能用来说两家的关系。"}, "sentence_index": 6, "correct_answer": "相好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很相好。", "explanation": "这里应该用〈结实〉。相好用于人与人之间的关系，椅子的牢固程度要说结实。"}, {"text": "这家饭馆的菜很相好。", "explanation": "这里应该用〈可口〉。相好指人与人之间感情亲密，食物的味道好要说可口。"}, {"text": "他的文章写得很相好。", "explanation": "这里应该用〈精彩〉。相好描写的是人与人之间的关系，文章写得好要说精彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表哥和表弟相好很。", "corrected_sentence": "表哥和表弟相好得很。", "error_description": "补语错误：表示程度的补语要用“得”引出，应说“相好得很”，不能漏掉“得”说“相好很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位老朋友相好很了，从此不再吵架。", "corrected_sentence": "两位老朋友相好起来了，从此不再吵架。", "error_description": "副词误用：“很”修饰形容词，不能与“了”连用；表示关系转好应说“相好起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89320, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忙", "is_correct": true, "explanation": "正确。忙与闲相对，表示事情多、没有空。"}, {"text": "甜", "is_correct": false, "explanation": "甜指味道像糖，与“闲”没有反义关系。"}, {"text": "饱", "is_correct": false, "explanation": "饱指吃得满足，与“闲”没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "快指速度，与“闲”的空闲义不构成反义。"}], "correct_answer": "忙", "explanations": {"忙": "正确。忙与闲相对，表示事情多、没有空。", "甜": "甜指味道像糖，与“闲”没有反义关系。", "饱": "饱指吃得满足，与“闲”没有反义关系。", "快": "快指速度，与“闲”的空闲义不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89320, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忙", "is_correct": true, "explanation": "正确。忙与闲相对，表示事情多、没有空。"}, {"text": "硬", "is_correct": false, "explanation": "硬指质地坚实或态度强硬，与“闲”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净指清洁，与“闲”没有反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "圆指形状，与“闲”没有反义关系。"}], "correct_answer": "忙", "explanations": {"忙": "正确。忙与闲相对，表示事情多、没有空。", "硬": "硬指质地坚实或态度强硬，与“闲”没有反义关系。", "干净": "干净指清洁，与“闲”没有反义关系。", "圆": "圆指形状，与“闲”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89320, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有事情做；有空。", "primary_collocate": null, "pronunciation": "xián", "ipa": "ɕjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "我今天不忙，很闲。", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你明天闲吗？我们去看电影。", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近太闲了，每天在家睡觉。", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理很忙，没有闲的时候。", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末你闲不闲？来我家吃饭吧。", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在店里客人少，大家都很闲。", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她工作太多，一点儿也不闲。", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你闲的话，能帮我看孩子吗？", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人退休以后，每天都很闲。", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天他闲得没事做，一直看手机。", "target_word": "闲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闲着", "label": "体标"}, {"form": "空闲", "label": "复合"}, {"form": "清闲", "label": "复合"}, {"form": "閒", "label": "繁体"}], "register": "口语", "sense_fingerprint": "没有事做、有空，与忙相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed30a35-9b40-419e-ba00-be7904a18ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89320, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "闲", "is_correct": true, "explanation": "正确。闲 xián（第二声），意思是没有事做、有空。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xián（第二声）声调不同，意思是先后的先，不是有空。"}, {"text": "现", "is_correct": false, "explanation": "xiàn（第四声）与 xián（第二声）声调不同，意思是现在。"}, {"text": "线", "is_correct": false, "explanation": "xiàn（第四声）与 xián（第二声）声调不同，意思是线条。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xián（第二声）声调不同，意思是明显、显示。"}, {"text": "前", "is_correct": false, "explanation": "qián 与 xián 声母不同（q 与 x），意思是前面。"}], "explanations": {"闲": "正确。闲 xián（第二声），意思是没有事做、有空。", "先": "xiān（第一声）与 xián（第二声）声调不同，意思是先后的先，不是有空。", "现": "xiàn（第四声）与 xián（第二声）声调不同，意思是现在。", "线": "xiàn（第四声）与 xián（第二声）声调不同，意思是线条。", "显": "xiǎn（第三声）与 xián（第二声）声调不同，意思是明显、显示。", "前": "qián 与 xián 声母不同（q 与 x），意思是前面。"}, "sentence_index": null, "correct_answer": "闲"}, "level_3": {"options": [{"text": "闲", "is_correct": true, "explanation": "正确。与前句“不忙”相对，表示没有事做。"}, {"text": "忙", "is_correct": false, "explanation": "语义：“很忙”与前句“我今天不忙”自相矛盾，不能接在这里。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“很饱”只说吃得满足，不用来说一天的空闲状态。"}, {"text": "快", "is_correct": false, "explanation": "语义：“很快”说的是速度，不能形容一天的空闲程度。"}], "explanations": {"闲": "正确。与前句“不忙”相对，表示没有事做。", "忙": "语义：“很忙”与前句“我今天不忙”自相矛盾，不能接在这里。", "饱": "搭配：“很饱”只说吃得满足，不用来说一天的空闲状态。", "快": "语义：“很快”说的是速度，不能形容一天的空闲程度。"}, "sentence_index": 0, "correct_answer": "闲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条马路上很闲，几乎没有车。", "explanation": "这里应该用〈冷清〉。闲指人没有事做，不用来形容马路上车少人稀的样子。"}, {"text": "这个集市一到周末就很闲。", "explanation": "这里应该用〈热闹〉。闲指人没有事做，不能用来形容集市上人多、气氛热闹。"}, {"text": "山村的夜晚很闲。", "explanation": "这里应该用〈宁静〉。闲指人没有事做，不用来形容夜晚环境的安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89320, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "闲", "is_correct": true, "explanation": "正确。闲 xián（第二声），意思是没有事做、有空。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xián（第二声）声调不同，意思是新鲜。"}, {"text": "献", "is_correct": false, "explanation": "xiàn（第四声）与 xián（第二声）声调不同，意思是献出、奉献。"}, {"text": "限", "is_correct": false, "explanation": "xiàn（第四声）与 xián（第二声）声调不同，意思是限制。"}, {"text": "险", "is_correct": false, "explanation": "xiǎn（第三声）与 xián（第二声）声调不同，意思是危险。"}], "explanations": {"闲": "正确。闲 xián（第二声），意思是没有事做、有空。", "鲜": "xiān（第一声）与 xián（第二声）声调不同，意思是新鲜。", "献": "xiàn（第四声）与 xián（第二声）声调不同，意思是献出、奉献。", "限": "xiàn（第四声）与 xián（第二声）声调不同，意思是限制。", "险": "xiǎn（第三声）与 xián（第二声）声调不同，意思是危险。"}, "sentence_index": null, "correct_answer": "闲"}, "level_3": {"options": [{"text": "闲", "is_correct": true, "explanation": "正确。与前句“工作太多”相对，表示没有事做。"}, {"text": "忙碌", "is_correct": false, "explanation": "语义：“一点儿也不忙碌”与前句“工作太多”矛盾，不能接在这里。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”形容明白或分明，与工作多少无关，句子不通。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列或外观，不用来形容工作量。"}], "explanations": {"闲": "正确。与前句“工作太多”相对，表示没有事做。", "忙碌": "语义：“一点儿也不忙碌”与前句“工作太多”矛盾，不能接在这里。", "清楚": "语义：“清楚”形容明白或分明，与工作多少无关，句子不通。", "整齐": "搭配：“整齐”形容排列或外观，不用来形容工作量。"}, "sentence_index": 6, "correct_answer": "闲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个好消息，他心里很闲。", "explanation": "这里应该用〈轻松〉。闲指没有事情做，不能用来形容心情舒展；心里放松、轻快要说“轻松”。"}, {"text": "周末的日程很闲。", "explanation": "这里应该用〈空〉。说日程、时间有没有安排要用“空”，闲多用来形容人没有事做。"}, {"text": "泡完温泉以后，身体很闲。", "explanation": "这里应该用〈舒服〉。闲指人没有事情做，不能用来形容身体的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这周闲地很，每天都在看书。", "corrected_sentence": "他这周闲得很，每天都在看书。", "error_description": "“闲”后的补语标记应用“得”，说“闲得很”。写成“闲地很”误用了状语标记“地”，结构不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一点儿也闲，每天都在整理书房。", "corrected_sentence": "她一点儿也不闲，每天都在整理书房。", "error_description": "“一点儿也”后面要用否定词“不”，应说“一点儿也不闲”。去掉“不”后句子意思相反，且与“每天整理书房”的语境不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ebcf91-383e-41cf-a68f-4a6fbf22dbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "杂", "is_correct": true, "explanation": "反义：“杂”指混入别的东西，与“纯”意思相反。"}, {"text": "厚", "is_correct": false, "explanation": "与“纯”无反义关系：“厚”说的是厚度。"}, {"text": "深", "is_correct": false, "explanation": "与“纯”无反义关系：“深”说的是深浅。"}, {"text": "快", "is_correct": false, "explanation": "与“纯”无反义关系：“快”说的是速度。"}], "correct_answer": "杂", "explanations": {"杂": "反义：“杂”指混入别的东西，与“纯”意思相反。", "厚": "与“纯”无反义关系：“厚”说的是厚度。", "深": "与“纯”无反义关系：“深”说的是深浅。", "快": "与“纯”无反义关系：“快”说的是速度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "杂", "is_correct": true, "explanation": "反义：“杂”指混入别的东西，与“纯”意思相反。"}, {"text": "远", "is_correct": false, "explanation": "与“纯”无反义关系：“远”说的是距离。"}, {"text": "慢", "is_correct": false, "explanation": "与“纯”无反义关系：“慢”说的是速度。"}, {"text": "软", "is_correct": false, "explanation": "与“纯”无反义关系：“软”说的是硬度。"}], "correct_answer": "杂", "explanations": {"杂": "反义：“杂”指混入别的东西，与“纯”意思相反。", "远": "与“纯”无反义关系：“远”说的是距离。", "慢": "与“纯”无反义关系：“慢”说的是速度。", "软": "与“纯”无反义关系：“软”说的是硬度。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "里面只有这一样，没有别的东西混进去。", "primary_collocate": null, "pronunciation": "chún", "ipa": "ʈʂʰwən˧˥", "syllable_count": 1, "sentences": [{"text": "这种蜂蜜很纯，没有加糖。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这杯果汁是纯的，没加水。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块金子不够纯，里面有别的金属。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶橄榄油很纯，没有掺别的油。", "target_word": "纯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗水很纯，没有一点脏东西。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶酒很纯，一点水也没掺。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服是纯羊毛的，很暖和。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子里的盐很纯，没有沙子。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块玉很纯，没有别的颜色。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的泉水很纯，我们喝了不少。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "纯净", "label": "复合"}, {"form": "纯正", "label": "复合"}, {"form": "純", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物质成分单一，没有掺进别的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d78632b-8856-4b08-affc-b5331421b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯（chún），里面只有这一样，没有别的东西混进去。"}, {"text": "春", "is_correct": false, "explanation": "chūn（第一声）与 chún（第二声）声调不同，意思是春天。"}, {"text": "蠢", "is_correct": false, "explanation": "chǔn（第三声）与 chún（第二声）声调不同，意思是愚蠢。"}, {"text": "存", "is_correct": false, "explanation": "cún 与 chún 声母不同（c 与 ch），意思是保存。"}, {"text": "船", "is_correct": false, "explanation": "chuán 与 chún 韵母不同（-uán 与 -ún），意思是船。"}], "explanations": {"纯": "正确：纯（chún），里面只有这一样，没有别的东西混进去。", "春": "chūn（第一声）与 chún（第二声）声调不同，意思是春天。", "蠢": "chǔn（第三声）与 chún（第二声）声调不同，意思是愚蠢。", "存": "cún 与 chún 声母不同（c 与 ch），意思是保存。", "船": "chuán 与 chún 韵母不同（-uán 与 -ún），意思是船。"}, "sentence_index": null, "correct_answer": "纯"}, "level_3": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯，“很纯”说蜂蜜里没有掺杂，与后句“没有加糖”一致。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”说的是形状，不能用来形容蜂蜜。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”不用来形容蜂蜜的状态。"}, {"text": "长", "is_correct": false, "explanation": "语义：“长”说的是长短，不能用来形容蜂蜜。"}], "explanations": {"纯": "正确：纯，“很纯”说蜂蜜里没有掺杂，与后句“没有加糖”一致。", "圆": "语义：“圆”说的是形状，不能用来形容蜂蜜。", "快": "搭配：“快”不用来形容蜂蜜的状态。", "长": "语义：“长”说的是长短，不能用来形容蜂蜜。"}, "sentence_index": 0, "correct_answer": "纯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱很纯，夏天也不太费电。", "explanation": "这里应该用〈节能〉。纯说的是成分单一、不掺杂，形容省电要用节能。"}, {"text": "这间厨房的台面很纯，每天都擦得亮亮的。", "explanation": "这里应该用〈洁净〉。纯说的是不掺杂质，形容台面干净要用洁净。"}, {"text": "他骑自行车骑得很纯，一点也不费力。", "explanation": "这里应该用〈纯熟〉。纯熟指技艺熟练，形容骑车的熟练程度要用纯熟，“很纯”没有这种用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯（chún），里面只有这一样，没有别的东西混进去。"}, {"text": "蝉", "is_correct": false, "explanation": "chán 与 chún 韵母不同（-an 与 -un），意思是蝉。"}, {"text": "陈", "is_correct": false, "explanation": "chén 与 chún 韵母不同（-en 与 -un），意思是陈旧。"}, {"text": "沉", "is_correct": false, "explanation": "chén 与 chún 韵母不同（-en 与 -un），意思是下沉。"}], "explanations": {"纯": "正确：纯（chún），里面只有这一样，没有别的东西混进去。", "蝉": "chán 与 chún 韵母不同（-an 与 -un），意思是蝉。", "陈": "chén 与 chún 韵母不同（-en 与 -un），意思是陈旧。", "沉": "chén 与 chún 韵母不同（-en 与 -un），意思是下沉。"}, "sentence_index": null, "correct_answer": "纯"}, "level_3": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯，修饰“羊毛”，表示羊毛里不掺别的纤维。"}, {"text": "尖", "is_correct": false, "explanation": "语义：“尖”说的是尖端，不能修饰羊毛的成分。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：“瘦”不用来修饰羊毛。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”是味道，不能修饰羊毛。"}], "explanations": {"纯": "正确：纯，修饰“羊毛”，表示羊毛里不掺别的纤维。", "尖": "语义：“尖”说的是尖端，不能修饰羊毛的成分。", "瘦": "搭配：“瘦”不用来修饰羊毛。", "甜": "语义：“甜”是味道，不能修饰羊毛。"}, "sentence_index": 6, "correct_answer": "纯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把扇子的做工很纯，纹路也很细。", "explanation": "这里应该用〈精致〉。纯说的是不掺杂质，形容做工的精巧要用精致。"}, {"text": "这张照片很纯，连远处的树都看得见。", "explanation": "这里应该用〈清晰〉。纯说的是不掺杂质，形容照片的清楚程度要用清晰。"}, {"text": "这台仪器的测量很纯，误差很小。", "explanation": "这里应该用〈精准〉。纯说的是不掺杂质，形容测量的准确程度要用精准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这瓶蜂蜜没纯，没有掺别的东西。", "corrected_sentence": "这瓶蜂蜜很纯，没有掺别的东西。", "error_description": "错误：形容词“纯”作谓语时，前面应用程度副词“很”，不能用“没”。“没纯”不成立，正确说法是“很纯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种玉石的成分纯很。", "corrected_sentence": "这种玉石的成分很纯。", "error_description": "错误：“很”放在了“纯”的后面，语序错误。正确说法是“很纯”，“很”要放在形容词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "反义：“复杂”指心思繁多、不简单，与“单纯”意思相反。"}, {"text": "厚", "is_correct": false, "explanation": "与“纯”无反义关系：“厚”说的是厚度。"}, {"text": "甜", "is_correct": false, "explanation": "与“纯”无反义关系：“甜”说的是味道。"}, {"text": "远", "is_correct": false, "explanation": "与“纯”无反义关系：“远”说的是距离。"}], "correct_answer": "复杂", "explanations": {"复杂": "反义：“复杂”指心思繁多、不简单，与“单纯”意思相反。", "厚": "与“纯”无反义关系：“厚”说的是厚度。", "甜": "与“纯”无反义关系：“甜”说的是味道。", "远": "与“纯”无反义关系：“远”说的是距离。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "反义：“复杂”指心思繁多、不简单，与“单纯”意思相反。"}, {"text": "慢", "is_correct": false, "explanation": "与“纯”无反义关系：“慢”说的是速度。"}, {"text": "硬", "is_correct": false, "explanation": "与“纯”无反义关系：“硬”说的是硬度。"}, {"text": "宽", "is_correct": false, "explanation": "与“纯”无反义关系：“宽”说的是宽窄。"}], "correct_answer": "复杂", "explanations": {"复杂": "反义：“复杂”指心思繁多、不简单，与“单纯”意思相反。", "慢": "与“纯”无反义关系：“慢”说的是速度。", "硬": "与“纯”无反义关系：“硬”说的是硬度。", "宽": "与“纯”无反义关系：“宽”说的是宽窄。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（人的心思、感情、动机）单纯，不复杂，不掺别的目的。", "primary_collocate": null, "pronunciation": "chún", "ipa": "ʈʂʰwən˧˥", "syllable_count": 1, "sentences": [{"text": "这个孩子的心很纯。", "target_word": "纯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她年纪不大，人很纯。", "target_word": "纯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们俩的友情很纯，没有别的想法。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还很纯，别人说什么他都信。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小姑娘很纯，从来不说假话。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的爱情很纯，不看对方有没有钱。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的笑容很纯，像个孩子。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的动机不纯，只想要我们的钱。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的想法很纯，只想帮助别人。", "target_word": "纯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从来没骗过人，心思特别纯。", "target_word": "纯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纯真", "label": "复合"}, {"form": "纯粹", "label": "复合"}, {"form": "純", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人心思单纯不复杂；感情、动机不掺杂别的目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d78632b-8856-4b08-affc-b5331421b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯（chún），形容心思单纯、不复杂。"}, {"text": "春", "is_correct": false, "explanation": "chūn（第一声）与 chún（第二声）声调不同，意思是春天。"}, {"text": "蠢", "is_correct": false, "explanation": "chǔn（第三声）与 chún（第二声）声调不同，意思是愚蠢。"}, {"text": "存", "is_correct": false, "explanation": "cún 与 chún 声母不同（c 与 ch），意思是保存。"}, {"text": "船", "is_correct": false, "explanation": "chuán 与 chún 韵母不同（-uán 与 -ún），意思是船。"}], "explanations": {"纯": "正确：纯（chún），形容心思单纯、不复杂。", "春": "chūn（第一声）与 chún（第二声）声调不同，意思是春天。", "蠢": "chǔn（第三声）与 chún（第二声）声调不同，意思是愚蠢。", "存": "cún 与 chún 声母不同（c 与 ch），意思是保存。", "船": "chuán 与 chún 韵母不同（-uán 与 -ún），意思是船。"}, "sentence_index": null, "correct_answer": "纯"}, "level_3": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯，形容孩子心地单纯，与“很纯”搭配。"}, {"text": "扁", "is_correct": false, "explanation": "语义：“扁”说的是形状，不能用来形容心。"}, {"text": "陡", "is_correct": false, "explanation": "搭配：“陡”用于坡、路等，不能用来形容心。"}, {"text": "方", "is_correct": false, "explanation": "语义：“方”说的是形状，不能用来形容心。"}], "explanations": {"纯": "正确：纯，形容孩子心地单纯，与“很纯”搭配。", "扁": "语义：“扁”说的是形状，不能用来形容心。", "陡": "搭配：“陡”用于坡、路等，不能用来形容心。", "方": "语义：“方”说的是形状，不能用来形容心。"}, "sentence_index": 0, "correct_answer": "纯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩很纯，每门课都是满分。", "explanation": "这里应该用〈优秀〉。纯说的是单纯或不掺杂，形容成绩好要用优秀。"}, {"text": "他做事很纯，从不拖拉。", "explanation": "这里应该用〈利落〉。纯说的是单纯或不掺杂，形容做事干脆利索要用利落。"}, {"text": "这次旅行很纯，大家都很开心。", "explanation": "这里应该用〈轻松〉。纯说的是单纯或不掺杂，形容旅行的愉快、轻松要用轻松。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯（chún），形容心思单纯、不复杂。"}, {"text": "蝉", "is_correct": false, "explanation": "chán 与 chún 韵母不同（-an 与 -un），意思是蝉。"}, {"text": "陈", "is_correct": false, "explanation": "chén 与 chún 韵母不同（-en 与 -un），意思是陈旧。"}, {"text": "沉", "is_correct": false, "explanation": "chén 与 chún 韵母不同（-en 与 -un），意思是下沉。"}], "explanations": {"纯": "正确：纯（chún），形容心思单纯、不复杂。", "蝉": "chán 与 chún 韵母不同（-an 与 -un），意思是蝉。", "陈": "chén 与 chún 韵母不同（-en 与 -un），意思是陈旧。", "沉": "chén 与 chún 韵母不同（-en 与 -un），意思是下沉。"}, "sentence_index": null, "correct_answer": "纯"}, "level_3": {"options": [{"text": "纯", "is_correct": true, "explanation": "正确：纯，形容笑容单纯、没有心机，与“像个孩子”一致。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”是味道，不能用来形容笑容。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说的是高度，不能用来形容笑容。"}, {"text": "方", "is_correct": false, "explanation": "语义：“方”说的是形状，不能用来形容笑容。"}], "explanations": {"纯": "正确：纯，形容笑容单纯、没有心机，与“像个孩子”一致。", "咸": "语义：“咸”是味道，不能用来形容笑容。", "矮": "搭配：“矮”说的是高度，不能用来形容笑容。", "方": "语义：“方”说的是形状，不能用来形容笑容。"}, "sentence_index": 6, "correct_answer": "纯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的服务很纯，客人都很满意。", "explanation": "这里应该用〈周到〉。纯说的是单纯或不掺杂，形容服务细致要用周到。"}, {"text": "这场比赛很纯，观众一直在欢呼。", "explanation": "这里应该用〈精彩〉。纯说的是单纯或不掺杂，形容比赛的精彩程度要用精彩。"}, {"text": "这排书摆得很纯，一本也不乱。", "explanation": "这里应该用〈整齐〉。纯说的是单纯或不掺杂，形容摆放得有条理要用整齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小男孩的心纯很，从不撒谎。", "corrected_sentence": "这个小男孩的心很纯，从不撒谎。", "error_description": "错误：程度副词“很”应放在形容词前。应说“心很纯”，不能说“心纯很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人的动机很没纯，只想骗我们。", "corrected_sentence": "这个人的动机很不纯，只想骗我们。", "error_description": "错误：形容词的否定要用“不”，不能用“没”。“没纯”不成立，正确说法是“很不纯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
