INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89325, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "阐明是把一件事讲清楚，让大家都懂。", "primary_collocate": null, "pronunciation": "chǎn míng", "ipa": "ʈʂʰan˨˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "经理向大家阐明了公司的计划。", "target_word": "阐明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上阐明了这道题的做法。", "target_word": "阐明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力阐明自己的想法，让大家都懂。", "target_word": "阐明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书阐明了地球为什么会有四季。", "target_word": "阐明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生向病人阐明了手术的好处。", "target_word": "阐明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能不能阐明一下这个词的意思？", "target_word": "阐明", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他讲了半个小时，终于阐明了问题。", "target_word": "阐明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上，大家请他阐明做这件事的目的。", "target_word": "阐明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人用故事阐明了做人的道理。", "target_word": "阐明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开始时，主任先阐明了今天的任务。", "target_word": "阐明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阐明了", "label": "体标"}, {"form": "阐明过", "label": "体标"}, {"form": "闡明", "label": "繁体"}], "register": "书面", "sense_fingerprint": "向别人把事情讲清楚，使大家都明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89325, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阐明", "is_correct": true, "explanation": "阐明（chǎn míng）：向别人讲清楚事情，使大家明白，这正是该词的读音。"}, {"text": "蝉鸣", "is_correct": false, "explanation": "chán（第二声）与 chǎn（第三声）声调不同，蝉鸣的意思是蝉的叫声。"}, {"text": "厂名", "is_correct": false, "explanation": "chǎng 与 chǎn 韵母不同（-ng 与 -n），厂名的意思是工厂的名称。"}, {"text": "长鸣", "is_correct": false, "explanation": "cháng 与 chǎn 的韵母和声调都不同，长鸣的意思是声音持续很长时间。"}], "explanations": {"阐明": "阐明（chǎn míng）：向别人讲清楚事情，使大家明白，这正是该词的读音。", "蝉鸣": "chán（第二声）与 chǎn（第三声）声调不同，蝉鸣的意思是蝉的叫声。", "厂名": "chǎng 与 chǎn 韵母不同（-ng 与 -n），厂名的意思是工厂的名称。", "长鸣": "cháng 与 chǎn 的韵母和声调都不同，长鸣的意思是声音持续很长时间。"}, "sentence_index": null, "correct_answer": "阐明"}, "level_3": {"options": [{"text": "阐明", "is_correct": true, "explanation": "阐明：讲清楚、说明白，与“经理向大家讲清楚计划”的语境相合。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象是食物，不能说烤计划。"}, {"text": "藏", "is_correct": false, "explanation": "语义：“藏”是隐藏起来，与“向大家”把计划讲给别人的语境相反。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”用于切割实物，不能接“计划”作宾语。"}], "explanations": {"阐明": "阐明：讲清楚、说明白，与“经理向大家讲清楚计划”的语境相合。", "烤": "搭配：“烤”的对象是食物，不能说烤计划。", "藏": "语义：“藏”是隐藏起来，与“向大家”把计划讲给别人的语境相反。", "切": "搭配：“切”用于切割实物，不能接“计划”作宾语。"}, "sentence_index": 0, "correct_answer": "阐明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很难阐明心里的难过。", "explanation": "这里应该用〈表达〉。阐明用于讲清道理、观点，表达心情要用“表达”。"}, {"text": "他给孩子们阐明了一个很长的童话。", "explanation": "这里应该用〈讲述〉。阐明的对象是道理或观点，讲童话要用“讲述”。"}, {"text": "我在窗前阐明了一阵鸟叫。", "explanation": "这里应该用〈听见〉。阐明是讲清道理，不能用来说听到了声音，应为“听见了一阵鸟叫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阐明", "is_correct": true, "explanation": "阐明：讲清楚、说明白，与“讲了半个小时，终于把问题讲清楚”的语境相合。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”用于烹饪食物，不能接“问题”作宾语。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：“吞”的对象是食物或实物，不能说吞问题。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”的对象是人或具体物体，不能接“问题”作宾语。"}], "explanations": {"阐明": "阐明：讲清楚、说明白，与“讲了半个小时，终于把问题讲清楚”的语境相合。", "煎": "搭配：“煎”用于烹饪食物，不能接“问题”作宾语。", "吞": "搭配：“吞”的对象是食物或实物，不能说吞问题。", "拍": "搭配：“拍”的对象是人或具体物体，不能接“问题”作宾语。"}, "sentence_index": 6, "correct_answer": "阐明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她笑着点点头，阐明了同意。", "explanation": "这里应该用〈表示〉。点头只能表示态度，阐明用于讲清道理，不能用来表达同意。"}, {"text": "我在人群里一下子阐明了妈妈。", "explanation": "这里应该用〈认出〉。阐明的对象是道理、观点，不能用来指人，应为“认出了妈妈”。"}, {"text": "他阐明了那只箱子。", "explanation": "这里应该用〈打开〉。阐明是讲清道理，不能用于具体的物品，应为“打开了那只箱子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师阐明很清楚。", "corrected_sentence": "这位老师阐明得很清楚。", "error_description": "错误：“阐明”后的程度补语漏掉了“得”。应为“阐明得很清楚”，程度补语要用“得”与动词相连。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有阐明了这个问题的原因。", "corrected_sentence": "他没有阐明这个问题的原因。", "error_description": "错误：否定词“没有”与动态助词“了”不能同用。否定句中的“阐明”后不加“了”，应为“没有阐明这个问题的原因”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
