INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89327, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或一家有多少钱，钱够不够用。", "primary_collocate": null, "pronunciation": "jīng jì qíng kuàng", "ipa": "tɕiŋ˥ tɕi˥˩ tɕʰiŋ˧˥ kʰwaŋ˥˩", "syllable_count": 4, "sentences": [{"text": "他家经济情况不好，买不起新手机。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的经济情况很好，每年都能去旅游。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "结婚以前，她问了我的经济情况。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家经济情况一般，不能常常去饭馆吃饭。", "target_word": "经济情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要了解学生的经济情况，才能给他们帮助。", "target_word": "经济情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她经济情况不太好，所以先找工作。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的经济情况怎么样？", "target_word": "经济情况", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸生病以后，我们家的经济情况越来越差。", "target_word": "经济情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为经济情况好了，他们换了大房子。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的经济情况不好，老师让他不用交钱。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "經濟情況", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人或家庭有多少钱、够不够花的状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89327, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济情况", "is_correct": true, "explanation": "正确：“经济情况”指家里有多少钱、够不够用，与“不好，买不起新手机”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气象，不能用来说一个家的好坏，句中的“买不起新手机”也无法由天气解释。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的高矮，不能用在一个家庭上，也与后面的消费情况无关。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”是数字，不说“年龄不好”来做评价。"}], "explanations": {"经济情况": "正确：“经济情况”指家里有多少钱、够不够用，与“不好，买不起新手机”相符。", "天气": "语义：天气指气象，不能用来说一个家的好坏，句中的“买不起新手机”也无法由天气解释。", "身高": "语义：身高是人的高矮，不能用在一个家庭上，也与后面的消费情况无关。", "年龄": "搭配：“年龄”是数字，不说“年龄不好”来做评价。"}, "sentence_index": 0, "correct_answer": "经济情况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个月的经济情况是五千块。", "explanation": "这里应该用〈收入〉。经济情况指状况，不表示具体的钱数，说每月多少钱要用收入。"}, {"text": "他留给儿子很多经济情况。", "explanation": "这里应该用〈财产〉。经济情况是状况，不是能留下、能数多少的东西，可以留下的是财产。"}, {"text": "这块板子的经济情况很厚。", "explanation": "这里应该用〈厚度〉。经济情况是状况，不能说厚薄；说板子的厚薄要用厚度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济情况", "is_correct": true, "explanation": "正确：问对方的收支状况用“怎么样”，与句意相符。"}, {"text": "国籍", "is_correct": false, "explanation": "搭配：问国籍用“是哪国人”，不说“国籍怎么样”。"}, {"text": "学号", "is_correct": false, "explanation": "语义：学号是编号，没有好坏之分，不能用“怎么样”来问。"}, {"text": "籍贯", "is_correct": false, "explanation": "搭配：籍贯指出生地或祖籍，不用“怎么样”来评价。"}], "explanations": {"经济情况": "正确：问对方的收支状况用“怎么样”，与句意相符。", "国籍": "搭配：问国籍用“是哪国人”，不说“国籍怎么样”。", "学号": "语义：学号是编号，没有好坏之分，不能用“怎么样”来问。", "籍贯": "搭配：籍贯指出生地或祖籍，不用“怎么样”来评价。"}, "sentence_index": 6, "correct_answer": "经济情况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的专业是经济情况，毕业以后想去银行工作。", "explanation": "这里说的是学科“经济”，经济情况指人或家庭的状况，不能当作专业名称。"}, {"text": "这间屋子的经济情况很好，大家都喜欢在这里看书。", "explanation": "这里应该用〈光线〉。经济情况指一个人或一家的钱财状况，不能用于房间；说房间的明暗要用光线。"}, {"text": "这本书的经济情况很好，大家都愿意看。", "explanation": "这里应该用〈内容〉。经济情况指一个人或一家的钱财状况，不能用于书；说书好不好要用内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只经济情况让人很担心。", "corrected_sentence": "这种经济情况让人很担心。", "error_description": "量词错误：“情况”是抽象名词，应该用“种”，不能用“只”（“只”用于动物、成对的物品等）。应改为“这种经济情况让人很担心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年，我们家的经济情况变好着。", "corrected_sentence": "这几年，我们家的经济情况变好了。", "error_description": "体标错误：“变好”表示已经发生的变化，要用“了”；“着”表示持续的状态，这里不能用“着”。应改为“变好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
