INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89328, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人、家庭或国家在收入、财产等方面的状况。", "primary_collocate": null, "pronunciation": "jīng jì qíng kuàng", "ipa": "tɕiŋ˥ tɕi˥˩ tɕʰiŋ˧˥ kʰwaŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这个国家的经济情况越来越好。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行会先看你的收入和经济情况。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "申请房子的时候，要写家里的经济情况。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年国家的经济情况不太好，工作不容易找。", "target_word": "经济情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问了每个学生家里的经济情况。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的经济情况很稳定，不用担心。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家公布了今年的经济情况。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "了解一个家庭的经济情况，可以看他们的收入。", "target_word": "经济情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的经济情况不同，所以生活方式也不一样。", "target_word": "经济情况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村家庭的经济情况现在比以前好。", "target_word": "经济情况", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "經濟情況", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人、家庭或国家在收入和财产方面的整体状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济情况", "is_correct": true, "explanation": "正确：指一个国家在收入、财产等方面的状况，与“越来越好”相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高属于个人，国家没有身高，不能这样说。"}, {"text": "视力", "is_correct": false, "explanation": "语义：视力是个人眼睛的能力，不能用在一个国家上。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：发型是个人的外观，不说“国家的发型”。"}], "explanations": {"经济情况": "正确：指一个国家在收入、财产等方面的状况，与“越来越好”相符。", "身高": "语义：身高属于个人，国家没有身高，不能这样说。", "视力": "语义：视力是个人眼睛的能力，不能用在一个国家上。", "发型": "搭配：发型是个人的外观，不说“国家的发型”。"}, "sentence_index": 0, "correct_answer": "经济情况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的经济情况很结实。", "explanation": "这里应该用〈质地〉。经济情况指人、家庭或国家的钱财状况，不能用于椅子；说椅子结实要说质地。"}, {"text": "去年全国的经济情况增加了百分之五。", "explanation": "这里应该用〈产值〉。“增加百分之五”说的是数量，经济情况是状况，不能这样计量。"}, {"text": "这条河的经济情况很清。", "explanation": "这里应该用〈水质〉。经济情况不能用来形容河流；说河水干净要用水质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济情况", "is_correct": true, "explanation": "正确：公布的是国家今年的收支和财产等状况，与句意相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是个人的疾病，国家不会把它当作公布的内容。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是日常食物，不是政府公布的内容。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“公布”不和“心情”搭配，心情是个人的情绪。"}], "explanations": {"经济情况": "正确：公布的是国家今年的收支和财产等状况，与句意相符。", "感冒": "语义：感冒是个人的疾病，国家不会把它当作公布的内容。", "饭菜": "语义：饭菜是日常食物，不是政府公布的内容。", "心情": "搭配：“公布”不和“心情”搭配，心情是个人的情绪。"}, "sentence_index": 6, "correct_answer": "经济情况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学学的是经济情况，现在在银行工作。", "explanation": "这里说的是学科“经济”，经济情况指人或家庭的状况，不能当作学科名称。"}, {"text": "这匹马的经济情况很好，跑得很快。", "explanation": "这里应该用〈体力〉。经济情况指人、家庭或国家的钱财状况，不能用于马；说马的力气要用体力。"}, {"text": "这首歌的经济情况很美，大家都爱听。", "explanation": "这里应该用〈旋律〉。经济情况不能用于歌曲；说歌好听不好听要用旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的经济情况正在慢慢好变。", "corrected_sentence": "这个国家的经济情况正在慢慢变好。", "error_description": "补语语序错误：“变好”是动词加结果补语，不能说“好变”，应说“慢慢变好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区的经济情况变化的很快。", "corrected_sentence": "这个地区的经济情况变化得很快。", "error_description": "程度补语错误：动词后引出补语要用“得”，不能用“的”，应说“变化得很快”，不能说“变化的很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89329, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "看衰", "is_correct": true, "explanation": "正确：“看衰”表示认为某人某事不会好，与“看好”正相反。"}, {"text": "忽略", "is_correct": false, "explanation": "无反义关系：“忽略”指不注意，与“看好”不构成反义。"}, {"text": "放弃", "is_correct": false, "explanation": "无反义关系：“放弃”指不再坚持，与“看好”不是反义。"}, {"text": "搁置", "is_correct": false, "explanation": "无反义关系：“搁置”指暂时不处理，与“看好”不是反义。"}], "correct_answer": "看衰", "explanations": {"看衰": "正确：“看衰”表示认为某人某事不会好，与“看好”正相反。", "忽略": "无反义关系：“忽略”指不注意，与“看好”不构成反义。", "放弃": "无反义关系：“放弃”指不再坚持，与“看好”不是反义。", "搁置": "无反义关系：“搁置”指暂时不处理，与“看好”不是反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89329, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "看衰", "is_correct": true, "explanation": "正确：“看衰”表示认为某人某事不会好，与“看好”正相反。"}, {"text": "冷落", "is_correct": false, "explanation": "无反义关系：“冷落”指怠慢，不是对前景判断的反义。"}, {"text": "推迟", "is_correct": false, "explanation": "无反义关系：“推迟”指把时间往后挪，与“看好”不构成反义。"}, {"text": "拒绝", "is_correct": false, "explanation": "无反义关系：“拒绝”指不接受，与“看好”不构成反义。"}], "correct_answer": "看衰", "explanations": {"看衰": "正确：“看衰”表示认为某人某事不会好，与“看好”正相反。", "冷落": "无反义关系：“冷落”指怠慢，不是对前景判断的反义。", "推迟": "无反义关系：“推迟”指把时间往后挪，与“看好”不构成反义。", "拒绝": "无反义关系：“拒绝”指不接受，与“看好”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89329, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "看好是觉得某人某事会很棒，有希望。", "primary_collocate": null, "pronunciation": "kàn hǎo", "ipa": "kʰan˥˩ xaʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "我很看好你，你一定能赢。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看好这个小男孩的表演。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们都看好他的新店。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看好这个歌手，他唱得真好。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练看好这个年轻人。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们最看好小王。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不看好这部电影。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都看好这个想法，连投资人也想参与。", "target_word": "看好", "complexity_tier": "T3", "furigana": "kàn hǎo", "sentence_source": "generated"}, {"text": "谁都看好她会拿第一名。", "target_word": "看好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看好这个办法，想马上试试。", "target_word": "看好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看好了", "label": "完成体"}, {"form": "不看好", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "觉得某人某事会很棒、有希望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看好", "is_correct": true, "explanation": "正确：“看好”表示觉得对方会很棒、有希望，与句中的鼓励语气相合。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示厌恶、轻视，与“你一定能赢”的鼓励语气相反。"}, {"text": "同情", "is_correct": false, "explanation": "语义：“同情”表示怜悯，与句中充满信心的语气不合。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”是动作，前面加“很”后不能表达对对方能力的评价，与句意不合。"}], "explanations": {"看好": "正确：“看好”表示觉得对方会很棒、有希望，与句中的鼓励语气相合。", "嫌弃": "语义：“嫌弃”表示厌恶、轻视，与“你一定能赢”的鼓励语气相反。", "同情": "语义：“同情”表示怜悯，与句中充满信心的语气不合。", "拥抱": "搭配：“拥抱”是动作，前面加“很”后不能表达对对方能力的评价，与句意不合。"}, "sentence_index": 0, "correct_answer": "看好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在街上看好了老同学。", "explanation": "这里应该用〈看见〉。“看好”表示认为前景好，不表示视线接触到某人；在路上遇到人要说“看见”。"}, {"text": "我非常看好猫。", "explanation": "这里应该用〈喜欢〉。“看好”表示认为前景好，不表示对某种动物的喜爱；表示喜欢要说“喜欢”。"}, {"text": "你放心，我会看好你的行李。", "explanation": "这里应该用〈看管〉。本义项的“看好”表示觉得某人某事会很棒、有希望，不表示照看东西；照看行李要说“看管”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看好", "is_correct": true, "explanation": "正确：“看好”表示觉得某事会很棒、有希望，与“不”组合后表示不看好。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于器物和机器，不能修理一部电影。"}, {"text": "扮演", "is_correct": false, "explanation": "搭配：“扮演”接角色，不能扮演一部电影。"}, {"text": "批改", "is_correct": false, "explanation": "语义：“批改”是给作业、文章打分修改，与电影无关。"}], "explanations": {"看好": "正确：“看好”表示觉得某事会很棒、有希望，与“不”组合后表示不看好。", "修理": "搭配：“修理”用于器物和机器，不能修理一部电影。", "扮演": "搭配：“扮演”接角色，不能扮演一部电影。", "批改": "语义：“批改”是给作业、文章打分修改，与电影无关。"}, "sentence_index": 6, "correct_answer": "看好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我终于看好了他的真面目。", "explanation": "这里应该用〈认清〉。“看好”表示觉得某人某事会很棒、有希望，不能用来表示识别事物的真相。"}, {"text": "大家都看好他的失败。", "explanation": "这里应该用〈嘲笑〉。“看好”表示觉得某事会很好，不能用来表示对别人失败的讥讽。"}, {"text": "他看好了我的错误，我很感动。", "explanation": "这里应该用〈原谅〉。“看好”表示觉得事情会很好，不能用来表示对错误的宽恕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很看好着这个小孩，他一定会有出息。", "corrected_sentence": "我很看好这个小孩，他一定会有出息。", "error_description": "错误：“看好着”。正确：“看好”。“看好”是动词，后面直接接宾语，不能在“看好”后面加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看好好这个新办法，想马上试试。", "corrected_sentence": "他看好这个新办法，想马上试试。", "error_description": "错误：“看好好”，“好”重复。正确：“看好”。“看好”是一个词，不能重复其中的“好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
