INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "认为前景好，有发展希望。", "primary_collocate": null, "pronunciation": "kàn hǎo", "ipa": "kʰan˥˩ xaʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "很多人看好这家公司的未来。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都看好他。", "target_word": "看好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家看好今年的经济。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不太看好这个计划。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投资人看好这个新市场。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师很看好这个学生。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人看好这支球队。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看好这个行业，所以辞职了。", "target_word": "看好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司看好明年的发展。", "target_word": "看好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人曾经看好这家店，后来却关门了。", "target_word": "看好", "complexity_tier": "T3", "furigana": "kàn hǎo", "sentence_source": "generated"}], "morphological_forms": [{"form": "看好了", "label": "完成体"}, {"form": "不看好", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "认为前景好、有发展希望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看好", "is_correct": true, "explanation": "正确：“看好”表示认为前景好，与句中的“未来”搭配。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指想起过去的事，未来还没有发生，不能回忆。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”多接具体的物品或技术，不接“未来”这类抽象的对象。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于器物和机器，不能修理一家公司的未来。"}], "explanations": {"看好": "正确：“看好”表示认为前景好，与句中的“未来”搭配。", "回忆": "语义：“回忆”指想起过去的事，未来还没有发生，不能回忆。", "发明": "搭配：“发明”多接具体的物品或技术，不接“未来”这类抽象的对象。", "修理": "搭配：“修理”用于器物和机器，不能修理一家公司的未来。"}, "sentence_index": 0, "correct_answer": "看好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司很看好员工的迟到。", "explanation": "这里应该用〈反感〉。“看好”表示认为前景好，不能用来表示对员工迟到的态度；表示不满要说“反感”。"}, {"text": "他从我的表情中看好了不安。", "explanation": "这里应该用〈看出〉。“看好”表示认为前景好，不表示察觉某种情绪；从表情中察觉要用“看出”。"}, {"text": "大家应该用平常心看好失败。", "explanation": "这里应该用〈看待〉。“看好”表示认为前景好，不能用来表示对待失败的态度；应说“用平常心看待失败”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看好", "is_correct": true, "explanation": "正确：“看好”表示认为前景好，符合“没有人……这支球队”所表达的对前景的判断。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”接车、船、飞机等交通工具，不能驾驶一支球队。"}, {"text": "扫描", "is_correct": false, "explanation": "搭配：“扫描”接文件、图像等，不接球队。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是把一种语言转成另一种语言，不能翻译一支球队。"}], "explanations": {"看好": "正确：“看好”表示认为前景好，符合“没有人……这支球队”所表达的对前景的判断。", "驾驶": "搭配：“驾驶”接车、船、飞机等交通工具，不能驾驶一支球队。", "扫描": "搭配：“扫描”接文件、图像等，不接球队。", "翻译": "语义：“翻译”是把一种语言转成另一种语言，不能翻译一支球队。"}, "sentence_index": 6, "correct_answer": "看好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一眼就看好了问题的关键。", "explanation": "这里应该用〈看准〉。“看好”表示认为前景好，不表示准确判断问题的关键；说“看准”更合适。"}, {"text": "他终于看好了事情的真相。", "explanation": "这里应该用〈看清〉。“看好”只用于对前景的判断，不表示看清事情的真相。"}, {"text": "她一下子看好了他的谎话。", "explanation": "这里应该用〈看穿〉。“看好”表示认为前景好，不能用来指识破谎言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多人看好着这家公司的前景。", "corrected_sentence": "很多人看好这家公司的前景。", "error_description": "错误：“看好着”。正确：“看好”。“看好”是动词，表示认为前景好，后面直接接宾语，不能在“看好”后面加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看好好这个行业的前景。", "corrected_sentence": "他看好这个行业的前景。", "error_description": "错误：“看好好”，“好”重复。正确：“看好”。“看好”是一个词，不能重复其中的“好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
