INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "战争或统治期间关押并虐待大批人员的场所。", "primary_collocate": null, "pronunciation": "jí zhōng yíng", "ipa": "tɕi˧˥ ʈʂʊŋ˥ iŋ˧˥", "syllable_count": 3, "sentences": [{"text": "战争期间，敌人建了许多集中营。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集中营里的囚犯每天都要做苦工。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵把大批平民关进了集中营。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，人们打开了这座集中营的大门。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸存者讲述了他在集中营的遭遇。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，我们学到了纳粹集中营的罪行。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集中营旧址前立着一块纪念碑。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵把父母和孩子分开，送进不同的集中营。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在集中营里受到了残酷的虐待。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者来到旧集中营，采访了几位老人。", "target_word": "集中营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座集中营", "label": "量词"}, {"form": "集中營", "label": "繁体"}], "register": "书面", "sense_fingerprint": "战争或统治期间关押并虐待大批人员的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62e3c067-3c4e-4854-b164-7c1afd2d112c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集中营", "is_correct": true, "explanation": "正确。集中营是战争期间敌人建造的关押场所，符合句意。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“建”不与“歌曲”搭配，歌曲应说“创作”或“唱”。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是自然地理事物，不能由敌人建造，句意不通。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，不是战争中敌人建造的设施，与句意冲突。"}], "explanations": {"集中营": "正确。集中营是战争期间敌人建造的关押场所，符合句意。", "歌曲": "搭配：“建”不与“歌曲”搭配，歌曲应说“创作”或“唱”。", "海洋": "语义：海洋是自然地理事物，不能由敌人建造，句意不通。", "面条": "语义：面条是食物，不是战争中敌人建造的设施，与句意冲突。"}, "sentence_index": 0, "correct_answer": "集中营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班周末去集中营野餐，大家玩得很开心。", "explanation": "这里应该用〈公园〉。集中营是战争或统治期间关押并虐待大批人员的场所，不是野餐游玩的地方，应用公园。"}, {"text": "洪水过后，村民被安置在集中营里。", "explanation": "这里应该用〈收容所〉。集中营是迫害和关押大批人员的场所，安置村民要用收容所。"}, {"text": "他每天都在集中营里写作业。", "explanation": "这里应该用〈学校〉。集中营是关押并虐待大批人员的场所，不能用来写作业，应用学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集中营", "is_correct": true, "explanation": "正确。“……旧址前立着一块纪念碑”指的是曾经关押人员的场所旧址，集中营符合句意。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮品，不是可以有旧址的地点，句意不通。"}, {"text": "乒乓球", "is_correct": false, "explanation": "语义：乒乓球是体育用品，不能有旧址，与“立着一块纪念碑”的情境不符。"}, {"text": "春天", "is_correct": false, "explanation": "搭配：“旧址”只用于建筑或场所，不能用于时间，“春天旧址”不成词。"}], "explanations": {"集中营": "正确。“……旧址前立着一块纪念碑”指的是曾经关押人员的场所旧址，集中营符合句意。", "牛奶": "语义：牛奶是饮品，不是可以有旧址的地点，句意不通。", "乒乓球": "语义：乒乓球是体育用品，不能有旧址，与“立着一块纪念碑”的情境不符。", "春天": "搭配：“旧址”只用于建筑或场所，不能用于时间，“春天旧址”不成词。"}, "sentence_index": 6, "correct_answer": "集中营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在集中营里看了一场足球比赛。", "explanation": "这里应该用〈体育场〉。集中营是战争或统治期间关押并虐待大批人员的场所，不能用来看足球比赛，应用体育场。"}, {"text": "周末我们在集中营游泳。", "explanation": "这里应该用〈游泳池〉。集中营是战争或统治期间关押并虐待大批人员的场所，不能用来游泳，应用游泳池。"}, {"text": "他每天早上都去集中营买菜。", "explanation": "这里应该用〈菜市场〉。集中营是关押并虐待大批人员的场所，不能去买菜，应用菜市场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "战争结束后，那只集中营被拆掉了。", "corrected_sentence": "战争结束后，那座集中营被拆掉了。", "error_description": "量词错误：集中营是场所，应用量词“座”，“只”多用于动物。应说“那座集中营”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座的集中营旧址现在改成了博物馆。", "corrected_sentence": "这座集中营旧址现在改成了博物馆。", "error_description": "错误形式：“这座的集中营旧址”；正确形式：“这座集中营旧址”。量词短语“这座”后面不能加“的”再修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89333, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穿", "is_correct": true, "explanation": "正确：“穿”与“脱”互为反义，脱衣服与穿衣服相对。"}, {"text": "煮", "is_correct": false, "explanation": "“煮”是烹饪，与脱衣服没有反义关系。"}, {"text": "扫", "is_correct": false, "explanation": "“扫”是清除灰尘，与脱衣服没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”是发出乐音，与“脱”没有反义关系。"}], "correct_answer": "穿", "explanations": {"穿": "正确：“穿”与“脱”互为反义，脱衣服与穿衣服相对。", "煮": "“煮”是烹饪，与脱衣服没有反义关系。", "扫": "“扫”是清除灰尘，与脱衣服没有反义关系。", "唱": "“唱”是发出乐音，与“脱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89333, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "穿", "is_correct": true, "explanation": "正确：“穿”与“脱”互为反义，脱衣服与穿衣服相对。"}, {"text": "看", "is_correct": false, "explanation": "“看”是视觉活动，与脱衣服没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "“读”是阅读，与“脱”没有反义关系。"}, {"text": "等", "is_correct": false, "explanation": "“等”是等待，与脱衣服没有反义关系。"}], "correct_answer": "穿", "explanations": {"穿": "正确：“穿”与“脱”互为反义，脱衣服与穿衣服相对。", "看": "“看”是视觉活动，与脱衣服没有反义关系。", "读": "“读”是阅读，与“脱”没有反义关系。", "等": "“等”是等待，与脱衣服没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89333, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把穿在身上的衣服拿下来。", "primary_collocate": null, "pronunciation": "tuō", "ipa": "tʰuɔ˥", "syllable_count": 1, "sentences": [{"text": "他把外套脱了。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋里很热，请脱外套。", "target_word": "脱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "洗澡以前，先脱衣服。", "target_word": "脱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生让我脱下上衣，检查身体。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气暖和了，我可以脱毛衣了。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一回家就脱下湿衣服，去洗澡。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子自己会脱衣服，不用妈妈帮忙。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他正在房间里脱外套，电话响了。", "target_word": "脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有在别人面前脱过衣服。", "target_word": "脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热的话，你可以把衬衫脱下来。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱了", "label": "体标"}, {"form": "脱过", "label": "体标"}, {"form": "脱下", "label": "复合"}, {"form": "脫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把外套、衣服等穿在身上的衣服取下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89333, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脱", "is_correct": true, "explanation": "正确：脱 tuō（第一声），意思是把穿在身上的衣服拿下来。"}, {"text": "驮", "is_correct": false, "explanation": "tuó（第二声）与 tuō（第一声）声调不同，意思是用背承载。"}, {"text": "拓", "is_correct": false, "explanation": "tuò（第四声）与 tuō（第一声）声调不同，意思是开拓、拓印。"}, {"text": "退", "is_correct": false, "explanation": "tuì 与 tuō 韵母不同（ì 与 ō），意思是后退。"}, {"text": "锅", "is_correct": false, "explanation": "guō 与 tuō 声母不同（g 与 t），声调相同，意思是锅。"}, {"text": "梭", "is_correct": false, "explanation": "suō 与 tuō 声母不同（s 与 t），声调相同，意思是织布用的梭子。"}], "explanations": {"脱": "正确：脱 tuō（第一声），意思是把穿在身上的衣服拿下来。", "驮": "tuó（第二声）与 tuō（第一声）声调不同，意思是用背承载。", "拓": "tuò（第四声）与 tuō（第一声）声调不同，意思是开拓、拓印。", "退": "tuì 与 tuō 韵母不同（ì 与 ō），意思是后退。", "锅": "guō 与 tuō 声母不同（g 与 t），声调相同，意思是锅。", "梭": "suō 与 tuō 声母不同（s 与 t），声调相同，意思是织布用的梭子。"}, "sentence_index": null, "correct_answer": "脱"}, "level_3": {"options": [{"text": "脱", "is_correct": true, "explanation": "正确：把穿在身上的外套取下来，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能支配“外套”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不是衣物。"}, {"text": "写", "is_correct": false, "explanation": "语义：外套不能被“写”，句子无法理解。"}], "explanations": {"脱": "正确：把穿在身上的外套取下来，与句意相符。", "吃": "搭配：“吃”不能支配“外套”。", "喝": "搭配：“喝”的对象是饮料，不是衣物。", "写": "语义：外套不能被“写”，句子无法理解。"}, "sentence_index": 0, "correct_answer": "脱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙脱进了锁孔，打开了门。", "explanation": "这里应该用〈插〉。脱用于衣物、鞋袜，钥匙插进锁孔要说插。"}, {"text": "我把行李脱上了车，准备出发。", "explanation": "这里应该用〈搬〉。脱用于衣物、鞋袜，行李搬上车要说搬。"}, {"text": "他在河边脱到了一条大鱼，很高兴。", "explanation": "这里应该用〈钓〉。脱用于衣物、鞋袜，钓到鱼要说钓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89333, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "脱", "is_correct": true, "explanation": "正确：脱 tuō（第一声），意思是把穿在身上的衣服拿下来。"}, {"text": "驼", "is_correct": false, "explanation": "tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。"}, {"text": "妥", "is_correct": false, "explanation": "tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。"}, {"text": "推", "is_correct": false, "explanation": "tuī 与 tuō 韵母不同（ī 与 ō），意思是用力向前移动。"}, {"text": "多", "is_correct": false, "explanation": "duō 与 tuō 声母不同（d 与 t），声调相同，意思是数量大。"}, {"text": "唾", "is_correct": false, "explanation": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液、吐唾沫。"}], "explanations": {"脱": "正确：脱 tuō（第一声），意思是把穿在身上的衣服拿下来。", "驼": "tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。", "妥": "tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。", "推": "tuī 与 tuō 韵母不同（ī 与 ō），意思是用力向前移动。", "多": "duō 与 tuō 声母不同（d 与 t），声调相同，意思是数量大。", "唾": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液、吐唾沫。"}, "sentence_index": null, "correct_answer": "脱"}, "level_3": {"options": [{"text": "脱", "is_correct": true, "explanation": "正确：孩子自己把衣服脱下，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：衣服不能唱，句子无法理解。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”不能支配“衣服”。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”用于人或动物，不用于衣服。"}], "explanations": {"脱": "正确：孩子自己把衣服脱下，与句意相符。", "唱": "语义：衣服不能唱，句子无法理解。", "读": "搭配：“读”不能支配“衣服”。", "喂": "搭配：“喂”用于人或动物，不用于衣服。"}, "sentence_index": 6, "correct_answer": "脱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先脱开了衬衫的扣子，然后出门。", "explanation": "这里应该用〈解〉（解开扣子）。扣子是解开的，不是脱掉。"}, {"text": "他把水脱进了杯子，喝了一口。", "explanation": "这里应该用〈倒〉。脱用于衣物、鞋袜，水倒进杯子要说倒。"}, {"text": "孩子把玩具脱回了箱子里。", "explanation": "这里应该用〈放〉。脱用于衣物、鞋袜，玩具放回箱子要说放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, mo