INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89334, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把穿在脚上的鞋、袜等从脚上取下。", "primary_collocate": null, "pronunciation": "tuō", "ipa": "tʰuɔ˥", "syllable_count": 1, "sentences": [{"text": "进门要脱鞋。", "target_word": "脱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太热了，他把袜子脱了。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她脱下湿袜子，放在门口。", "target_word": "脱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子睡觉前自己脱鞋。", "target_word": "脱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "游泳以前，请先把鞋脱了。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从来没有在饭馆里脱过鞋。", "target_word": "脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在家里，我喜欢脱了鞋走路。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "袜子湿了，快脱下来换一双。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面很冷，别脱袜子。", "target_word": "脱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他脱下脏鞋，换上了干净的拖鞋。", "target_word": "脱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱了", "label": "体标"}, {"form": "脱过", "label": "体标"}, {"form": "脱下", "label": "复合"}, {"form": "脫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把鞋、袜子等穿戴的东西从身体上取下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62cc808b-1d77-4da2-a098-96e4506bf48a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89334, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脱", "is_correct": true, "explanation": "正确：脱 tuō（第一声），意思是使衣物、鞋袜等离开身体。"}, {"text": "驼", "is_correct": false, "explanation": "tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。"}, {"text": "妥", "is_correct": false, "explanation": "tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。"}, {"text": "唾", "is_correct": false, "explanation": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液、吐唾沫。"}, {"text": "推", "is_correct": false, "explanation": "tuī 与 tuō 韵母不同（ī 与 ō），意思是用力向前移动。"}, {"text": "多", "is_correct": false, "explanation": "duō 与 tuō 声母不同（d 与 t），声调相同，意思是数量大。"}], "explanations": {"脱": "正确：脱 tuō（第一声），意思是使衣物、鞋袜等离开身体。", "驼": "tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。", "妥": "tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。", "唾": "tuò（第四声）与 tuō（第一声）声调不同，意思是唾液、吐唾沫。", "推": "tuī 与 tuō 韵母不同（ī 与 ō），意思是用力向前移动。", "多": "duō 与 tuō 声母不同（d 与 t），声调相同，意思是数量大。"}, "sentence_index": null, "correct_answer": "脱"}, "level_3": {"options": [{"text": "脱", "is_correct": true, "explanation": "正确：进门后把鞋取下，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能支配“鞋”。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象不是鞋。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象不是鞋，进门要唱鞋不合情理。"}], "explanations": {"脱": "正确：进门后把鞋取下，与句意相符。", "吃": "搭配：“吃”不能支配“鞋”。", "写": "搭配：“写”的对象不是鞋。", "唱": "语义：唱的对象不是鞋，进门要唱鞋不合情理。"}, "sentence_index": 0, "correct_answer": "脱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "进门以后，他先脱开鞋带。", "explanation": "这里应该用〈解〉。鞋带要说解开，不说脱。"}, {"text": "他从树上脱了一朵花，送给了妈妈。", "explanation": "这里应该用〈采〉。脱用于衣物、鞋袜等穿戴的东西，从树上取花要说采。"}, {"text": "我把墙上的画脱下来擦干净了。", "explanation": "这里应该用〈取〉。脱用于衣物、鞋袜等穿在身上的东西，墙上的画要说取下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89334, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "脱", "is_correct": true, "explanation": "正确：脱 tuō（第一声），意思是使衣物、鞋袜等离开身体。"}, {"text": "锅", "is_correct": false, "explanation": "guō 与 tuō 声母不同（g 与 t），声调相同，意思是锅。"}, {"text": "梭", "is_correct": false, "explanation": "suō 与 tuō 声母不同（s 与 t），声调相同，意思是织布用的梭子。"}, {"text": "拓", "is_correct": false, "explanation": "tuò（第四声）与 tuō（第一声）声调不同，意思是开拓、拓印。"}, {"text": "陀", "is_correct": false, "explanation": "tuó（第二声）与 tuō（第一声）声调不同，多见于“陀螺”。"}, {"text": "退", "is_correct": false, "explanation": "tuì 与 tuō 韵母不同（ì 与 ō），意思是后退。"}], "explanations": {"脱": "正确：脱 tuō（第一声），意思是使衣物、鞋袜等离开身体。", "锅": "guō 与 tuō 声母不同（g 与 t），声调相同，意思是锅。", "梭": "suō 与 tuō 声母不同（s 与 t），声调相同，意思是织布用的梭子。", "拓": "tuò（第四声）与 tuō（第一声）声调不同，意思是开拓、拓印。", "陀": "tuó（第二声）与 tuō（第一声）声调不同，多见于“陀螺”。", "退": "tuì 与 tuō 韵母不同（ì 与 ō），意思是后退。"}, "sentence_index": null, "correct_answer": "脱"}, "level_3": {"options": [{"text": "脱", "is_correct": true, "explanation": "正确：在家不穿鞋走路，与句意相符。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等，不说“戴鞋”。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于取下帽子、花等，不用于鞋。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的对象是书、文章，不能说“读鞋”。"}], "explanations": {"脱": "正确：在家不穿鞋走路，与句意相符。", "戴": "搭配：“戴”用于帽子、眼镜等，不说“戴鞋”。", "摘": "搭配：“摘”用于取下帽子、花等，不用于鞋。", "读": "搭配：“读”的对象是书、文章，不能说“读鞋”。"}, "sentence_index": 6, "correct_answer": "脱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把眼镜脱下来放在桌上。", "explanation": "这里应该用〈摘〉。脱用于衣物、鞋袜，眼镜戴在脸上，取下要说摘。"}, {"text": "他把被子脱在身上，很快睡着了。", "explanation": "这里应该用〈盖〉。脱用于衣物、鞋袜，被子盖在身上要说盖，不说脱。"}, {"text": "他从书架上脱下一本书，坐下来读。", "explanation": "这里应该用〈拿〉。脱用于衣物、鞋袜，书架上的书要说拿下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一进门就把鞋脱。", "corrected_sentence": "他一进门就把鞋脱了。", "error_description": "“把”字句缺少“了”：“把”字句的动词后要有“了”或补语，应说“把鞋脱了”，不能只说“把鞋脱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐下来，慢慢脱了下鞋。", "corrected_sentence": "他坐下来，慢慢脱下了鞋。", "error_description": "补语与“了”的位置错误：“脱下”是动词加结果补语，“了”应放在补语后，说“脱下了鞋”，不能说“脱了下鞋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a87eb31a-25b9-4918-8ffa-4fb95551d27c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
