INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89335, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看相是有人看你的脸，说你以后会怎么样。", "primary_collocate": null, "pronunciation": "kàn xiàng", "ipa": "kʰan˥˩ ɕiaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "朋友会看相，他看了看我的脸。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“我来给你看相吧。”", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他看相很准，大家都想试试。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在晚会上玩看相的游戏。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着我的脸，开始给我看相。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说我以后会有钱，这是他看相的结果。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想让他给你看相吗？", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸开玩笑说，他也会看相。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看相的人说我明年会去国外。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想看相，我想自己决定以后。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看了相", "label": "体标（了）"}, {"form": "看过相", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "看人的脸并说其将来会怎样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与后半句“看了看我的脸”没有关系，前后不呼应。"}, {"text": "看相", "is_correct": true, "explanation": "正确：“看相”指看人的脸说其将来会怎样，与后半句“看了看我的脸”呼应。"}, {"text": "修车", "is_correct": false, "explanation": "语义：“修车”与看脸不是同一类事情，前后不呼应。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“朋友会唱歌”与后半句的“看脸”搭配不上，前后语义断开。"}], "explanations": {"游泳": "语义：“游泳”与后半句“看了看我的脸”没有关系，前后不呼应。", "看相": "正确：“看相”指看人的脸说其将来会怎样，与后半句“看了看我的脸”呼应。", "修车": "语义：“修车”与看脸不是同一类事情，前后不呼应。", "唱歌": "搭配：“朋友会唱歌”与后半句的“看脸”搭配不上，前后语义断开。"}, "sentence_index": 0, "correct_answer": "看相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仓库管理员每天在仓库里看相，检查货物。", "explanation": "这里应该用〈检查〉。看相是看面貌算命，不能用来指检查货物。"}, {"text": "她每天早上看相，花很长时间才出门。", "explanation": "这里应该用〈化妆〉。看相是看面貌算命，不能指早上打扮自己。"}, {"text": "他在电影院看相，买了一桶爆米花。", "explanation": "这里应该用〈看电影〉。看相是算命，不能用来指在电影院观影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "配价：“出生”不能带“给你”这样的间接对象，“给你出生”不通。"}, {"text": "看相", "is_correct": true, "explanation": "正确：“看相”可以用“给你”引出对象，“你想让他给你看相吗”通顺。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能说“给你睡觉”。"}, {"text": "生", "is_correct": false, "explanation": "语义：“给你生”指替你生孩子，与“看相”的语境完全不符。"}], "explanations": {"出生": "配价：“出生”不能带“给你”这样的间接对象，“给你出生”不通。", "看相": "正确：“看相”可以用“给你”引出对象，“你想让他给你看相吗”通顺。", "睡觉": "配价：“睡觉”是不及物动词，不能说“给你睡觉”。", "生": "语义：“给你生”指替你生孩子，与“看相”的语境完全不符。"}, "sentence_index": 6, "correct_answer": "看相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去车站看相，等了一个小时的车。", "explanation": "这里应该用〈等车〉。看相是算命，不能用来说在车站等车。"}, {"text": "他在超市看相，买了很多水果。", "explanation": "这里应该用〈买水果〉。看相是算命，在超市购物要说“买”。"}, {"text": "我每天晚上在河边看相，游了一个小时的泳。", "explanation": "这里应该用〈游泳〉。看相是看面貌算命，不能指在河里游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看相看很准，大家都找他。", "corrected_sentence": "他看相看得很准，大家都找他。", "error_description": "错误：“看相看很准”，缺少补语标记“得”。正确：“看相看得很准”，动词后带表示程度的补语要用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看了我的脸，然后把我看相。", "corrected_sentence": "他看了我的脸，然后给我看相。", "error_description": "错误：“把我看相”，“把”字句不能这样用。正确：“给我看相”，“给”引出看相的对象，句子才通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
