INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据人的面貌、体态等判断其命运吉凶的迷信做法。", "primary_collocate": null, "pronunciation": "kàn xiàng", "ipa": "kʰan˥˩ ɕiaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "奶奶年轻时相信看相，现在不信了。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在庙门口给人看相。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说看相能知道一个人的命运，但这是迷信。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人以前靠看相过日子。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来不去看相，因为我不信命。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请了一位先生给孩子看相。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街边有个人在看相，很多人围着他。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人过年时去庙里看相算命。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去看相以后，心里一直不安。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看相是旧社会的一种迷信做法。", "target_word": "看相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看了相", "label": "体标（了）"}, {"form": "看过相", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "凭面相体态判断命运吉凶的迷信做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "搭配：“相信”后接的是说法或道理，不能接“游泳”。"}, {"text": "看相", "is_correct": true, "explanation": "正确：“相信看相”指相信看面貌算命的做法，与后面“现在不信了”呼应。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“相信跑步”搭配不通，“相信”不接体育活动。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：“下棋”是游戏，与迷信做法不是同一类事情，句意不通。"}], "explanations": {"游泳": "搭配：“相信”后接的是说法或道理，不能接“游泳”。", "看相": "正确：“相信看相”指相信看面貌算命的做法，与后面“现在不信了”呼应。", "跑步": "搭配：“相信跑步”搭配不通，“相信”不接体育活动。", "下棋": "语义：“下棋”是游戏，与迷信做法不是同一类事情，句意不通。"}, "sentence_index": 0, "correct_answer": "看相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生在诊室里看相，很多病人在排队。", "explanation": "这里应该用〈看病〉。看相是根据面貌算命，诊室里的工作要说“看病”。"}, {"text": "他在图书馆看相，很安静。", "explanation": "这里应该用〈看书〉。看相是算命的意思，在图书馆读书要说“看书”。"}, {"text": "周末他去电影院看相，买了一张票。", "explanation": "这里应该用〈看电影〉。看相是算命，不能用来指在电影院观影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗澡", "is_correct": false, "explanation": "语义：街边洗澡不合常理，“围着他”的场面也对不上。"}, {"text": "看相", "is_correct": true, "explanation": "正确：“看相”指街边给人算命，很多人围观，句意通顺。"}, {"text": "生孩子", "is_correct": false, "explanation": "语义：街边生孩子不符合情理，句子前后不连贯。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”是完成学业，不能说“街边有个人在毕业”，句意不通。"}], "explanations": {"洗澡": "语义：街边洗澡不合常理，“围着他”的场面也对不上。", "看相": "正确：“看相”指街边给人算命，很多人围观，句意通顺。", "生孩子": "语义：街边生孩子不符合情理，句子前后不连贯。", "毕业": "语义：“毕业”是完成学业，不能说“街边有个人在毕业”，句意不通。"}, "sentence_index": 6, "correct_answer": "看相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工作是看守仓库，每天晚上都要看相。", "explanation": "这里应该用〈看守〉。看相是算命的意思，不能用来指守护仓库。"}, {"text": "我每天早上看相，决定要不要带伞。", "explanation": "这里应该用〈看天〉。看相是看面貌算命，不能用来判断天气。"}, {"text": "周末我们去博物馆看相，看了很多展品。", "explanation": "这里应该用〈看展览〉。看相是算命，不能用来说参观展览。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶年轻时看相过。", "corrected_sentence": "奶奶年轻时看过相。", "error_description": "错误：“看相过”，“过”放错了位置。正确：“看过相”，离合词的“过”要插在“看”和“相”中间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街边那人看相看很仔细，很多人围着他。", "corrected_sentence": "街边那人看相看得很仔细，很多人围着他。", "error_description": "错误：“看相看很仔细”，缺少补语标记“得”。正确：“看相看得很仔细”，动词后带表示程度的补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89338, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好走", "is_correct": true, "explanation": "好走：（道路）平坦，容易走，与“难走”相反。"}, {"text": "干净", "is_correct": false, "explanation": "干净：形容清洁，与道路的难易无关，不是反义。"}, {"text": "安静", "is_correct": false, "explanation": "安静：形容环境没有声音，与道路的难易无关。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴：形容心情愉快，与道路的难易无关。"}], "correct_answer": "好走", "explanations": {"好走": "好走：（道路）平坦，容易走，与“难走”相反。", "干净": "干净：形容清洁，与道路的难易无关，不是反义。", "安静": "安静：形容环境没有声音，与道路的难易无关。", "高兴": "高兴：形容心情愉快，与道路的难易无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89338, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好走", "is_correct": true, "explanation": "好走：（道路）平坦，容易走，与“难走”相反。"}, {"text": "美丽", "is_correct": false, "explanation": "美丽：形容好看，与道路的难易无关。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线充足，与道路的难易无关。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容明白、分明，与道路的难易无关。"}], "correct_answer": "好走", "explanations": {"好走": "好走：（道路）平坦，容易走，与“难走”相反。", "美丽": "美丽：形容好看，与道路的难易无关。", "明亮": "明亮：形容光线充足，与道路的难易无关。", "清楚": "清楚：形容明白、分明，与道路的难易无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89338, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（道路）不好走；不平坦。", "primary_collocate": null, "pronunciation": "nán zǒu", "ipa": "nan˧˥ tsou˨˩˦", "syllable_count": 2, "sentences": [{"text": "下雨以后，山路特别难走。", "target_word": "难走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路又窄又滑，很难走。", "target_word": "难走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪太厚，路很难走。", "target_word": "难走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的路坑坑洼洼，很难走。", "target_word": "难走", "complexity_tier": "T3", "furigana": "cūn lǐ de lù kēng kēng wā wā, hěn nán zǒu.", "sentence_source": "generated"}, {"text": "山上的石头路不平，难走极了。", "target_word": "难走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路太难走，我们走了三个小时。", "target_word": "难走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条河边的路都是泥，特别难走。", "target_word": "难走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说前面的路难走，我们早点出发吧。", "target_word": "难走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾天，高速路也变得难走了。", "target_word": "难走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路难走，开车要慢一点。", "target_word": "难走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "道路不平坦，不好走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9972b9e1-64e7-4f48-a29b-69eff6f37281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "难走", "is_correct": true, "explanation": "难走：道路不好走，与“下雨以后”的路况相符。"}, {"text": "平坦", "is_correct": false, "explanation": "语义：“平坦”与“下雨以后”的路况相反，山路不会因下雨而平坦。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：下雨以后的山路不会干燥，与语境矛盾。"}, {"text": "晴朗", "is_correct": false, "explanation": "搭配：「晴朗」形容天气，不能用来修饰山路。"}], "explanations": {"难走": "难走：道路不好走，与“下雨以后”的路况相符。", "平坦": "语义：“平坦”与“下雨以后”的路况相反，山路不会因下雨而平坦。", "干燥": "语义：下雨以后的山路不会干燥，与语境矛盾。", "晴朗": "搭配：「晴朗」形容天气，不能用来修饰山路。"}, "sentence_index": 0, "correct_answer": "难走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他性格很古怪，大家都觉得他很难走。", "explanation": "这里应该用〈难相处〉。“难走”只用于道路，不能用来形容人的性格。"}, {"text": "这篇文章太深，读起来很难走。", "explanation": "这里应该用〈难懂〉。“难走”描述道路，形容文章要说“难懂”。"}, {"text": "这件衣服颜色太旧，看起来很难走。", "explanation": "这里应该用〈难看〉。“难走”只说道路，不能用来形容衣服的外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难走", "is_correct": true, "explanation": "难走：道路不好走，与“都是泥”的路况相符。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：「干燥」与「都是泥」的路况相反，泥路不会干燥。"}, {"text": "方便", "is_correct": false, "explanation": "语义：“方便”表示省事，不能用来描述泥路的状况。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来修饰道路。"}], "explanations": {"难走": "难走：道路不好走，与“都是泥”的路况相符。", "干燥": "语义：「干燥」与「都是泥」的路况相反，泥路不会干燥。", "方便": "语义：“方便”表示省事，不能用来描述泥路的状况。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来修饰道路。"}, "sentence_index": 6, "correct_answer": "难走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗很难走。", "explanation": "这里应该用〈难写〉。“难走”只说道路，诗要说“难写”。"}, {"text": "这件毛衣很难走。", "explanation": "这里应该用〈难洗〉。“难走”只说道路，衣服要说“难洗”。"}, {"text": "这首歌很难走。", "explanation": "这里应该用〈难听〉。“难走”只说道路，歌曲要说“难听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条泥路很很难走。", "corrected_sentence": "这条泥路很难走。", "error_description": "错误：程度副词「很」重复，成了「很很难走」。正确：「这条泥路很难走。」只用一个「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下过雨后，这条土路很难难走。", "corrected_sentence": "下过雨后，这条土路很难走。", "error_description": "错误：「难」字重复，成了「很难难走」。正确：「下过雨后，这条土路很难走。」「难走」中间不能多出一个「难」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2083af10-c9a0-4090-80b0-378d1e1818d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
