INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89339, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听别人说。", "primary_collocate": null, "pronunciation": "jiàn shuō", "ipa": "tɕjɛn˥˩ ʂwo˥", "syllable_count": 2, "sentences": [{"text": "见说他昨天生病了，今天还没来上班。", "target_word": "见说", "complexity_tier": "T3", "furigana": "jiàn shuō tā zuó tiān shēng bìng le, jīn tiān hái méi lái shàng bān", "sentence_source": "generated"}, {"text": "见说小李要去北京工作了。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说这家饭馆的鱼很好吃。", "target_word": "见说", "complexity_tier": "T3", "furigana": "jiàn shuō zhè jiā fàn guǎn de yú hěn hǎo chī", "sentence_source": "generated"}, {"text": "见说后天会下雪，大家都早点回家。", "target_word": "见说", "complexity_tier": "T3", "furigana": "jiàn shuō hòu tiān huì xià xuě, dà jiā dōu zǎo diǎn huí jiā", "sentence_source": "generated"}, {"text": "见说你擅长烹饪，不知可否赐教。", "target_word": "见说", "complexity_tier": "T3", "furigana": "jiàn shuō nǐ shàn cháng pēng rèn, bù zhī kě fǒu cì jiào", "sentence_source": "generated"}, {"text": "见说你已经搬到新家了。", "target_word": "见说", "complexity_tier": "T3", "furigana": "jiàn shuō nǐ yǐ jīng bān dào xīn jiā le", "sentence_source": "generated"}, {"text": "见说孙子已经回来了，老人很高兴。", "target_word": "见说", "complexity_tier": "T3", "furigana": "jiàn shuō sūn zi yǐ jīng huí lái le, lǎo rén hěn gāo xìng", "sentence_source": "generated"}, {"text": "见说那儿的人都很热情好客。", "target_word": "见说", "complexity_tier": "T3", "furigana": "jiàn shuō nàr de rén dōu hěn rè qíng hào kè", "sentence_source": "generated"}, {"text": "见说你的猫已经找到了。", "target_word": "见说", "complexity_tier": "T3", "furigana": "jiàn shuō nǐ de māo yǐ jīng zhǎo dào le", "sentence_source": "generated"}, {"text": "见说考试很难，大家都有点担心。", "target_word": "见说", "complexity_tier": "T3", "furigana": "jiàn shuō kǎo shì hěn nán, dà jiā dōu yǒu diǎn dān xīn", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "从别人那里听到消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见说", "is_correct": true, "explanation": "正确。见说表示听别人说，与“听说他昨天生病了”相符。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：祝贺是为喜事道贺，对生病不能祝贺，句意矛盾。"}, {"text": "赞扬", "is_correct": false, "explanation": "语义：赞扬是称赞好的表现，生病不值得赞扬，句意不通。"}, {"text": "叮嘱", "is_correct": false, "explanation": "配价：叮嘱后接的是要对方注意或去做的事，不能接已经发生的病情。"}], "explanations": {"见说": "正确。见说表示听别人说，与“听说他昨天生病了”相符。", "祝贺": "语义：祝贺是为喜事道贺，对生病不能祝贺，句意矛盾。", "赞扬": "语义：赞扬是称赞好的表现，生病不值得赞扬，句意不通。", "叮嘱": "配价：叮嘱后接的是要对方注意或去做的事，不能接已经发生的病情。"}, "sentence_index": 0, "correct_answer": "见说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我亲眼见说窗外下雪了。", "explanation": "这里应该用〈看见〉。见说表示听别人说，不能用于亲眼看到的事。"}, {"text": "我对他见说明天会下雪。", "explanation": "这里应该用〈说〉。见说表示听别人说，不能表示自己对人说话。"}, {"text": "我见说了一封信。", "explanation": "这里应该用〈收到〉。见说表示听别人说，不能接“一封信”这样的具体物品；收到信件才用“收到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见说", "is_correct": true, "explanation": "正确。见说表示听别人说，与“听说孙子已经回来了”相符。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：惩罚是处罚犯错的人，孙子回来不该受罚，与“老人很高兴”不协调。"}, {"text": "埋怨", "is_correct": false, "explanation": "语义：埋怨是抱怨，与“老人很高兴”的语气相矛盾。"}, {"text": "催促", "is_correct": false, "explanation": "配价：催促后接的是要对方尽快去做的事，不能接已经完成的“回来了”。"}], "explanations": {"见说": "正确。见说表示听别人说，与“听说孙子已经回来了”相符。", "惩罚": "语义：惩罚是处罚犯错的人，孙子回来不该受罚，与“老人很高兴”不协调。", "埋怨": "语义：埋怨是抱怨，与“老人很高兴”的语气相矛盾。", "催促": "配价：催促后接的是要对方尽快去做的事，不能接已经完成的“回来了”。"}, "sentence_index": 6, "correct_answer": "见说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我亲眼见说冰箱里有西瓜。", "explanation": "这里应该用〈看见〉。见说表示听别人说，与“亲眼”所见的意思矛盾，不能用于亲眼看到的东西。"}, {"text": "他在门口见说了客人。", "explanation": "这里应该用〈迎接〉。见说表示听别人说，不能用于在门口亲自迎接客人。"}, {"text": "他见说了我的手。", "explanation": "这里应该用〈握〉。见说表示听别人说，不能接身体部位；与人握手应说“握”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "见说了今天下午要开会。", "corrected_sentence": "见说今天下午要开会。", "error_description": "错误在“见说”后多了“了”。“见说”只用来引出所听到的消息，不带完成的意思，不能加“了”。应说“见说今天下午要开会。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "见说着他已经回来了。", "corrected_sentence": "见说他已经回来了。", "error_description": "错误在“着”。“见说”表示听别人说，是一次性的动作，不能加“着”，应说“见说他已经回来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
