INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89340, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（书面）听说。", "primary_collocate": null, "pronunciation": "jiàn shuō", "ipa": "tɕjɛn˥˩ ʂwo˥", "syllable_count": 2, "sentences": [{"text": "见说他已经回到了老家。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说今年的雨水特别多。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说那座老桥明年要重修。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说城里新开了一家书店。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说她考上了最好的大学。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说山那边的风景很美。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说这位老先生写了一本新书。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说他们下个月就要搬家。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说那里的冬天不太冷。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见说校长今天要来看我们。", "target_word": "见说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语的听说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = 