INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见说", "is_correct": true, "explanation": "正确。见说表示听别人说，与“听说他已经回到了老家”相符。"}, {"text": "命令", "is_correct": false, "explanation": "配价：命令后接的是要对方去做的事，不能接已经发生的情况。"}, {"text": "嘱咐", "is_correct": false, "explanation": "配价：嘱咐后接的是要对方去做的事，不能接已经发生的情况。"}, {"text": "要求", "is_correct": false, "explanation": "语义：要求是提出将来应该做的事，“已经回到了老家”是已发生的事，句意不通。"}], "explanations": {"见说": "正确。见说表示听别人说，与“听说他已经回到了老家”相符。", "命令": "配价：命令后接的是要对方去做的事，不能接已经发生的情况。", "嘱咐": "配价：嘱咐后接的是要对方去做的事，不能接已经发生的情况。", "要求": "语义：要求是提出将来应该做的事，“已经回到了老家”是已发生的事，句意不通。"}, "sentence_index": 0, "correct_answer": "见说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在街上见说了一位老朋友。", "explanation": "这里的“见”是会见的意思，“见说”只表示听别人说，不能用于与人见面。"}, {"text": "我亲耳见说他在台上唱歌。", "explanation": "这里应该用〈听见〉。见说表示从别人那里听来，不能用于自己亲耳听到的事。"}, {"text": "我抬头见说了天上的月亮。", "explanation": "这里应该用〈看见〉。见说表示听别人说，不能用于用眼睛看到天上的月亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见说", "is_correct": true, "explanation": "正确。见说表示听别人说，与“听说这位老先生写了一本新书”相符。"}, {"text": "催促", "is_correct": false, "explanation": "语义：催促是要求对方尽快做将来的事，与“写了一本新书”的已完成事实不合。"}, {"text": "决定", "is_correct": false, "explanation": "语义：决定表示意志上的选择，不能决定别人已经完成的事。"}, {"text": "吩咐", "is_correct": false, "explanation": "配价：吩咐后接要对方去做的事，不能接“写了一本新书”这样已完成的事实。"}], "explanations": {"见说": "正确。见说表示听别人说，与“听说这位老先生写了一本新书”相符。", "催促": "语义：催促是要求对方尽快做将来的事，与“写了一本新书”的已完成事实不合。", "决定": "语义：决定表示意志上的选择，不能决定别人已经完成的事。", "吩咐": "配价：吩咐后接要对方去做的事，不能接“写了一本新书”这样已完成的事实。"}, "sentence_index": 6, "correct_answer": "见说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在窗口亲眼见说他走过。", "explanation": "这里应该用〈看见〉。见说表示听别人说，与“亲眼”所见的意思矛盾。"}, {"text": "他在车站见说了老朋友。", "explanation": "这里应该用〈见到〉。见说表示听别人说，不能用于在车站亲眼遇见老朋友。"}, {"text": "老师见说了我们一顿饭。", "explanation": "这里应该用〈请〉，表示请人吃饭。见说表示听别人说消息，不能接“一顿饭”这样的具体事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
