INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89341, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "社区大学是在城市里，让大家晚上或周末也能上课学习的学校。", "primary_collocate": null, "pronunciation": "shè qū dà xué", "ipa": "ʂɤ˥˩ tɕʰy˥ ta˥˩ ɕɥe˧˥", "syllable_count": 4, "sentences": [{"text": "我晚上在社区大学学做饭。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所社区大学周末也有课。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在社区大学学了一年画画。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区大学离我家很近，走路十分钟就到。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班以后，他去社区大学上英语课。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区大学的学费不高，很多人都去学习。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们在社区大学学习用手机。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这里新开了一所社区大学。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去社区大学学习摄影。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区大学的老师晚上才来上课。", "target_word": "社区大学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "社區大學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "城市里晚上或周末也能上课的学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc75b4f-22f0-4900-bff9-b4adab964f2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89341, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医院", "is_correct": false, "explanation": "语义：医院不教做饭，「在医院学做饭」说不通。"}, {"text": "社区大学", "is_correct": true, "explanation": "正确：「社区大学」是晚上可以上课学习的学校，符合「在……学做饭」。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不是教学场所，不能在那里学做饭。"}, {"text": "地铁站", "is_correct": false, "explanation": "搭配：「学做饭」需要能上课的地方，地铁站不搭配。"}], "explanations": {"医院": "语义：医院不教做饭，「在医院学做饭」说不通。", "社区大学": "正确：「社区大学」是晚上可以上课学习的学校，符合「在……学做饭」。", "银行": "语义：银行不是教学场所，不能在那里学做饭。", "地铁站": "搭配：「学做饭」需要能上课的地方，地铁站不搭配。"}, "sentence_index": 0, "correct_answer": "社区大学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我周末去社区大学剪头发。", "explanation": "这里应该用〈理发店〉。社区大学是学校，剪头发要去理发店。"}, {"text": "小区的水管坏了，我们去社区大学报修。", "explanation": "这里应该用〈物业〉。社区大学负责开课，报修要找物业。"}, {"text": "他每次感冒都去社区大学看病。", "explanation": "这里应该用〈社区医院〉。社区大学是学校，看病要去医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89341, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是小朋友上学的地方，与「老人们」不合。"}, {"text": "小学", "is_correct": false, "explanation": "语义：小学招收的是儿童，与「老人们」矛盾。"}, {"text": "社区大学", "is_correct": true, "explanation": "正确：「社区大学」是成年人可以学习的地方，与「老人们」和「学习用手机」相符。"}, {"text": "游泳馆", "is_correct": false, "explanation": "搭配：「学习用手机」需要教学场所，游泳馆不搭配。"}], "explanations": {"幼儿园": "语义：幼儿园是小朋友上学的地方，与「老人们」不合。", "小学": "语义：小学招收的是儿童，与「老人们」矛盾。", "社区大学": "正确：「社区大学」是成年人可以学习的地方，与「老人们」和「学习用手机」相符。", "游泳馆": "搭配：「学习用手机」需要教学场所，游泳馆不搭配。"}, "sentence_index": 6, "correct_answer": "社区大学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的车坏了，我把它开到社区大学去修。", "explanation": "这里应该用〈修车厂〉。社区大学是上课的学校，修车要去修车厂。"}, {"text": "他的牙疼得厉害，去社区大学拔了牙。", "explanation": "这里应该用〈诊所〉。社区大学是学校，拔牙要去诊所。"}, {"text": "我每周六去社区大学买菜。", "explanation": "这里应该用〈农贸市场〉。社区大学是学校，买菜要去市场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张社区大学离我家很近。", "corrected_sentence": "这所社区大学离我家很近。", "error_description": "量词错误：学校的量词是「所」，「张」用于平面的东西。应把「张」改为「所」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他周末社区大学上绘画课。", "corrected_sentence": "他周末在社区大学上绘画课。", "error_description": "介词缺失：表示地点的「社区大学」前应加介词「在」，应为「在社区大学」，漏了「在」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9c3cd9f-57b3-40b7-8a0d-05cf86067979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
