INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "音乐学是研究音乐的学问。", "primary_collocate": null, "pronunciation": "yīn yuè xué", "ipa": "in˥˥ ɥɛ˥˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "音乐学是研究音乐的学问。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥大学毕业后，继续读音乐学。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐学不教你唱歌，只研究音乐。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解一点音乐学。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最喜欢上音乐学这门课。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是音乐学老师，每天听很多音乐。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学音乐学需要读很多书。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有很多音乐学的书。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐学让我知道了很多歌的故事。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么选了音乐学？", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "音乐学家", "label": "复合"}, {"form": "音樂學", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "研究音乐的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60eb8d25-3940-4b37-9ab8-c3a913d8c431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐学", "is_correct": true, "explanation": "正确：“音乐学”就是研究音乐的学问，与句子的定义完全一致。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：“篮球”是一种体育运动，不是研究音乐的学问，与定义相矛盾。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，不是学问，与定义中的“学问”不合。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与书面语的定义句不符，且泛指东西，不能指学问。"}], "explanations": {"音乐学": "正确：“音乐学”就是研究音乐的学问，与句子的定义完全一致。", "篮球": "语义：“篮球”是一种体育运动，不是研究音乐的学问，与定义相矛盾。", "厨房": "语义：“厨房”是做饭的地方，不是学问，与定义中的“学问”不合。", "玩意儿": "语域：“玩意儿”是口语说法，与书面语的定义句不符，且泛指东西，不能指学问。"}, "sentence_index": 0, "correct_answer": "音乐学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我学了一场音乐学。", "explanation": "这里应该用〈门〉。音乐学指研究音乐的学问，不是一场演出；“场”指音乐会这类活动，学问应用“门”计量。"}, {"text": "这位著名的音乐学写了很多歌。", "explanation": "这里应该用〈音乐家〉。“音乐学”指学问，不指人；能写歌的人要说“音乐家”。"}, {"text": "晚上我在房间里放音乐学。", "explanation": "这里应该用〈音乐〉。放的是音乐作品，音乐学是研究音乐的学问，不能播放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐学", "is_correct": true, "explanation": "正确：“学”的宾语是“音乐学”，指学习这门学问，句子说得通，且需要读很多书。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“学”要接知识或技能，“冰箱”是家电，无法作为学习的内容。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“学”要接可以学习的内容，“天空”不是学习的对象。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“学”不能接“操场”这类场所名词，两者不搭配。"}], "explanations": {"音乐学": "正确：“学”的宾语是“音乐学”，指学习这门学问，句子说得通，且需要读很多书。", "冰箱": "语义：“学”要接知识或技能，“冰箱”是家电，无法作为学习的内容。", "天空": "语义：“学”要接可以学习的内容，“天空”不是学习的对象。", "操场": "搭配：“学”不能接“操场”这类场所名词，两者不搭配。"}, "sentence_index": 6, "correct_answer": "音乐学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "音乐学演出得很好。", "explanation": "这里应该用〈乐队〉。音乐学是学科，不能做演出的主语，演出的是乐队。"}, {"text": "音乐学的灯光很亮。", "explanation": "这里应该用〈音乐厅〉。灯光属于演出场所，音乐学是学问，没有灯光。"}, {"text": "音乐学的票卖完了。", "explanation": "这里应该用〈音乐会〉。卖票的是演出，音乐学是学科，不能有票。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学过音乐学过。", "corrected_sentence": "我学过音乐学。", "error_description": "错误：经历体“过”重复出现，放在宾语“音乐学”之后（“学过音乐学过”）；正确说法是“学过音乐学”，“过”只用一次，紧跟动词“学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他读了三个音乐学的书。", "corrected_sentence": "他读了三本音乐学的书。", "error_description": "错误：量词用错了（“三个……书”）。“书”要用量词“本”，正确说法是“三本音乐学的书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
