INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以音乐的历史、理论及现象为研究对象的学科。", "primary_collocate": null, "pronunciation": "yīn yuè xué", "ipa": "in˥˥ ɥɛ˥˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "她在大学学音乐学。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐学研究音乐的历史和理论。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想申请音乐学的研究生。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐学课上，老师讲了很多古代音乐。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对音乐学很感兴趣。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学有很好的音乐学专业。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐学和音乐表演是两个不同的专业。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本关于音乐学的书。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学音乐学的人要读很多书。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的毕业论文是音乐学方面的。", "target_word": "音乐学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "音乐学家", "label": "复合"}, {"form": "音樂學", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "研究音乐历史、理论与现象的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60eb8d25-3940-4b37-9ab8-c3a913d8c431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐学", "is_correct": true, "explanation": "正确：“音乐学”是学科名称，“学”的宾语可以是学科，句子说在大学学习音乐学。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是就餐的场所，不是可以学习的知识或技能，与“学”不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不是学习的内容，与“在大学学”这一语境不符。"}, {"text": "停车场", "is_correct": false, "explanation": "搭配：“学”后面不能接“停车场”这类场所名词，两者不搭配。"}], "explanations": {"音乐学": "正确：“音乐学”是学科名称，“学”的宾语可以是学科，句子说在大学学习音乐学。", "食堂": "语义：“食堂”是就餐的场所，不是可以学习的知识或技能，与“学”不合。", "冰箱": "语义：“冰箱”是家用电器，不是学习的内容，与“在大学学”这一语境不符。", "停车场": "搭配：“学”后面不能接“停车场”这类场所名词，两者不搭配。"}, "sentence_index": 0, "correct_answer": "音乐学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他弹了一首音乐学。", "explanation": "这里应该用〈曲子〉。“音乐学”是学科，不是可以弹奏的作品；弹的应是曲子。"}, {"text": "他是一位音乐学。", "explanation": "这里应该用〈音乐学家〉。“音乐学”指学科，指研究音乐学的人要说“音乐学家”，不能直接说“音乐学”。"}, {"text": "我喜欢听音乐学。", "explanation": "这里应该用〈音乐〉。“音乐学”是研究音乐的学科，不指可以聆听的音乐作品，听的应是“音乐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐学", "is_correct": true, "explanation": "正确：“音乐学”是研究音乐的学科，与“音乐表演”是两个不同领域，可以拿来比较。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”泛指东西，不是专业，与“两个不同的专业”不合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是场所，不是专业，与“两个不同的专业”不合。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：“电梯”是设备，不是专业，与“两个不同的专业”不合。"}], "explanations": {"音乐学": "正确：“音乐学”是研究音乐的学科，与“音乐表演”是两个不同领域，可以拿来比较。", "玩意儿": "语义：“玩意儿”泛指东西，不是专业，与“两个不同的专业”不合。", "厨房": "语义：“厨房”是场所，不是专业，与“两个不同的专业”不合。", "电梯": "语义：“电梯”是设备，不是专业，与“两个不同的专业”不合。"}, "sentence_index": 6, "correct_answer": "音乐学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚上我们去剧院欣赏音乐学。", "explanation": "这里应该用〈音乐会〉。欣赏的应是演出，音乐学是学科，不能被欣赏。"}, {"text": "音乐学的音响很好。", "explanation": "这里应该用〈音乐厅〉。音响属于演出场所，音乐学是学科，没有音响，也不指场所。"}, {"text": "他会弹很多音乐学。", "explanation": "这里应该用〈乐器〉。会弹的是乐器，音乐学是学科，不能被演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在大学学习了三个年音乐学。", "corrected_sentence": "她在大学学习了三年音乐学。", "error_description": "错误：“年”前面多了量词“个”（“三个年”）。“年”直接跟数词，正确说法是“三年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一本关于音乐学新书。", "corrected_sentence": "他写了一本关于音乐学的新书。", "error_description": "错误：“关于音乐学”修饰“新书”时漏掉了“的”；正确说法是“关于音乐学的新书”，定语和中心语之间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
