INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89345, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有人觉得被欺负了，请法官来判断谁对谁错。", "primary_collocate": null, "pronunciation": "sù sòng", "ipa": "su˥˩ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他对公司提出了诉讼。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场诉讼打了两年。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得被骗了，就提起诉讼。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居之间的诉讼让大家很累。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官正在审理这起诉讼。", "target_word": "诉讼", "complexity_tier": "T3", "furigana": "fǎ guān zhèng zài shěn lǐ zhè qǐ sù sòng", "sentence_source": "generated"}, {"text": "为了这场诉讼，他请了律师。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起诉讼的结果很快就出来了。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定放弃这场诉讼。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们对工厂发起了诉讼。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诉讼开始前，两家人都很紧张。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场诉讼", "label": "量词"}, {"form": "一起诉讼", "label": "量词"}, {"form": "民事诉讼", "label": "复合"}], "register": "正式", "sense_fingerprint": "请法官判断对错的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诉讼", "is_correct": true, "explanation": "正确：“提出诉讼”指向法院提起法律程序，与“对公司”搭配自然。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“提出”可接“要求”“意见”，不能接“礼物”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以向公司提出的事项。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内心感受，不能作为向公司提出的内容。"}], "explanations": {"诉讼": "正确：“提出诉讼”指向法院提起法律程序，与“对公司”搭配自然。", "礼物": "搭配：“提出”可接“要求”“意见”，不能接“礼物”。", "天气": "语义：“天气”不是可以向公司提出的事项。", "心情": "语义：“心情”是内心感受，不能作为向公司提出的内容。"}, "sentence_index": 0, "correct_answer": "诉讼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和邻居为了停车位，谈了一场诉讼，闹得很不愉快。", "explanation": "这里应该用〈谈判〉。“谈”搭配谈判、谈话，诉讼是依法向法院提起的程序，不能用“谈”来说。"}, {"text": "他们为了一点小事每天吵一场诉讼，大家都很烦。", "explanation": "这里应该用〈争吵〉。“吵”不能搭配诉讼，诉讼是依法向法院提起的程序，不是口头争执。"}, {"text": "我决定向房东开一场诉讼，让他赔偿损失。", "explanation": "这里应该用〈提起〉。“开”不能搭配诉讼，应说“提起诉讼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诉讼", "is_correct": true, "explanation": "正确：“这起诉讼”指一桩法律案件，结果出来即判决出来。"}, {"text": "沙子", "is_correct": false, "explanation": "搭配：“这起”不能修饰“沙子”，沙子是不可数的物质。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“这起”不能用来计量“蛋糕”，应说“这块”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”没有“结果”可以很快出来，与句意不符。"}], "explanations": {"诉讼": "正确：“这起诉讼”指一桩法律案件，结果出来即判决出来。", "沙子": "搭配：“这起”不能修饰“沙子”，沙子是不可数的物质。", "蛋糕": "搭配：“这起”不能用来计量“蛋糕”，应说“这块”。", "脾气": "语义：“脾气”没有“结果”可以很快出来，与句意不符。"}, "sentence_index": 6, "correct_answer": "诉讼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩经历过一把诉讼，那段日子很难忘。", "explanation": "量词错误：这里应该用〈场〉。“把”用于有柄的东西，诉讼是事件，用“场”或“起”。"}, {"text": "他昨天在饭馆吃了一场诉讼，花了很多钱。", "explanation": "这里应该用〈饭〉。诉讼是向法院提起的法律程序，不能“吃”。"}, {"text": "法官已经宣布了诉讼，这件事就此结束了。", "explanation": "这里应该用〈判决〉。“宣布”搭配判决、结果，诉讼是整个法律程序，不能宣布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们为了房子的归属提起了一把诉讼。", "corrected_sentence": "他们为了房子的归属提起了一场诉讼。", "error_description": "量词错误：“诉讼”应搭配“场”或“起”，“把”用于有柄的物品。正确说法是“一场诉讼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把诉讼拖了三年，双方都很疲惫。", "corrected_sentence": "这场诉讼拖了三年，双方都很疲惫。", "error_description": "量词错误：“诉讼”应用“场”计量，“把”用于有柄的物品。正确说法是“这场诉讼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
