INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当事人向法院提起的、请求依法裁判的活动。", "primary_collocate": null, "pronunciation": "sù sòng", "ipa": "su˥˩ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "提起诉讼前，需要先向法院提交材料。", "target_word": "诉讼", "complexity_tier": "T3", "furigana": "tí qǐ sù sòng qián xū yào xiān xiàng fǎ yuàn tí jiāo cái liào", "sentence_source": "generated"}, {"text": "这起诉讼由当地法院受理。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当事人有权提起诉讼。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诉讼的费用由输的一方承担。", "target_word": "诉讼", "complexity_tier": "T3", "furigana": "sù sòng de fèi yòng yóu shū de yī fāng chéng dān", "sentence_source": "generated"}, {"text": "法院已经受理了这起诉讼。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们通过诉讼要回了欠款。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诉讼进行中，双方不能私下见面。", "target_word": "诉讼", "complexity_tier": "T3", "furigana": "sù sòng jìn xíng zhōng shuāng fāng bù néng sī xià jiàn miàn", "sentence_source": "generated"}, {"text": "这场诉讼的判决明天公布。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在诉讼中提供了合同。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诉讼要依法进行。", "target_word": "诉讼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场诉讼", "label": "量词"}, {"form": "一起诉讼", "label": "量词"}, {"form": "民事诉讼", "label": "复合"}], "register": "正式", "sense_fingerprint": "向法院提起的依法裁判活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f177837-ac51-402c-a2ba-4cafb4a97c24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诉讼", "is_correct": true, "explanation": "正确：“提起诉讼前”指向法院提起法律程序之前，后面的提交材料正与之相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“提起”可接“诉讼”“申请”，不能接“蛋糕”。"}, {"text": "想法", "is_correct": false, "explanation": "语义：“想法”不需要向法院提交材料，与句意矛盾。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是需要向法院提交材料的事项。"}], "explanations": {"诉讼": "正确：“提起诉讼前”指向法院提起法律程序之前，后面的提交材料正与之相符。", "蛋糕": "搭配：“提起”可接“诉讼”“申请”，不能接“蛋糕”。", "想法": "语义：“想法”不需要向法院提交材料，与句意矛盾。", "歌曲": "语义：“歌曲”不是需要向法院提交材料的事项。"}, "sentence_index": 0, "correct_answer": "诉讼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们为了房子谈了一场诉讼，费用由输的一方承担。", "explanation": "这里应该用〈谈判〉。“谈”搭配谈判，诉讼是依法向法院提起的程序，不能用“谈”来说。"}, {"text": "他们昨天给店主送了一场诉讼，店主很生气。", "explanation": "这里应该用〈起诉〉。“送”不能搭配诉讼，动作要说“起诉”，即向法院告对方。"}, {"text": "这把诉讼的费用由输的一方承担。", "explanation": "量词错误：这里应该用〈场〉或〈起〉。“把”用于有柄的东西，不能计量诉讼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诉讼", "is_correct": true, "explanation": "正确：“诉讼进行中”指法律程序在进行，双方不能私下见面，语义吻合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能说“进行中”。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”不是需要双方不能私下见面的程序。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”不能与“进行中”搭配，也不涉及双方见面的限制。"}], "explanations": {"诉讼": "正确：“诉讼进行中”指法律程序在进行，双方不能私下见面，语义吻合。", "天气": "搭配：“天气”不能说“进行中”。", "花园": "语义：“花园”不是需要双方不能私下见面的程序。", "早饭": "搭配：“早饭”不能与“进行中”搭配，也不涉及双方见面的限制。"}, "sentence_index": 6, "correct_answer": "诉讼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩的诉讼很深厚，大家都羡慕我们。", "explanation": "这里应该用〈感情〉。“深厚”形容感情，不形容诉讼这样的法律程序。"}, {"text": "妈妈给我做了一场诉讼当早饭。", "explanation": "这里应该用〈饭菜〉。诉讼是法律程序，不能“做”来吃。"}, {"text": "法院已经作出了诉讼，双方都很满意。", "explanation": "这里应该用〈判决〉。“作出”搭配判决、决定，诉讼是整个法律程序，不能作出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把诉讼从去年一直拖到现在。", "corrected_sentence": "这场诉讼从去年一直拖到现在。", "error_description": "量词错误：“诉讼”应用“场”或“起”计量，“把”用于有柄的物品。正确说法是“这场诉讼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司决定对那家工厂打开诉讼。", "corrected_sentence": "公司决定对那家工厂提起诉讼。", "error_description": "搭配错误：“诉讼”要说“提起诉讼”，不能说“打开诉讼”。正确说法是“公司决定对那家工厂提起诉讼。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22c7d5b9-6f19-41c4-91ba-23bc6b5952dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
