INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89347, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "空袭是飞机从天上来，对地面投下炸弹。", "primary_collocate": null, "pronunciation": "kōng xí", "ipa": "kʰʊŋ˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "昨天夜里，城市遭到了空袭。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空袭一来，大家就跑进地下室。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城里一有空袭，人们马上躲起来。", "target_word": "空袭", "complexity_tier": "T3", "furigana": "kōngxí", "sentence_source": "generated"}, {"text": "空袭中，飞机在天上投下了炸弹。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空袭把这座桥炸坏了。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年冬天，小镇有过一次空袭。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶小时候经历过空袭。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空袭过后，街上全是碎石。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的空袭让孩子们很害怕。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一次空袭持续了一个小时。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "空襲", "label": "繁体"}, {"form": "空袭警报", "label": "复合"}], "register": "中性", "sense_fingerprint": "飞机从天上飞来，向地面投下炸弹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89347, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "空袭", "is_correct": true, "explanation": "正确答案。空袭 kōng xí，指飞机从空中对地面的攻击。"}, {"text": "恐袭", "is_correct": false, "explanation": "kǒng（第三声）与 kōng（第一声）声调不同，意思是恐怖袭击。"}, {"text": "冲袭", "is_correct": false, "explanation": "chōng 与 kōng 声母不同（ch 与 k），意思是冲上去袭击。"}, {"text": "攻袭", "is_correct": false, "explanation": "gōng 与 kōng 声母不同（g 与 k），意思是进攻袭击。"}], "explanations": {"空袭": "正确答案。空袭 kōng xí，指飞机从空中对地面的攻击。", "恐袭": "kǒng（第三声）与 kōng（第一声）声调不同，意思是恐怖袭击。", "冲袭": "chōng 与 kōng 声母不同（ch 与 k），意思是冲上去袭击。", "攻袭": "gōng 与 kōng 声母不同（g 与 k），意思是进攻袭击。"}, "sentence_index": null, "correct_answer": "空袭"}, "level_3": {"options": [{"text": "空袭", "is_correct": true, "explanation": "正确。“遭到了”后接负面事件，“空袭”指飞机从空中的攻击，符合语境。"}, {"text": "展览", "is_correct": false, "explanation": "搭配：“遭到”多用于不幸的事件，不能说遭到“展览”。"}, {"text": "夜景", "is_correct": false, "explanation": "语义：“夜景”指夜晚的景色，与“遭到了”所说的灾难语境不符。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”是令人高兴的日子，与“遭到了”的不幸语境矛盾。"}], "explanations": {"空袭": "正确。“遭到了”后接负面事件，“空袭”指飞机从空中的攻击，符合语境。", "展览": "搭配：“遭到”多用于不幸的事件，不能说遭到“展览”。", "夜景": "语义：“夜景”指夜晚的景色，与“遭到了”所说的灾难语境不符。", "节日": "语义：“节日”是令人高兴的日子，与“遭到了”的不幸语境矛盾。"}, "sentence_index": 0, "correct_answer": "空袭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地面部队对村庄发动了空袭。", "explanation": "这里应该用〈袭击〉。空袭特指飞机从空中对地面目标的攻击，地面部队发动的攻击要说袭击。"}, {"text": "炮兵对阵地进行了空袭。", "explanation": "这里应该用〈炮击〉。空袭是飞机从空中的攻击，炮兵从地面开炮要说炮击。"}, {"text": "两架飞机在空中进行了空袭。", "explanation": "这里应该用〈空战〉。空袭的对象是地面目标，两架飞机之间的交战要说空战。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空袭", "is_correct": true, "explanation": "正确。“经历过”后接亲身经历的事件，“空袭”指战时的空中攻击，符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“经历过”说的是事件，不能说经历过“手机”。"}, {"text": "菜单", "is_correct": false, "explanation": "搭配：“经历过”说的是事件，不能说经历过“菜单”。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“经历过”说的是事件，不能说经历过“课本”。"}], "explanations": {"空袭": "正确。“经历过”后接亲身经历的事件，“空袭”指战时的空中攻击，符合语境。", "手机": "搭配：“经历过”说的是事件，不能说经历过“手机”。", "菜单": "搭配：“经历过”说的是事件，不能说经历过“菜单”。", "课本": "搭配：“经历过”说的是事件，不能说经历过“课本”。"}, "sentence_index": 6, "correct_answer": "空袭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机向灾区空袭了一批物资。", "explanation": "这里应该用〈空投〉。空袭是对地面目标的攻击，从飞机上把物资投下送给灾区要说空投。"}, {"text": "消防飞机对山林进行了空袭。", "explanation": "这里应该用〈灭火〉。空袭是对地面目标发动攻击，消防飞机向山林投水灭火要说灭火。"}, {"text": "摄影师乘直升机对山谷进行了空袭。", "explanation": "这里应该用〈航拍〉。空袭是对地面目标的攻击，从空中拍摄风景要说航拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天凌晨，那个港口遭到了一座空袭。", "corrected_sentence": "昨天凌晨，那个港口遭到了一次空袭。", "error_description": "量词错误：“空袭”是一次次发生的事件，应用量词“次”，说“一次空袭”。“座”用于山、桥、楼房等大型固定物，不能用于空袭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城里拉响了空袭，大家都躲进了防空洞。", "corrected_sentence": "城里拉响了空袭警报，大家都躲进了防空洞。", "error_description": "搭配错误：“拉响”的对象应是“警报”一类的声音，不能说拉响“空袭”；应说“拉响空袭警报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
