INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "军用飞机从空中对地面目标进行的攻击。", "primary_collocate": null, "pronunciation": "kōng xí", "ipa": "kʰʊŋ˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "军用飞机对机场发动了空袭。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空袭的目标是雷达站和仓库。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队计划明天清晨进行空袭。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次空袭炸毁了敌人的基地。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视上正在报道昨天的空袭。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空袭前，军方没有发出任何通知。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机对港口发动了第二次空袭。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家分析了这次空袭的原因。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用地图研究空袭的路线。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国军队都停止了空袭。", "target_word": "空袭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "空襲", "label": "繁体"}, {"form": "空袭警报", "label": "复合"}], "register": "中性", "sense_fingerprint": "军用飞机从空中对地面目标发动的军事攻击", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82fb6723-7629-4d18-9027-ad2587450605') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "空袭", "is_correct": true, "explanation": "正确答案。空袭 kōng xí，指军用飞机从空中对地面目标的攻击。"}, {"text": "恐袭", "is_correct": false, "explanation": "kǒng（第三声）与 kōng（第一声）声调不同，意思是恐怖袭击。"}, {"text": "冲袭", "is_correct": false, "explanation": "chōng 与 kōng 声母不同（ch 与 k），意思是冲上去袭击。"}, {"text": "攻袭", "is_correct": false, "explanation": "gōng 与 kōng 声母不同（g 与 k），意思是进攻袭击。"}], "explanations": {"空袭": "正确答案。空袭 kōng xí，指军用飞机从空中对地面目标的攻击。", "恐袭": "kǒng（第三声）与 kōng（第一声）声调不同，意思是恐怖袭击。", "冲袭": "chōng 与 kōng 声母不同（ch 与 k），意思是冲上去袭击。", "攻袭": "gōng 与 kōng 声母不同（g 与 k），意思是进攻袭击。"}, "sentence_index": null, "correct_answer": "空袭"}, "level_3": {"options": [{"text": "空袭", "is_correct": true, "explanation": "正确。“发动”可以搭配“空袭”，指军用飞机对机场的攻击。"}, {"text": "讲座", "is_correct": false, "explanation": "搭配：“发动”用于战争或攻势，不能说发动“讲座”。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不能被“发动”，句子说不通。"}, {"text": "节目", "is_correct": false, "explanation": "搭配：“发动”不能与“节目”搭配。"}], "explanations": {"空袭": "正确。“发动”可以搭配“空袭”，指军用飞机对机场的攻击。", "讲座": "搭配：“发动”用于战争或攻势，不能说发动“讲座”。", "春天": "语义：“春天”是季节，不能被“发动”，句子说不通。", "节目": "搭配：“发动”不能与“节目”搭配。"}, "sentence_index": 0, "correct_answer": "空袭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "特种部队对营地发动了空袭。", "explanation": "这里应该用〈突袭〉。空袭要求从空中对地面目标发动攻击，地面部队的突然袭击要说突袭。"}, {"text": "士兵用机枪对人群进行了空袭。", "explanation": "这里应该用〈扫射〉。空袭是飞机从空中的攻击，士兵从地面用机枪射击人群要说扫射。"}, {"text": "敌军的坦克部队对城堡进行了空袭。", "explanation": "这里应该用〈攻打〉。空袭是飞机从空中对地面目标的攻击，坦克从地面进攻城堡要说攻打。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空袭", "is_correct": true, "explanation": "正确。“第二次空袭”指战斗机对港口的又一次攻击，与“发动”搭配。"}, {"text": "演讲", "is_correct": false, "explanation": "搭配：“发动”不能与“演讲”搭配，句子说不通。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是庆祝的日子，与战斗机对港口的军事行动完全不符。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“发动”不能与“比赛”搭配。"}], "explanations": {"空袭": "正确。“第二次空袭”指战斗机对港口的又一次攻击，与“发动”搭配。", "演讲": "搭配：“发动”不能与“演讲”搭配，句子说不通。", "生日": "语义：“生日”是庆祝的日子，与战斗机对港口的军事行动完全不符。", "比赛": "搭配：“发动”不能与“比赛”搭配。"}, "sentence_index": 6, "correct_answer": "空袭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "边防队员每天都在空袭。", "explanation": "这里应该用〈巡逻〉。空袭是飞机对地面目标的攻击，边防人员沿边境走动警戒要说巡逻。"}, {"text": "农用飞机对农田进行了空袭。", "explanation": "这里应该用〈喷洒〉。空袭是对地面目标发动攻击，农用飞机向农田喷洒药物要说喷洒。"}, {"text": "地质队员对山区进行了空袭。", "explanation": "这里应该用〈测绘〉。空袭是对地面目标的攻击，地质人员对山区进行勘测要说测绘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "军方对港口发动了一座空袭。", "corrected_sentence": "军方对港口发动了一次空袭。", "error_description": "量词错误：“空袭”是一次次发生的事件，应用量词“次”，说“一次空袭”。“座”用于山、桥、楼房等大型固定物，不能用于空袭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里城里突然响起了空袭。", "corrected_sentence": "夜里城里突然响起了空袭警报。", "error_description": "搭配错误：“响起”搭配的应是“警报”一类的声音，不能说“响起空袭”；应说“响起空袭警报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1df75124-ac9b-4783-99e0-2907e11014bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
