INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89349, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预告是事情发生以前，先告诉大家。", "primary_collocate": null, "pronunciation": "yù gào", "ipa": "y˥˩ kɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "学校预告下周要考试。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视上预告明天会下大雨。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师预告了考试的时间。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店预告周末会打折。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理预告下个月公司要搬家。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校先预告了一下放假时间，大家都有准备。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站预告了火车晚点的消息。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台预告过这部电影下周播出。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交公司预告明天会调整路线。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司预告下周会公布新产品。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预告了", "label": "体标"}, {"form": "预告过", "label": "体标"}, {"form": "預告", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情发生前先告诉大家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60eb8d25-3940-4b37-9ab8-c3a913d8c431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89349, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预告", "is_correct": true, "explanation": "正确：“预告”表示事先告诉大家，句子说学校事先告知下周要考试。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“考试”这类事件搭配，“学校吃下周要考试”不成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是唱歌的动作，与“下周要考试”的内容无关，句意荒谬。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洁的动作，不能用来表示学校告知考试的消息。"}], "explanations": {"预告": "正确：“预告”表示事先告诉大家，句子说学校事先告知下周要考试。", "吃": "搭配：“吃”不能与“考试”这类事件搭配，“学校吃下周要考试”不成立。", "唱": "语义：“唱”是唱歌的动作，与“下周要考试”的内容无关，句意荒谬。", "洗": "语义：“洗”是清洁的动作，不能用来表示学校告知考试的消息。"}, "sentence_index": 0, "correct_answer": "预告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都预告一次自己的体重。", "explanation": "这里应该用〈称〉。“预告”是事先告诉大家，量体重要说“称”，不能用“预告”。"}, {"text": "我提前预告了一间房间。", "explanation": "这里应该用〈预订〉。预告是告诉大家，提前订房间要用“预订”。"}, {"text": "医生提醒大家要预告感冒。", "explanation": "这里应该用〈预防〉。预告指事先告知，防范疾病要用“预防”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预告", "is_correct": true, "explanation": "正确：“预告”表示事先告知，车站提前告知火车晚点的消息，句意通顺。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理，与“消息”不搭，句子说不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪的动作，不能用于处理消息。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”不能接“消息”这类抽象名词，两者不搭配。"}], "explanations": {"预告": "正确：“预告”表示事先告知，车站提前告知火车晚点的消息，句意通顺。", "修": "语义：“修”是修理，与“消息”不搭，句子说不通。", "煮": "语义：“煮”是烹饪的动作，不能用于处理消息。", "踢": "搭配：“踢”不能接“消息”这类抽象名词，两者不搭配。"}, "sentence_index": 6, "correct_answer": "预告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他预告了一个月的工资。", "explanation": "这里应该用〈预支〉。预支指提前领取工资，预告只表示事先告知，不能用于钱款。"}, {"text": "运动前要预告身体。", "explanation": "这里应该用〈预热〉。预热指运动前让身体活动开，预告不能用于身体。"}, {"text": "我昨天预告了一顿晚饭，今天就吃到了。", "explanation": "这里应该用〈预订〉。预告是事先告知，提前订餐要说“预订”；“预告”不能用于订购饭菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电视台了预告了明天的节目。", "corrected_sentence": "电视台预告了明天的节目。", "error_description": "错误：动态助词“了”多放在动词“预告”之前（“了预告了”）；正确说法是“预告了”，“了”只放在动词后表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校预告了昨天的放假安排。", "corrected_sentence": "学校预告了下周的放假安排。", "error_description": "错误：“预告”指事先告知将来的事，与“昨天”矛盾（“预告了昨天的放假安排”）；正确说法是“预告了下周的放假安排”，时间应是将来的“下周”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
