INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89350, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先通知或宣布。", "primary_collocate": null, "pronunciation": "yù gào", "ipa": "y˥˩ kɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "电影院预告下个月有新电影。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校已经预告了开学的日期。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店预告明天早上会停水。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆预告下周有新展览。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂预告了停电时间。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板预告过今年会发奖金。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台预告今晚有一场音乐会。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行预告周日不办业务。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府预告下周要修路。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园预告春天要办花展。", "target_word": "预告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预告了", "label": "体标"}, {"form": "预告过", "label": "体标"}, {"form": "預告", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事先通知或宣布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60eb8d25-3940-4b37-9ab8-c3a913d8c431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预告", "is_correct": true, "explanation": "正确：“预告”表示事先通知，影院提前告知下个月有新电影，句意通顺。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理的意思，不能用来告知新电影的消息。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪的动作，与告知电影上映的信息不相关。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫”不能与“有新电影”这类信息搭配，句子不通。"}], "explanations": {"预告": "正确：“预告”表示事先通知，影院提前告知下个月有新电影，句意通顺。", "修": "语义：“修”是修理的意思，不能用来告知新电影的消息。", "煮": "语义：“煮”是烹饪的动作，与告知电影上映的信息不相关。", "扫": "搭配：“扫”不能与“有新电影”这类信息搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "预告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我提前预告了一条裙子的长度。", "explanation": "这里应该用〈量〉。“预告”是事先告知，测量裙子的长度要说“量”，不能用“预告”。"}, {"text": "工厂每年都要预告火灾。", "explanation": "这里应该用〈预防〉。预告指事先告知，防范火灾要用“预防”。"}, {"text": "我们正在预告下个月的饭菜钱。", "explanation": "这里应该用〈预算〉。预告是事先告知，规划饭菜钱要说“预算”，不能用“预告”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预告", "is_correct": true, "explanation": "正确：“预告”表示事先告知，电视台提前告知今晚有一场音乐会，句意通顺。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”是搬运的动作，不能用来告知音乐会的消息。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是烹饪的动作，与告知演出安排无关。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”不与“音乐会”这类活动搭配，“电视台拆今晚有音乐会”不成立。"}], "explanations": {"预告": "正确：“预告”表示事先告知，电视台提前告知今晚有一场音乐会，句意通顺。", "搬": "语义：“搬”是搬运的动作，不能用来告知音乐会的消息。", "烤": "语义：“烤”是烹饪的动作，与告知演出安排无关。", "拆": "搭配：“拆”不与“音乐会”这类活动搭配，“电视台拆今晚有音乐会”不成立。"}, "sentence_index": 6, "correct_answer": "预告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他提前预告了一张桌子。", "explanation": "这里应该用〈预订〉。预订指提前订下座位或物品，预告只表示事先告知，不能用于订桌子。"}, {"text": "妈妈预告了一把伞。", "explanation": "这里应该用〈预备〉。预备指提前准备物品，预告不能用于准备伞这类东西。"}, {"text": "跑步前要预告身体。", "explanation": "这里应该用〈预热〉。预热指跑步前让身体活动开，预告不能用于身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板预告过过明年的加薪计划。", "corrected_sentence": "老板预告过明年的加薪计划。", "error_description": "错误：经历体“过”被重复使用（“预告过过”）；动词后只需一个“过”，多加的一个“过”使句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校预告很早，大家都有准备。", "corrected_sentence": "学校预告得很早，大家都有准备。", "error_description": "错误：补语标志“得”漏掉了（“预告很早”）；正确说法是“预告得很早”，动词和程度补语之间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89351, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐瞒", "is_correct": true, "explanation": "反义：“隐瞒”指隐藏、不让别人知道，与“说出”（讲出来）相对。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指随意走路，与“说出”没有近义或反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "无关：“洗澡”指清洁身体，与“说出”没有近义或反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”指休息，与“说出”没有近义或反义关系。"}], "correct_answer": "隐瞒", "explanations": {"隐瞒": "反义：“隐瞒”指隐藏、不让别人知道，与“说出”（讲出来）相对。", "散步": "无关：“散步”指随意走路，与“说出”没有近义或反义关系。", "洗澡": "无关：“洗澡”指清洁身体，与“说出”没有近义或反义关系。", "睡觉": "无关：“睡觉”指休息，与“说出”没有近义或反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
