INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89351, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用嘴把心里的话讲出来。", "primary_collocate": null, "pronunciation": "shuō chū", "ipa": "ʂwo⁵⁵ ʈʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "他终于说出了心里的话。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不敢说出自己的想法。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她犹豫了很久，终于说出了那句话。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭着说出了真相。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不想说出他的名字。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以说出你的看法吗？", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次说出“妈妈”。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说出的话让大家很吃惊。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说出了多年的心事。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想说出自己的愿望。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说出了", "label": "体标"}], "register": "通用", "sense_fingerprint": "开口把心里的话、想法、名字等讲出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1db7579-ff47-4f4b-8f4b-d3cbfdbf4ed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89351, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说出", "is_correct": true, "explanation": "正确。“说出”表示用嘴把心里的话讲出来，与“心里的话”搭配，符合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”只能用于食物，不能和“心里的话”搭配。"}, {"text": "数", "is_correct": false, "explanation": "语义：“数”是清点数目的意思，“心里的话”不能被数。"}, {"text": "打听", "is_correct": false, "explanation": "语义：“打听”是探问消息的意思，不表示把心里的话讲出来。"}], "explanations": {"说出": "正确。“说出”表示用嘴把心里的话讲出来，与“心里的话”搭配，符合句意。", "吃掉": "搭配：“吃掉”只能用于食物，不能和“心里的话”搭配。", "数": "语义：“数”是清点数目的意思，“心里的话”不能被数。", "打听": "语义：“打听”是探问消息的意思，不表示把心里的话讲出来。"}, "sentence_index": 0, "correct_answer": "说出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她从我的表情里说出了我的心事。", "explanation": "这里应该用〈看出〉。“说出”指用嘴讲出来，从表情得知别人的心事要用“看出”。"}, {"text": "他说出了一篇很好的文章。", "explanation": "这里应该用〈写出〉。“说出”指用嘴讲出来，写文章要用“写出”。"}, {"text": "她说出了一首动人的歌。", "explanation": "这里应该用〈唱出〉。“说出”指用嘴讲出来，唱歌要用“唱出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89351, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说出", "is_correct": true, "explanation": "正确。“说出”表示用嘴把想法讲出来，“孩子第一次说出”符合语境。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住，不能用来表示发出“妈妈”这个称呼。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品或身体，不能和“妈妈”这个称呼搭配。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指使物体落地，不能和“妈妈”这个称呼搭配。"}], "explanations": {"说出": "正确。“说出”表示用嘴把想法讲出来，“孩子第一次说出”符合语境。", "咬": "语义：“咬”指用牙齿夹住，不能用来表示发出“妈妈”这个称呼。", "洗": "搭配：“洗”的对象是物品或身体，不能和“妈妈”这个称呼搭配。", "摔": "搭配：“摔”指使物体落地，不能和“妈妈”这个称呼搭配。"}, "sentence_index": 6, "correct_answer": "说出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说出了一幅很漂亮的画。", "explanation": "这里应该用〈画出〉。“说出”指用嘴讲出来，画画要用“画出”。"}, {"text": "工人说出了一台新机器。", "explanation": "这里应该用〈造出〉。“说出”指用嘴讲出来，制造机器要用“造出”。"}, {"text": "他用笔在纸上说出了自己的名字。", "explanation": "这里应该用〈写出〉。“说出”指用嘴讲出来，用笔在纸上要用“写出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她鼓起勇气说出了了心里的话。", "corrected_sentence": "她鼓起勇气说出了心里的话。", "error_description": "体标重复：“说出了”后不能再加“了”，应说“说出了心里的话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把心里的话说出了来。", "corrected_sentence": "他终于把心里的话说出来了。", "error_description": "补语位置错误：趋向补语“来”应紧跟“说出”，构成“说出来”，再加“了”。不能把“了”放在“来”前面，说成“说出了来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
