INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89352, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用语言表达出来。", "primary_collocate": null, "pronunciation": "shuō chū", "ipa": "ʂwo⁵⁵ ʈʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "他说出了大家的心声。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌说出了我的感受。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书说出了生活的真相。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想用简单的话说出这个道理。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说出了很多人的担心。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话说出了问题的关键。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话说出了父母的爱。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用一个小故事说出了做人的道理。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说出这件事的意义吗？", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用几句话说出了心里的难过。", "target_word": "说出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说出了", "label": "体标"}], "register": "通用", "sense_fingerprint": "用话语把感受、道理、问题等表达出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1db7579-ff47-4f4b-8f4b-d3cbfdbf4ed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说出", "is_correct": true, "explanation": "正确。“说出”表示用语言表达出来，“他说出了大家的心声”符合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”只能用于食物，不能和“心声”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体或饮品，不能和“心声”搭配。"}, {"text": "数", "is_correct": false, "explanation": "语义：“数”是清点数目的意思，不表示用语言表达心声。"}], "explanations": {"说出": "正确。“说出”表示用语言表达出来，“他说出了大家的心声”符合句意。", "吃掉": "搭配：“吃掉”只能用于食物，不能和“心声”搭配。", "喝": "搭配：“喝”的对象是液体或饮品，不能和“心声”搭配。", "数": "语义：“数”是清点数目的意思，不表示用语言表达心声。"}, "sentence_index": 0, "correct_answer": "说出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说出了一篇很长的文章。", "explanation": "这里应该用〈写出〉。“说出”指用语言表达想法，写文章要用“写出”。"}, {"text": "她说出了一幅很美的画。", "explanation": "这里应该用〈画出〉。“说出”指用语言表达想法，画画要用“画出”。"}, {"text": "他说出了一道好吃的菜。", "explanation": "这里应该用〈做出〉。“说出”指用语言表达想法，做菜要用“做出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说出", "is_correct": true, "explanation": "正确。“说出”表示用语言表达出来，“这句话说出了父母的爱”符合句意。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指使物体落地，不能和“爱”搭配表示表达。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品或身体，不能和“爱”搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住，不能表示用语言表达感情。"}], "explanations": {"说出": "正确。“说出”表示用语言表达出来，“这句话说出了父母的爱”符合句意。", "摔": "搭配：“摔”指使物体落地，不能和“爱”搭配表示表达。", "洗": "搭配：“洗”的对象是物品或身体，不能和“爱”搭配。", "咬": "语义：“咬”指用牙齿夹住，不能表示用语言表达感情。"}, "sentence_index": 6, "correct_answer": "说出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们说出了一座漂亮的房子。", "explanation": "这里应该用〈造出〉。“说出”指用语言表达想法，建造房子要用“造出”。"}, {"text": "我从他的眼神说出了他很难过。", "explanation": "这里应该用〈看出〉。“说出”需要说话的人，从眼神察觉别人的情绪要用“看出”。"}, {"text": "他说出了一锅很香的汤。", "explanation": "这里应该用〈烧出〉。“说出”指用语言表达想法，做汤要用“烧出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用几句话说出了了心里的委屈。", "corrected_sentence": "她用几句话说出了心里的委屈。", "error_description": "体标重复：“说出了”后不能再加“了”，应说“说出了心里的委屈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一开口就被说出了大家的顾虑。", "corrected_sentence": "她一开口就说出了大家的顾虑。", "error_description": "被字句误用：“被”引出的是受事，而主语“她”是说话的人（施事），两者冲突。应删去“被”，说“她一开口就说出了大家的顾虑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
