INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89354, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究和解释儒家经典的学问。", "primary_collocate": null, "pronunciation": "jīng xué", "ipa": "tɕiŋ˥ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "经学是研究儒家经典的学问。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉代的经学很受重视。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里专门研究经学。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经学和历史学有很多关系。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老先生一辈子都在研究经学。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习经学，要先读懂古文。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本讲经学的书，书里全是儒家经典的注解。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清代有很多人研究经学。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经学在古代中国很重要。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对经学很感兴趣，想多读一些。", "target_word": "经学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "經學", "label": "繁体"}, {"form": "经学家", "label": "复合"}], "register": "书面语", "sense_fingerprint": "研究、注解儒家经典的传统学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed153e7-0a2c-4ca6-9ac2-d5bcdbc4229a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经学", "is_correct": true, "explanation": "“研究儒家经典的学问”正是经学的定义，只有“经学”符合语境。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学研究数量与图形，不研究儒家经典。"}, {"text": "化学", "is_correct": false, "explanation": "语义：化学研究物质的组成与变化，与儒家经典无关。"}, {"text": "经典", "is_correct": false, "explanation": "搭配：“经典”指典籍本身，不能说“经典是……学问”。"}], "explanations": {"经学": "“研究儒家经典的学问”正是经学的定义，只有“经学”符合语境。", "数学": "语义：数学研究数量与图形，不研究儒家经典。", "化学": "语义：化学研究物质的组成与变化，与儒家经典无关。", "经典": "搭配：“经典”指典籍本身，不能说“经典是……学问”。"}, "sentence_index": 0, "correct_answer": "经学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经学课上，老师讲了人体骨骼的结构。", "explanation": "这里应该用〈医学〉。经学研究儒家经典，讲人体骨骼的结构要用医学。"}, {"text": "经学研究的是国家的资源分配。", "explanation": "这里应该用〈经济学〉。经学研究儒家经典，研究资源分配要用经济学。"}, {"text": "经学研究山川、气候和人口的分布。", "explanation": "这里应该用〈地理学〉。经学研究儒家经典，研究山川、气候和人口的分布要用地理学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经学", "is_correct": true, "explanation": "“讲……的书”后接学问名称，且与“写了一本”的学术著作相符，只有“经学”合适。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“讲礼物的书”不是学术著作，与这里的学问含义不符。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：“茶杯”是器物，不能作为一本学术书的主题。"}, {"text": "石头", "is_correct": false, "explanation": "语义：书里全是儒家经典的注解，主题不可能是“石头”。"}], "explanations": {"经学": "“讲……的书”后接学问名称，且与“写了一本”的学术著作相符，只有“经学”合适。", "礼物": "语义：“讲礼物的书”不是学术著作，与这里的学问含义不符。", "茶杯": "语义：“茶杯”是器物，不能作为一本学术书的主题。", "石头": "语义：书里全是儒家经典的注解，主题不可能是“石头”。"}, "sentence_index": 6, "correct_answer": "经学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我做饭很有经学，朋友都说好吃。", "explanation": "这里应该用〈经验〉。经学指研究经典的学问，不指生活中积累的做事体会；做饭很有经验要说经验。"}, {"text": "经学课上，老师讲了二次方程的解法。", "explanation": "这里应该用〈数学〉。经学研究儒家经典，讲二次方程要用数学。"}, {"text": "经学研究物质和能量的关系。", "explanation": "这里应该用〈物理学〉。经学研究儒家经典，研究物质和能量的关系要用物理学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大学时学过一只经学。", "corrected_sentence": "他大学时学过一门经学。", "error_description": "量词错误：学科应用量词“门”，应说“一门经学”，不能说“一只经学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她大学时不学过经学。", "corrected_sentence": "她大学时没学过经学。", "error_description": "否定词错误：表示没有某种经历要用“没”，“学过”前不能用“不”。应说“没学过经学”，不能说“不学过经学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
