INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89356, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻纠纷或不安定的事情。", "primary_collocate": null, "pronunciation": "fēng bō", "ipa": "fɤŋ˥˥ pwo˥˥", "syllable_count": 2, "sentences": [{"text": "公司里出了一场风波。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场风波很快就过去了。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了钱闹起了风波。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师来了，班里的风波平静下来。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想再惹风波。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场风波让两家人不说话了。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事引起了不小的风波。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想办法平息风波。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学之间的风波终于结束了。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李因为这场风波离开了公司。", "target_word": "风波", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "風波", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比喻纠纷或不安定的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60eb8d25-3940-4b37-9ab8-c3a913d8c431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风波", "is_correct": true, "explanation": "正确：风波指纠纷或不安定的事，可以说“出了一场风波”。"}, {"text": "会议", "is_correct": false, "explanation": "搭配：会议要说“开”，不说“出”，“出了一场会议”不成立。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不是会在公司里“出”的事，句子不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科名称，不是会在公司里发生的事件，句子不通。"}], "explanations": {"风波": "正确：风波指纠纷或不安定的事，可以说“出了一场风波”。", "会议": "搭配：会议要说“开”，不说“出”，“出了一场会议”不成立。", "雨": "语义：雨是天气现象，不是会在公司里“出”的事，句子不通。", "数学": "语义：数学是学科名称，不是会在公司里发生的事件，句子不通。"}, "sentence_index": 0, "correct_answer": "风波"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里出了一只风波，大家都很慌。", "explanation": "这里应该用〈场〉。“只”用于动物或成对物品中的一个，风波要用“场”来计量。"}, {"text": "放学以后，班里恢复了风波。", "explanation": "这里应该用〈平静〉。“恢复”指回到原来的平静状态，风波指纷乱的事，不能被“恢复”。"}, {"text": "我们开了一场风波，一起商量怎么办。", "explanation": "这里应该用〈讨论〉。“开”可以搭配会议、讨论，但风波是纠纷，不能“开”；表示引发纠纷应说“引起”或“掀起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风波", "is_correct": true, "explanation": "正确：风波指纠纷、不安定的事，可以被“引起”。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“引起”后接事件或反应，不能说“引起不小的高度”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑物，不是能被“引起”的事，句子不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不能作为“引起”的对象，句子不通。"}], "explanations": {"风波": "正确：风波指纠纷、不安定的事，可以被“引起”。", "高度": "搭配：“引起”后接事件或反应，不能说“引起不小的高度”。", "房子": "语义：房子是建筑物，不是能被“引起”的事，句子不通。", "水果": "语义：水果是食物，不能作为“引起”的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "风波"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的风波很好听。", "explanation": "这里应该用〈旋律〉。风波指纠纷、不安定的事，不是乐曲，不能用“好听”来形容。"}, {"text": "他是个风波，天天惹麻烦。", "explanation": "这里应该用〈惹事精〉。风波指事件，不指人，不能说“他是个风波”。"}, {"text": "他得了一场风波，在家躺了两天。", "explanation": "这里应该用〈感冒〉。“得”用于疾病，风波是纠纷，不是病，不能说“得了风波”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校里闹出了一件风波，老师很着急。", "corrected_sentence": "学校里闹出了一场风波，老师很着急。", "error_description": "量词错误：风波要用“场”计量，“件”不能用来计量风波，应改为“一场风波”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们因为一件小事闹了起风波，老师很生气。", "corrected_sentence": "同学们因为一件小事闹起了风波，老师很生气。", "error_description": "补语位置错误：动补“闹起”中，“起”必须紧跟“闹”，“闹了起风波”不成立，应为“闹起了风波”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdb309e5-ca00-49b0-8a49-d7c71206434d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
