INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89360, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把话说得过于绝对，不留余地。", "primary_collocate": null, "pronunciation": "shuō sǐ", "ipa": "ʂuɔ˥ sɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "谁也不能把结果说死。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看人不能说死，人是会变的。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说死了这个办法一定行。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结果还没出来，别说死。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把话说死了，万一错了怎么办？", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生没有说死，只说要再看看。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种事说死了不好，大家都可能错。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总爱把话说死，听的人很不舒服。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不敢说死明年会不会涨价。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想把答案说死，先听听大家的想法。", "target_word": "说死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说死了", "label": "体标"}, {"form": "没说死", "label": "否定"}, {"form": "說死", "label": "繁体"}], "register": "口语", "sense_fingerprint": "对结果、评价等下过于绝对的断言，不给例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4935a66f-b0a5-4cd5-b0f8-380dba48c616') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89360, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "说死", "is_correct": true, "explanation": "正确。说死：把话讲得过于绝对，不留余地。"}, {"text": "硕士", "is_correct": false, "explanation": "shuò（第四声）与 shuō（第一声）声调不同，shì 与 sǐ 声母、声调都不同，意思是研究生学位。"}, {"text": "睡死", "is_correct": false, "explanation": "shuì（第四声）与 shuō（第一声）韵母和声调都不同，意思是睡得很沉。"}, {"text": "戳死", "is_correct": false, "explanation": "chuō 与 shuō 声母不同（ch 与 sh），意思是用尖的东西刺死。"}, {"text": "说是", "is_correct": false, "explanation": "第二音节 shì（第四声）与 sǐ（第三声）声母不同（sh 与 s）且声调不同，意思是据说或表示确认。"}], "explanations": {"说死": "正确。说死：把话讲得过于绝对，不留余地。", "硕士": "shuò（第四声）与 shuō（第一声）声调不同，shì 与 sǐ 声母、声调都不同，意思是研究生学位。", "睡死": "shuì（第四声）与 shuō（第一声）韵母和声调都不同，意思是睡得很沉。", "戳死": "chuō 与 shuō 声母不同（ch 与 sh），意思是用尖的东西刺死。", "说是": "第二音节 shì（第四声）与 sǐ（第三声）声母不同（sh 与 s）且声调不同，意思是据说或表示确认。"}, "sentence_index": null, "correct_answer": "说死"}, "level_3": {"options": [{"text": "说死", "is_correct": true, "explanation": "说死：对结果下过于绝对的断言，符合句意。"}, {"text": "说累", "is_correct": false, "explanation": "搭配：“说累”的主语是说话的人，不能说“把结果说累”。"}, {"text": "说教", "is_correct": false, "explanation": "配价：“说教”是不及物动词，不能带“把结果”作宾语。"}, {"text": "说活", "is_correct": false, "explanation": "语义：“说活”指把结果说得有余地，与句中“谁也不能”的绝对语气相反，句意不通。"}], "explanations": {"说死": "说死：对结果下过于绝对的断言，符合句意。", "说累": "搭配：“说累”的主语是说话的人，不能说“把结果说累”。", "说教": "配价：“说教”是不及物动词，不能带“把结果”作宾语。", "说活": "语义：“说活”指把结果说得有余地，与句中“谁也不能”的绝对语气相反，句意不通。"}, "sentence_index": 0, "correct_answer": "说死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我真想说死你的帮助。", "explanation": "这里应该用〈感谢〉。说死用于对结果、评价下绝对断言，不能带“帮助”作宾语表示谢意。"}, {"text": "他一直在说死那张桌子。", "explanation": "这里应该用〈搬〉。说死的对象是结果或评价，不能指桌子这类物品。"}, {"text": "我向老师说死了这个问题。", "explanation": "这里应该用〈请教〉。说死表示下绝对断言，不能表示向人询问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说死", "is_correct": true, "explanation": "说死：对结果下过于绝对的断言，此处指把这种事说得太绝对，符合句意。"}, {"text": "说准", "is_correct": false, "explanation": "语义：“说准”指说得非常确定，与“大家都可能错”的不确定语境矛盾。"}, {"text": "说假", "is_correct": false, "explanation": "搭配：“说假”不是常用搭配，句中要表达的是不宜把话说绝，不能用“说假”。"}, {"text": "说对", "is_correct": false, "explanation": "语义：“说对”指判断正确，与“大家都可能错”的语境相矛盾。"}], "explanations": {"说死": "说死：对结果下过于绝对的断言，此处指把这种事说得太绝对，符合句意。", "说准": "语义：“说准”指说得非常确定，与“大家都可能错”的不确定语境矛盾。", "说假": "搭配：“说假”不是常用搭配，句中要表达的是不宜把话说绝，不能用“说假”。", "说对": "语义：“说对”指判断正确，与“大家都可能错”的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "说死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家热烈地说死新同学。", "explanation": "这里应该用〈欢迎〉。说死指对结果或评价下绝对断言，不能用于迎接人。"}, {"text": "他很喜欢说死这些邮票。", "explanation": "这里应该用〈收藏〉。说死的对象是结果或评价，不能指邮票这类物品。"}, {"text": "老师在认真地说死课。", "explanation": "这里应该用〈讲〉。说死表示对结果下绝对断言，不能用于讲授课程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不把答案说死地，以后还能改。", "corrected_sentence": "我不把答案说死，以后还能改。", "error_description": "助词错误：“说死”后不能加“地”，应说“我不把答案说死”，不能说“我不把答案说死地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把结论说死起来，大家都不同意。", "corrected_sentence": "他把结论说死了，大家都不同意。", "error_description": "补语错误：“说死”后的补语应为“了”，不能用“起来”，应说“他把结论说死了”，不能说“说死起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb98565d-ae19-4540-ba1b-0947fd340358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
