INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89361, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "经由是说通过某个地方或某条路线到达。", "primary_collocate": null, "pronunciation": "jīng yóu", "ipa": "tɕiŋ˥ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我们经由北京去上海。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他经由这条小路回到了村子。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机经由香港飞往东京。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物经由海路运到了国外。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人经由后门进了餐厅。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车经由长江大桥开往南方。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们经由山路走到了山顶。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船经由这条河开进了城里。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客经由西门进入公园。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车经由高速公路开到了海边。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "通过某条路线到达某地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c98c2ea0-82f7-4d76-b905-50f0974de4d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经由", "is_correct": true, "explanation": "经由：表示通过某地到达另一地，符合“北京→上海”的途经关系。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，不表示途经某地，“我们为了北京去上海”不通。"}, {"text": "对于", "is_correct": false, "explanation": "语义：“对于”引出对象或话题，不表示路线，“我们对于北京去上海”不通。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”后接依据或标准，不接地点，“按照北京去上海”不成立。"}], "explanations": {"经由": "经由：表示通过某地到达另一地，符合“北京→上海”的途经关系。", "为了": "语义：“为了”表示目的，不表示途经某地，“我们为了北京去上海”不通。", "对于": "语义：“对于”引出对象或话题，不表示路线，“我们对于北京去上海”不通。", "按照": "搭配：“按照”后接依据或标准，不接地点，“按照北京去上海”不成立。"}, "sentence_index": 0, "correct_answer": "经由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经由一个小时，雨停了。", "explanation": "这里应该用〈经过〉。经由表示通过某条路线或途径到达某地，不能用来表示一段时间的流逝。"}, {"text": "经由明天开始，我们每天早上跑步。", "explanation": "这里应该用〈从〉。经由表示经过某路线，不能用于时间的起点，应说“从明天开始”。"}, {"text": "我经由她写了一封信。", "explanation": "这里应该用〈替〉。经由表示通过某条路线或途径，不表示代替别人做事，应说“替她写了一封信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经由", "is_correct": true, "explanation": "经由：表示通过山路到达山顶，符合途经的语境。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”要求后接被处置的宾语，“把山路走到了山顶”结构不成立。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替，与“山路”表示的途径不符。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”引出为谁或为何，不表示途经，“为山路走到山顶”不通。"}], "explanations": {"经由": "经由：表示通过山路到达山顶，符合途经的语境。", "把": "配价：“把”要求后接被处置的宾语，“把山路走到了山顶”结构不成立。", "替": "语义：“替”表示代替，与“山路”表示的途径不符。", "为": "语义：“为”引出为谁或为何，不表示途经，“为山路走到山顶”不通。"}, "sentence_index": 6, "correct_answer": "经由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经由老师请教了问题。", "explanation": "这里应该用〈向〉。经由表示经过某条路线或途径，不引出请教的对象，应说“向老师请教”。"}, {"text": "航班经由天气原因取消了。", "explanation": "这里应该用〈由于〉。经由表示途径，不表示原因。"}, {"text": "我经由北京工作了五年。", "explanation": "这里应该用〈在〉。经由表示经过某地，不表示在某地做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "列车经由了郑州开往西安。", "corrected_sentence": "列车经由郑州开往西安。", "error_description": "体标误用：介词“经由”后不能加“了”，应去掉“了”，说“列车经由郑州开往西安”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆公交车经由从环城路开到了车站。", "corrected_sentence": "这辆公交车经由环城路开到了车站。", "error_description": "错误：“经由”后又加了介词“从”，两个介词叠用。正确：去掉“从”，“经由环城路”单独作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
