INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89362, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "通过，取道；表示途径或方式。", "primary_collocate": null, "pronunciation": "jīng yóu", "ipa": "tɕiŋ˥ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他经由朋友的介绍认识了老板。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生经由考试进入这所大学。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息经由报纸传开了。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我经由老师的推荐买到了这本书。", "target_word": "经由", "complexity_tier": "T3", "furigana": "wǒ jīng yóu lǎo shī de tuī jiàn mǎi dào le zhè běn shū", "sentence_source": "generated"}, {"text": "我们经由电话联系上了他。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他经由自学学会了日语。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家经由网络可以看到各地的新闻。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他经由同事的引荐认识了这位专家。", "target_word": "经由", "complexity_tier": "T3", "furigana": "tā jīng yóu tóng shì de yǐn jiàn rèn shi le zhè wèi zhuān jiā", "sentence_source": "generated"}, {"text": "她经由中介找到了房子。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份礼物经由邮局寄到了我家。", "target_word": "经由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示通过某种途径或方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c98c2ea0-82f7-4d76-b905-50f0974de4d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经由", "is_correct": true, "explanation": "经由：表示通过朋友的介绍这一途径，符合句意。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，不表示途径，“为了朋友的介绍认识老板”不通。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替，与“通过朋友的介绍”不符，“替朋友的介绍认识”不通。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”要求后接被处置的宾语，“把朋友的介绍认识了老板”结构不成立。"}], "explanations": {"经由": "经由：表示通过朋友的介绍这一途径，符合句意。", "为了": "语义：“为了”表示目的，不表示途径，“为了朋友的介绍认识老板”不通。", "替": "语义：“替”表示代替，与“通过朋友的介绍”不符，“替朋友的介绍认识”不通。", "把": "配价：“把”要求后接被处置的宾语，“把朋友的介绍认识了老板”结构不成立。"}, "sentence_index": 0, "correct_answer": "经由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经由下周开始，我们每天早上练习口语。", "explanation": "这里应该用〈从〉。经由表示途径或方式，不表示时间的起点，应说“从下周开始”。"}, {"text": "经由孩子，他放弃了工作。", "explanation": "这里应该用〈为了〉。经由表示途径或方式，不表示目的。"}, {"text": "经由天气不好，比赛推迟了。", "explanation": "这里应该用〈由于〉。经由表示途径或方式，不表示原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经由", "is_correct": true, "explanation": "经由：表示通过网络这一途径，符合句意。"}, {"text": "对于", "is_correct": false, "explanation": "语义：“对于”引出对象或话题，不表示凭借的途径，“对于网络可以看到”不通。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”后接依据或标准，不接媒介，“按照网络”不成立。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”引出为谁或为何，与途径不符，“为网络可以看到”不通。"}], "explanations": {"经由": "经由：表示通过网络这一途径，符合句意。", "对于": "语义：“对于”引出对象或话题，不表示凭借的途径，“对于网络可以看到”不通。", "按照": "搭配：“按照”后接依据或标准，不接媒介，“按照网络”不成立。", "为": "语义：“为”引出为谁或为何，与途径不符，“为网络可以看到”不通。"}, "sentence_index": 6, "correct_answer": "经由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经由父亲去开会。", "explanation": "这里应该用〈替〉。经由表示途径，不表示代替，“替父亲去开会”才对。"}, {"text": "我经由深圳工作了三年。", "explanation": "这里应该用〈在〉。经由表示经过某地或途径，不表示在某地做事，应说“在深圳工作”。"}, {"text": "我经由老师很热情。", "explanation": "这里应该用〈对〉。经由表示途径或方式，不表示对人的态度，应说“对老师很热情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我经由的网络找到了这份资料。", "corrected_sentence": "我经由网络找到了这份资料。", "error_description": "错误：“经由”后多加了“的”，把介词和途径名词隔开。正确：“经由网络”，“经由”是介词，后面直接接途径名词，不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个消息经由从电视传开了。", "corrected_sentence": "这个消息经由电视传开了。", "error_description": "错误：“经由”后又加了介词“从”，两个介词叠用。正确：去掉“从”，“经由电视”单独作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
