INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89363, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "体育场是跑步、踢球和比赛的大场地。", "primary_collocate": null, "pronunciation": "tǐ yù chǎng", "ipa": "tʰi˨˩ y˥˩ ʈʂʰaŋ˨˩", "syllable_count": 3, "sentences": [{"text": "我们星期六在体育场踢球。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "体育场很大，很多人在里面跑步。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校旁边有一个新体育场。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的比赛在城东的体育场举行。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "体育场里坐满了看球的人。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每天早上在体育场的跑道上散步。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛开始前，体育场门口排着长队。", "target_word": "体育场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在体育场跑了五圈，累死了。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "体育场的灯一亮，球迷都叫了起来。", "target_word": "体育场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座体育场能坐五万名观众。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "體育場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "供人跑步、踢球、比赛的大型场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89363, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体育场", "is_correct": true, "explanation": "正确。体育场是供跑步、踢球、比赛的大场地，可以在那里踢球。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅、看书的地方，不能在那里踢球。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“踢球”要在场地上进行，厨房不能用来踢球。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，与踢球无关。"}], "explanations": {"体育场": "正确。体育场是供跑步、踢球、比赛的大场地，可以在那里踢球。", "图书馆": "语义：图书馆是借阅、看书的地方，不能在那里踢球。", "厨房": "搭配：“踢球”要在场地上进行，厨房不能用来踢球。", "医院": "语义：医院是看病的地方，与踢球无关。"}, "sentence_index": 0, "correct_answer": "体育场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校有一只体育场，很大。", "explanation": "这里应该用〈座〉。体育场是大型建筑，量词用“座”；“只”多用于动物或成对物品中的一个。"}, {"text": "市里新建了一条体育场。", "explanation": "这里应该用〈座〉。“条”用于细长的物体，体育场要用“座”。"}, {"text": "爷爷每天去一位体育场散步。", "explanation": "这里应该用〈座〉。“位”用于人，不能用于场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体育场", "is_correct": true, "explanation": "正确。体育场是大型场地，比赛前可以在它门口排队。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠是自然地貌，没有门口，不能排队。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是自然地理，不是有门的场所，不能有门口。"}, {"text": "农田", "is_correct": false, "explanation": "搭配：“门口排队”多用于建筑或场所，农田不能说门口。"}], "explanations": {"体育场": "正确。体育场是大型场地，比赛前可以在它门口排队。", "沙漠": "语义：沙漠是自然地貌，没有门口，不能排队。", "海洋": "语义：海洋是自然地理，不是有门的场所，不能有门口。", "农田": "搭配：“门口排队”多用于建筑或场所，农田不能说门口。"}, "sentence_index": 6, "correct_answer": "体育场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个体育场的藏书很多，可以借阅。", "explanation": "这里应该用〈图书馆〉。藏书供人借阅要去图书馆；体育场是跑步、踢球、比赛的场地，不藏书。"}, {"text": "我每周末去体育场游泳。", "explanation": "这里应该用〈游泳馆〉。游泳要在游泳池里进行，体育场是跑步、踢球、比赛的场地。"}, {"text": "这座体育场设有急诊科，二十四小时接诊。", "explanation": "这里应该用〈医院〉。急诊科接诊病人属于医院；体育场是运动场地，不提供诊疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只体育场很大，能坐很多人。", "corrected_sentence": "这座体育场很大，能坐很多人。", "error_description": "“体育场”是大型建筑，量词应用“座”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们体育场跑步。", "corrected_sentence": "孩子们在体育场跑步。", "error_description": "“体育场”表示地点时，前面要加介词“在”，应说“在体育场跑步”，不能说“体育场跑步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
