INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89364, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供体育比赛和运动训练用的场地。", "primary_collocate": null, "pronunciation": "tǐ yù chǎng", "ipa": "tʰi˨˩ y˥˩ ʈʂʰaŋ˨˩", "syllable_count": 3, "sentences": [{"text": "这座体育场可以举行大型比赛。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动员每天在体育场训练四小时。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里新建了一座体育场。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "体育场的草地每周都要修剪。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家队明天到体育场进行训练。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个体育场有标准的四百米跑道。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校的体育场周末对外开放。", "target_word": "体育场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了办运动会，他们修好了体育场。", "target_word": "体育场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育场里灯光很亮，晚上也能训练。", "target_word": "体育场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，体育场里的观众慢慢离开。", "target_word": "体育场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "體育場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用于体育比赛和运动训练的专用场地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体育场", "is_correct": true, "explanation": "正确。体育场是可以举行大型比赛的场地，符合句意。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅、看书的地方，不能举行大型比赛。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：举行大型比赛要在场馆进行，医院不能用来举行比赛。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不能用来举行大型比赛。"}], "explanations": {"体育场": "正确。体育场是可以举行大型比赛的场地，符合句意。", "图书馆": "语义：图书馆是借阅、看书的地方，不能举行大型比赛。", "医院": "搭配：举行大型比赛要在场馆进行，医院不能用来举行比赛。", "教室": "语义：教室是上课的地方，不能用来举行大型比赛。"}, "sentence_index": 0, "correct_answer": "体育场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只体育场可以举行大型比赛。", "explanation": "这里应该用〈座〉。体育场是大型建筑，量词用“座”；“只”不用于场地。"}, {"text": "这条体育场可以举行大型比赛。", "explanation": "这里应该用〈座〉。“条”用于细长的物体，不能用于体育场。"}, {"text": "这位体育场可以举行大型比赛。", "explanation": "这里应该用〈座〉。“位”用于人，不能用于场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体育场", "is_correct": true, "explanation": "正确。学校的体育场可以在周末对外开放，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是储存食物的家电，不能对外开放。"}, {"text": "电梯", "is_correct": false, "explanation": "搭配：“对外开放”多用于场所、设施，电梯不能说对外开放。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：“对外开放”不用于交通工具，火车不能说周末对外开放。"}], "explanations": {"体育场": "正确。学校的体育场可以在周末对外开放，符合句意。", "冰箱": "语义：冰箱是储存食物的家电，不能对外开放。", "电梯": "搭配：“对外开放”多用于场所、设施，电梯不能说对外开放。", "火车": "搭配：“对外开放”不用于交通工具，火车不能说周末对外开放。"}, "sentence_index": 6, "correct_answer": "体育场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在体育场上了三节数学课。", "explanation": "这里应该用〈教室〉。数学课要在教室里上；体育场是供比赛和训练的场地，不用于上文化课。"}, {"text": "妈妈把脏衣服放进体育场里洗。", "explanation": "这里应该用〈洗衣机〉。洗衣服要用洗衣机；体育场是供比赛和运动训练的场地，不是洗衣服的电器。"}, {"text": "我们在体育场买了一套房子。", "explanation": "这里应该用〈售楼处〉。买房要到售楼处办理；体育场是供比赛和训练的场地，不办理房产业务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校附近新修了一把体育场。", "corrected_sentence": "学校附近新修了一座体育场。", "error_description": "“体育场”是大型建筑，量词应用“座”，不能用“把”（“把”多用于有柄的物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
