INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89365, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遭是碰上了不好的事。", "primary_collocate": null, "pronunciation": "zāo", "ipa": "tsɑʊ˥", "syllable_count": 1, "sentences": [{"text": "他今天真倒霉，出门就遭了雨。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司遭了难，大家都很着急。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑车回家，半路遭了劫。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民们说，今年的庄稼遭了虫灾。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李在网上遭人骗，很难过。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没遭过这样的冷眼。", "target_word": "遭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在街上遭了抢，警察马上赶来了。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家遭了火灾，什么都没有留下。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁都不愿意遭人白眼。", "target_word": "遭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟在学校遭人欺负，不敢告诉我们。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遭了", "label": "体标"}, {"form": "遭过", "label": "体标"}, {"form": "遭到", "label": "复合"}, {"form": "遭遇", "label": "复合"}, {"form": "遭受", "label": "复合"}], "register": "中性", "sense_fingerprint": "碰上不好的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遭", "is_correct": true, "explanation": "遭（zāo）是正确答案，表示碰上不好的事。"}, {"text": "早", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是早晨。"}, {"text": "皂", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是肥皂。"}, {"text": "招", "is_correct": false, "explanation": "zhāo 与 zāo 只有声母不同（zh 与 z），意思是招呼、招收。"}, {"text": "操", "is_correct": false, "explanation": "cāo 与 zāo 只有声母不同（c 与 z），意思是操作、体操。"}], "explanations": {"遭": "遭（zāo）是正确答案，表示碰上不好的事。", "早": "zǎo（第三声）与 zāo（第一声）声调不同，意思是早晨。", "皂": "zào（第四声）与 zāo（第一声）声调不同，意思是肥皂。", "招": "zhāo 与 zāo 只有声母不同（zh 与 z），意思是招呼、招收。", "操": "cāo 与 zāo 只有声母不同（c 与 z），意思是操作、体操。"}, "sentence_index": null, "correct_answer": "遭"}, "level_3": {"options": [{"text": "借", "is_correct": false, "explanation": "搭配：“借”的对象是物或钱，雨不能被借，“借了雨”搭配不当。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指赠予，与“出门就碰上不好的事”的语境不符。"}, {"text": "遭", "is_correct": true, "explanation": "遭：表示碰上不好的事，与“真倒霉”“出门就”的语境相合。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”只用于可摘取的东西，雨不能摘，“摘了雨”搭配不当。"}], "explanations": {"借": "搭配：“借”的对象是物或钱，雨不能被借，“借了雨”搭配不当。", "送": "语义：“送”指赠予，与“出门就碰上不好的事”的语境不符。", "遭": "遭：表示碰上不好的事，与“真倒霉”“出门就”的语境相合。", "摘": "搭配：“摘”只用于可摘取的东西，雨不能摘，“摘了雨”搭配不当。"}, "sentence_index": 0, "correct_answer": "遭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在路上遭了好心人，他帮我们修好了车。", "explanation": "这里应该用〈遇到〉。遭只用于不幸或不利的事，好心人帮忙是好事，要说遇到。"}, {"text": "他的努力遭了老师的肯定。", "explanation": "这里应该用〈得到〉。遭只用于不幸或不利的事，老师的肯定是好事，要说得到。"}, {"text": "我们在街上遭了一个老朋友。", "explanation": "这里应该用〈碰上〉。遭只用于不幸或不利的事，见到老朋友是好事，要说碰上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89365, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "遭", "is_correct": true, "explanation": "遭（zāo）是正确答案，表示碰上不好的事。"}, {"text": "澡", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是洗澡。"}, {"text": "灶", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是炉灶。"}, {"text": "造", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是制造。"}, {"text": "糙", "is_correct": false, "explanation": "cāo 与 zāo 只有声母不同（c 与 z），意思是粗糙。"}], "explanations": {"遭": "遭（zāo）是正确答案，表示碰上不好的事。", "澡": "zǎo（第三声）与 zāo（第一声）声调不同，意思是洗澡。", "灶": "zào（第四声）与 zāo（第一声）声调不同，意思是炉灶。", "造": "zào（第四声）与 zāo（第一声）声调不同，意思是制造。", "糙": "cāo 与 zāo 只有声母不同（c 与 z），意思是粗糙。"}, "sentence_index": null, "correct_answer": "遭"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "搭配：“写”不能与“抢”搭配作宾语，“写了抢”不成说法。"}, {"text": "遭", "is_correct": true, "explanation": "遭：表示遭受抢劫，与“老人在街上”“警察马上赶来”的语境相合。"}, {"text": "教", "is_correct": false, "explanation": "语义：“教”指传授，与街上发生的抢劫场景不合。"}, {"text": "请", "is_correct": false, "explanation": "搭配：“请”指邀请或聘请人，“请了抢”搭配不当。"}], "explanations": {"写": "搭配：“写”不能与“抢”搭配作宾语，“写了抢”不成说法。", "遭": "遭：表示遭受抢劫，与“老人在街上”“警察马上赶来”的语境相合。", "教": "语义：“教”指传授，与街上发生的抢劫场景不合。", "请": "搭配：“请”指邀请或聘请人，“请了抢”搭配不当。"}, "sentence_index": 6, "correct_answer": "遭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的字遭人夸奖，大家都很羡慕。", "explanation": "这里应该用〈受到〉。遭人表示碰上不好的事，夸奖是好事，要说受到夸奖。"}, {"text": "这位老人遭人感谢，大家都很高兴。", "explanation": "这里应该用〈得到〉。遭人表示碰上不好的事，感谢是好事，要说得到感谢。"}, {"text": "他的创意遭人欢迎，很快就推广开来。", "explanation": "这里应该用〈赢得〉。遭人表示碰上不好的事，欢迎是好事，要说赢得欢迎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天下班路上被遭了雨，全身都湿了。", "corrected_sentence": "他昨天下班路上遭了雨，全身都湿了。", "error_description": "“遭”本身是动词，已表示碰上不好的事，前面不能再加“被”。应说“遭了雨”，不说“被遭了雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候遭了过很多白眼。", "corrected_sentence": "他小时候遭过很多白眼。", "error_description": "“遭”后的“了”和“过”只用其一，不能连用。表示经历过时应说“遭过”，不说“遭了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
