INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89366, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇到(不幸或不利的事)。", "primary_collocate": null, "pronunciation": "zāo", "ipa": "tsɑʊ˥", "syllable_count": 1, "sentences": [{"text": "昨天夜里，他家遭了小偷。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子去年遭了一场大水。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在路上遭人抢了钱包。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王做事不认真，遭了老板的批评。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的船在海上遭了大风。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他小时候遭过不少白眼。", "target_word": "遭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友在国外遭过抢。", "target_word": "遭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕再遭人笑话，就不敢开口。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好多地方今年遭了旱灾，粮食很少。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个商人遭人陷害，丢了工作。", "target_word": "遭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遭了", "label": "体标"}, {"form": "遭过", "label": "体标"}, {"form": "遭到", "label": "复合"}, {"form": "遭遇", "label": "复合"}, {"form": "遭受", "label": "复合"}], "register": "中性", "sense_fingerprint": "遇到不幸或不利的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遭", "is_correct": true, "explanation": "遭（zāo）是正确答案，表示遇到不幸或不利的事。"}, {"text": "早", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是早晨。"}, {"text": "造", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是制造。"}, {"text": "招", "is_correct": false, "explanation": "zhāo 与 zāo 只有声母不同（zh 与 z），意思是招呼、招收。"}, {"text": "操", "is_correct": false, "explanation": "cāo 与 zāo 只有声母不同（c 与 z），意思是操作、体操。"}], "explanations": {"遭": "遭（zāo）是正确答案，表示遇到不幸或不利的事。", "早": "zǎo（第三声）与 zāo（第一声）声调不同，意思是早晨。", "造": "zào（第四声）与 zāo（第一声）声调不同，意思是制造。", "招": "zhāo 与 zāo 只有声母不同（zh 与 z），意思是招呼、招收。", "操": "cāo 与 zāo 只有声母不同（c 与 z），意思是操作、体操。"}, "sentence_index": null, "correct_answer": "遭"}, "level_3": {"options": [{"text": "雇", "is_correct": false, "explanation": "语义：“雇”指雇用人做事，与“夜里偷东西”的叙述不符。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”要带受赠的人，“小偷”不能作受赠者，“送了小偷”搭配不当。"}, {"text": "遭", "is_correct": true, "explanation": "遭：表示遇到不幸的事，“小偷”与“夜里”的语境相合。"}, {"text": "聘", "is_correct": false, "explanation": "语义：“聘”指聘用人员，与夜里家里被偷的叙述不符，“聘了小偷”说不通。"}], "explanations": {"雇": "语义：“雇”指雇用人做事，与“夜里偷东西”的叙述不符。", "送": "搭配：“送”要带受赠的人，“小偷”不能作受赠者，“送了小偷”搭配不当。", "遭": "遭：表示遇到不幸的事，“小偷”与“夜里”的语境相合。", "聘": "语义：“聘”指聘用人员，与夜里家里被偷的叙述不符，“聘了小偷”说不通。"}, "sentence_index": 0, "correct_answer": "遭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天遭了好运，考试全对。", "explanation": "这里应该用〈遇到〉。遭只用于不幸或不利的事，好运是好事，要说遇到。"}, {"text": "他因为工作努力，遭了老板的表扬。", "explanation": "这里应该用〈受〉。遭只用于不幸或不利的事，表扬是好事，要说受。"}, {"text": "他在国外遭了一位热心的老师，学到了很多东西。", "explanation": "这里应该用〈遇见〉。遭只用于不幸或不利的事，遇见热心的老师是好事，不能用遭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89366, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "遭", "is_correct": true, "explanation": "遭（zāo）是正确答案，表示遇到不幸或不利的事。"}, {"text": "澡", "is_correct": false, "explanation": "zǎo（第三声）与 zāo（第一声）声调不同，意思是洗澡。"}, {"text": "灶", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是炉灶。"}, {"text": "皂", "is_correct": false, "explanation": "zào（第四声）与 zāo（第一声）声调不同，意思是肥皂。"}, {"text": "糙", "is_correct": false, "explanation": "cāo 与 zāo 只有声母不同（c 与 z），意思是粗糙。"}], "explanations": {"遭": "遭（zāo）是正确答案，表示遇到不幸或不利的事。", "澡": "zǎo（第三声）与 zāo（第一声）声调不同，意思是洗澡。", "灶": "zào（第四声）与 zāo（第一声）声调不同，意思是炉灶。", "皂": "zào（第四声）与 zāo（第一声）声调不同，意思是肥皂。", "糙": "cāo 与 zāo 只有声母不同（c 与 z），意思是粗糙。"}, "sentence_index": null, "correct_answer": "遭"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "搭配：“写”不能与“抢”搭配作宾语，“写过抢”不成说法。"}, {"text": "教", "is_correct": false, "explanation": "语义：“教”指传授知识，与“抢”所表示的犯罪行为不相合。"}, {"text": "遭", "is_correct": true, "explanation": "遭：表示遭受抢劫，“过”表示经历过，语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不与“抢”搭配，“吃过抢”不成说法。"}], "explanations": {"写": "搭配：“写”不能与“抢”搭配作宾语，“写过抢”不成说法。", "教": "语义：“教”指传授知识，与“抢”所表示的犯罪行为不相合。", "遭": "遭：表示遭受抢劫，“过”表示经历过，语境相合。", "吃": "搭配：“吃”不与“抢”搭配，“吃过抢”不成说法。"}, "sentence_index": 6, "correct_answer": "遭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的作品遭人称赞，很快出了名。", "explanation": "这里应该用〈获得〉。遭人表示遭遇不利的事，称赞是好事，要说获得称赞。"}, {"text": "这位老师遭人敬重，学生都很喜欢他。", "explanation": "这里应该用〈受到〉。遭人表示遭遇不利的事，敬重是好事，要说受到敬重。"}, {"text": "他遭人信任，很快当上了班长。", "explanation": "这里应该用〈得到〉。遭人表示遭遇不利的事，信任是好事，要说得到信任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家上个月被遭了小偷。", "corrected_sentence": "他家上个月遭了小偷。", "error_description": "“遭”本身是动词，已表示遇到不幸的事，前面不能再加“被”。应说“他家遭了小偷”，不说“被遭了小偷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时遭了过不少罪。", "corrected_sentence": "他年轻时遭过不少罪。", "error_description": "“遭”后的“了”和“过”只用其一，不能连用。表示经历过时应说“遭过不少罪”，不说“遭了过不少罪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
