INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89367, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89367, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说话，常放在别人讲的话后面。", "primary_collocate": null, "pronunciation": "shuō dào", "ipa": "ʂwo⁵⁵ tɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "“我有点累了，”他说道。", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“明天会下雨，”妈妈说道。", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“请大家坐下，”老师说道。", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这里很安静，”小王说道。", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我们一起去吧，”小明笑着说道。", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“别担心，”爸爸轻声说道，“我在这里。”", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“谢谢你的帮助，”她对我说道。", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“时间不早了，”哥哥看看表说道。", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这个问题不难，”老师说道。", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我想回家了，”孩子小声说道。", "target_word": "说道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "说话；置于引语之后，如“……，”他说道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1db7579-ff47-4f4b-8f4b-d3cbfdbf4ed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89367, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说道", "is_correct": true, "explanation": "正确：“说道”用在引语之后，表示说话，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，不能用来引出“我有点累了”这样的话。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要食物作宾语，不能用来引出一句话。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是身体动作，不发出话语，与引语内容不符。"}], "explanations": {"说道": "正确：“说道”用在引语之后，表示说话，与句意相符。", "唱": "语义：“唱”指唱歌，不能用来引出“我有点累了”这样的话。", "吃": "配价：“吃”需要食物作宾语，不能用来引出一句话。", "跳": "语义：“跳”是身体动作，不发出话语，与引语内容不符。"}, "sentence_index": 0, "correct_answer": "说道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看着窗外，说道一块石头。", "explanation": "这里应该用〈搬〉。“说道”只能引出说的话，“一块石头”要用“搬”。"}, {"text": "小王坐在桌前，说道一封信。", "explanation": "这里应该用〈写〉。“说道”只能引出说的话，“一封信”要用“写”。"}, {"text": "“明天会下雨，”妈妈在纸上说道。", "explanation": "这里应该用〈写道〉。“说道”指口头说话，写在纸上要用“写道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说道", "is_correct": true, "explanation": "正确：“说道”用在引语之后，表示她对我说话，与句意相符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”是哭泣的动作，不能用来引出“谢谢你的帮助”这样的话。"}, {"text": "打", "is_correct": false, "explanation": "配价：“打”需要动作对象，“对我打”之后缺少内容，不能引出引语。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“谢谢你的帮助”这样的话语不相关，不能引出引语。"}], "explanations": {"说道": "正确：“说道”用在引语之后，表示她对我说话，与句意相符。", "哭": "语义：“哭”是哭泣的动作，不能用来引出“谢谢你的帮助”这样的话。", "打": "配价：“打”需要动作对象，“对我打”之后缺少内容，不能引出引语。", "睡": "语义：“睡”与“谢谢你的帮助”这样的话语不相关，不能引出引语。"}, "sentence_index": 6, "correct_answer": "说道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他停下脚步，说道一辆自行车。", "explanation": "这里应该用〈骑〉。“说道”只能引出说的话，“一辆自行车”要用“骑”。"}, {"text": "孩子坐在床上，说道一本故事书。", "explanation": "这里应该用〈读〉。“说道”只能引出说的话，“一本故事书”要用“读”。"}, {"text": "孩子小声说道一个箱子。", "explanation": "这里应该用〈抬〉。“说道”只能引出说的话，“一个箱子”要用“抬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“我明白了，”他点点头说道着。", "corrected_sentence": "“我明白了，”他点点头说道。", "error_description": "错误：“说道着”应为“说道”。“说道”用于引语之后，不带“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“别着急，”奶奶慢慢说道着。", "corrected_sentence": "“别着急，”奶奶慢慢说道。", "error_description": "错误：“说道”作引语之后的说话标记，后面不能加“着”，应说“奶奶慢慢说道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e08398dc-9b25-4ac7-bd3f-71623cf8b442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
