INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89369, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "纲领是一个团体写下来的，要做什么和怎么做的大计划。", "primary_collocate": null, "pronunciation": "gāng lǐng", "ipa": "kɑŋ˥ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个小组写了一份新的纲领。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先读一读公司的纲领。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生会的纲领写得很清楚。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份纲领说明了我们要做什么。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起讨论了俱乐部的纲领。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把纲领贴在墙上，让大家看。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协会的纲领有三页。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新成员要先了解团体的纲领。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纲领写着我们的目标和做法。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份纲领是去年写的，现在要改一改。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "綱領", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "团体写成文字的目标与做法的总计划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed153e7-0a2c-4ca6-9ac2-d5bcdbc4229a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纲领", "is_correct": true, "explanation": "正确。纲领指团体写下的目标和做法，可以用量词“份”计量，与“写了一份新的”相合。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“写”不能与“蛋糕”搭配，写的对象应是文字材料。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是活的动物，不是可以写下来的文件。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然地理事物，不能写成一份新的东西。"}], "explanations": {"纲领": "正确。纲领指团体写下的目标和做法，可以用量词“份”计量，与“写了一份新的”相合。", "蛋糕": "搭配：“写”不能与“蛋糕”搭配，写的对象应是文字材料。", "小猫": "语义：小猫是活的动物，不是可以写下来的文件。", "河流": "语义：河流是自然地理事物，不能写成一份新的东西。"}, "sentence_index": 0, "correct_answer": "纲领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在操场上大声喊出了纲领。", "explanation": "这里应该用〈口号〉。口号是喊出来的，纲领是写成文件的团体方针，不能说“喊出纲领”。"}, {"text": "他这周的纲领是复习数学、准备考试。", "explanation": "这里应该用〈安排〉。纲领指团体的基本方针，个人一周要做的具体事项应说安排。"}, {"text": "我们的纲领是下个月去北京旅行。", "explanation": "这里应该用〈计划〉。纲领指团体的基本方针，不是具体的行程安排；安排一次旅行应说计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纲领", "is_correct": true, "explanation": "正确。纲领是写成的文件，“协会的……有三页”说的是文字材料的页数。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：脸是人的面部，没有页数，不能说“有三页”。"}, {"text": "腿", "is_correct": false, "explanation": "配价：“有三页”要求主语是可以分页的材料，“腿”不符合。"}, {"text": "镜子", "is_correct": false, "explanation": "配价：镜子没有页数，“有三页”的主语应是文字材料。"}], "explanations": {"纲领": "正确。纲领是写成的文件，“协会的……有三页”说的是文字材料的页数。", "脸": "体貌：脸是人的面部，没有页数，不能说“有三页”。", "腿": "配价：“有三页”要求主语是可以分页的材料，“腿”不符合。", "镜子": "配价：镜子没有页数，“有三页”的主语应是文字材料。"}, "sentence_index": 6, "correct_answer": "纲领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上都要写一份纲领。", "explanation": "这里应该用〈日记〉。纲领是团体制定的基本方针，个人每天写的记录应说日记。"}, {"text": "妈妈出门前列了一份纲领，记着要买的菜。", "explanation": "这里应该用〈购物清单〉。纲领是团体的基本方针，记着要买的菜应写成购物清单。"}, {"text": "我把纲领翻到第十页，找朋友的电话号码。", "explanation": "这里应该用〈电话簿〉。纲领是团体的基本方针，记录电话号码的应是电话簿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校刚刚公布了一把新的纲领。", "corrected_sentence": "学校刚刚公布了一份新的纲领。", "error_description": "错误：“一把纲领”；正确：“一份纲领”。纲领是写成的文件，应用量词“份”，“把”用于有柄的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份纲领写很清楚，大家都看得懂。", "corrected_sentence": "这份纲领写得很清楚，大家都看得懂。", "error_description": "错误：“写很清楚”；正确：“写得很清楚”。“V得”后接补语，漏掉“得”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
