INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政党或团体为实现目标而制定的行动准则和基本方针。", "primary_collocate": null, "pronunciation": "gāng lǐng", "ipa": "kɑŋ˥ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个政党公布了新的纲领。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政党的纲领要让人民看得懂。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按照纲领一步一步工作。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份纲领是全党行动的方针。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会通过了这个新纲领。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会的纲领写着要保护工人。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体有自己的纲领。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纲领里说，要先发展教育。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党员都要认真学习党的纲领。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们制定纲领，是为了实现目标。", "target_word": "纲领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "綱領", "label": "繁体"}, {"form": "政治纲领", "label": "复合"}], "register": "书面语", "sense_fingerprint": "政党或团体为实现目标制定的行动准则和基本方针", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aed153e7-0a2c-4ca6-9ac2-d5bcdbc4229a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纲领", "is_correct": true, "explanation": "正确。纲领是政党制定的行动准则，是可以“公布”的文件。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“公布”不能与“蛋糕”搭配，公布的应是文件或政策。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然事物，不能被“公布”。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子是日用品，不是可以公布的内容。"}], "explanations": {"纲领": "正确。纲领是政党制定的行动准则，是可以“公布”的文件。", "蛋糕": "搭配：“公布”不能与“蛋糕”搭配，公布的应是文件或政策。", "河流": "语义：河流是自然事物，不能被“公布”。", "镜子": "语义：镜子是日用品，不是可以公布的内容。"}, "sentence_index": 0, "correct_answer": "纲领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们在广场上高喊纲领。", "explanation": "这里应该用〈口号〉。口号是高喊出来的，纲领是写成文件的政治方针，不能说“高喊纲领”。"}, {"text": "妈妈的纲领写着红烧肉的做法。", "explanation": "这里应该用〈食谱〉。纲领是政党或团体的行动方针，写菜谱做法的应是食谱。"}, {"text": "饭馆门口的纲领上写着今天的菜价。", "explanation": "这里应该用〈菜单〉。纲领是政党或团体的行动准则，写菜品和价格的应是菜单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纲领", "is_correct": true, "explanation": "正确。团体可以拥有自己的纲领，纲领是团体的行动方针。"}, {"text": "尾巴", "is_correct": false, "explanation": "配价：“有自己的”要求团体可以拥有的事物，团体不能有尾巴。"}, {"text": "胡子", "is_correct": false, "explanation": "体貌：胡子是人的面部特征，团体不会长胡子。"}, {"text": "鼻子", "is_correct": false, "explanation": "体貌：鼻子是人或动物的器官，团体没有鼻子。"}], "explanations": {"纲领": "正确。团体可以拥有自己的纲领，纲领是团体的行动方针。", "尾巴": "配价：“有自己的”要求团体可以拥有的事物，团体不能有尾巴。", "胡子": "体貌：胡子是人的面部特征，团体不会长胡子。", "鼻子": "体貌：鼻子是人或动物的器官，团体没有鼻子。"}, "sentence_index": 6, "correct_answer": "纲领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在纲领上记下了明天要买的东西。", "explanation": "这里应该用〈备忘录〉。纲领是团体的基本方针，记下要买的东西应该用备忘录。"}, {"text": "老师把纲领发给学生，让他们回家做数学题。", "explanation": "这里应该用〈作业〉。纲领是团体制定的行动方针，老师让学生回家做的数学题是作业。"}, {"text": "这台洗衣机的纲领有十页，教人怎么洗衣服。", "explanation": "这里应该用〈说明书〉。纲领是团体的基本方针，教人怎么操作机器的应是说明书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大会终于通过了一棵新的纲领。", "corrected_sentence": "大会终于通过了一份新的纲领。", "error_description": "错误：“一棵纲领”；正确：“一份纲领”。“棵”用于植物，纲领是写成的文件，应用量词“份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个党的纲领写很清楚，人人都能看懂。", "corrected_sentence": "这个党的纲领写得很清楚，人人都能看懂。", "error_description": "错误：“写很清楚”；正确：“写得很清楚”。“V得”后接补语，漏掉“得”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d3059c8-1a72-4f3e-a1db-361cc0491071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
